CREATE OR REPLACE FUNCTION "public"."actions_ca_requises"("p_entite_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN (
    SELECT jsonb_agg(
      jsonb_build_object(
        'id', a.id,
        'priorite', a.priorite,
        'titre', a.titre,
        'description', a.description,
        'domaine', a.domaine,
        'echeance', a.echeance,
        'responsable', a.responsable,
        'impact_attendu', a.impact_attendu,
        'statut', a.statut
      ) ORDER BY a.priorite, a.echeance
    )
    FROM (
      SELECT 
        gen_random_uuid() as id,
        'Haute' as priorite,
        'Validation Plan d''Action Corrective — Ratios Prudentiels' as titre,
        'Deux écarts mineurs identifiés sur les ratios prudentiels BCEAO. Soumission du PAC au Comité des Risques avant le 15 du mois.' as description,
        'Conformité Réglementaire' as domaine,
        (CURRENT_DATE + interval '15 days')::date as echeance,
        'Directeur des Risques' as responsable,
        'Conformité totale aux ratios BCEAO dans 30 jours' as impact_attendu,
        'En attente CA' as statut
      UNION ALL
      SELECT gen_random_uuid(), 'Haute', 'Approbation Budget Conformité ESG ISSB 2026',
        'Budget estimé 450M FCFA pour la mise en conformité double matérialité S1/S2. Nécessite vote CA avant budget annuel.',
        'ESG & Durabilité', (CURRENT_DATE + interval '30 days')::date, 'Directeur Financier',
        'Conformité ISSB d''ici Q2 2027', 'En attente CA'
      UNION ALL
      SELECT gen_random_uuid(), 'Majeure', 'Renforcement Dispositif LBC/FT — Mise à jour GAFI 2026',
        'Mise à jour du dispositif LBC/FT suite aux nouvelles exigences GAFI 2026. Audit externe prévu Q4 2026.',
        'LBC/FT & Sanctions', (CURRENT_DATE + interval '45 days')::date, 'Responsable Conformité',
        'Conformité GAFI renforcée, réduction risque sanction', 'En préparation'
      UNION ALL
      SELECT gen_random_uuid(), 'Majeure', 'Revue Composition CA — Circulaire BCEAO 01/2017',
        'Vérification annuelle de l''indépendance des administrateurs et respect des comités spécialisés.',
        'Gouvernance', (CURRENT_DATE + interval '60 days')::date, 'Secrétaire du CA',
        'Conformité BCEAO 01/2017 maintenue', 'Programmé'
      UNION ALL
      SELECT gen_random_uuid(), 'Normale', 'Mise en place Stress Tests Climatiques Pilier 2',
        'Intégration des stress tests climatiques dans le dispositif Pilier 2 BCEAO/COBAC.',
        'Risque Climatique', (CURRENT_DATE + interval '90 days')::date, 'Directeur des Risques',
        'Préparation inspection BCEAO 2027', 'Planifié'
    ) a
  );
END;
$$;


ALTER FUNCTION "public"."actions_ca_requises"("p_entite_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_rag_embedding"("doc_id" "uuid", "emb_vector_text" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE rag_documents 
  SET embedding = emb_vector_text::vector,
      updated_at = now()
  WHERE id = doc_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Document introuvable');
  END IF;

  RETURN jsonb_build_object('success', true, 'document_id', doc_id);
END;
$$;


ALTER FUNCTION "public"."apply_rag_embedding"("doc_id" "uuid", "emb_vector_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_score_lead"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_sector TEXT;
  v_country TEXT;
  v_firmographic_score INTEGER;
  v_engagement_score INTEGER;
  v_behavioral_score INTEGER;
  v_predictive_score INTEGER;
  v_conversion_probability INTEGER;
  v_estimated_value BIGINT;
  v_next_best_action TEXT;
  v_churn_risk TEXT;
  v_signals JSONB;
  v_days_since_activity INTEGER;
  v_existing_id BIGINT;
BEGIN
  -- Detect sector from lead_category or source_page
  v_sector := COALESCE(NEW.lead_category, 'PME');
  IF NEW.source_page ILIKE '%banque%' OR NEW.source_page ILIKE '%bceao%' OR NEW.source_page ILIKE '%financier%' THEN
    v_sector := 'Banque';
  ELSIF NEW.source_page ILIKE '%microfinance%' OR NEW.source_page ILIKE '%sfd%' THEN
    v_sector := 'Microfinance';
  ELSIF NEW.source_page ILIKE '%fintech%' OR NEW.source_page ILIKE '%paiement%' THEN
    v_sector := 'Fintech';
  ELSIF NEW.source_page ILIKE '%holding%' OR NEW.source_page ILIKE '%familiale%' THEN
    v_sector := 'Holding familiale';
  END IF;

  v_country := 'Togo';

  -- Firmographic Score
  v_firmographic_score := CASE
    WHEN v_sector = 'Banque' THEN 90
    WHEN v_sector = 'Microfinance' THEN 85
    WHEN v_sector = 'Fintech' THEN 80
    WHEN v_sector = 'Assurance' THEN 75
    WHEN v_sector IN ('SFD', 'EMF') THEN 80
    WHEN v_sector = 'Holding familiale' THEN 70
    WHEN v_sector = 'Groupe multinational' THEN 90
    WHEN v_sector = 'Public' THEN 60
    ELSE 50
  END;

  -- Engagement Score
  v_engagement_score := 10;
  IF NEW.source_page ILIKE '%diagnostic%' THEN v_engagement_score := v_engagement_score + 20; END IF;
  IF NEW.source_page ILIKE '%pricing%' OR NEW.source_page ILIKE '%offre%' THEN v_engagement_score := v_engagement_score + 10; END IF;
  IF NEW.source_page ILIKE '%service%' THEN v_engagement_score := v_engagement_score + 8; END IF;
  IF NEW.pipeline_stage = 'qualified' OR NEW.pipeline_stage = 'proposal' THEN v_engagement_score := v_engagement_score + 15; END IF;
  IF NEW.pipeline_stage = 'negotiation' OR NEW.pipeline_stage = 'closing' THEN v_engagement_score := v_engagement_score + 25; END IF;
  IF NEW.deal_value IS NOT NULL AND NEW.deal_value > 20000000 THEN v_engagement_score := v_engagement_score + 10; END IF;
  IF NEW.probability IS NOT NULL AND NEW.probability > 50 THEN v_engagement_score := v_engagement_score + 10; END IF;
  IF NEW.email_1_opened IS TRUE THEN v_engagement_score := v_engagement_score + 3; END IF;
  IF NEW.email_2_opened IS TRUE THEN v_engagement_score := v_engagement_score + 5; END IF;
  IF NEW.email_3_opened IS TRUE THEN v_engagement_score := v_engagement_score + 7; END IF;
  IF NEW.calendar_link_clicked IS TRUE THEN v_engagement_score := v_engagement_score + 25; END IF;
  IF NEW.meeting_scheduled_at IS NOT NULL THEN v_engagement_score := v_engagement_score + 20; END IF;
  v_engagement_score := LEAST(100, v_engagement_score);

  -- Behavioral Score
  v_days_since_activity := 30;
  IF NEW.last_activity_at IS NOT NULL THEN
    v_days_since_activity := EXTRACT(DAY FROM (NOW() - NEW.last_activity_at))::INTEGER;
  ELSIF NEW.last_contact_at IS NOT NULL THEN
    v_days_since_activity := EXTRACT(DAY FROM (NOW() - NEW.last_contact_at))::INTEGER;
  END IF;
  v_behavioral_score := GREATEST(20, 100 - (v_days_since_activity * 3));
  v_behavioral_score := LEAST(100, v_behavioral_score);

  -- Predictive Score
  v_predictive_score := ROUND((v_firmographic_score * 0.30) + (v_engagement_score * 0.40) + (v_behavioral_score * 0.30));

  -- Conversion Probability
  v_conversion_probability := ROUND(100.0 / (1.0 + EXP(-(v_predictive_score - 50)::NUMERIC / 15.0)));

  -- Estimated Value
  v_estimated_value := COALESCE(NEW.deal_value, (CASE WHEN v_sector IN ('Banque', 'Microfinance', 'Fintech') THEN 25000000 ELSE 15000000 END)::BIGINT);
  v_estimated_value := ROUND(v_estimated_value * (v_predictive_score::NUMERIC / 50.0))::BIGINT;

  -- Next Best Action
  v_next_best_action := CASE
    WHEN v_predictive_score >= 75 THEN 'Appeler dans les 24h - lead chaud pret a convertir'
    WHEN v_predictive_score >= 50 THEN 'Envoyer livre blanc sectoriel + proposer diagnostic flash'
    WHEN v_predictive_score >= 30 THEN 'Nurturing email sequence - 3 touches sur 2 semaines'
    ELSE 'Ajouter a la newsletter mensuelle - rechauffer progressivement'
  END;

  -- Churn Risk
  v_churn_risk := CASE
    WHEN v_predictive_score < 25 THEN 'high'
    WHEN v_predictive_score < 45 THEN 'medium'
    ELSE 'low'
  END;

  -- Signals JSON
  v_signals := jsonb_build_object(
    'source_page', COALESCE(NEW.source_page, ''),
    'pipeline_stage', COALESCE(NEW.pipeline_stage, 'new'),
    'email_opens', (CASE WHEN NEW.email_1_opened IS TRUE THEN 1 ELSE 0 END + CASE WHEN NEW.email_2_opened IS TRUE THEN 1 ELSE 0 END + CASE WHEN NEW.email_3_opened IS TRUE THEN 1 ELSE 0 END),
    'calendar_clicked', COALESCE(NEW.calendar_link_clicked, false),
    'meeting_scheduled', CASE WHEN NEW.meeting_scheduled_at IS NOT NULL THEN true ELSE false END
  );

  -- Upsert
  SELECT id INTO v_existing_id FROM lead_scores WHERE lead_id = NEW.id;

  IF v_existing_id IS NOT NULL THEN
    UPDATE lead_scores SET
      lead_name = COALESCE(NEW.full_name, NEW.organization),
      company = NEW.organization,
      sector = v_sector,
      country = v_country,
      predictive_score = v_predictive_score,
      engagement_score = v_engagement_score,
      firmographic_score = v_firmographic_score,
      behavioral_score = v_behavioral_score,
      conversion_probability = v_conversion_probability,
      estimated_value_fcfa = v_estimated_value,
      next_best_action = v_next_best_action,
      risk_of_churn = v_churn_risk,
      last_activity_date = COALESCE(NEW.last_activity_at, NEW.last_contact_at, NOW()),
      signals = v_signals,
      analyzed_at = NOW()
    WHERE id = v_existing_id;
  ELSE
    INSERT INTO lead_scores (
      lead_id, lead_name, company, sector, country,
      predictive_score, engagement_score, firmographic_score, behavioral_score,
      conversion_probability, estimated_value_fcfa, next_best_action,
      risk_of_churn, last_activity_date, signals, analyzed_at
    ) VALUES (
      NEW.id,
      COALESCE(NEW.full_name, NEW.organization),
      NEW.organization,
      v_sector,
      v_country,
      v_predictive_score,
      v_engagement_score,
      v_firmographic_score,
      v_behavioral_score,
      v_conversion_probability,
      v_estimated_value,
      v_next_best_action,
      v_churn_risk,
      COALESCE(NEW.last_activity_at, NEW.last_contact_at, NOW()),
      v_signals,
      NOW()
    );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."auto_score_lead"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."batch_request_rag_embeddings"("batch_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  doc record;
  req_id bigint;
  embedding_text text;
  api_key text;
  generated int := 0;
BEGIN
  BEGIN
    SELECT decrypted_secret INTO api_key FROM vault.decrypted_secrets WHERE name = 'OPENAI_API_KEY';
  EXCEPTION WHEN OTHERS THEN
    api_key := NULL;
  END;

  IF api_key IS NULL OR api_key = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'OPENAI_API_KEY non configurée dans le Vault Supabase. Allez dans Supabase > Vault > Add Secret.');
  END IF;

  FOR doc IN 
    SELECT id, titre, description, mots_cles, domaine, sous_domaine, pays, organisation, type_document, statut, content
    FROM rag_documents
    WHERE est_public = true AND embedding IS NULL
    LIMIT batch_limit
  LOOP
    embedding_text := '';
    IF doc.titre IS NOT NULL THEN embedding_text := embedding_text || 'Titre: ' || doc.titre || E'\n'; END IF;
    IF doc.description IS NOT NULL THEN embedding_text := embedding_text || 'Description: ' || doc.description || E'\n'; END IF;
    IF doc.domaine IS NOT NULL THEN embedding_text := embedding_text || 'Domaine: ' || doc.domaine || E'\n'; END IF;
    IF doc.sous_domaine IS NOT NULL THEN embedding_text := embedding_text || 'Sous-domaine: ' || doc.sous_domaine || E'\n'; END IF;
    IF doc.pays IS NOT NULL THEN embedding_text := embedding_text || 'Pays: ' || doc.pays || E'\n'; END IF;
    IF doc.organisation IS NOT NULL THEN embedding_text := embedding_text || 'Organisation: ' || doc.organisation || E'\n'; END IF;
    IF doc.type_document IS NOT NULL THEN embedding_text := embedding_text || 'Type: ' || doc.type_document || E'\n'; END IF;
    IF doc.statut IS NOT NULL THEN embedding_text := embedding_text || 'Statut: ' || doc.statut || E'\n'; END IF;
    IF doc.mots_cles IS NOT NULL THEN embedding_text := embedding_text || 'Mots-clés: ' || array_to_string(doc.mots_cles, ', ') || E'\n'; END IF;
    IF doc.content IS NOT NULL THEN embedding_text := embedding_text || 'Contenu: ' || substring(doc.content, 1, 6000); END IF;
    embedding_text := substring(embedding_text, 1, 8000);

    req_id := net.http_post(
      url := 'https://api.openai.com/v1/embeddings',
      body := jsonb_build_object('model', 'text-embedding-3-small', 'input', embedding_text, 'dimensions', 1536),
      headers := jsonb_build_object('Authorization', 'Bearer ' || api_key, 'Content-Type', 'application/json'),
      timeout_milliseconds := 30000
    );

    generated := generated + 1;
    PERFORM pg_sleep(0.1);
  END LOOP;

  RETURN jsonb_build_object('success', true, 'generated', generated, 'message', generated || ' requêtes envoyées à OpenAI.');
END;
$$;


ALTER FUNCTION "public"."batch_request_rag_embeddings"("batch_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_ao_updates"() RETURNS "void"
    LANGUAGE "plpgsql"
    AS $_$
declare
  ao record;
  sub record;
  msg text;
  slack_url text;
  discord_url text;
  svc_key text;
  supabase_url text;
begin
  slack_url   := current_setting('app.slack_webhook_url', true);
  discord_url := current_setting('app.discord_webhook_url', true);
  svc_key     := current_setting('app.settings.service_role_key', true);
  supabase_url:= 'https://pgfwhahiwqvqeahpirjx.supabase.co';

  for ao in
    select * from public.ao_ami
    where crawled_at > now() - interval '5 minutes'
      and notified = false
    order by montant_usd desc nulls last
  loop
    for sub in
      select * from public.ao_alert_subs
      where (pays is null or ao.pays = any(pays))
        and coalesce(ao.montant_usd, 0) between budget_min and budget_max
        and (secteurs is null or secteurs && ao.secteurs)
    loop
      msg := format(
        '🚨 *Nouvelle opportunité %s — %s*%n%s%n• Pays : %s%n• Budget : $%s%n• Deadline : %s%n• Lien : %s',
        ao.source,
        coalesce(ao.type, 'AO'),
        ao.titre,
        ao.pays,
        to_char(coalesce(ao.montant_usd, 0), 'FM999,999,999,999'),
        to_char(ao.deadline, 'DD Mon YYYY'),
        ao.url
      );

      if 'slack' = any(sub.networks) and slack_url is not null and slack_url not like '%PLACEHOLDER%' then
        perform net.http_post(
          url  := slack_url,
          body := jsonb_build_object('text', msg)
        );
      end if;

      if 'discord' = any(sub.networks) and discord_url is not null and discord_url not like '%PLACEHOLDER%' then
        perform net.http_post(
          url  := discord_url,
          body := jsonb_build_object('content', msg)
        );
      end if;

      if 'email' = any(sub.networks) and svc_key is not null and svc_key != 'NOT_CONFIGURED' then
        perform net.http_post(
          url     := supabase_url || '/functions/v1/kos-tender-email-notify',
          headers := jsonb_build_object(
            'Content-Type',  'application/json',
            'Authorization', 'Bearer ' || svc_key
          ),
          body    := jsonb_build_object(
            'recipient', sub.user_email,
            'subject',   '[KHEPRA] Nouvelle opportunité ' || ao.source || ' — ' || ao.titre,
            'body',      msg,
            'ao_id',     ao.id,
            'source',    ao.source,
            'country',   ao.pays,
            'deadline',  ao.deadline
          )
        );
      end if;

    end loop;

    update public.ao_ami 
    set notified = true 
    where id = ao.id;

  end loop;
end;
$_$;


ALTER FUNCTION "public"."check_ao_updates"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_rag_embedding_result"("net_req_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  resp record;
  embedding_arr jsonb;
  emb_values text;
  emb_vector text;
BEGIN
  SELECT 
    response_body,
    error_msg,
    status_code
  INTO resp
  FROM net._http_response
  WHERE id = net_req_id;

  IF resp IS NULL THEN
    RETURN jsonb_build_object('status', 'pending', 'message', 'En attente de la réponse OpenAI...');
  END IF;

  IF resp.error_msg IS NOT NULL THEN
    RETURN jsonb_build_object('status', 'error', 'error', resp.error_msg, 'status_code', resp.status_code);
  END IF;

  embedding_arr := resp.response_body::jsonb->'data'->0->'embedding';

  IF embedding_arr IS NULL THEN
    RETURN jsonb_build_object('status', 'error', 'error', 'Pas d''embedding dans la réponse OpenAI');
  END IF;

  SELECT string_agg(value::text, ',') INTO emb_values
  FROM jsonb_array_elements_text(embedding_arr) AS value;

  emb_vector := '[' || emb_values || ']';

  RETURN jsonb_build_object(
    'status', 'ready',
    'embedding', emb_vector,
    'dimensions', jsonb_array_length(embedding_arr),
    'message', 'Embedding prêt. Utilisez apply_rag_embedding(''' || emb_vector || ''', doc_id) pour le stocker.'
  );
END;
$$;


ALTER FUNCTION "public"."check_rag_embedding_result"("net_req_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_rate_limit"("p_client_id" "text", "p_endpoint" "text", "p_max_req" integer DEFAULT 100) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_count int;
BEGIN
  SELECT COUNT(*) INTO v_count
  FROM public.rate_limit_bigfour
  WHERE client_id = p_client_id
    AND endpoint = p_endpoint
    AND ts > now() - interval '1 minute';
  RETURN v_count < p_max_req;
END;
$$;


ALTER FUNCTION "public"."check_rate_limit"("p_client_id" "text", "p_endpoint" "text", "p_max_req" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_regulator_sla"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.last_crawl < now() - interval '2 hours' THEN
    INSERT INTO regulator_sla_violations(regulator_name, latency_ms, severity, steps)
    VALUES (
      NEW.regulator,
      EXTRACT(EPOCH FROM now() - NEW.last_crawl) * 1000,
      CASE
        WHEN NEW.last_crawl < now() - interval '6 hours' THEN 'critical'
        WHEN NEW.last_crawl < now() - interval '4 hours' THEN 'high'
        ELSE 'warning'
      END,
      jsonb_build_object(
        'url', NEW.url,
        'feed_type', NEW.doc_type,
        'content_hash', NEW.content_hash,
        'country', NEW.country,
        'crawled_by', NEW.crawled_by
      )
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."check_regulator_sla"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_regulator_updates"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.last_crawl < now() - interval '24 hours' THEN
    INSERT INTO regulator_sla_violations(regulator, violated_at)
    VALUES (NEW.name, now());
  END IF;
  RETURN NEW;
END;
$$;


