CREATE OR REPLACE FUNCTION "public"."check_table_rls"("t_name" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE 
  rls_active boolean;
BEGIN
  SELECT relrowsecurity INTO rls_active 
  FROM pg_class c 
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public' AND c.relname = t_name;
  RETURN COALESCE(rls_active, false);
END;
$$;


