CREATE OR REPLACE FUNCTION "public"."cron_kos_regulator_crawler"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_url text := 'https://pgfwhahiwqvqeahpirjx.supabase.co/functions/v1/kos-regulator-crawler/crawl';
  v_req_id bigint;
BEGIN
  SELECT net.http_post(
    url := v_url,
    headers := jsonb_build_object('Content-Type', 'application/json'),
    body := ''::jsonb
  ) INTO v_req_id;
END;
$$;


