CREATE OR REPLACE FUNCTION "public"."extract_table_text"("p_schema" "text", "p_table" "text") RETURNS TABLE("content" "text", "title" "text", "metadata" "jsonb")
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_sql text;
  v_text_cols text[];
  v_title_col text;
BEGIN
  SELECT array_agg(column_name) INTO v_text_cols
  FROM information_schema.columns
  WHERE table_schema = p_schema AND table_name = p_table
    AND data_type IN ('text', 'varchar', 'character varying', 'jsonb');

  SELECT column_name INTO v_title_col
  FROM information_schema.columns
  WHERE table_schema = p_schema AND table_name = p_table
    AND column_name IN ('title', 'name', 'label', 'subject', 'nom', 'titre')
  LIMIT 1;

  IF v_text_cols IS NULL OR array_length(v_text_cols, 1) = 0 THEN
    RETURN;
  END IF;

  v_sql := format('SELECT string_agg(%s, '' ''), MAX(%s::text), jsonb_build_object(''table'', %L, ''schema'', %L, ''row_count'', count(*))
            FROM %I.%I
            WHERE %s IS NOT NULL',
    array_to_string(array(SELECT format('COALESCE(%I::text, '''')', col) FROM unnest(v_text_cols) col), ' || '' '' || '),
    COALESCE(v_title_col, '''' || p_table || ''''),
    p_table, p_schema, p_schema, p_table,
    v_text_cols[1]
  );

  RETURN QUERY EXECUTE v_sql;
END; $$;


ALTER FUNCTION "public"."extract_table_text"("p_schema" "text", "p_table" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_audit_program"("p_audit_type" "text", "p_entite_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_result jsonb;
  v_risques jsonb;
  v_controles jsonb;
  v_questionnaire jsonb;
  v_checklist jsonb;
  v_plan jsonb;
BEGIN
  -- Matrice risques
  SELECT jsonb_agg(jsonb_build_object(
    'categorie', categorie, 'risque', risque,
    'probabilite', probabilite, 'impact', impact, 'severite', severite,
    'referentiel', referentiel, 'statut', statut, 'priorite', priorite
  ) ORDER BY severite DESC)
  INTO v_risques
  FROM kos_risk_matrix(p_entite_id);

  -- Matrice contrôles COSO
  SELECT jsonb_agg(jsonb_build_object(
    'composante', composante_cos, 'principe', principe,
    'controle', controle, 'efficacite', efficacite,
    'preuve', preuve, 'frequence', frequence,
    'responsable', responsable, 'ecart', ecart
  ) ORDER BY efficacite ASC)
  INTO v_controles
  FROM kos_controls_matrix(p_entite_id, 'COSO');

  -- Questionnaire adaptatif
  SELECT jsonb_agg(jsonb_build_object(
    'domaine', domaine, 'question', question,
    'type', type_reponse, 'options', options,
    'poids', poids, 'referentiel', referentiel, 'ordre', ordre
  ) ORDER BY ordre)
  INTO v_questionnaire
  FROM kos_generate_questionnaire(p_audit_type);

  -- Checklist IFC
  SELECT jsonb_agg(jsonb_build_object(
    'ps', ps_number, 'standard', performance_standard,
    'critere', critere, 'applicable', applicable,
    'conforme', conforme, 'preuve', preuve,
    'priorite', priorite, 'ecart_majeur', ecart_majeur
  ) ORDER BY ps_number)
  INTO v_checklist
  FROM kos_checklist_ifc(p_entite_id);

  -- Plan audit auto
  SELECT jsonb_agg(jsonb_build_object(
    'phase', phase, 'periode', periode,
    'duree_jours', duree_jours, 'objectifs', objectifs,
    'livrables', livrables, 'equipe', equipe,
    'risques_cles', risques_cles, 'jalons', jalons
  ) ORDER BY phase)
  INTO v_plan
  FROM kos_audit_plan_auto(p_entite_id);

  -- Assembly final
  v_result := jsonb_build_object(
    'matrice_risques', COALESCE(v_risques, '[]'::jsonb),
    'matrice_controles', COALESCE(v_controles, '[]'::jsonb),
    'questionnaire', COALESCE(v_questionnaire, '[]'::jsonb),
    'checklist', COALESCE(v_checklist, '[]'::jsonb),
    'plan_audit', COALESCE(v_plan, '[]'::jsonb),
    'delai_generation', '< 10 minutes',
    'referentiel', 'ISAE 3000 + ISO 19011',
    'audit_type', p_audit_type,
    'entite_id', p_entite_id,
    'genere_le', NOW(),
    'version', 'KOS Audit Engine v1.0'
  );

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."generate_audit_program"("p_audit_type" "text", "p_entite_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_circular_page_map"("p_regulator_code" "text" DEFAULT 'BCEAO'::"text") RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  c record;
  v_count int := 0;
  v_base_slug text;
  v_suffixes text[][] := ARRAY[
    ['resume', 'Resume', 'informationnel'],
    ['guide-complet', 'Article_Explique', 'informationnel'],
    ['checklist-conformite', 'Checklist', 'transactionnel'],
    ['faq', 'FAQ', 'informationnel'],
    ['cas-pratique-sfd', 'Cas_Pratique', 'transactionnel']
  ];
BEGIN
  FOR c IN
    SELECT id, circular_number, title
    FROM public.circulars
    WHERE source_authority = p_regulator_code
      AND NOT EXISTS (
        SELECT 1 FROM public.circular_page_map
        WHERE circular_id = circulars.id
      )
  LOOP
    v_base_slug := 'bigfour/' || lower(regexp_replace(c.circular_number, '[^a-zA-Z0-9]', '-', 'g'));
    FOR i IN 1..array_length(v_suffixes, 1) LOOP
      INSERT INTO public.circular_page_map (circular_id, slug, type, intent, priority)
      VALUES (
        c.id,
        v_base_slug || '-' || v_suffixes[i][1],
        v_suffixes[i][2],
        v_suffixes[i][3],
        CASE v_suffixes[i][2]
          WHEN 'Checklist' THEN 1.0
          WHEN 'Cas_Pratique' THEN 0.95
          WHEN 'Article_Explique' THEN 0.9
          WHEN 'FAQ' THEN 0.85
          ELSE 0.8
        END
      )
      ON CONFLICT (slug) DO NOTHING;
      v_count := v_count + 1;
    END LOOP;
  END LOOP;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."generate_circular_page_map"("p_regulator_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_livre_blanc"("secteur_input" "text", "lang_input" "text" DEFAULT 'fr'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  report_id uuid;
  sources_json jsonb;
  hash_value text;
BEGIN
  -- 1. Collecte auto depuis kb_docs (recherche textuelle + metadata)
  SELECT jsonb_agg(
    jsonb_build_object(
      'fait', LEFT(k.content, 500),
      'source', COALESCE(k.url, 'kb_docs/' || k.id::text),
      'regulator', COALESCE(k.regulator, k.type, 'INCONNU'),
      'date', COALESCE(k.created_at::text, now()::text),
      'sha256', k.sha256
    )
    ORDER BY k.created_at DESC
  )
  INTO sources_json
  FROM (
    SELECT id, content, url, regulator, type, sha256, created_at
    FROM kb_docs
    WHERE (lang = lang_input OR lang IS NULL)
      AND (
        content ILIKE '%' || secteur_input || '%'
        OR COALESCE(title, '') ILIKE '%' || secteur_input || '%'
        OR COALESCE(bigfour_metadata->>'secteur', '') ILIKE '%' || secteur_input || '%'
        OR COALESCE(bigfour_metadata->>'domain', '') ILIKE '%' || secteur_input || '%'
      )
    ORDER BY created_at DESC
    LIMIT 50
  ) k;

  -- Fallback si aucune source
  IF sources_json IS NULL OR jsonb_array_length(sources_json) = 0 THEN
    sources_json := jsonb_build_array(
      jsonb_build_object(
        'fait','Aucune source spécifique trouvée dans kb_docs pour ce secteur. Penser à enrichir la base KB.',
        'source','fallback',
        'regulator','KHEPRA',
        'date',now()::text
      )
    );
  END IF;

  -- 2. Hash d'audit SHA-256 sur le contexte complet
  hash_value := encode(digest(
    secteur_input || '|' || lang_input || '|' || now()::text || '|' || sources_json::text,
    'sha256'
  ), 'hex');

  -- 3. Insérer le squelette de Livre Blanc
  INSERT INTO think_tank_reports(
    type, secteur, lang, titre, methodologie,
    constats, recommandations, hash_audit, statut, generation_provider
  )
  VALUES (
    'Livre Blanc',
    secteur_input,
    lang_input,
    'État et Perspectives : ' || secteur_input || ' — UEMOA/CEMAC',
    'COSO + ISO 31000 + Benchmark 12 pays UEMOA/CEMAC + KHEPRA KB Docs',
    sources_json,
    '[]'::jsonb, -- Enrichi par Edge Function LLM ensuite
    hash_value,
    'draft',
    'plpgsql-rag-v1'
  )
  RETURNING id INTO report_id;

  RETURN report_id;
END;
$$;


ALTER FUNCTION "public"."generate_livre_blanc"("secteur_input" "text", "lang_input" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_note_ca"("p_entite_id" "uuid", "p_periode" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_resume_exec jsonb;
  v_kpi_cles jsonb;
  v_points_attention jsonb;
  v_decisions_requises jsonb;
  v_annexes jsonb;
BEGIN
  -- 1. Résumé exécutif via LLM
  v_resume_exec := kos_llm_summary('conseil_administration', p_entite_id, p_periode);

  -- 2. KPIs clés
  v_kpi_cles := jsonb_build_object(
    'conformite', COALESCE(
      (SELECT taux_conforme FROM compliance_dashboard WHERE entite_id = p_entite_id),
      0
    ),
    'risque_global', COALESCE(
      (SELECT ROUND(AVG(score)::numeric, 2) FROM risk_register WHERE entite_id = p_entite_id),
      0
    ),
    'incidents_critiques', COALESCE(
      (SELECT count(*)::int FROM incidents 
       WHERE severity = 'critique' 
         AND date_incident >= p_periode 
         AND (entite_id = p_entite_id OR p_entite_id IS NULL)),
      0
    ),
    'ecarts_majeurs', COALESCE(
      (SELECT ecarts_majeurs FROM compliance_dashboard WHERE entite_id = p_entite_id),
      0
    ),
    'recommandations', COALESCE(
      (SELECT recommandations FROM compliance_dashboard WHERE entite_id = p_entite_id),
      0
    ),
    'top_risque_score', COALESCE(
      (SELECT MAX(score) FROM risk_register WHERE entite_id = p_entite_id),
      0
    )
  );

  -- 3. Top 3 risques
  v_points_attention := top3_risques(p_entite_id);

  -- 4. Décisions requises pour le CA
  v_decisions_requises := actions_ca_requises(p_entite_id);

  -- 5. Annexes — rapports réglementaires de la période
  v_annexes := COALESCE(
    (SELECT jsonb_agg(
      jsonb_build_object(
        'titre', rr.titre,
        'url', rr.url,
        'type', rr.type_rapport,
        'date', rr.date_rapport,
        'reference', rr.référence
      ) ORDER BY rr.date_rapport DESC
    )
    FROM regulatory_reports rr
    WHERE rr.entite_id = p_entite_id
      AND rr.date_rapport >= p_periode
      AND rr.statut = 'final'),
    '[]'::jsonb
  );

  -- Assemblage final
  RETURN jsonb_build_object(
    'resume_exec', v_resume_exec,
    'kpi_cles', v_kpi_cles,
    'points_attention', v_points_attention,
    'decisions_requises', v_decisions_requises,
    'annexes', v_annexes,
    'genere_en', '<90s',
    'methodologie', 'COSO + ISO 37000',
    'meta', jsonb_build_object(
      'entite_id', p_entite_id,
      'periode', p_periode,
      'date_generation', now(),
      'version_note', 'v1.0-KOS'
    )
  );
END;
$$;


ALTER FUNCTION "public"."generate_note_ca"("p_entite_id" "uuid", "p_periode" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_pages_from_circular"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  m record;
  v_regulator_name text;
BEGIN
  IF NEW.crawled = true AND OLD.crawled = false THEN
    SELECT r.name INTO v_regulator_name
    FROM public.regulators r
    WHERE r.id = NEW.regulator_id;
    IF v_regulator_name IS NULL THEN
      v_regulator_name := NEW.source_authority;
    END IF;
    FOR m IN
      SELECT * FROM public.circular_page_map
      WHERE circular_id = NEW.id
    LOOP
      INSERT INTO public.kb_pages (
        slug, title, meta_desc, h1, content_html,
        bigfour_metadata, sitemap_priority, last_updated
      )
      VALUES (
        m.slug,
        NEW.title || ' — ' || m.type || ' | Khepra Experts',
        'Décryptage Big Four ' || NEW.title || ' (' || v_regulator_name || ' ' || NEW.circular_number || ') — Guide ' || m.type || ' par Khepra.',
        NEW.title || ' : ' || m.type,
        '<p class="kos-placeholder">Contenu en cours de génération par KOS AI — Big Four Engine v4.0</p>' ||
        '<div class="kos-meta">' ||
          '<span data-regulator="' || v_regulator_name || '"></span>' ||
          '<span data-circulaire="' || NEW.circular_number || '"></span>' ||
          '<span data-page-type="' || m.type || '"></span>' ||
        '</div>',
        jsonb_build_object(
          'regulator', v_regulator_name,
          'regulator_id', NEW.regulator_id,
          'circular_number', NEW.circular_number,
          'circular_title', NEW.title,
          'circular_date', NEW.date_issued,
          'official_url', NEW.official_url,
          'page_type', m.type,
          'intent', m.intent,
          'priority', m.priority,
          'themes', NEW.keywords,
          'articles_cles', NEW.articles_cles
        ),
        COALESCE(m.priority, 0.9),
        now()
      )
      ON CONFLICT (slug) DO UPDATE SET
        title = EXCLUDED.title,
        meta_desc = EXCLUDED.meta_desc,
        h1 = EXCLUDED.h1,
        bigfour_metadata = EXCLUDED.bigfour_metadata,
        updated_at = now(),
        last_updated = now();
    END LOOP;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."generate_pages_from_circular"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_regulatory_report_ca"("report_month" "text" DEFAULT "to_char"("now"(), 'MM'::"text"), "report_year" "text" DEFAULT "to_char"("now"(), 'YYYY'::"text")) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  result jsonb;
  global_score int;
  register_count int;
  open_actions int;
  critical_count int;
  evidence_count int;
  validated_evidence int;
  pending_evidence int;
  pending_alerts int;
BEGIN
  SELECT COUNT(*) INTO register_count FROM regulatory_register;
  SELECT COUNT(*) INTO open_actions FROM remediation_logs WHERE statut = 'en_attente';
  SELECT COUNT(*) INTO critical_count FROM remediation_logs WHERE statut = 'en_attente' AND type_correction = 'remplacement';
  SELECT COUNT(*) INTO evidence_count FROM evidence_library;
  SELECT COUNT(*) INTO validated_evidence FROM evidence_library WHERE statut = 'valide';
  SELECT COUNT(*) INTO pending_evidence FROM evidence_library WHERE statut = 'en_attente';
  SELECT COUNT(*) INTO pending_alerts FROM regulatory_intelligence_feed WHERE traite = false;
  SELECT COALESCE(ROUND(AVG(score_conformite)), 0) INTO global_score FROM regulatory_register;

  result := jsonb_build_object(
    'period', report_month || '/' || report_year,
    'generated_at', now(),
    'titre', 'Rapport Mensuel CA — Conformite Reglementaire ' || report_month || '/' || report_year,
    'executive_summary', jsonb_build_object(
      'score_global_conformite', global_score,
      'total_textes_references', register_count,
      'actions_ouvertes', open_actions,
      'actions_critiques', critical_count,
      'preuves_collectees', evidence_count,
      'preuves_validees', validated_evidence,
      'preuves_en_attente', pending_evidence,
      'alertes_non_traitees', pending_alerts,
      'recommandation', CASE 
        WHEN global_score >= 90 THEN 'Conformite globale satisfaisante. Maintenir la veille active.'
        WHEN global_score >= 75 THEN 'Conformite acceptable. Prioriser les actions critiques et renforcer la preuve.'
        ELSE 'Conformite insuffisante. Mobilisation immediate du War Room requise.'
      END
    ),
    'scores_par_domaine', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'domaine', domaine,
        'score_moyen', ROUND(AVG(score_conformite)),
        'total_textes', COUNT(*),
        'conformes', COUNT(*) FILTER (WHERE statut_conformite = 'conforme'),
        'partiels', COUNT(*) FILTER (WHERE statut_conformite = 'partiel'),
        'non_conformes', COUNT(*) FILTER (WHERE statut_conformite NOT IN ('conforme', 'partiel')),
        'gaps_critiques', COUNT(*) FILTER (WHERE niveau_risque = 'critique')
      ) ORDER BY domaine)
      FROM regulatory_register
      GROUP BY domaine
    ), '[]'::jsonb),
    'actions_critiques_ouvertes', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', id,
        'reference', reference_id,
        'type', type_correction,
        'ancien_texte', LEFT(ancien_texte, 120),
        'nouveau_texte', LEFT(nouveau_texte, 120),
        'fichier', fichier_source,
        'date', date_correction,
        'statut', statut
      ) ORDER BY date_correction DESC)
      FROM remediation_logs
      WHERE statut = 'en_attente'
      LIMIT 20
    ), '[]'::jsonb),
    'preuves_audit', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', id,
        'type', type,
        'titre', titre,
        'reference', reference_id,
        'statut', COALESCE(statut, 'en_attente'),
        'horodatage', horodatage,
        'responsable', responsable
      ) ORDER BY horodatage DESC)
      FROM evidence_library
      LIMIT 20
    ), '[]'::jsonb),
    'alertes_veille', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', id,
        'source', source,
        'autorite', autorite,
        'titre', titre,
        'severite', severite,
        'date_detection', date_detection
      ) ORDER BY date_detection DESC)
      FROM regulatory_intelligence_feed
      WHERE traite = false
      LIMIT 10
    ), '[]'::jsonb)
  );

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."generate_regulatory_report_ca"("report_month" "text", "report_year" "text") OWNER TO "postgres";


