CREATE OR REPLACE FUNCTION "public"."get_public_tables"() RETURNS TABLE("tablename" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY 
  SELECT t.tablename::text 
  FROM pg_tables t 
  WHERE t.schemaname = 'public' 
    AND t.tablename NOT LIKE 'pg_%' 
    AND t.tablename NOT LIKE 'sql_%'
  ORDER BY t.tablename;
END;
$$;


ALTER FUNCTION "public"."get_public_tables"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_rag_document_stats"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  total bigint;
  enriched bigint;
  result json;
BEGIN
  SELECT COUNT(*) INTO total FROM rag_documents;
  SELECT COUNT(*) INTO enriched FROM rag_documents WHERE source_url IS NOT NULL AND source_url != '';
  
  SELECT json_build_object(
    'total_documents', total,
    'enriched_from_sources', enriched,
    'manually_entered', total - enriched,
    'sources', COALESCE((
      SELECT json_object_agg(source, cnt)
      FROM (
        SELECT source, COUNT(*) as cnt
        FROM rag_documents
        WHERE source IS NOT NULL AND source != ''
        GROUP BY source
        ORDER BY cnt DESC
      ) s
    ), '{}'),
    'domaines', COALESCE((
      SELECT json_object_agg(domaine, cnt)
      FROM (
        SELECT domaine, COUNT(*) as cnt
        FROM rag_documents
        WHERE domaine IS NOT NULL AND domaine != ''
        GROUP BY domaine
        ORDER BY cnt DESC
      ) d
    ), '{}')
  ) INTO result;
  
  RETURN result;
END;
$$;


ALTER FUNCTION "public"."get_rag_document_stats"() OWNER TO "postgres";


