CREATE OR REPLACE FUNCTION "public"."hybrid_search_khepra"("query_embedding" "public"."vector", "query_text" "text", "match_count" integer) RETURNS TABLE("id" "uuid", "title" "text", "content" "text", "url" "text", "regulator" "text", "sha256" "text", "score" double precision)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  WITH vector_search AS (
    SELECT 
      kb_docs.id, 
      kb_docs.title, 
      kb_docs.content, 
      kb_docs.url, 
      COALESCE(kb_docs.bigfour_metadata->>'regulator', kb_docs.type) as regulator,
      kb_docs.content_hash as sha256,
      1 - (kb_docs.embedding <=> query_embedding) as v_score
    FROM kb_docs 
    WHERE COALESCE(kb_docs.bigfour_metadata->>'regulator', kb_docs.type) 
      IN ('BCEAO','COBAC','OHADA','GAFI','UEMOA','CIMA','BEAC')
    ORDER BY kb_docs.embedding <=> query_embedding 
    LIMIT match_count * 2
  ),
  bm25_search AS (
    SELECT 
      kb_docs.id, 
      kb_docs.title, 
      kb_docs.content, 
      kb_docs.url, 
      COALESCE(kb_docs.bigfour_metadata->>'regulator', kb_docs.type) as regulator,
      kb_docs.content_hash as sha256,
      ts_rank(to_tsvector('french', kb_docs.content), plainto_tsquery('french', query_text)) as t_score
    FROM kb_docs 
    WHERE to_tsvector('french', kb_docs.content) @@ plainto_tsquery('french', query_text)
    LIMIT match_count * 2
  ),
  rrf AS (
    SELECT 
      id, title, content, url, regulator, sha256,
      COALESCE(1.0/(60 + row_number() OVER (ORDER BY v_score DESC)), 0) +
      COALESCE(1.0/(60 + row_number() OVER (ORDER BY t_score DESC)), 0) as score
    FROM vector_search 
    UNION ALL
    SELECT 
      id, title, content, url, regulator, sha256,
      COALESCE(1.0/(60 + row_number() OVER (ORDER BY v_score DESC)), 0) +
      COALESCE(1.0/(60 + row_number() OVER (ORDER BY t_score DESC)), 0) as score
    FROM bm25_search
  )
  SELECT DISTINCT ON (id) id, title, content, url, regulator, sha256, score 
  FROM rrf 
  ORDER BY id, score DESC 
  LIMIT match_count;
END;
$$;


ALTER FUNCTION "public"."hybrid_search_khepra"("query_embedding" "public"."vector", "query_text" "text", "match_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."hybrid_search_khepra"("query_embedding" "public"."vector", "query_text" "text", "lang_filter" "text" DEFAULT 'fr'::"text", "match_count" integer DEFAULT 5) RETURNS TABLE("id" bigint, "title" "text", "content" "text", "url" "text", "regulator" "text", "lang" "text", "sha256" "text", "score" double precision)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  WITH
  vector_search AS (
    SELECT k.id, k.title, k.content, k.url, k.regulator, k.lang, k.sha256,
           1 - (k.embedding <=> query_embedding) as v_score
    FROM kb_docs k
    WHERE k.lang = lang_filter
      AND k.regulator IN ('BCEAO','COBAC','OHADA','GAFI','CEMAC','UEMOA')
    ORDER BY k.embedding <=> query_embedding LIMIT match_count * 3
  ),
  bm25_search AS (
    SELECT k.id, k.title, k.content, k.url, k.regulator, k.lang, k.sha256,
           ts_rank(to_tsvector('french', k.content), plainto_tsquery('french', query_text)) as t_score
    FROM kb_docs k
    WHERE k.lang = lang_filter
      AND to_tsvector('french', k.content) @@ plainto_tsquery('french', query_text)
    LIMIT match_count * 3
  ),
  rrf AS (
    SELECT v.*,
           COALESCE(1.0/(60 + row_number() OVER (ORDER BY v.v_score DESC)), 0) +
           COALESCE(1.0/(60 + row_number() OVER (ORDER BY b.t_score DESC)), 0) as rrf_score
    FROM vector_search v
    FULL OUTER JOIN bm25_search b USING (id)
  )
  SELECT r.id, r.title, r.content, r.url, r.regulator, r.lang, r.sha256, r.rrf_score as score
  FROM rrf r ORDER BY r.rrf_score DESC LIMIT match_count;
END; $$;


ALTER FUNCTION "public"."hybrid_search_khepra"("query_embedding" "public"."vector", "query_text" "text", "lang_filter" "text", "match_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."hybrid_search_khepra_auto"("query_embedding" "public"."vector", "query_text" "text", "lang_filter" "text" DEFAULT 'fr'::"text", "match_count" integer DEFAULT 5) RETURNS TABLE("id" "uuid", "title" "text", "content" "text", "url" "text", "regulator" "text", "lang" "text", "sha256" "text", "score" double precision)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  WITH vector_search AS (
    SELECT k.id, k.title, k.content, k.url, k.regulator, k.lang, k.sha256,
           1 - (k.embedding_bge <=> query_embedding) as v_score
    FROM kb_docs k
    WHERE k.lang = lang_filter AND k.embedding_bge IS NOT NULL
    ORDER BY k.embedding_bge <=> query_embedding LIMIT match_count * 3
  ),
  bm25_search AS (
    SELECT k.id, k.title, k.content, k.url, k.regulator, k.lang, k.sha256,
           ts_rank(k.search_vector, plainto_tsquery('french', query_text)) as t_score
    FROM kb_docs k
    WHERE k.search_vector @@ plainto_tsquery('french', query_text)
      AND k.lang = lang_filter
    LIMIT match_count * 3
  ),
  rrf AS (
    SELECT COALESCE(v.id, b.id) as id,
           COALESCE(v.title, b.title) as title,
           COALESCE(v.content, b.content) as content,
           COALESCE(v.url, b.url) as url,
           COALESCE(v.regulator, b.regulator) as regulator,
           COALESCE(v.lang, b.lang) as lang,
           COALESCE(v.sha256, b.sha256) as sha256,
           COALESCE(1.0/(60 + row_number() OVER (ORDER BY v.v_score DESC)), 0) +
           COALESCE(1.0/(60 + row_number() OVER (ORDER BY b.t_score DESC)), 0) as rrf_score
    FROM vector_search v FULL OUTER JOIN bm25_search b USING (id)
  )
  SELECT r.id, r.title, r.content, r.url, r.regulator, r.lang, r.sha256, r.rrf_score as score
  FROM rrf r ORDER BY r.rrf_score DESC LIMIT match_count;
END;
$$;


