CREATE OR REPLACE FUNCTION "public"."kg_reasoning_engine"("p_query" "text", "p_context" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
  query_emb vector(1024);
  v_entities jsonb;
  v_relations jsonb;
  v_deduction jsonb;
BEGIN
  query_emb := kos_generate_embedding_internal_v4(p_query, p_context);
  
  SELECT jsonb_agg(jsonb_build_object(
    'id', id, 'type', type, 'name', name, 'code', code, 'regulator', regulator,
    'score', 1 - (embedding <=> query_emb)
  ) ORDER BY embedding <=> query_emb)
  INTO v_entities
  FROM kg_entities
  WHERE embedding <=> query_emb < 0.4
  LIMIT 20;
  
  SELECT jsonb_agg(jsonb_build_object(
    'from', fe.name, 'from_type', fe.type,
    'relation', r.relation_type,
    'to', te.name, 'to_type', te.type,
    'weight', r.weight, 'confidence', r.confidence
  ))
  INTO v_relations
  FROM kg_relations r
  JOIN kg_entities fe ON fe.id = r.from_entity_id
  JOIN kg_entities te ON te.id = r.to_entity_id
  WHERE fe.id IN (SELECT (x->>'id')::uuid FROM jsonb_array_elements(v_entities) x)
     OR te.id IN (SELECT (x->>'id')::uuid FROM jsonb_array_elements(v_entities) x);
  
  v_deduction := jsonb_build_object(
    'entities_found', jsonb_array_length(v_entities),
    'relations_found', jsonb_array_length(v_relations),
    'reasoning_type', CASE 
      WHEN p_query ~* 'comparer|différence' THEN 'comparative'
      WHEN p_query ~* 'risque|sanction' THEN 'risk_analysis'
      WHEN p_query ~* 'obligation|doit' THEN 'compliance_check'
      ELSE 'deductive'
    END,
    'inference', 'Basé sur ' || jsonb_array_length(v_relations) || ' relations du Knowledge Graph',
    'big_four_output', 'Conclusion: ' || COALESCE(
      (SELECT fe.name || ' ' || r.relation_type || ' ' || te.name 
       FROM kg_relations r JOIN kg_entities fe ON fe.id = r.from_entity_id 
       JOIN kg_entities te ON te.id = r.to_entity_id 
       WHERE r.weight > 0.8 ORDER BY r.confidence DESC LIMIT 1),
      'Aucune relation forte détectée'
    )
  );
  
  RETURN jsonb_build_object(
    'entities', v_entities,
    'relations', v_relations,
    'reasoning', v_deduction,
    'external_api_calls', 0
  );
END;
$$;


ALTER FUNCTION "public"."kg_reasoning_engine"("p_query" "text", "p_context" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_agent_reasoning"("p_query" "text", "p_context" "jsonb" DEFAULT NULL::"jsonb", "p_max_iterations" integer DEFAULT 3) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
v_iteration int := 0;
v_search_results jsonb;
v_reasoning text := '';
v_final_answer text;
v_tools_used text[] := ARRAY[]::text[];
v_start timestamptz := clock_timestamp();
v_context jsonb;
BEGIN
v_context := p_context;
IF v_context IS NULL THEN v_context := jsonb_build_object(); END IF;

v_search_results := (SELECT jsonb_agg(row_to_json(s)) FROM (
SELECT title, regulator, score_total, content_snippet, big_four_summary
FROM kos_search_bigfour_v4(p_query, 5)
) s);
v_tools_used := array_append(v_tools_used, 'kos_search_bigfour_v4');

v_reasoning := 'Analyse requête: ' || p_query || E'\n';
v_reasoning := v_reasoning || 'Documents trouvés: ' || jsonb_array_length(v_search_results) || E'\n';

IF jsonb_array_length(v_search_results) > 0 THEN
v_reasoning := v_reasoning || 'Top régulateur: ' || (v_search_results->0->>'regulator') || E'\n';
v_reasoning := v_reasoning || 'Score max: ' || round((v_search_results->0->>'score_total')::numeric, 3) || E'\n';
v_final_answer := 'Selon ' || (v_search_results->0->>'regulator') || ', ' ||
(v_search_results->0->>'big_four_summary') || '. Sources: ' ||
(SELECT string_agg(value->>'title', '; ') FROM jsonb_array_elements(v_search_results) LIMIT 3);
ELSE
v_final_answer := 'Aucune source réglementaire trouvée dans la base KOS pour cette requête.';
END IF;

IF v_context ? 'history' THEN
v_reasoning := v_reasoning || 'Contexte conversationnel détecté.';
END IF;

RETURN jsonb_build_object(
'answer', v_final_answer,
'reasoning_trace', v_reasoning,
'sources', v_search_results,
'tools_used', v_tools_used,
'iterations', v_iteration + 1,
'latency_ms', extract(epoch from clock_timestamp() - v_start) * 1000,
'engine', 'kos-agent-internal-v1',
'external_api_calls', 0,
'trademark', 'KOS REGTECH AI'
);
END;
$$;


ALTER FUNCTION "public"."kos_agent_reasoning"("p_query" "text", "p_context" "jsonb", "p_max_iterations" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_audit_log"("p_event_type" "text", "p_actor_id" "uuid", "p_actor_type" "text", "p_resource" "text", "p_action" "text", "p_old" "jsonb" DEFAULT NULL::"jsonb", "p_new" "jsonb" DEFAULT NULL::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_prev_hash text;
  v_block_hash text;
  v_signature text;
  v_id uuid;
  v_payload text;
  v_secret text;
BEGIN
  SELECT block_hash INTO v_prev_hash FROM public.kos_audit_chain ORDER BY id DESC LIMIT 1;

  v_payload := p_event_type || p_actor_id::text || p_resource || p_action || coalesce(p_new::text, '') || now()::text;
  v_block_hash := encode(digest(coalesce(v_prev_hash, '') || v_payload, 'sha256'), 'hex');

  v_secret := coalesce(current_setting('app.settings.audit_secret', true), 'kos-bigfour-audit-chain-secret-v1');
  v_signature := encode(hmac(v_block_hash, v_secret, 'sha256'), 'hex');

  INSERT INTO public.kos_audit_chain (
    block_hash, previous_hash, event_type, actor_id, actor_type,
    resource, action, old_value, new_value, signature
  ) VALUES (
    v_block_hash, v_prev_hash, p_event_type, p_actor_id, p_actor_type,
    p_resource, p_action, p_old, p_new, v_signature
  ) RETURNING id INTO v_id;

  RETURN v_id;
END; $$;


ALTER FUNCTION "public"."kos_audit_log"("p_event_type" "text", "p_actor_id" "uuid", "p_actor_type" "text", "p_resource" "text", "p_action" "text", "p_old" "jsonb", "p_new" "jsonb") OWNER TO "postgres";


