CREATE OR REPLACE FUNCTION "public"."kos_auto_capitalize_from_audit"() RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_count int := 0;
  v_query text;
BEGIN
  FOR v_query IN
    SELECT query FROM kos_audit_trail
    WHERE created_at > now() - interval '7 days'
    GROUP BY query HAVING COUNT(*) >= 5
  LOOP
    INSERT INTO kb_docs (title, content, type, regulator)
    SELECT 
      'FAQ: ' || left(v_query, 100),
      'Réponse générée automatiquement basée sur ' || COUNT(*) || ' requêtes similaires.',
      'faq',
      'KOS-AUTO'
    FROM kos_audit_trail WHERE query = v_query
    ON CONFLICT DO NOTHING;
    
    v_count := v_count + 1;
  END LOOP;
  
  INSERT INTO kg_entities (type, name, regulator, metadata)
  SELECT DISTINCT 
    'obligation',
    regexp_replace(upper(left(content, 50)), '[^A-Z0-9 ]', '', 'g'),
    COALESCE(regulator, 'AUTO'),
    jsonb_build_object('source', 'auto_capitalize', 'doc_id', id)
  FROM kb_docs 
  WHERE type = 'directive' AND created_at > now() - interval '7 days'
  ON CONFLICT DO NOTHING;
  
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."kos_auto_capitalize_from_audit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_auto_create_tickets_from_latest_crawl"() RETURNS TABLE("action" "text", "detail" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  latest_run_id text;
  broken_record record;
  existing_count int;
  last_ticket_id text;
  next_seq int := 1;
  today_str text;
  new_ticket_id text;
  ticket_priority text;
  tickets_created int := 0;
  tickets_updated int := 0;
BEGIN
  -- Get latest check run
  SELECT check_run_id INTO latest_run_id
  FROM url_check_results
  ORDER BY checked_at DESC
  LIMIT 1;

  IF latest_run_id IS NULL THEN
    RETURN QUERY SELECT 'info'::text, 'Aucun crawl trouve'::text;
    RETURN;
  END IF;

  -- Get last ticket sequence
  SELECT ticket_id INTO last_ticket_id
  FROM kos_auto_correction_tickets
  ORDER BY id DESC
  LIMIT 1;

  IF last_ticket_id IS NOT NULL THEN
    BEGIN
      next_seq := split_part(last_ticket_id, '-', 3)::int + 1;
    EXCEPTION WHEN OTHERS THEN
      next_seq := 1;
    END;
  END IF;

  today_str := to_char(NOW(), 'YYYYMMDD');

  -- Loop through broken results
  FOR broken_record IN
    SELECT DISTINCT ON (target_url) target_url, source_url, status_code, error_message, check_type, check_run_id
    FROM url_check_results
    WHERE check_run_id = latest_run_id AND is_broken = true
    ORDER BY target_url, checked_at DESC
  LOOP
    -- Check if ticket already exists
    SELECT COUNT(*) INTO existing_count
    FROM kos_auto_correction_tickets
    WHERE target_url = broken_record.target_url AND status IN ('open', 'in_progress');

    IF existing_count > 0 THEN
      -- Update existing
      UPDATE kos_auto_correction_tickets
      SET occurrence_count = occurrence_count + 1,
          last_seen_at = NOW()
      WHERE target_url = broken_record.target_url AND status IN ('open', 'in_progress');
      tickets_updated := tickets_updated + 1;
    ELSE
      -- Determine priority
      IF broken_record.status_code = 404 OR broken_record.status_code = 410 THEN
        ticket_priority := 'critical';
      ELSIF broken_record.status_code IS NULL OR broken_record.status_code >= 500 THEN
        ticket_priority := 'high';
      ELSE
        ticket_priority := 'medium';
      END IF;

      -- Create ticket
      new_ticket_id := 'TKT-' || today_str || '-' || LPAD(next_seq::text, 4, '0');
      next_seq := next_seq + 1;

      INSERT INTO kos_auto_correction_tickets (
        ticket_id, target_url, source_url, status_code, error_message,
        check_type, check_run_id, status, priority, occurrence_count,
        auto_fix_attempted, auto_fix_success, first_seen_at, last_seen_at
      ) VALUES (
        new_ticket_id, broken_record.target_url, broken_record.source_url,
        broken_record.status_code, broken_record.error_message,
        broken_record.check_type, broken_record.check_run_id,
        'open', ticket_priority, 1, false, false, NOW(), NOW()
      );

      tickets_created := tickets_created + 1;

      -- Create critical event for high-priority tickets
      IF ticket_priority IN ('critical', 'high') THEN
        INSERT INTO kos_critical_events (hub_id, hub_name, event_type, title, message, metric_name, current_value, threshold_value, acknowledged)
        VALUES (
          49, 'URL Auto-Pointage',
          CASE WHEN ticket_priority = 'critical' THEN 'critical' ELSE 'warning' END,
          'Ticket ' || new_ticket_id || ': ' || LEFT(broken_record.target_url, 55),
          COALESCE(broken_record.error_message, 'Erreur de connexion') || ' — ' || COALESCE('Source: ' || broken_record.source_url, 'Detection crawl direct'),
          broken_record.target_url,
          COALESCE(broken_record.status_code, 0),
          400,
          false
        );
      END IF;
    END IF;
  END LOOP;

  RETURN QUERY
    SELECT 'created'::text, tickets_created::text || ' tickets crees'
    WHERE tickets_created > 0
    UNION ALL
    SELECT 'updated'::text, tickets_updated::text || ' tickets mis a jour'
    WHERE tickets_updated > 0
    UNION ALL
    SELECT 'done'::text, 'Synchronisation terminee'
    WHERE tickets_created = 0 AND tickets_updated = 0;
END;
$$;


ALTER FUNCTION "public"."kos_auto_create_tickets_from_latest_crawl"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_auto_dev"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.human_score < 80 AND NEW.human_score IS NOT NULL THEN
    UPDATE public.kos_agents
    SET auto_dev_enabled = TRUE,
        last_trained = NOW()
    WHERE id = NEW.agent_id;

    INSERT INTO public.security_log(event, details, ts)
    VALUES (
      'KOS_LOW_SCORE',
      jsonb_build_object(
        'agent_id', NEW.agent_id,
        'agent_name', (SELECT name FROM public.kos_agents WHERE id = NEW.agent_id),
        'score', NEW.human_score,
        'question_snippet', LEFT(NEW.question, 80),
        'auto_dev_triggered', TRUE
      ),
      NOW()
    );
  END IF;
  RETURN NEW;
END;
$$;


