CREATE OR REPLACE FUNCTION "public"."kos_automaton_trigger_process_scan"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Only process bloc_scan_completed events
  IF NEW.event_type = 'bloc_total_compliance' AND NEW.action = 'bloc_scan_completed' THEN
    -- Log the auto-processing trigger
    INSERT INTO kos_correction_loop_log (phase, status, details, duration)
    VALUES (
      'kos_automaton_v3',
      'trigger_auto_process_started',
      json_build_object(
        'correlation_id', NEW.correlation_id,
        'entity_id', NEW.entity_id,
        'state', NEW.new_state
      )::text,
      'trigger'
    );
  END IF;
  RETURN NEW;
END;
$$;


