CREATE OR REPLACE FUNCTION "public"."kos_autonomous_cycle"() RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_task record;
BEGIN
  FOR v_task IN 
    SELECT * FROM kos_autonomous_tasks 
    WHERE task_type = 'observe' AND status = 'pending' 
    LIMIT 10
  LOOP
    UPDATE kos_autonomous_tasks SET status = 'running', started_at = now() WHERE id = v_task.id;
    UPDATE kos_autonomous_tasks SET status = 'completed', completed_at = now() WHERE id = v_task.id;
  END LOOP;
  
  INSERT INTO kos_autonomous_tasks (task_type, input)
  SELECT 'learn', jsonb_build_object('doc_id', id)
  FROM kb_docs WHERE embedding_bge IS NULL AND created_at > now() - interval '1 hour';
  
  INSERT INTO kos_autonomous_tasks (task_type, input)
  SELECT 'capitalize', jsonb_build_object('query_pattern', query)
  FROM kos_audit_trail
  WHERE created_at > now() - interval '1 day'
  GROUP BY query HAVING COUNT(*) > 5;
  
  INSERT INTO kos_autonomous_tasks (task_type, input)
  VALUES ('evaluate', jsonb_build_object('check', 'coverage', 'target', 0.95));
END;
$$;


ALTER FUNCTION "public"."kos_autonomous_cycle"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_backfill_kb_from_tables"() RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_table record;
  v_text_cols text[];
  v_title_col text;
  v_col_exprs text;
  v_sql text;
  v_row_count int;
  v_inserted int := 0;
  v_skipped int := 0;
  v_errors int := 0;
  v_start timestamptz := clock_timestamp();
BEGIN
  FOR v_table IN
    SELECT schemaname, tablename
    FROM pg_tables
    WHERE schemaname = 'public'
      AND tablename NOT IN ('kos_knowledge_base', 'kos_search_logs', 'spatial_ref_sys')
      AND tablename NOT LIKE 'pg_%'
      AND tablename NOT LIKE '_prisma_%'
      AND tablename NOT LIKE 'supabase_%'
      AND tablename NOT LIKE 'v_%'
    ORDER BY tablename
  LOOP
    BEGIN
      SELECT array_agg(column_name) INTO v_text_cols
      FROM information_schema.columns
      WHERE table_schema = v_table.schemaname AND table_name = v_table.tablename
        AND data_type IN ('text', 'varchar', 'character varying', 'jsonb');

      IF v_text_cols IS NULL OR array_length(v_text_cols, 1) = 0 THEN
        v_skipped := v_skipped + 1;
        CONTINUE;
      END IF;

      SELECT column_name INTO v_title_col
      FROM information_schema.columns
      WHERE table_schema = v_table.schemaname AND table_name = v_table.tablename
        AND column_name IN ('title', 'name', 'label', 'subject', 'nom', 'titre', 'full_name')
      LIMIT 1;

      SELECT string_agg(format('COALESCE(%I::text, '''')', col), ' || '' '' || ') INTO v_col_exprs
      FROM unnest(v_text_cols) col;

      v_sql := format(
        'INSERT INTO public.kos_knowledge_base (source_type, source_url, title, content, metadata, scraped_at)
         SELECT ''internal_doc'',
                ''backfill://%I/%I'',
                MAX(%s::text),
                string_agg(%s, '' ''),
                jsonb_build_object(''source_table'', %L, ''source_schema'', %L, ''backfilled_at'', now()::text, ''row_count'', count(*)),
                now()
         FROM %I.%I
         WHERE %s IS NOT NULL
         HAVING length(string_agg(%s, '' '')) > 20',
        v_table.schemaname, v_table.tablename,
        COALESCE(v_title_col, '''' || v_table.tablename || ''''),
        v_col_exprs,
        v_table.tablename, v_table.schemaname,
        v_table.schemaname, v_table.tablename,
        v_text_cols[1],
        v_col_exprs
      );

      EXECUTE v_sql;
      GET DIAGNOSTICS v_row_count = ROW_COUNT;
      v_inserted := v_inserted + v_row_count;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'tables_total', (SELECT count(*) FROM pg_tables WHERE schemaname = 'public' AND tablename NOT LIKE 'pg_%' AND tablename NOT LIKE '_prisma_%' AND tablename NOT LIKE 'supabase_%' AND tablename NOT LIKE 'v_%' AND tablename NOT IN ('kos_knowledge_base', 'kos_search_logs', 'spatial_ref_sys')),
    'docs_inserted', v_inserted,
    'docs_skipped', v_skipped,
    'errors', v_errors,
    'duration_seconds', round(extract(epoch from clock_timestamp() - v_start)::numeric, 2),
    'status', 'completed'
  );
END; $$;


ALTER FUNCTION "public"."kos_backfill_kb_from_tables"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_backfill_tp_text"("p_authority" "text", "p_reference" "text", "p_title" "text", "p_date" "date", "p_url" "text", "p_content" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_id uuid;
BEGIN
  INSERT INTO public.kos_regulatory_corpus (
    authority, reference, title, date_publication,
    url_source, content, content_tsv, status, source_type
  ) VALUES (
    p_authority, p_reference, p_title, p_date,
    p_url, p_content,
    to_tsvector('french', p_content),
    'EN_VIGUEUR', 'REGULATORY_CORPUS'
