CREATE OR REPLACE FUNCTION "public"."kos_champion_tick"("p_timezone" "text" DEFAULT 'Africa/Lome'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_config JSONB;
  v_routing JSONB;
  v_metrics JSONB;
  v_results JSONB := jsonb_build_array();
  v_champion TEXT;
  v_champion_result JSONB;
  v_case TEXT;
  v_success_count INTEGER := 0;
  v_total_count INTEGER := 0;
  v_tick_id TEXT;
  v_start_ts TIMESTAMPTZ := now();
  v_entry RECORD;
BEGIN
  v_tick_id := 'TICK-' || to_char(now(), 'YYYYMMDD-HH24MISS-') || '-' || floor(random()*10000)::text;

  -- Load champion config
  SELECT new_state INTO v_config
  FROM kos_universal_audit_log
  WHERE event_type = 'kos_champion_config'
    AND action = 'champion_config_snapshot'
  ORDER BY created_at DESC
  LIMIT 1;

  v_routing := COALESCE(v_config->'kos_routing', jsonb_build_array());
  v_metrics := COALESCE(v_config->'kos_metrics', jsonb_build_object('runs', 0, 'success_rate', 0, 'cost_tokens', 0, 'champions_used', jsonb_build_object()));

  -- Execute each champion case
  FOR v_entry IN 
    SELECT r->>'case' AS case_name, r->>'champion' AS champ_name
    FROM jsonb_array_elements(v_routing) AS r
    WHERE r->>'case' IS NOT NULL
  LOOP
    v_case := v_entry.case_name;
    v_champion := v_entry.champ_name;
    v_total_count := v_total_count + 1;

    BEGIN
      -- Execute champion (without payload for tick - just health check routing)
      SELECT kos_execute_champion(v_case, jsonb_build_object('tick_id', v_tick_id, 'mode', 'tick_health_check'))
      INTO v_champion_result;

      IF (v_champion_result->>'success')::boolean THEN
        v_success_count := v_success_count + 1;
      END IF;

      v_results := v_results || jsonb_build_object(
        'case', v_case,
        'champion', v_champion,
        'success', (v_champion_result->>'success')::boolean,
        'duration_ms', (v_champion_result->>'duration_ms')::int,
        'engine', v_champion_result->>'engine'
      );

    EXCEPTION WHEN OTHERS THEN
      v_results := v_results || jsonb_build_object(
        'case', v_case,
        'champion', v_champion,
        'success', false,
        'error', SQLERRM
      );
    END;
  END LOOP;

  -- Update config metrics
  v_metrics := v_metrics || jsonb_build_object(
    'runs', COALESCE((v_metrics->>'runs')::int, 0) + 1,
    'success_rate', CASE WHEN v_total_count > 0 THEN round((v_success_count::numeric / v_total_count) * 100, 1) ELSE 0 END,
    'last_tick', to_char(now(), 'YYYY-MM-DD HH24:MI:SS TZ'),
    'champions_active', v_total_count,
    'champions_ok', v_success_count
  );

  -- Persist updated metrics
  UPDATE kos_universal_audit_log
  SET new_state = v_config || jsonb_build_object('kos_metrics', v_metrics)
  WHERE event_type = 'kos_champion_config'
    AND action = 'champion_config_snapshot'
    AND id = (
      SELECT id FROM kos_universal_audit_log
      WHERE event_type = 'kos_champion_config'
        AND action = 'champion_config_snapshot'
      ORDER BY created_at DESC LIMIT 1
    );

  -- Log tick to audit trail
  INSERT INTO kos_universal_audit_log (
    event_type, entity_type, entity_id, action, actor, new_state, impact, correlation_id
  ) VALUES (
    'kos_champion_tick', 'champion_engine', v_tick_id,
    'champion_tick_executed', 'kos_champion_engine',
    jsonb_build_object(
      'tick_id', v_tick_id,
      'champions_tested', v_total_count,
      'champions_ok', v_success_count,
      'results', v_results,
      'engine', 'CHAMPION ENGINE v2026.07'
    ),
    jsonb_build_object(
      'total', v_total_count,
      'success', v_success_count,
      'success_rate', CASE WHEN v_total_count > 0 THEN round((v_success_count::numeric / v_total_count) * 100, 1) ELSE 0 END
    ),
    v_tick_id
  );

  RETURN jsonb_build_object(
    'success', true,
    'tick_id', v_tick_id,
    'champions_tested', v_total_count,
    'champions_ok', v_success_count,
    'success_rate', CASE WHEN v_total_count > 0 THEN round((v_success_count::numeric / v_total_count) * 100, 1) ELSE 0 END,
    'results', v_results,
    'engine', 'CHAMPION ENGINE v2026.07',
    'format', 'KPMG Big Four',
    'executed_at', to_char(now(), 'YYYY-MM-DD HH24:MI:SS TZ'),
    'duration_ms', EXTRACT(MILLISECONDS FROM (now() - v_start_ts))::INTEGER
  );
END;
$$;


ALTER FUNCTION "public"."kos_champion_tick"("p_timezone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_check_routing_sla"() RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE 
  kpi RECORD;
  webhook_url text := 'https://hooks.slack.com/services/T000/B000/XXXX';
BEGIN
  SELECT * INTO kpi FROM kos_routing_kpis_24h;
  
  -- Alerte 1 : Failover > 10
  IF kpi.failover_count > 10 THEN
    INSERT INTO kos_routing_alerts(alert_type, metric_value, threshold) 
    VALUES ('failover_spike', kpi.failover_count, 10);
    PERFORM net.http_post(url:=webhook_url, body:=jsonb_build_object(
      'text', format('🚨 KOS ALERT 150%%: Failover spike %s > 10 en 24h', kpi.failover_count)
    ));
  END IF;
  
  -- Alerte 2 : Success rate < 99%
  IF kpi.primary_success_rate < 0.99 THEN
    INSERT INTO kos_routing_alerts(alert_type, metric_value, threshold) 
    VALUES ('success_rate_drop', kpi.primary_success_rate, 0.99);
    PERFORM net.http_post(url:=webhook_url, body:=jsonb_build_object(
      'text', format('🚨 KOS ALERT 150%%: Success rate %s%% < 99%%', round(kpi.primary_success_rate*100,2))
    ));
  END IF;
END;
$$;


ALTER FUNCTION "public"."kos_check_routing_sla"() OWNER TO "postgres";


