CREATE OR REPLACE FUNCTION "public"."kos_crawl_all_sources"() RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  src RECORD;
  crawled_count int := 0;
  content_fetched text;
  doc_id uuid;
  http_resp record;
BEGIN
  FOR src IN SELECT id, url, regulator, lang FROM kb_sources LOOP
    BEGIN
      http_resp := http_get(src.url);
      content_fetched := http_resp.content;
    EXCEPTION WHEN OTHERS THEN
      CONTINUE;
    END;

    INSERT INTO kb_docs(source_id, url, title, content, regulator, lang, sha256)
    VALUES (
      src.id, src.url,
      substring(content_fetched from '<title>(.*?)</title>'),
      content_fetched, src.regulator, src.lang,
      encode(digest(content_fetched, 'sha256'), 'hex')
    )
    ON CONFLICT (source_id, url) DO UPDATE SET
      content = EXCLUDED.content,
      sha256 = EXCLUDED.sha256,
      updated_at = now()
    RETURNING id INTO doc_id;

    crawled_count := crawled_count + 1;
    PERFORM pg_sleep(0.1);
  END LOOP;

  RETURN jsonb_build_object(
    'sources_crawled', crawled_count,
    'timestamp', now(),
    'embedding_engine', 'bge-m3-local',
    'api_externe', 0
  );
END;
$$;


ALTER FUNCTION "public"."kos_crawl_all_sources"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_cross_resolve_notify"("p_resolved_ticket_id" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_ticket RECORD;
  v_related RECORD;
  v_notified_count INTEGER := 0;
  v_notified_engines TEXT[];
  v_alert_id INTEGER;
  v_log_id INTEGER;
BEGIN
  -- Get the resolved ticket
  SELECT * INTO v_ticket 
  FROM kos_auto_correction_tickets 
  WHERE id = p_resolved_ticket_id;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Ticket not found');
  END IF;
  
  -- If not resolved, exit
  IF v_ticket.status NOT IN ('resolved', 'auto_fixed') THEN
    RETURN jsonb_build_object('success', false, 'message', 'Ticket not in resolved status');
  END IF;
  
  -- Find related open/in_progress tickets in OTHER engines with matching target_url
  v_notified_engines := ''::TEXT[];
  
  FOR v_related IN
    SELECT id, ticket_id, source_engine, status
    FROM kos_auto_correction_tickets
    WHERE target_url = v_ticket.target_url
      AND source_engine != v_ticket.source_engine
      AND status IN ('open', 'in_progress')
      AND id != p_resolved_ticket_id
  LOOP
    -- Create cross resolution log
    INSERT INTO kos_cross_resolution_logs (
      resolving_engine, resolved_ticket_id, resolved_target_url,
      notified_engine, notified_ticket_ids, alert_message
    ) VALUES (
      v_ticket.source_engine,
      v_ticket.ticket_id,
      v_ticket.target_url,
      v_related.source_engine,
      ARRAY[v_related.ticket_id],
      'Le ticket ' || v_ticket.ticket_id || ' (' || v_ticket.source_engine || ') concernant ' || v_ticket.target_url || ' a été résolu. Vérifiez si cela impacte votre ticket ' || v_related.ticket_id || '.'
    )
    RETURNING id INTO v_log_id;
    
    -- Create critical event for the notified engine
    INSERT INTO kos_critical_events (
      hub_id, hub_name, event_type, title, message, metric_name
    ) VALUES (
      49,
      v_related.source_engine,
      'resolved',
      'Résolution croisée — ' || v_ticket.source_engine,
      'Le ticket ' || v_ticket.ticket_id || ' concernant ' || v_ticket.target_url || ' a été résolu dans le moteur ' || v_ticket.source_engine || '. Ticket lié : ' || v_related.ticket_id,
      'cross_resolution'
    );
    
    v_notified_engines := array_append(v_notified_engines, v_related.source_engine);
    v_notified_count := v_notified_count + 1;
  END LOOP;
  
  RETURN jsonb_build_object(
    'success', true,
    'notified_count', v_notified_count,
    'notified_engines', v_notified_engines,
    'resolving_engine', v_ticket.source_engine,
    'target_url', v_ticket.target_url
  );
END;
$$;


ALTER FUNCTION "public"."kos_cross_resolve_notify"("p_resolved_ticket_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_decision_intelligence"("p_query" "text", "p_twin_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  v_search jsonb;
  v_reasoning jsonb;
  v_risks jsonb;
  v_decision jsonb;
BEGIN
  v_search := kos_search_bigfour_v6(p_query, 5, NULL, true);
  v_reasoning := kg_reasoning_engine(p_query, jsonb_build_object('twin_id', p_twin_id));
  
  v_risks := jsonb_build_array(
    jsonb_build_object('risk', 'Non-conformité', 'cost', 100000000, 'probability', 0.6, 'impact', 'critical'),
    jsonb_build_object('risk', 'Sanction BCEAO', 'cost', 50000000, 'probability', 0.3, 'impact', 'high'),
    jsonb_build_object('risk', 'Réputation', 'cost', 20000000, 'probability', 0.5, 'impact', 'medium')
  );
  
  v_decision := jsonb_build_object(
    'recommendation', 'Action immédiate requise',
    'risks', v_risks,
    'costs', jsonb_build_object('implementation', 50000000, 'inaction', 170000000),
    'roi', 2.4,
    'priorities', jsonb_build_array('P0: Audit gouvernance', 'P1: Formation LBC/FT', 'P2: Reporting'),
    'scenarios', jsonb_build_object(
      'do_nothing', jsonb_build_object('cost', 170000000, 'probability', 0.6),
      'partial', jsonb_build_object('cost', 80000000, 'probability', 0.3),
      'full_compliance', jsonb_build_object('cost', 50000000, 'probability', 0.1)
    ),
    'probabilities', jsonb_build_object('success', 0.85, 'delay', 0.10, 'failure', 0.05)
  );
  
  RETURN v_search || v_reasoning || jsonb_build_object('decision_intelligence', v_decision);
END;
$$;


ALTER FUNCTION "public"."kos_decision_intelligence"("p_query" "text", "p_twin_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_decision_intelligence_v2"("p_query" "text", "p_twin_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
