  v_risks jsonb;
  v_roi jsonb;
  v_priorities jsonb;
  v_roadmap jsonb;
BEGIN
  -- 1. Diagnostic
  v_diagnostic := jsonb_build_object(
    'current_state', 'Non-conformite partielle UEMOA 007-2024',
    'gap_analysis', jsonb_build_array('Agrement BCEAO manquant', 'Capital < 300M FCFA', 'Reporting trimestriel absent'),
    'maturity', 0.65
  );

  -- 2. Scenarios
  v_scenarios := jsonb_build_array(
