    jsonb_build_object('name', 'Partial Compliance', 'cost', 80000000, 'probability', 0.3, 'impact', 'Sanction reduite'),
    jsonb_build_object('name', 'Full Compliance', 'cost', 50000000, 'probability', 0.1, 'impact', '0 sanction')
  );

  -- 3. Options
  v_options := jsonb_build_array(
    jsonb_build_object('option', 'Audit gouvernance immediat', 'cost', 10000000, 'duration_days', 30),
    jsonb_build_object('option', 'Recapitalisation 300M', 'cost', 300000000, 'duration_days', 90),
    jsonb_build_object('option', 'Formation LBC/FT', 'cost', 5000000, 'duration_days', 15)
  );

  -- 4. Risques
  v_risks := jsonb_build_array(
    jsonb_build_object('risk', 'Sanction BCEAO', 'probability', 0.7, 'impact', 100000000, 'mitigation', 'Audit immediat'),
    jsonb_build_object('risk', 'Retrait agrement', 'probability', 0.4, 'impact', 500000000, 'mitigation', 'Recapitalisation'),
    jsonb_build_object('risk', 'Reputation', 'probability', 0.8, 'impact', 50000000, 'mitigation', 'Communication')
  );

  -- 5. ROI
  v_roi := jsonb_build_object(
    'investment', 50000000,
    'cost_avoided', 150000000,
    'roi_ratio', 3.0,
    'payback_months', 4
  );

  -- 6. Priorites
  v_priorities := jsonb_build_array(
    jsonb_build_object('priority', 'P0', 'action', 'Audit gouvernance', 'deadline', '2025-02-28'),
    jsonb_build_object('priority', 'P1', 'action', 'Recapitalisation', 'deadline', '2025-05-31'),
    jsonb_build_object('priority', 'P2', 'action', 'Formation', 'deadline', '2025-03-31')
  );

  -- 7. Roadmap
  v_roadmap := jsonb_build_object(
    'phase_1', jsonb_build_object('name', 'Urgence', 'duration', '30j', 'actions', ARRAY['Audit', 'Plan']),
    'phase_2', jsonb_build_object('name', 'Mise en conformite', 'duration', '90j', 'actions', ARRAY['Capital', 'Process']),
    'phase_3', jsonb_build_object('name', 'Optimisation', 'duration', '180j', 'actions', ARRAY['Formation', 'Monitoring'])
  );

  RETURN jsonb_build_object(
    'diagnostic', v_diagnostic,
    'scenarios', v_scenarios,
    'options', v_options,
    'risks', v_risks,
    'roi', v_roi,
    'priorities', v_priorities,
    'roadmap', v_roadmap,
    'external_api_calls', 0,
    'big_four_certified', true
  );
END;
$$;


