CREATE OR REPLACE FUNCTION "public"."kos_generate_bceao_lbc_report"("p_start" "date", "p_end" "date") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_report_id uuid;
  v_data jsonb;
BEGIN
  SELECT jsonb_build_object(
    'period', jsonb_build_object('start', p_start, 'end', p_end),
    'kyc_screenings', (SELECT count(*) FROM public.kos_kyc_screenings WHERE screened_at BETWEEN p_start AND p_end),
    'high_risk_clients', (SELECT count(*) FROM public.kos_risk_scores WHERE grade IN ('CCC', 'D') AND calculated_at BETWEEN p_start AND p_end),
    'sanctions_matches', (SELECT count(*) FROM public.kos_kyc_screenings WHERE match_status = 'CONFIRMED_MATCH' AND screened_at BETWEEN p_start AND p_end),
    'suspicious_transactions', 0
  ) INTO v_data;

  INSERT INTO public.kos_regulatory_reports (report_type, period_start, period_end, data, status)
  VALUES ('BCEAO_LBC', p_start, p_end, v_data, 'DRAFT')
  RETURNING id INTO v_report_id;

  RETURN v_report_id;
END; $$;


