CREATE OR REPLACE FUNCTION "public"."kos_generate_embedding_internal_v2"("input_text" "text", "meta" "jsonb" DEFAULT "jsonb_build_object"()) RETURNS "public"."vector"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
emb float8[];
word_hash bigint;
i int;
j int;
norm float8;
kw_bigfour jsonb := '{
"bceao": 1.0, "cobac": 1.0, "ohada": 0.95, "gafi": 0.95,
"agrément": 0.9, "sfd": 0.9, "lbc": 0.9, "ft": 0.9,
"banque": 0.8, "crédit": 0.8, "directive": 0.85, "règlement": 0.85,
"ifrs": 1.0, "ias": 0.95, "normes": 0.9, "comptable": 0.9,
"iasb": 0.95, "bilan": 0.8, "résultat": 0.8, "juste valeur": 0.95,
"provision": 0.85, "dépréciation": 0.9, "amortissement": 0.85,
"circulaire": 0.85, "obligation": 0.9, "sanction": 0.9,
"iso27001": 1.0, "iso42001": 1.0, "coso": 0.95, "bâle": 0.95
}'::jsonb;
kw text;
kw_weight float8;
regulator text;
impact_score int;
BEGIN
emb := array_fill(0.0::float8, ARRAY[1024]);
word_hash := ('x' || substr(md5(lower(coalesce(input_text, ''))), 1, 16))::bit(64)::bigint;

FOR kw, kw_weight IN SELECT * FROM jsonb_each_text(kw_bigfour) LOOP
IF position(kw IN lower(coalesce(input_text, ''))) > 0 THEN
i := abs(hashtext(kw) % 180) + 1;
emb[i] := COALESCE(emb[i], 0.0) + COALESCE(kw_weight, 0.0);
emb[i + 200] := COALESCE(emb[i + 200], 0.0) + COALESCE(kw_weight, 0.0) * 0.3;
END IF;
END LOOP;

regulator := lower(meta->>'regulator');
IF regulator IS NOT NULL THEN
i := 201 + abs(hashtext(regulator) % 50);
emb[i] := 1.0;
END IF;

impact_score := COALESCE((meta->>'impact_score')::int, 0);
IF impact_score > 0 THEN
emb[251] := COALESCE(impact_score, 0) / 100.0;
END IF;

FOR i IN 301..1024 LOOP
emb[i] := COALESCE(emb[i], 0.0) + ((word_hash >> ((i-301) % 63)) & 1)::float8 * 0.05;
END LOOP;

norm := sqrt(GREATEST((SELECT sum(val*val) FROM unnest(emb) val), 0.0001));
FOR j IN 1..1024 LOOP
emb[j] := COALESCE(emb[j] / norm, 0.0);
END LOOP;

RETURN emb::vector(1024);
END;
$$;


ALTER FUNCTION "public"."kos_generate_embedding_internal_v2"("input_text" "text", "meta" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_generate_embedding_internal_v3"("input_text" "text") RETURNS "public"."vector"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  emb float8[]; word_hash bigint; i int; j int; norm float8;
  kw text; kw_weight float8;
BEGIN
  emb := array_fill(0.0::float8, ARRAY[1024]);
  word_hash := ('x' || substr(md5(lower(coalesce(input_text, ''))), 1, 16))::bit(64)::bigint;
  FOR kw, kw_weight IN SELECT * FROM jsonb_each_text('{"bceao":1.0,"cobac":1.0,"ohada":0.95,"gafi":0.95,"uemoa":0.95,"cemac":0.95,"beac":0.9,"crepmf":0.9,"agrément":0.9,"sfd":0.9,"microfinance":0.9,"emf":0.9,"lbc":0.9,"ft":0.9,"kyc":0.85,"centif":0.85,"banque":0.8,"crédit":0.8,"directive":0.85,"règlement":0.85,"circulaire":0.85,"instruction":0.85,"décision":0.85,"loi":0.8,"obligation":0.9,"sanction":0.9,"échéance":0.85,"rapport":0.7,"audit":0.9,"risque":0.85,"conformité":0.9,"solvabilité":0.9,"prudentiel":0.9,"provision":0.85,"gouvernance":0.85,"contrôle":0.8,"surveillance":0.85,"créance":0.8,"douteuse":0.8,"recouvrement":0.8,"fonds propres":0.9,"liquidité":0.85,"capital":0.85,"blanchiment":0.9,"terrorisme":0.9,"fraude":0.85,"iso27001":1.0,"iso42001":1.0,"coso":0.95,"ifrs":0.9,"ifrs9":0.9,"normes":0.8,"inclusion":0.8,"financière":0.8,"digital":0.75,"transformation":0.75,"stratégie":0.7,"pme":0.7,"fiscalité":0.8,"prix transfert":0.85,"beps":0.85,"esg":0.8,"durabilité":0.75,"climatique":0.75,"résilience":0.8,"continuité":0.8,"pca":0.8,"protection":0.75,"données":0.75,"rgpd":0.8}'::jsonb) LOOP
    IF position(kw IN lower(coalesce(input_text, ''))) > 0 THEN
      i := abs(hashtext(kw) % 180) + 1;
      emb[i] := COALESCE(emb[i], 0.0) + COALESCE(kw_weight, 0.0);
      emb[i + 200] := COALESCE(emb[i + 200], 0.0) + COALESCE(kw_weight, 0.0) * 0.3;
    END IF;
  END LOOP;
  FOR i IN 301..1024 LOOP
    emb[i] := COALESCE(emb[i], 0.0) + ((word_hash >> ((i-301) % 63)) & 1)::float8 * 0.03;
  END LOOP;
  norm := sqrt(GREATEST((SELECT sum(val*val) FROM unnest(emb) val), 0.0001));
  FOR j IN 1..1024 LOOP emb[j] := COALESCE(emb[j] / norm, 0.0); END LOOP;
  RETURN emb::vector(1024);
END;
$$;


