CREATE OR REPLACE FUNCTION "public"."kos_generate_embedding_internal_v3"("input_text" "text", "meta" "jsonb" DEFAULT NULL::"jsonb") RETURNS "public"."vector"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
emb float8[];
word_hash bigint;
i int;
j int;
norm float8;
safe_meta jsonb;
kw_bigfour jsonb := '{"bceao":1.0,"cobac":1.0,"ohada":0.95,"gafi":0.95,"uemoa":1.0,"cemac":0.95,"beac":0.9,"agrément":0.95,"sfd":0.95,"emf":0.95,"microfinance":1.0,"imf":0.95,"inclusion":0.8,"loi":0.9,"directive":0.9,"règlement":0.9,"instruction":0.9,"décision":0.9,"circulaire":0.85,"lbc":0.9,"ft":0.9,"lcbft":0.95,"kyc":0.9,"centif":0.9,"giaba":0.9,"ifrs":1.0,"ias":0.95,"ifrs9":0.95,"ifrs16":0.9,"normes":0.9,"comptable":0.9,"syscohada":0.9,"prudentiel":0.9,"solvabilité":0.9,"liquidité":0.85,"gouvernance":0.85,"risque":0.85,"contrôle":0.8,"audit":0.9,"sanction":0.9,"obligation":0.9,"iso27001":1.0,"iso42001":1.0,"coso":0.95,"bâle":0.95,"khepra":1.0}'::jsonb;
kw text;
kw_weight float8;
regulator text;
impact_score int;
work_text text;
BEGIN
safe_meta := COALESCE(meta, jsonb_build_object());
emb := array_fill(0.0::float8, ARRAY[1024]);
word_hash := ('x' || substr(md5(lower(coalesce(input_text, ''))), 1, 16))::bit(64)::bigint;

work_text := lower(coalesce(input_text, ''));

IF position('nouvelle loi' IN work_text) > 0 THEN
work_text := work_text || ' loi directive règlement uemoa';
END IF;
IF position('microfinance' IN work_text) > 0 THEN
work_text := work_text || ' sfd emf agrément instruction';
END IF;

FOR kw, kw_weight IN SELECT * FROM jsonb_each_text(kw_bigfour) LOOP
IF position(kw IN work_text) > 0 THEN
i := abs(hashtext(kw) % 180) + 1;
emb[i] := COALESCE(emb[i], 0.0) + COALESCE(kw_weight, 0.0);
emb[i + 200] := COALESCE(emb[i + 200], 0.0) + COALESCE(kw_weight, 0.0) * 0.4;
END IF;
END LOOP;

regulator := lower(safe_meta->>'regulator');
IF regulator IS NOT NULL THEN
i := 201 + abs(hashtext(regulator) % 50);
emb[i] := 1.0;
END IF;

impact_score := COALESCE((safe_meta->>'impact_score')::int, 0);
IF impact_score > 0 THEN
emb[251] := COALESCE(impact_score, 0) / 100.0;
END IF;

FOR i IN 301..1024 LOOP
emb[i] := COALESCE(emb[i], 0.0) + ((word_hash >> ((i-301) % 63)) & 1)::float8 * 0.05;
END LOOP;

norm := sqrt(GREATEST((SELECT sum(val*val) FROM unnest(emb) val), 0.0001));
FOR j IN 1..1024 LOOP
emb[j] := COALESCE(emb[j] / norm, 0.0);
END LOOP;

RETURN emb::vector(1024);
END;
$$;


ALTER FUNCTION "public"."kos_generate_embedding_internal_v3"("input_text" "text", "meta" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_generate_embedding_internal_v4"("input_text" "text", "meta" "jsonb" DEFAULT NULL::"jsonb") RETURNS "public"."vector"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$ DECLARE emb float8[]; word_hash bigint; i int; j int; norm float8; kw_bigfour jsonb := '{ "uemoa":1.0,"bceao":1.0,"cobac":1.0,"ohada":0.95,"gafi":0.95,"cemac":0.95,"beac":0.9, "microfinance":1.0,"sfd":0.95,"emf":0.95,"imf":0.95,"inclusion":0.85,"agrément":0.95, "loi":0.95,"directive":0.95,"règlement":0.95,"instruction":0.9,"décision":0.9,"circulaire":0.85, "ifrs":1.0,"ifrs9":1.0,"ifrs16":0.95,"ias":0.9,"normes":0.9,"comptable":0.9,"syscohada":0.95, "lbc":0.9,"ft":0.9,"lcbft":0.95,"kyc":0.9,"centif":0.9,"giaba":0.9, "prudentiel":0.9,"solvabilité":0.9,"liquidité":0.85,"gouvernance":0.9,"contrôle":0.85,"audit":0.9, "risque":0.85,"conformité":0.9,"sanction":0.9,"obligation":0.9,"échéance":0.85, "nouvelle":0.8,"réforme":0.85,"révision":0.8,"mise à jour":0.8,"entrée en vigueur":0.85, "iso27001":1.0,"iso42001":1.0,"coso":0.95,"bâle":0.95,"khepra":1.0 }'::jsonb; kw text; kw_weight float8; text_expanded text; BEGIN text_expanded := lower(coalesce(input_text, '')); IF text_expanded ~* 'nouvelle loi|loi.*microfinance' THEN text_expanded := text_expanded || ' directive uemoa 007-2024 règlement sfd agrément'; END IF; IF text_expanded ~* 'ifrs|normes comptables' THEN text_expanded := text_expanded || ' ifrs9 ifrs16 ias syscohada bceao'; END IF; IF text_expanded ~* 'lbc|lcbft|blanchiment' THEN text_expanded := text_expanded || ' kyc centif giaba gafi'; END IF; emb := array_fill(0.0::float8, ARRAY[1024]); word_hash := ('x' || substr(md5(text_expanded), 1, 16))::bit(64)::bigint; FOR kw, kw_weight IN SELECT * FROM jsonb_each_text(kw_bigfour) LOOP IF position(kw IN text_expanded) > 0 THEN i := abs(hashtext(kw) % 180) + 1; emb[i] := COALESCE(emb[i], 0.0) + COALESCE(kw_weight, 0.0); emb[i + 200] := COALESCE(emb[i + 200], 0.0) + COALESCE(kw_weight, 0.0) * 0.5; emb[i + 400] := COALESCE(emb[i + 400], 0.0) + COALESCE(kw_weight, 0.0) * 0.25; END IF; END LOOP; norm := sqrt(GREATEST((SELECT sum(val*val) FROM unnest(emb) val), 0.0001)); FOR j IN 1..1024 LOOP emb[j] := COALESCE(emb[j] / norm, 0.0); END LOOP; RETURN emb::vector(1024); END; $$;


ALTER FUNCTION "public"."kos_generate_embedding_internal_v4"("input_text" "text", "meta" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_generate_embedding_local"("content" "text") RETURNS "public"."vector"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE
  req_id bigint;
  res_body jsonb;
  emb float8[];
  i int;
BEGIN
  SELECT net.http_post(
    url := 'http://172.17.0.1:11434/api/embeddings',
    headers := '{"Content-Type":"application/json"}'::jsonb,
    body := jsonb_build_object('model','bge-m3','prompt',content)
  ) INTO req_id;

  FOR i IN 1..7 LOOP
    PERFORM pg_sleep(0.5);
    EXECUTE 'SELECT content::jsonb FROM net._http_response WHERE id = $1' INTO res_body USING req_id;
    IF res_body IS NOT NULL THEN EXIT; END IF;
  END LOOP;

  IF res_body IS NULL THEN
    RAISE EXCEPTION 'Ollama unreachable: no response after 3.5s';
  END IF;

  IF NOT (res_body ? 'embedding') OR jsonb_typeof(res_body->'embedding') != 'array' THEN
    RAISE EXCEPTION 'Ollama response invalid: %', res_body;
  END IF;

  emb := ARRAY(SELECT jsonb_array_elements_text(res_body->'embedding'))::float8[];

  IF array_length(emb, 1) IS NULL OR array_length(emb, 1) != 1024 THEN
    RAISE EXCEPTION 'Dimension invalide: % vs 1024', coalesce(array_length(emb,1)::text, 'NULL');
  END IF;

  RETURN emb::vector(1024);
END;
$_$;


ALTER FUNCTION "public"."kos_generate_embedding_local"("content" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_generate_executive_report"("p_twin_id" "uuid", "p_type" "text", "p_period" "daterange") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  v_twin jsonb;
  v_regs jsonb;
  v_risks jsonb;
  v_report jsonb;
BEGIN
  SELECT to_jsonb(t) INTO v_twin FROM kos_client_twins t WHERE id = p_twin_id;
  SELECT jsonb_agg(to_jsonb(r)) INTO v_regs FROM kos_get_applicable_regs(p_twin_id) r;
  
  v_risks := jsonb_build_array(
    jsonb_build_object('risk', 'Non-conformité UEMOA 007-2024', 'probability', 0.7, 'impact', 'critical', 'cost', 100000000),
    jsonb_build_object('risk', 'Sanction LBC/FT', 'probability', 0.4, 'impact', 'high', 'cost', 50000000)
  );
  
  v_report := jsonb_build_object(
    'executive_summary', 'Risque principal: Non-conformité Directive 007-2024. Coût évité: 150M FCFA.',
    'kpis', jsonb_build_object('conformite_score', 0.72, 'risques_critiques', 2, 'obligations_pending', 8),
    'risks', v_risks,
    'recommendations', jsonb_build_array(
      jsonb_build_object('action', 'Audit gouvernance', 'priority', 'P0', 'roi', 3.2, 'deadline', '2025-03-31'),
      jsonb_build_object('action', 'Formation LBC/FT', 'priority', 'P1', 'roi', 2.1, 'deadline', '2025-06-30')
    ),
    'scenarios', jsonb_build_object(
      'best_case', 'Conformité 100% = 0 sanction',
      'worst_case', 'Sanction 100M + retrait agrément',
      'probable', 'Mise en conformité 6 mois = 50M coût'
    )
  );
  
  RETURN v_report;
END;
$$;


ALTER FUNCTION "public"."kos_generate_executive_report"("p_twin_id" "uuid", "p_type" "text", "p_period" "daterange") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_generate_jsonld"("p_slug" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_page record;
  v_jsonld jsonb;
BEGIN
  SELECT * INTO v_page FROM public.kos_public_pages WHERE slug = p_slug AND is_indexable = true;

  IF NOT FOUND THEN RETURN NULL; END IF;

  v_jsonld := jsonb_build_object(
    '@context', 'https://schema.org',
    '@type', CASE v_page.page_type
      WHEN 'OFFRE' THEN 'Service'
      WHEN 'BLOG' THEN 'BlogPosting'
      WHEN 'PUBLICATION' THEN 'TechArticle'
      WHEN 'KBR' THEN 'Dataset'
      ELSE 'WebPage'
    END,
    'name', v_page.title,
    'description', v_page.description,
    'url', v_page.url,
    'datePublished', v_page.published_at,
    'dateModified', v_page.updated_at,
    'provider', jsonb_build_object(
      '@type', 'Organization',
      'name', 'Khepra Experts',
      'url', 'https://khepraexperts.com',
      'logo', 'https://khepraexperts.com/logo.png',
      'sameAs', ARRAY[
        'https://www.linkedin.com/company/khepra-experts',
        'https://twitter.com/khepraexperts'
      ]
    ),
    'keywords', v_page.keywords
  );

  IF v_page.bu = 'KOS_REGTECH' THEN
    v_jsonld := v_jsonld || jsonb_build_object(
      'serviceType', 'RegTech Compliance',
      'areaServed', jsonb_build_object('@type', 'Place', 'name', 'UEMOA')
    );
  END IF;

  RETURN v_jsonld;
END; $$;


