CREATE OR REPLACE FUNCTION "public"."kos_generate_sitemap"() RETURNS "xml"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_xml xml;
BEGIN
  SELECT xmlconcat(
    '<?xml version="1.0" encoding="UTF-8"?>'::xml,
    xmlelement(name urlset,
      xmlattributes('http://www.sitemaps.org/schemas/sitemap/0.9' AS xmlns),
      xmlagg(
        xmlelement(name url,
          xmlelement(name loc, url),
          xmlelement(name lastmod, to_char(updated_at, 'YYYY-MM-DD')),
          xmlelement(name changefreq, changefreq),
          xmlelement(name priority, priority)
        )
      )
    )
  ) INTO v_xml
  FROM public.kos_public_pages
  WHERE is_indexable = true
  ORDER BY priority DESC, updated_at DESC;

  RETURN v_xml;
END; $$;


ALTER FUNCTION "public"."kos_generate_sitemap"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_get_applicable_regs"("p_twin_id" "uuid") RETURNS TABLE("entity_id" "uuid", "name" "text", "type" "text", "risk_level" "text")
    LANGUAGE "plpgsql" STABLE
    AS $$
BEGIN
  RETURN QUERY
  SELECT e.id, e.name, e.type,
    CASE 
      WHEN e.type = 'sanction' THEN 'critical'
      WHEN e.type = 'obligation' THEN 'high'
      ELSE 'medium'
    END as risk_level
  FROM kg_entities e
  WHERE e.id = ANY((SELECT applicable_regulations FROM kos_client_twins WHERE id = p_twin_id))
  ORDER BY risk_level DESC, e.effective_date DESC;
END;
$$;


ALTER FUNCTION "public"."kos_get_applicable_regs"("p_twin_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_get_cached_or_compute"("p_key" "text", "p_compute_sql" "text", "p_ttl_seconds" integer DEFAULT 3600) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_cached jsonb;
  v_result jsonb;
BEGIN
  -- 1. Check cache
  SELECT cache_value INTO v_cached FROM kos_local_cache
  WHERE cache_key = p_key AND expires_at > now();

  IF v_cached IS NOT NULL THEN
    RETURN v_cached || jsonb_build_object('cache_hit', true);
  END IF;

  -- 2. Compute si cache miss
  EXECUTE p_compute_sql INTO v_result;

  -- 3. Store cache
  INSERT INTO kos_local_cache (cache_key, cache_value, expires_at)
  VALUES (p_key, v_result, now() + (p_ttl_seconds || ' seconds')::interval)
  ON CONFLICT (cache_key) DO UPDATE SET
    cache_value = EXCLUDED.cache_value,
    expires_at = EXCLUDED.expires_at;

  RETURN v_result || jsonb_build_object('cache_hit', false);
END;
$$;


ALTER FUNCTION "public"."kos_get_cached_or_compute"("p_key" "text", "p_compute_sql" "text", "p_ttl_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_get_coverage_stats"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_total int;
  v_tp_count int;
  v_by_authority jsonb;
  v_missing jsonb;
  v_last_cron timestamptz;
  v_cron_status text;
BEGIN
  SELECT COUNT(*) INTO v_total FROM public.kos_regulatory_corpus;

  SELECT COUNT(*) INTO v_tp_count
  FROM public.kos_regulatory_corpus
  WHERE content ~* 'prix de transfert|intra-groupe|BEPS|parties liées|2257|API TP';

  SELECT jsonb_object_agg(authority, cnt) INTO v_by_authority
  FROM (
    SELECT authority, COUNT(*) as cnt
    FROM public.kos_regulatory_corpus
    WHERE content ~* 'prix de transfert|intra-groupe|BEPS'
    GROUP BY authority
  ) t;

  SELECT jsonb_agg(ref) INTO v_missing
  FROM unnest(ARRAY[
    'Circ-009-2025', 'Circ-007-2024', 'Instr-010-05-2022',
    'Règlement 02-2023', 'Circulaire 03-2024', 'COBAC R-2016/01',
    'Instr-02-2025', 'Instruction 008/GR/2019'
  ]) ref
  WHERE NOT EXISTS (
    SELECT 1 FROM public.kos_regulatory_corpus
    WHERE reference = ref
  );

  SELECT start_time, status INTO v_last_cron, v_cron_status
  FROM cron.job_run_details
  WHERE jobid = 70
  ORDER BY start_time DESC LIMIT 1;

  RETURN jsonb_build_object(
    'total_corpus', v_total,
    'tp_texts', v_tp_count,
    'coverage_pct', ROUND((v_tp_count::numeric / NULLIF(v_total, 0) * 100), 1),
    'by_authority', v_by_authority,
    'missing_critical', COALESCE(v_missing, '[]'::jsonb),
    'last_ingest', v_last_cron,
    'cron_status', v_cron_status,
    'big_four_compliant', v_tp_count >= 20 AND v_cron_status = 'succeeded'
  );
END;
$$;


ALTER FUNCTION "public"."kos_get_coverage_stats"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_get_page_seo"("p_slug" "text", "p_lang" "text" DEFAULT 'fr'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_page record;
  v_redirect record;
  v_i18n jsonb;
BEGIN
  SELECT * INTO v_page FROM public.kos_seo_pages WHERE slug = p_slug AND lang = p_lang AND noindex = false;
  IF v_page IS NULL THEN
    SELECT * INTO v_redirect FROM public.kos_redirects WHERE from_path = p_slug;
    IF v_redirect IS NOT NULL THEN
      RETURN jsonb_build_object('redirect', v_redirect.to_path, 'status', v_redirect.status_code);
    END IF;
    RETURN jsonb_build_object('status', 404);
  END IF;

  SELECT jsonb_object_agg(key, value) INTO v_i18n FROM public.kos_i18n WHERE context = 'ui' AND lang = p_lang;

  RETURN jsonb_build_object(
    'title', v_page.title,
    'description', v_page.description,
    'canonical', v_page.canonical_url,
    'og', jsonb_build_object(
      'title', v_page.title,
      'description', v_page.description,
      'image', v_page.og_image,
      'type', v_page.og_type,
      'url', v_page.canonical_url
    ),
    'twitter', jsonb_build_object('card', v_page.twitter_card, 'image', v_page.og_image),
    'schema', COALESCE(v_page.schema_jsonld, ''::jsonb),
    'i18n', COALESCE(v_i18n, ''::jsonb),
    'status', 200
  );
END; $$;


ALTER FUNCTION "public"."kos_get_page_seo"("p_slug" "text", "p_lang" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_get_routing_decision"("p_function_name" "text") RETURNS TABLE("function_name" "text", "active_provider" "text", "endpoint_url" "text", "fallback_provider" "text", "fallback_endpoint" "text", "status" "text", "reason" "text")
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  rec RECORD;
BEGIN
  SELECT * INTO rec FROM kos_function_routing WHERE kos_function_routing.function_name = p_function_name;
  IF rec IS NULL THEN
    RETURN QUERY SELECT p_function_name, 'edge_function'::TEXT, NULL::TEXT, 'none'::TEXT, NULL::TEXT, 'unknown'::TEXT, 'Function not registered in routing table'::TEXT;
    RETURN;
  END IF;
  IF rec.status = 'inactive' OR rec.status = 'deprecated' THEN
    RETURN QUERY SELECT rec.function_name, rec.fallback_provider, CASE rec.fallback_provider WHEN 'n8n' THEN rec.n8n_webhook_url WHEN 'edge_function' THEN rec.edge_function_name ELSE NULL END, 'none'::TEXT, NULL::TEXT, rec.status, 'Primary inactive, fallback forced'::TEXT;
    RETURN;
  END IF;
  IF rec.error_count >= rec.max_errors_before_fallback THEN
    RETURN QUERY SELECT rec.function_name, rec.fallback_provider, CASE rec.fallback_provider WHEN 'n8n' THEN rec.n8n_webhook_url WHEN 'edge_function' THEN rec.edge_function_name ELSE NULL END, rec.primary_provider, CASE rec.primary_provider WHEN 'n8n' THEN rec.n8n_webhook_url WHEN 'edge_function' THEN rec.edge_function_name ELSE NULL END, 'degraded'::TEXT, 'Error threshold exceeded, fallback active'::TEXT;
    RETURN;
  END IF;
  RETURN QUERY SELECT rec.function_name, rec.primary_provider, CASE rec.primary_provider WHEN 'n8n' THEN rec.n8n_webhook_url WHEN 'edge_function' THEN rec.edge_function_name ELSE NULL END, rec.fallback_provider, CASE rec.fallback_provider WHEN 'n8n' THEN rec.n8n_webhook_url WHEN 'edge_function' THEN rec.edge_function_name ELSE NULL END, rec.status, 'Primary provider active'::TEXT;
  RETURN;
END;
$$;


ALTER FUNCTION "public"."kos_get_routing_decision"("p_function_name" "text") OWNER TO "postgres";


