CREATE OR REPLACE FUNCTION "public"."kos_hermes_memory_episodic"("p_query" "text", "p_limit" integer DEFAULT 10) RETURNS TABLE("entity_type" "text", "action" "text", "actor" "text", "result_summary" "text", "created_at" timestamp with time zone, "relevance_score" real)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    aul.entity_type,
    aul.action,
    aul.actor,
    COALESCE(aul.reason, aul.action) AS result_summary,
    aul.created_at,
    similarity(COALESCE(aul.action, '') || ' ' || COALESCE(aul.reason, ''), p_query) AS relevance_score
  FROM kos_universal_audit_log aul
  WHERE aul.action IS NOT NULL
    AND similarity(COALESCE(aul.action, '') || ' ' || COALESCE(aul.reason, ''), p_query) > 0.1
  ORDER BY relevance_score DESC, aul.created_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."kos_hermes_memory_episodic"("p_query" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_hermes_memory_procedural_store"("p_skill_name" "text", "p_skill_data" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  INSERT INTO kos_correction_loop_log (phase, status, details, duration, created_at)
  VALUES (
    'hermes_procedural',
    'stored',
    jsonb_build_object(
      'skill_name', p_skill_name,
      'skill_data', p_skill_data,
      'stored_at', now(),
      'expires_at', now() + INTERVAL '7 days'
    )::text,
    'procedural',
    now()
  );
  -- Curator: delete expired skills (older than 7 days)
  DELETE FROM kos_correction_loop_log
  WHERE phase = 'hermes_procedural'
    AND created_at < now() - INTERVAL '7 days';
END;
$$;


ALTER FUNCTION "public"."kos_hermes_memory_procedural_store"("p_skill_name" "text", "p_skill_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_hermes_orchestrator_heartbeat"("p_entity_id" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_heartbeat_count INT;
  v_zombie_count INT;
BEGIN
  -- Heartbeat: update the ticket's updated_at as heartbeat indicator
  UPDATE kos_auto_correction_tickets
  SET updated_at = now(),
      resolution_notes = COALESCE(resolution_notes, '') || E'\n[HERMES HEARTBEAT ' || to_char(now(), 'HH24:MI:SS') || ']'
  WHERE check_run_id = p_entity_id AND status = 'open';
  
  GET DIAGNOSTICS v_heartbeat_count = ROW_COUNT;
  
  -- Zombie reclaim: tickets with no heartbeat in 5+ minutes → retry
  UPDATE kos_auto_correction_tickets
  SET status = 'retry',
      resolution_notes = COALESCE(resolution_notes, '') || E'\n[HERMES ZOMBIE RECLAIM ' || to_char(now(), 'YYYY-MM-DD HH24:MI') || '] Auto-retry triggered.'
  WHERE status = 'open'
    AND updated_at < now() - INTERVAL '5 minutes'
    AND source_engine = 'kos_automaton_v3';
  
  GET DIAGNOSTICS v_zombie_count = ROW_COUNT;
  
  -- Hallucination gate: check if any output doesn't match Big Four format
  UPDATE kos_auto_correction_tickets
  SET status = 'review',
      resolution_notes = COALESCE(resolution_notes, '') || E'\n[HERMES HALLUCINATION GATE] Output failed Big Four format check. Pattern: ^[A-Z]{2}-\\d{4} not matched.'
  WHERE status = 'open'
    AND error_message !~ '^[A-Z]{2}-\d{4}'
    AND source_engine = 'kos_automaton_v3';
  
  RETURN jsonb_build_object(
    'heartbeat_count', v_heartbeat_count,
    'zombie_reclaimed', v_zombie_count,
    'ts', now()
  )::text;
END;
$$;


ALTER FUNCTION "public"."kos_hermes_orchestrator_heartbeat"("p_entity_id" "text") OWNER TO "postgres";


