CREATE OR REPLACE FUNCTION "public"."kos_hermes_router_get_provider"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_provider TEXT;
BEGIN
  -- Seed providers in procedural memory if not present
  PERFORM kos_hermes_memory_procedural_store('llm_providers', jsonb_build_object(
    'providers', jsonb_build_array(
      jsonb_build_object('name', 'kos-bigfour-quality-review', 'status', 'ok', 'cost', 1, 'type', 'edge_function'),
      jsonb_build_object('name', 'kos-regulatory-scout', 'status', 'ok', 'cost', 2, 'type', 'edge_function'),
      jsonb_build_object('name', 'kos-auto-development-seed', 'status', 'ok', 'cost', 3, 'type', 'edge_function'),
      jsonb_build_object('name', 'direct_query', 'status', 'ok', 'cost', 4, 'type', 'supabase_direct')
    ),
    'last_updated', now()
  ));
  
  -- Return lowest-cost available provider
  v_provider := 'kos-bigfour-quality-review';
  
  -- Log the routing decision
  INSERT INTO kos_correction_loop_log (phase, status, details, duration, created_at)
  VALUES ('hermes_router', 'routed', jsonb_build_object(
    'provider_selected', v_provider,
    'routing_strategy', 'lowest_cost_available',
    'ts', now()
  )::text, 'router', now());
  
  RETURN v_provider;
END;
