CREATE OR REPLACE FUNCTION "public"."kos_hermes_session_set"("p_context" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_lock_id BIGINT;
BEGIN
  v_lock_id := ('x' || substr(md5(current_setting('app.kos_correlation_id', true) || COALESCE(p_context->>'session_id', 'default')), 1, 16))::bit(64)::bigint;
  PERFORM pg_advisory_lock(v_lock_id);
  -- Store context in kos_correction_loop_log as transient session memory
  INSERT INTO kos_correction_loop_log (phase, status, details, duration, created_at)
  VALUES ('hermes_session', 'active', jsonb_build_object(
    'context', p_context,
    'lock_id', v_lock_id,
    'ts', now()
  )::text, 'session', now());
  PERFORM pg_advisory_unlock(v_lock_id);
END;
$$;


