CREATE OR REPLACE FUNCTION "public"."kos_hyperion_autodev"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_config JSONB;
  v_skills_seeded INT := 0;
  v_rules_patched INT := 0;
  v_skills_curated INT := 0;
  v_workflows_analyzed INT := 0;
  v_new_skill JSONB;
  v_skill_name TEXT;
  v_routine RECORD;
  v_low_success_routines JSONB := '[]'::JSONB;
  v_rule TEXT;
  v_now TIMESTAMPTZ := now();
  v_dev_id TEXT := 'AUTODEV-' || extract(epoch FROM v_now)::BIGINT;
BEGIN
  -- Load config
  SELECT new_state INTO v_config
  FROM kos_universal_audit_log
  WHERE event_type = 'kos_hyperion_config'
    AND action = 'hyperion_config_snapshot'
  ORDER BY created_at DESC
  LIMIT 1;

  -- ═══ COLLECT: Analyze routine execution metrics ═══
  -- Find routines with low success rate (< 90%) or high avg duration (> 30s)
  FOR v_routine IN
    SELECT
      new_state->>'routine_id' AS routine_id,
      new_state->>'routine_name' AS routine_name,
      COUNT(*) FILTER (WHERE new_state->>'success' = 'true') AS success_count,
      COUNT(*) AS total_count,
      AVG((new_state->>'duration_ms')::INT) AS avg_duration_ms,
      MAX(created_at) AS last_run
    FROM kos_universal_audit_log
    WHERE event_type = 'kos_routine_execution'
      AND action = 'readdy_execute_routine'
      AND created_at > now() - INTERVAL '7 days'
    GROUP BY new_state->>'routine_id', new_state->>'routine_name'
    HAVING COUNT(*) >= 3
  LOOP
    v_workflows_analyzed := v_workflows_analyzed + 1;

    -- ═══ ANALYSE: Check if needs auto-correction ═══
    IF v_routine.success_count::NUMERIC / NULLIF(v_routine.total_count, 0) < 0.9 THEN
      -- Low success rate — generate kos_rule
      v_rule := 'Si routine "' || v_routine.routine_name || '" success_rate < 90%, auto-precheck avant LLM call. Vérifier tokens, prompt format, API key.';
      v_rules_patched := v_rules_patched + 1;

      -- Store rule
      INSERT INTO kos_universal_audit_log (
        event_type, entity_type, entity_id, action, actor, new_state
      ) VALUES (
        'kos_hyperion_rule',
        'rule',
        'rule_' || md5(v_rule),
        'rule_auto_generated',
        'kos_hyperion_autodev',
        jsonb_build_object(
          'rule', v_rule,
          'source_routine', v_routine.routine_id,
          'source_routine_name', v_routine.routine_name,
          'iso_ref', '8.5.1',
          'generated_at', v_now,
          'auto_correction_type', 'low_success_rate'
        )
      );
    END IF;

    IF COALESCE(v_routine.avg_duration_ms, 0) > 30000 THEN
      v_rule := 'Si routine "' || v_routine.routine_name || '" avg_duration > 30s, appliquer skill compress_context. Token budget auto-adjust.';
      v_rules_patched := v_rules_patched + 1;

      INSERT INTO kos_universal_audit_log (
        event_type, entity_type, entity_id, action, actor, new_state
      ) VALUES (
        'kos_hyperion_rule',
        'rule',
        'rule_' || md5(v_rule),
        'rule_auto_generated',
        'kos_hyperion_autodev',
        jsonb_build_object(
          'rule', v_rule,
          'source_routine', v_routine.routine_id,
          'source_routine_name', v_routine.routine_name,
          'iso_ref', '8.5.1',
          'generated_at', v_now,
          'auto_correction_type', 'high_latency'
        )
      );
    END IF;

    -- ═══ SKILL SEEDING: If 3+ success AND duration < percentile_20 ═══
    IF v_routine.success_count >= 3 AND COALESCE(v_routine.avg_duration_ms, 5000) < 15000 THEN
      v_skill_name := 'skill_auto_' || v_routine.routine_id || '_' || to_char(v_now, 'YYYYMMDD');

      v_new_skill := jsonb_build_object(
        'skill_id', md5(v_skill_name),
        'name', v_skill_name,
        'source_routine', v_routine.routine_id,
        'success_count', v_routine.success_count,
        'avg_duration_ms', v_routine.avg_duration_ms,
        'generated_at', v_now,
        'reuse_strategy', 'read_first',
        'tokens_saved_pct', 40
      );

      -- Store skill in procedural memory (kos_correction_loop_log)
      INSERT INTO kos_correction_loop_log (
        phase, status, details, executed_at
      ) VALUES (
        'kos_hyperion_skill',
        'skills_seeded',
        jsonb_build_object(
          'skill', v_new_skill,
          'engine', 'HYPERION v5.0',
          'iso_clause', 'ISO 9001 8.5.1',
          'executed_at', v_now::TEXT
        )::TEXT,
        v_now
      );

      v_skills_seeded := v_skills_seeded + 1;
    END IF;
  END LOOP;

  -- ═══ CURATOR: Clean skills older than 7 days ═══
  DELETE FROM kos_correction_loop_log
  WHERE phase = 'kos_hyperion_skill'
    AND executed_at < v_now - INTERVAL '7 days';
  GET DIAGNOSTICS v_skills_curated = ROW_COUNT;

  -- ═══ UPDATE METRICS ═══
  v_config := jsonb_set(v_config, '{metrics,last_autodev_run}', to_jsonb(v_now::TEXT));
  v_config := jsonb_set(v_config, '{metrics,skills_seeded}',
    to_jsonb(COALESCE((v_config->'metrics'->>'skills_seeded')::INT, 0) + v_skills_seeded));

  -- ═══ LOG ═══
  INSERT INTO kos_universal_audit_log (
    event_type, entity_type, entity_id, action, actor, new_state, correlation_id
  ) VALUES (
    'kos_hyperion_autodev',
    'hyperion_engine',
    v_dev_id,
    'autodev_executed',
    'kos_hyperion_v5',
    jsonb_build_object(
      'skills_seeded', v_skills_seeded,
      'rules_patched', v_rules_patched,
      'skills_curated', v_skills_curated,
      'workflows_analyzed', v_workflows_analyzed,
      'executed_at', v_now,
      'engine', 'HYPERION v5.0'
    ),
    v_dev_id
  );

  RETURN jsonb_build_object(
    'success', true,
    'dev_id', v_dev_id,
    'skills_seeded', v_skills_seeded,
    'rules_patched', v_rules_patched,
    'skills_curated', v_skills_curated,
    'workflows_analyzed', v_workflows_analyzed,
    'executed_at', v_now::TEXT,
    'engine', 'HYPERION v5.0'
  );
END;
$$;


ALTER FUNCTION "public"."kos_hyperion_autodev"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_ingest_regulatory_text"("p_authority" "text", "p_ref" "text", "p_title" "text", "p_content" "text", "p_date" "date", "p_penalties" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE 
  v_id uuid;
BEGIN
  INSERT INTO public.kos_regulatory_corpus (
    authority, 
    doc_type, 
    reference, 
    title, 
    content,
    date_publication, 
    date_vigueur, 
    penalties, 
    status
  ) VALUES (
    p_authority, 
    'REGLEMENT', 
    p_ref, 
    p_title, 
    p_content,
    p_date, 
    p_date + interval '3 months', 
    p_penalties, 
    'EN_VIGUEUR'
  )
  ON CONFLICT (authority, reference) DO UPDATE SET
    title = EXCLUDED.title,
    content = EXCLUDED.content,
    date_publication = EXCLUDED.date_publication,
    date_vigueur = EXCLUDED.date_vigueur,
    penalties = EXCLUDED.penalties,
    status = 'EN_VIGUEUR',
    date_abrogation = NULL
  RETURNING id INTO v_id;

  RETURN v_id;
END; 
$$;


