        'responsable', 'DG / DAF',
        'kpis_cibles', jsonb_build_array('Réduction 10% Scope 1&2', 'Diversité Conseil ≥40%')
      ),
      jsonb_build_object(
        'phase', 'Moyen terme (6-18 mois)',
        'actions', jsonb_build_array(
          'Déployer un Système de Management Environnemental ISO 14001',
