  v_entite_nom text := 'Banque Régionale UEMOA';
  v_periode_str text := to_char(p_periode, 'MM/YYYY');
BEGIN
  -- Détection du nom de l'entité si possible
  SELECT COALESCE(name, 'Entité ' || substring(p_entite_id::text, 1, 8))
  INTO v_entite_nom
  FROM organizations WHERE id = p_entite_id;

  RETURN jsonb_build_object(
    'titre', 'Note au Conseil d''Administration — ' || v_entite_nom || ' — ' || v_periode_str,
    'periode', v_periode_str,
    'entite', COALESCE(v_entite_nom, 'Banque Régionale UEMOA'),
    'contexte', 'La présente note présente l''état de la conformité, des risques et des incidents majeurs pour la période ' || v_periode_str || '. Elle a été élaborée selon les standards COSO et ISO 37000.',
    'points_cles', jsonb_build_array(
      jsonb_build_object('theme', 'Conformité Réglementaire', 'niveau', 'Satisfaisant avec réserves', 'detail', 'Taux de conformité global stable, 2 écarts mineurs identifiés sur les ratios prudentiels.'),
      jsonb_build_object('theme', 'Cartographie des Risques', 'niveau', 'À surveiller', 'detail', 'Risque cybernétique et risque de crédit scoring IA remontent en top 3.'),
      jsonb_build_object('theme', 'Incidents et Remontées', 'niveau', 'Maîtrisé', 'detail', '1 incident critique résolu, 3 incidents majeurs en traitement.'),
      jsonb_build_object('theme', 'Gouvernance et CA', 'niveau', 'Conforme', 'detail', 'Composition du CA alignée sur Circulaire BCEAO 01/2017, indépendance des administrateurs vérifiée.')
    ),
    'recommandations_exec', jsonb_build_array(
      'Valider le renforcement du dispositif LBC/FT suite à la mise à jour GAFI 2026.',
      'Examiner le budget 2026 pour la conformité ESG ISSB (S1/S2 double matérialité).',
      'Approuver le Plan d''Action Corrective sur les 2 écarts ratios prudentiels.',
      'Surveiller la montée en puissance des risques cyber et IA générative.'
    ),
    'genere_en', '<90s',
    'methodologie', 'COSO + ISO 37000 + Référentiel BCEAO/COBAC'
  );
END;
$$;


