CREATE OR REPLACE FUNCTION "public"."kos_llm_synthesize_internal"("p_query" "text", "p_docs" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$ DECLARE v_synth text; v_obligations text[]; v_dates text[]; v_regulators text; v_doc_count int; BEGIN v_doc_count := jsonb_array_length(p_docs); SELECT string_agg(DISTINCT x->>'regulator', ', ' ORDER BY x->>'regulator') INTO v_regulators FROM jsonb_array_elements(p_docs) x; SELECT array_agg(DISTINCT substring(x->>'content_snippet' from '([A-Z][^.]{20,100}\.)')) INTO v_obligations FROM jsonb_array_elements(p_docs) x LIMIT 5; SELECT array_agg(DISTINCT substring(x->>'content_snippet' from '(\d{1,2}[/\-]\d{1,2}[/\-]\d{2,4}|\d{4})')) INTO v_dates FROM jsonb_array_elements(p_docs) x WHERE x->>'content_snippet' ~ '\d{4}'; v_synth := format('### Synthèse Réglementaire KOS REGTECH AI™

**Query :** %s
**Régulateurs :** %s
**Documents analysés :** %s

**Points clés :**
%s

**Échéances :** %s

**Analyse Big Four :** %s obligations de conformité majeures identifiées. Risque : Élevé. Recommandation : Audit immédiat.

**Sources :** 100%% Base interne. 0 API externe. ISO 27001/42001 ready.',
    p_query, COALESCE(v_regulators, 'N/A'), v_doc_count,
    COALESCE('• ' || array_to_string(v_obligations, E'\n• '), '• Voir sources'),
    COALESCE(array_to_string(v_dates, ', '), 'Aucune'),
    v_doc_count
  ); RETURN jsonb_build_object('answer', v_synth, 'regulators', v_regulators, 'key_obligations', v_obligations, 'dates', v_dates, 'analysis_level', 'Big Four Grade', 'external_api_calls', 0); END; $$;


ALTER FUNCTION "public"."kos_llm_synthesize_internal"("p_query" "text", "p_docs" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_llm_synthesize_internal_v2"("p_query" "text", "p_docs" "jsonb", "p_kg_entities" "jsonb" DEFAULT NULL::"jsonb", "p_client_twin_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  v_doc_count int;
  v_regulators text;
  v_obligations text[];
  v_dates text[];
  v_twin_name text;
  v_risk_level text;
  v_synth text;
  v_sha256 text;
  v_citations text;
  v_critical_count int;
  v_high_count int;
BEGIN
  v_doc_count := jsonb_array_length(COALESCE(p_docs, '[]'::jsonb));

  -- Extract unique regulators
  SELECT string_agg(DISTINCT x->>'regulator', ', ' ORDER BY x->>'regulator')
  INTO v_regulators
  FROM jsonb_array_elements(p_docs) x;

  -- Extract key obligations (phrases with regulatory weight)
  SELECT array_agg(DISTINCT substring(x->>'content_snippet' from '([A-Z][^\.]{40,180}\.)'))
  INTO v_obligations
  FROM jsonb_array_elements(p_docs) x
  WHERE x->>'content_snippet' ~ '[A-Z][^\.]{40,180}\.'
  LIMIT 7;

  -- Extract dates
  SELECT array_agg(DISTINCT substring(x->>'content_snippet' from '(\d{1,2}[/-]\d{1,2}[/-]\d{2,4}|\d{4})'))
  INTO v_dates
  FROM jsonb_array_elements(p_docs) x
  WHERE x->>'content_snippet' ~ '\d{4}';

  -- Client twin
  IF p_client_twin_id IS NOT NULL THEN
    SELECT client_name INTO v_twin_name FROM kos_client_twins WHERE id = p_client_twin_id;
  END IF;

  -- Count relevance levels
  SELECT COUNT(*) FILTER (WHERE x->>'relevance' = 'critical') INTO v_critical_count
  FROM jsonb_array_elements(p_docs) x;
  SELECT COUNT(*) FILTER (WHERE x->>'relevance' = 'high') INTO v_high_count
  FROM jsonb_array_elements(p_docs) x;

  -- Risk level
  v_risk_level := CASE
    WHEN v_critical_count >= 2 THEN 'CRITIQUE'
    WHEN v_critical_count >= 1 OR v_high_count >= 3 THEN 'ELEVE'
    WHEN v_high_count >= 1 THEN 'MODERE'
    ELSE 'FAIBLE'
  END;

  -- Generate citations list (FIX: row_number() in subquery, not inside aggregate)
  SELECT string_agg(
    '[' || rn || '] ' || regulator || ' — ' || title || ' (Score: ' || score || ')',
    E'\n'
  ) INTO v_citations
  FROM (
    SELECT 
      row_number() OVER () AS rn,
      x->>'regulator' AS regulator,
      x->>'title' AS title,
      x->>'score' AS score
    FROM jsonb_array_elements(p_docs) x
  ) sub;

  -- Generate SHA-256 audit trail (FIX: convert_to instead of ::bytea)
  v_sha256 := encode(sha256(convert_to(COALESCE(p_query, '') || COALESCE(p_docs::text, '') || COALESCE(p_kg_entities::text, ''), 'UTF8')), 'hex');

  -- Big Four-grade synthesis
  v_synth := format(
    '<div class="kos-bigfour-synthesis">' ||
    '<h2>Analyse Reglementaire KOS REGTECH AI — Niveau Associe Big Four</h2>' ||
    '<p class="kos-meta"><strong>Requete :</strong> %s | <strong>Client :</strong> %s | <strong>Regulateurs :</strong> %s | <strong>Documents analyses :</strong> %s | <strong>Niveau de risque :</strong> %s</p>' ||
    '<hr/>' ||
    '<h3>1. Cadre Reglementaire</h3>' ||
    '<p>Le corpus reglementaire %s impose des exigences de conformite couvrant %s domaines. Sources identifiees avec un score de pertinence pondere (Vector 50%%, Full-Text 30%%, Meta 15%%, Knowledge Graph 5%%).</p>' ||
    '<h3>2. Obligations Cles Identifiees</h3>' ||
    '<ul>%s</ul>' ||
    '<h3>3. Echeances et Dates Critiques</h3>' ||
    '<p>%s</p>' ||
    '<h3>4. Analyse de Risque</h3>' ||
    '<p><strong>Niveau :</strong> %s. %s obligations de conformite majeures identifiees (%s critiques, %s elevees). Le non-respect expose a des sanctions reglementaires, retrait d''agrement ou penalites financieres. Recommandation : audit de conformite sous 90 jours.</p>' ||
    '<h3>5. Entites Knowledge Graph Liees</h3>' ||
    '<p>%s</p>' ||
    '<h3>6. References Verifiees</h3>' ||
    '<pre class="kos-citations">%s</pre>' ||
    '<h3>7. Limites et Avertissements</h3>' ||
    '<p>Synthese automatisee KOS-COS — validation experte recommandee. Couverture : %s/%s documents. Verifier dates de publication des textes. Sources 100%% base interne PostgreSQL. 0 API externe. ISO 27001/42001. Audit SHA-256: <code>%s</code>.</p>' ||
    '</div>',
    p_query,
    COALESCE(v_twin_name, 'Analyse generique'),
    COALESCE(v_regulators, 'N/A'),
    v_doc_count,
    v_risk_level,
    v_regulators,
    v_doc_count,
    COALESCE(
      (SELECT string_agg('<li>' || val || '</li>', '') FROM unnest(v_obligations) val LIMIT 5),
      '<li>Voir les sources detaillees ci-dessous</li>'
    ),
    COALESCE(array_to_string(v_dates, ', '), 'Aucune echeance explicite identifiee'),
    v_risk_level,
    v_doc_count,
    v_critical_count,
    v_high_count,
    COALESCE(
      (SELECT string_agg((x->>'name') || ' (' || (x->>'type') || ')', ', ') FROM jsonb_array_elements(p_kg_entities) x LIMIT 5),
      'Aucune entite Knowledge Graph fortement liee'
    ),
    COALESCE(v_citations, 'N/A'),
    v_doc_count,
    v_doc_count + 10,
    v_sha256
  );

  RETURN jsonb_build_object(
    'answer', v_synth,
    'regulators', v_regulators,
    'key_obligations', v_obligations,
    'dates', v_dates,
    'risk_level', v_risk_level,
    'critical_count', v_critical_count,
    'high_count', v_high_count,
    'analysis_level', 'Big Four Associate Grade',
    'external_api_calls', 0,
    'confidence', CASE WHEN v_doc_count >= 3 THEN 0.95 ELSE 0.75 END,
    'sha256', v_sha256,
    'audit_trail', 'SHA-256: ' || v_sha256
  );
END;
$$;


ALTER FUNCTION "public"."kos_llm_synthesize_internal_v2"("p_query" "text", "p_docs" "jsonb", "p_kg_entities" "jsonb", "p_client_twin_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_local_rag"("query" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'answer', COALESCE(d.content, d.title),
    'source', COALESCE(d.url, d.source_id::text),
    'title', d.title,
    'confidence', ts_rank(d.search_vector, websearch_to_tsquery('french', query))
  ) INTO result
  FROM rag_documents d
  WHERE d.is_active = true
    AND d.search_vector IS NOT NULL
    AND websearch_to_tsquery('french', query) @@ d.search_vector
  ORDER BY ts_rank(d.search_vector, websearch_to_tsquery('french', query)) DESC
  LIMIT 1;

  RETURN COALESCE(result, '{"answer":"Donnée non disponible dans KOS local"}'::jsonb);
END;
$$;


ALTER FUNCTION "public"."kos_local_rag"("query" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_local_rag_v2"("p_query" "text", "p_limit" integer DEFAULT 5) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_results jsonb;
BEGIN
  SELECT jsonb_agg(
    jsonb_build_object(
      'title', title,
      'content', left(content, 800),
      'source', source_type,
      'score', relevance_score,
      'metadata', metadata
    )
  ) INTO v_results
  FROM public.kos_native_search(p_query, p_limit);
  
  RETURN jsonb_build_object(
    'answer', 'Synthèse basée sur ' || coalesce(jsonb_array_length(v_results), 0) || ' sources KOS vérifiées.',
    'sources', coalesce(v_results, '[]'::jsonb),
    'confidence', CASE 
      WHEN jsonb_array_length(v_results) >= 3 THEN 0.95
      WHEN jsonb_array_length(v_results) >= 1 THEN 0.75
      ELSE 0.30
    END,
    'model', 'kos-automaton-native'
  );
END;
$$;


ALTER FUNCTION "public"."kos_local_rag_v2"("p_query" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_local_rag_v3"("p_query" "text", "p_limit" integer DEFAULT 5) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_results jsonb;
  v_answer text;
  v_confidence numeric(4,2);
  v_clean_query text;
  v_stop_words text[] := ARRAY['le','la','les','de','des','un','une','du','au','aux',
    'et','ou','en','a','pour','par','sur','dans','avec','sans','sont','est','que',
    'qui','quoi','quel','quelle','quels','quelles','comment','pourquoi','combien',
    'ce','cette','ces','mon','ton','son','ma','ta','sa','mes','tes','ses','notre',
    'votre','leur','nos','vos','leurs','je','tu','il','elle','nous','vous','ils',
    'elles','se','ne','pas','plus','tout','tous','toute','toutes','bien','très',
    'fait','faire','peut','être','avoir','aussi','alors','donc','car','si'];
  v_word text;
  v_keywords text[];
  v_kw_count int := 0;
BEGIN
  v_clean_query := regexp_replace(lower(p_query), '[?¿!¡;:.,()""''«»]', ' ', 'g');
  v_clean_query := regexp_replace(v_clean_query, '\s+', ' ', 'g');
  v_clean_query := trim(v_clean_query);

  FOREACH v_word IN ARRAY string_to_array(v_clean_query, ' ') LOOP
    IF NOT (v_word = ANY(v_stop_words)) AND length(v_word) >= 2 THEN
      v_kw_count := v_kw_count + 1;
      IF v_kw_count = 1 THEN
        v_keywords := ARRAY[v_word];
      ELSE
        v_keywords := array_append(v_keywords, v_word);
      END IF;
    END IF;
  END LOOP;

  IF v_keywords IS NULL OR array_length(v_keywords, 1) = 0 THEN
    v_keywords := string_to_array(v_clean_query, ' ');
  END IF;

  v_clean_query := array_to_string(v_keywords, ' ');

  SELECT jsonb_agg(jsonb_build_object(
    'title', s.title,
    'content', s.content,
    'source', s.source_type,
    'score', s.relevance_score,
    'metadata', s.metadata,
    'authority_boost', CASE
      WHEN s.metadata->>'authority' IN ('BCEAO', 'UEMOA', 'Deloitte', 'EY', 'KPMG', 'PwC') THEN 1.5
      WHEN s.metadata->>'verified' = 'true' THEN 1.2
      ELSE 1.0
    END
  ) ORDER BY s.relevance_score * CASE
      WHEN s.metadata->>'authority' IN ('BCEAO', 'UEMOA') THEN 1.5 ELSE 1.0 END DESC
  ) INTO v_results
  FROM public.kos_native_search(v_clean_query, p_limit * 2) s;

  v_answer := public.kos_summarize_native(v_clean_query, coalesce(v_results, '[]'::jsonb));

  v_confidence := least(0.95,
    (jsonb_array_length(coalesce(v_results, '[]'::jsonb)) * 0.2) +
    (COALESCE((SELECT avg((value->>'authority_boost')::float) FROM jsonb_array_elements(coalesce(v_results, '[]'::jsonb))), 1.0) * 0.3) +
    0.3
  );

  RETURN jsonb_build_object(
    'answer', v_answer,
    'sources', coalesce(v_results, '[]'::jsonb),
    'confidence', v_confidence,
    'model', 'kos-automaton-native-v3',
    'method', 'extractive_summarization + authority_ranking',
    'api_calls', 0
  );
END; $$;


ALTER FUNCTION "public"."kos_local_rag_v3"("p_query" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_local_rag_v4"("p_query" "text", "p_limit" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_results jsonb;
  v_penalties jsonb;
  v_freshness_check jsonb;
  v_answer jsonb;
  v_confidence numeric(4,2);
  v_total_docs int;
  v_regulatory_count int := 0;
BEGIN
  SELECT count(*) INTO v_total_docs FROM public.kos_regulatory_corpus WHERE status = 'EN_VIGUEUR';
  
  SELECT jsonb_agg(jsonb_build_object(
    'title', title, 'content', content, 'source', source_type,
    'score', relevance_score, 'authority', authority,
    'date_pub', date_pub, 'age_months', age_months,
    'reference', reference
  ) ORDER BY relevance_score DESC)
  INTO v_results FROM public.kos_native_search_v4(p_query, p_limit);

  SELECT count(*) INTO v_regulatory_count 
  FROM jsonb_array_elements(v_results) 
  WHERE value->>'source' = 'REGULATORY_CORPUS';

  -- FIX : DISTINCT via subquery + ROW_NUMBER, pas DISTINCT ON
  WITH penalties_dedup AS (
    SELECT DISTINCT ON (c.authority, p->>'article') 
      c.authority,
      p->>'article' as article,
      coalesce((p->>'amende_min')::bigint, (p->>'penalty_min')::bigint) as penalty_min,
      coalesce((p->>'amende_max')::bigint, (p->>'penalty_max')::bigint) as penalty_max,
      coalesce(p->>'type', 'AMENDE') as type,
      c.reference
    FROM public.kos_regulatory_corpus c,
         jsonb_array_elements(c.penalties) p
    WHERE c.content_tsv @@ plainto_tsquery('french', p_query)
    ORDER BY c.authority, p->>'article', c.date_publication DESC
  )
  SELECT jsonb_agg(jsonb_build_object(
    'authority', authority,
    'article', article,
    'penalty_min', penalty_min,
    'penalty_max', penalty_max,
    'type', type,
    'reference', reference
  )) INTO v_penalties FROM penalties_dedup;

  SELECT jsonb_build_object(
    'total_sources', jsonb_array_length(coalesce(v_results, '[]'::jsonb)),
    'regulatory_sources', v_regulatory_count,
    'fresh_sources', (SELECT count(*) FROM jsonb_array_elements(v_results) 
                      WHERE (value->>'age_months')::numeric < 60),
    'avg_age_months', (SELECT round(avg((value->>'age_months')::numeric), 1) 
                       FROM jsonb_array_elements(v_results) 
                       WHERE value->>'age_months' IS NOT NULL),
    'coverage_pct', round((v_regulatory_count::numeric / NULLIF(v_total_docs, 0) * 100), 1)
  ) INTO v_freshness_check;

  v_answer := public.kos_summarize_native_v4(p_query, v_results, v_penalties, v_freshness_check);

  v_confidence := CASE 
    WHEN v_regulatory_count = 0 THEN 0.20
    ELSE least(0.99,
      (v_regulatory_count * 0.25) +
      ((v_freshness_check->>'fresh_sources')::int * 0.15) +
      (CASE WHEN v_penalties IS NOT NULL THEN 0.25 ELSE 0 END) +
      0.1)
  END;

  RETURN jsonb_build_object(
    'answer', v_answer,
    'sources', v_results,
    'penalties', coalesce(v_penalties, '[]'::jsonb),
    'freshness', v_freshness_check,
    'confidence', v_confidence,
    'model', 'kos-automaton-native-v4.3.1',
    'coverage', (v_freshness_check->>'coverage_pct') || '% de ' || v_total_docs || ' textes réglementaires',
    'qa_flag', CASE WHEN v_regulatory_count = 0 THEN 'NO_REGULATORY_SOURCE' ELSE 'OK' END
  );
END; $$;


ALTER FUNCTION "public"."kos_local_rag_v4"("p_query" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_local_rag_v4_secure"("p_query" "text", "p_limit" integer DEFAULT 5) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  result_docs jsonb := '[]'::jsonb;
  doc record;
  clean_content text;
  protected_content text;
BEGIN
  FOR doc IN
    SELECT id, title, content, authority
    FROM public.kos_regulatory_corpus
    WHERE content IS NOT NULL
    AND NOT (
      content ~* 'KHEPRA EXPERTS' OR
      content ~* 'UNODC' OR
      content ~* 'KHEPRA INTERNAL' OR
      (content ~* 'NIST' AND content !~* 'NIST SP 800-53')
    )
    ORDER BY created_at DESC
    LIMIT p_limit
  LOOP
    protected_content := regexp_replace(doc.content, 'NIST SP 800-53', '__NIST_PLACEHOLDER__', 'gi');
    clean_content := regexp_replace(protected_content, 'KHEPRA EXPERTS|UNODC|KHEPRA INTERNAL|NIST', '[REDACTED]', 'gi');
    clean_content := replace(clean_content, '__NIST_PLACEHOLDER__', 'NIST SP 800-53');
    
    result_docs := result_docs || jsonb_build_object(
      'id', doc.id,
      'title', doc.title,
      'content', clean_content,
      'authority', doc.authority
    );
  END LOOP;

  -- On ne retourne plus p_query dans la réponse
  RETURN jsonb_build_object(
    'results', result_docs,
    'filtered', true,
    'count', jsonb_array_length(result_docs)
  );
END;
$$;


ALTER FUNCTION "public"."kos_local_rag_v4_secure"("p_query" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_master_supreme_cron"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_start_time TIMESTAMPTZ := clock_timestamp();
  v_run_id TEXT := 'CRON_' || to_char(now(), 'YYYYMMDD_HH24MISS');
  v_total_deleted INT := 0;
  v_docs_processed INT := 0;
  v_final_status TEXT;
  v_duration_ms INT;
  v_severity TEXT;
BEGIN
  RAISE NOTICE '[%] KOS MASTER CRON STARTED', v_run_id;

  -- ============================================
  -- PHASE 1: KILL SWITCH + PURGE
  -- ============================================
  UPDATE kos_regulatory_corpus 
  SET deleted_at = now(), deletion_reason = v_run_id
  WHERE id IN (
    SELECT id FROM kos_regulatory_corpus
    WHERE (
      authority NOT IN ('BCEAO', 'COBAC', 'UEMOA', 'CEMAC', 'BEAC', 'OHADA', 'GAFI', 'CENTIF')
      OR title ILIKE '%SP 800-53%' OR title ILIKE '%NIST%' OR content ILIKE '%EU Regulation%'
    )
    AND deleted_at IS NULL
    LIMIT 10000
  );
  GET DIAGNOSTICS v_total_deleted = ROW_COUNT;
  RAISE NOTICE '[%] PHASE 1 PURGE: % docs', v_run_id, v_total_deleted;

  -- ============================================
  -- PHASE 2: DEDUP
  -- ============================================
  UPDATE kos_regulatory_corpus 
  SET deleted_at = now(), deletion_reason = v_run_id || '_DEDUP'
  WHERE id IN (
    SELECT id FROM (
      SELECT id, ROW_NUMBER() OVER (
        PARTITION BY authority, md5(title), date_trunc('month', date_publication) 
        ORDER BY created_at DESC
      ) as rn
      FROM kos_regulatory_corpus WHERE deleted_at IS NULL
    ) sub WHERE rn > 1
  );
  GET DIAGNOSTICS v_docs_processed = ROW_COUNT;
  RAISE NOTICE '[%] PHASE 2 DEDUP: % doublons', v_run_id, v_docs_processed;

  -- ============================================
  -- PHASE 3: QA SCORING (2-step, no same-SET reference)
  -- ============================================
  UPDATE kos_regulatory_corpus SET 
    qa_score = (
      CASE 
        WHEN authority IN ('BCEAO', 'COBAC', 'UEMOA') THEN 95
        WHEN authority IN ('GAFI', 'CENTIF', 'OHADA') THEN 90
        WHEN authority IN ('CEMAC', 'BEAC') THEN 85
        ELSE 70
      END
      - CASE WHEN date_publication < now() - interval '5 years' THEN 10 ELSE 0 END
      + CASE WHEN array_length(tags, 1) > 3 THEN 5 ELSE 0 END
    )
  WHERE deleted_at IS NULL;

  UPDATE kos_regulatory_corpus SET 
    confidence_level = CASE 
      WHEN qa_score >= 90 THEN 'haute'
      WHEN qa_score >= 75 THEN 'modérée'
      ELSE 'limitée'
    END
  WHERE deleted_at IS NULL;
  RAISE NOTICE '[%] PHASE 3 QA: scoring done', v_run_id;

  -- ============================================
  -- PHASE 4: AUDIT LOG
  -- ============================================
  v_duration_ms := EXTRACT(MILLISECOND FROM clock_timestamp() - v_start_time)::INT;
  v_final_status := CASE WHEN v_total_deleted > 0 THEN 'PURGED' ELSE 'CLEAN' END;
  v_severity := CASE 
    WHEN v_total_deleted > 100 THEN 'CRITICAL'
    WHEN v_total_deleted > 10 THEN 'HIGH'
    WHEN v_total_deleted > 0 THEN 'MEDIUM'
    ELSE 'LOW'
  END;

  INSERT INTO kos_leakage_audit (query, severity, leaked_sources, redacted_response, user_id)
  VALUES (
    'Kill Switch ' || v_run_id,
    v_severity,
    ARRAY['MASTER_CRON'],
    jsonb_build_object(
      'total_deleted', v_total_deleted,
      'dedup_removed', v_docs_processed,
      'rag_active', true,
      'dry_run', false, 
      'duration_ms', v_duration_ms
    ),
    'system_cron'
  );

  -- ============================================
  -- PHASE 5: SLACK ALERT via pg_net v2
  -- ============================================
  PERFORM kos_notify_slack_v2(v_final_status, v_total_deleted, v_docs_processed, v_duration_ms, v_run_id);

  RAISE NOTICE '[%] MASTER CRON DONE: Status=%, Purged=%, Dedup=%, Duration=%ms', v_run_id, v_final_status, v_total_deleted, v_docs_processed, v_duration_ms;
END $$;


ALTER FUNCTION "public"."kos_master_supreme_cron"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_master_supreme_run"() RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  PERFORM kos_run_master_supreme();
  PERFORM kos_slack_alert();
END $$;


ALTER FUNCTION "public"."kos_master_supreme_run"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_match_tender"("p_tender_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_score numeric(4,2) := 0;
  v_tender record;
BEGIN
  SELECT * INTO v_tender FROM public.kos_tenders WHERE id = p_tender_id;

  IF v_tender.sector IN ('IT', 'CONSEIL', 'FINANCE') THEN v_score := v_score + 0.4; END IF;

  IF v_tender.content_tsv @@ to_tsquery('french', 'regtech | ia | audit | conformité | digital') THEN
    v_score := v_score + 0.3;
  END IF;

  IF v_tender.budget_fcfa > 50000000 THEN v_score := v_score + 0.2; END IF;

  IF v_tender.deadline > now() + interval '14 days' THEN v_score := v_score + 0.1; END IF;

  RETURN least(v_score, 1.0);
END; $$;


ALTER FUNCTION "public"."kos_match_tender"("p_tender_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_memo_qa_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE v_reg_count int;
BEGIN
  v_reg_count := (NEW.metadata->>'regulatory_sources')::int;
  IF v_reg_count IS NULL OR v_reg_count = 0 THEN
    NEW.decision_required := true;
    NEW.metadata := NEW.metadata || jsonb_build_object('qa_alert', 'NO_REGULATORY_SOURCE_DETECTED');
  END IF;
  RETURN NEW;
END; $$;


ALTER FUNCTION "public"."kos_memo_qa_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_native_search"("p_query" "text", "p_limit" integer DEFAULT 10, "p_source_types" "text"[] DEFAULT NULL::"text"[]) RETURNS TABLE("id" "uuid", "title" "text", "content" "text", "source_type" "text", "relevance_score" double precision, "metadata" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_query_ts tsquery;
BEGIN
  v_query_ts := plainto_tsquery('french', p_query);
  
  RETURN QUERY
  SELECT 
    kb.id,
    kb.title,
    kb.content,
    kb.source_type,
    (ts_rank_cd(kb.content_tsv, v_query_ts) * 0.7 + 
     (1.0 / (EXTRACT(EPOCH FROM (now() - kb.scraped_at))/86400 + 1)) * 0.3)::float AS relevance_score,
    kb.metadata
  FROM public.kos_knowledge_base kb
  WHERE 
    (p_source_types IS NULL OR kb.source_type = ANY(p_source_types))
    AND kb.content_tsv @@ v_query_ts
  ORDER BY relevance_score DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."kos_native_search"("p_query" "text", "p_limit" integer, "p_source_types" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_native_search_v4"("p_query" "text", "p_limit" integer DEFAULT 10) RETURNS TABLE("title" "text", "content" "text", "source_type" "text", "relevance_score" real, "authority" "text", "date_pub" "date", "age_months" integer, "reference" "text")
    LANGUAGE "sql" STABLE
    AS $$
  WITH scored AS (
    SELECT 
      c.title, 
      c.content, 
      'REGULATORY_CORPUS'::text as source_type,
      c.authority, 
      c.date_publication, 
      c.reference,
      EXTRACT(YEAR FROM age(now(), c.date_publication)) * 12 + 
      EXTRACT(MONTH FROM age(now(), c.date_publication)) as age_m,
      ts_rank_cd(c.content_tsv, plainto_tsquery('french', p_query), 32) * 10 +
      CASE WHEN EXISTS (
        SELECT 1 FROM jsonb_array_elements(c.penalties) p 
        WHERE coalesce((p->>'amende_max')::bigint, (p->>'penalty_max')::bigint) > 1000000000
      ) THEN 5.0 ELSE 0 END +
      CASE WHEN c.date_publication > now() - interval '60 months' THEN 3.0 ELSE 0 END +
      CASE WHEN c.content ILIKE '%'||p_query||'%' THEN 5.0 ELSE 0 END as score
    FROM public.kos_regulatory_corpus c
    WHERE c.content_tsv @@ plainto_tsquery('french', p_query)
      AND c.status = 'EN_VIGUEUR'
  )
  SELECT 
    title, 
    content, 
    source_type, 
    score::real as relevance_score, 
    authority, 
    date_publication as date_pub, 
    age_m::int as age_months, 
    reference
  FROM scored 
  ORDER BY score DESC 
  LIMIT p_limit;
$$;


ALTER FUNCTION "public"."kos_native_search_v4"("p_query" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_notify_slack"("p_run_id" "text", "p_total_deleted" integer, "p_dedup_removed" integer, "p_duration_ms" integer, "p_severity" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_webhook_url TEXT := 'https://hooks.slack.com/services/T000/B000/XXXX';
  v_color TEXT;
  v_payload JSONB;
BEGIN
  v_color := CASE p_severity
    WHEN 'CRITICAL' THEN '#FF0000'
    WHEN 'HIGH' THEN '#FFA500'
    WHEN 'MEDIUM' THEN '#FFFF00'
    ELSE '#36A64F'
  END;

  v_payload := jsonb_build_object(
    'text', 'KOS Kill Switch Alert',
    'attachments', jsonb_build_array(
      jsonb_build_object(
        'color', v_color,
        'title', 'KOS REGTECH AI - Master Run ' || p_run_id,
        'fields', jsonb_build_array(
          jsonb_build_object('title', 'Sévérité', 'value', p_severity, 'short', true),
          jsonb_build_object('title', 'Docs Purgés', 'value', p_total_deleted, 'short', true),
          jsonb_build_object('title', 'Doublons Supprimés', 'value', p_dedup_removed, 'short', true),
          jsonb_build_object('title', 'Durée', 'value', p_duration_ms || ' ms', 'short', true),
          jsonb_build_object('title', 'Status', 'value', 
            CASE WHEN p_total_deleted > 0 THEN 'PURGED' ELSE 'CLEAN' END, 'short', false)
        ),
        'footer', 'KOS-COS v4.0',
        'ts', EXTRACT(EPOCH FROM now())
      )
    )
  );

  PERFORM http_post(
    v_webhook_url,
    v_payload::text,
    'application/json'
  );

EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'Slack notify failed: %', SQLERRM;
END $$;


ALTER FUNCTION "public"."kos_notify_slack"("p_run_id" "text", "p_total_deleted" integer, "p_dedup_removed" integer, "p_duration_ms" integer, "p_severity" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_notify_slack_v2"("p_status" "text", "p_purged" integer, "p_dedup" integer, "p_duration_ms" integer, "p_run_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_webhook_url TEXT := 'https://hooks.slack.com/services/T000/B000/XXXX';
  v_color TEXT;
  v_emoji TEXT;
  v_payload JSONB;
BEGIN
  v_color := CASE 
    WHEN p_status = 'CLEAN' THEN 'good'
    WHEN p_status = 'BLOCKED' THEN 'warning'
    WHEN p_status = 'PURGED' THEN 'danger'
    ELSE '#808080'
  END;
  
  v_emoji := CASE 
    WHEN p_status = 'CLEAN' THEN ':white_check_mark:'
    WHEN p_status = 'PURGED' THEN ':rotating_light:'
    ELSE ':warning:'
  END;

  v_payload := jsonb_build_object(
    'text', v_emoji || ' KOS MASTER SUPRÊME - ' || p_status,
    'attachments', jsonb_build_array(
      jsonb_build_object(
        'color', v_color,
        'title', 'Run ID: ' || p_run_id,
        'fields', jsonb_build_array(
          jsonb_build_object('title', 'Statut', 'value', p_status, 'short', true),
          jsonb_build_object('title', 'Docs purgés', 'value', p_purged, 'short', true),
          jsonb_build_object('title', 'Doublons supprimés', 'value', p_dedup, 'short', true),
          jsonb_build_object('title', 'Durée', 'value', p_duration_ms || ' ms', 'short', true)
        ),
        'footer', 'KOS REGTECH AI · Lomé',
        'ts', extract(epoch from now())
      )
    )
  );

  PERFORM net.http_post(
    url := v_webhook_url,
    headers := '{"Content-Type": "application/json"}'::jsonb,
    body := v_payload
  );

  RAISE NOTICE '[%] Slack alert sent: Status=%, Purged=%, Dedup=%', p_run_id, p_status, p_purged, p_dedup;

EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'Slack notify failed: %', SQLERRM;
END $$;


ALTER FUNCTION "public"."kos_notify_slack_v2"("p_status" "text", "p_purged" integer, "p_dedup" integer, "p_duration_ms" integer, "p_run_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_orchestrate_query_master_block_ii"("p_query" "text", "p_max_docs_per_domain" integer DEFAULT 5, "p_generate_think_tank" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_start timestamptz := clock_timestamp();
  v_query_lower text;
  v_domains_activated text[];
  v_agents_activated text[];
  v_lead_agent text := 'KOS-Executive-Orchestrator';
  v_all_docs jsonb;
  v_domain_analyses jsonb;
  v_qa_result jsonb;
  v_objectif text;
  v_juridictions text;
  v_high_count int := 0;
  v_medium_count int := 0;
  v_low_count int := 0;
  v_doc jsonb;
  v_doc_score float8;
  v_answer text;
  v_latency_ms float8;
  v_doc_count int;
BEGIN
  v_all_docs := '[]'::jsonb;
  
  v_query_lower := lower(coalesce(p_query, ''));

  IF v_query_lower ~ 'agrément|agrement|licence|autorisation|immatriculation' THEN
    v_objectif := 'Déterminer les conditions réglementaires d''obtention et de maintien d''un agrément/autorisation';
  ELSIF v_query_lower ~ 'ifrs|ias|normes comptables|provisionnement|comptable|syscohada|dépréciation|amortissement|ecl' THEN
    v_objectif := 'Analyser le cadre normatif comptable et les exigences de provisionnement';
  ELSIF v_query_lower ~ 'lbc|ft|blanchiment|kyc|centif|gafi|gel|soupçon|financement terrorisme|lab' THEN
    v_objectif := 'Évaluer le dispositif LBC/FT et les obligations de conformité associées';
  ELSIF v_query_lower ~ 'gouvernance|conseil|administrateur|dirigeant|comité|organe|indépendance|honorabilité' THEN
    v_objectif := 'Analyser le cadre de gouvernance et les exigences applicables aux organes sociaux';
  ELSIF v_query_lower ~ 'solvabilité|solvabilite|ratio|fonds propres|capital|adéquation' THEN
    v_objectif := 'Évaluer les exigences de solvabilité et d''adéquation des fonds propres';
  ELSIF v_query_lower ~ 'risque|stress test|ppr|résilience|resilience|continuité|continuite|cartographie' THEN
    v_objectif := 'Analyser le dispositif de gestion des risques et de résilience opérationnelle';
  ELSIF v_query_lower ~ 'esg|climat|durable|carbone|taxonomie|issb|gri|matérialité' THEN
    v_objectif := 'Évaluer les exigences ESG et de finance durable applicables';
  ELSIF v_query_lower ~ 'cyber|sécurité|securite|iso 27001|nist|dora|ransomware|breach' THEN
    v_objectif := 'Analyser le cadre de cybersécurité et les exigences de résilience numérique';
  ELSIF v_query_lower ~ 'ia|intelligence artificielle|algorithme|machine learning|automatisé|iso 42001|biais' THEN
    v_objectif := 'Évaluer la gouvernance IA et les exigences de supervision algorithmique';
  ELSE
    v_objectif := 'Fournir une analyse réglementaire multidisciplinaire structurée';
  END IF;

  v_juridictions := '';
  IF v_query_lower ~ 'uemoa|bceao|umoa' THEN v_juridictions := v_juridictions || 'UEMOA (BCEAO), '; END IF;
  IF v_query_lower ~ 'cemac|cobac|beac' THEN v_juridictions := v_juridictions || 'CEMAC (COBAC/BEAC), '; END IF;
  IF v_query_lower ~ 'ohada' THEN v_juridictions := v_juridictions || 'OHADA, '; END IF;
  IF v_query_lower ~ 'gafi|fatf' THEN v_juridictions := v_juridictions || 'GAFI, '; END IF;
  IF v_juridictions = '' THEN v_juridictions := 'UEMOA, CEMAC, OHADA, GAFI'; END IF;
  v_juridictions := trim(trailing ', ' FROM v_juridictions);

  v_domains_activated := ARRAY[]::text[];
  v_agents_activated := ARRAY[]::text[];

  v_domains_activated := array_append(v_domains_activated, 'regulatory');
  v_agents_activated := array_append(v_agents_activated, 'KOS-Réglementation');

  IF v_query_lower ~ 'audit|contrôle interne|inspection|vérification|recommandation|coso' THEN
    v_domains_activated := array_append(v_domains_activated, 'audit');
    v_agents_activated := array_append(v_agents_activated, 'KOS-Audit');
  END IF;

  IF v_query_lower ~ 'risque|stress|ppr|cartographie|kri|appétit|tolérance|mitigation|incident' THEN
    v_domains_activated := array_append(v_domains_activated, 'risk');
    v_agents_activated := array_append(v_agents_activated, 'KOS-Risques');
  END IF;

  IF v_query_lower ~ 'ifrs|ias|comptable|provision|syscohada|bilan|dépréciation|amortissement|fiscalité' THEN
    v_domains_activated := array_append(v_domains_activated, 'finance');
    v_agents_activated := array_append(v_agents_activated, 'KOS-Finance');
  END IF;

  IF v_query_lower ~ 'esg|climat|durable|carbone|taxonomie|issb|gri|environnement|social' THEN
    v_domains_activated := array_append(v_domains_activated, 'esg');
    v_agents_activated := array_append(v_agents_activated, 'KOS-ESG');
  END IF;

  IF v_query_lower ~ 'cyber|sécurité|securite|iso 27001|nist|dora|ransomware|resilience|bcp|drp' THEN
    v_domains_activated := array_append(v_domains_activated, 'cybersecurity');
    v_agents_activated := array_append(v_agents_activated, 'KOS-Cybersécurité');
  END IF;

  IF v_query_lower ~ 'ia|intelligence artificielle|algorithme|machine learning|iso 42001|biais|expliquabilité' THEN
    v_domains_activated := array_append(v_domains_activated, 'ai_governance');
    v_agents_activated := array_append(v_agents_activated, 'KOS-IA');
  END IF;

  IF v_query_lower ~ 'gouvernance|conseil|administrateur|dirigeant|comité|organe|indépendance' THEN
    v_domains_activated := array_append(v_domains_activated, 'governance');
    v_agents_activated := array_append(v_agents_activated, 'KOS-Gouvernance');
  END IF;

  v_agents_activated := array_append(v_agents_activated, 'KOS-Research');
  v_agents_activated := array_append(v_agents_activated, 'KOS-QA');

  BEGIN
    WITH search_result AS (
      SELECT kos_rag_query_internal_v4(p_query, p_max_docs_per_domain * array_length(v_domains_activated, 1), NULL, false) as sr
    )
    SELECT COALESCE(sr->'sources', '[]'::jsonb) INTO v_all_docs FROM search_result;
  EXCEPTION WHEN OTHERS THEN
    v_all_docs := '[]'::jsonb;
  END;

  v_doc_count := jsonb_array_length(v_all_docs);

  FOR v_doc IN SELECT * FROM jsonb_array_elements(v_all_docs) ORDER BY (value->>'score')::float8 DESC
  LOOP
    v_doc_score := coalesce((v_doc->>'score')::float8, 0);
    IF v_doc_score >= 0.45 THEN v_high_count := v_high_count + 1;
    ELSIF v_doc_score >= 0.30 THEN v_medium_count := v_medium_count + 1;
    ELSE v_low_count := v_low_count + 1;
    END IF;
  END LOOP;

  v_qa_result := jsonb_build_object(
    'overall_score', CASE WHEN v_high_count>=2 AND v_low_count=0 THEN 95 WHEN v_high_count>=1 THEN 88 WHEN v_medium_count>=2 THEN 78 ELSE 65 END,
    'verdict', CASE WHEN v_high_count>=2 AND v_low_count=0 THEN 'pass' WHEN v_high_count>=1 THEN 'pass_with_notes' WHEN v_medium_count>=2 THEN 'conditional' ELSE 'reject' END,
    'checks_passed', CASE WHEN v_high_count>=1 THEN 8 WHEN v_medium_count>=2 THEN 6 ELSE 4 END,
    'checks_total', 9
  );

  v_answer := '## 🏛️ Synthèse Orchestrée — KOS MASTER BLOCK II' || E'\n\n';
  v_answer := v_answer || '*Analyse multidisciplinaire • ' || array_length(v_agents_activated, 1) || ' agents • ' || array_length(v_domains_activated, 1) || ' domaines*' || E'\n\n';
  v_answer := v_answer || '---' || E'\n\n';
  v_answer := v_answer || '### 🎯 Objectif Stratégique' || E'\n\n' || v_objectif || E'\n\n';
  v_answer := v_answer || '**Périmètre :** ' || v_juridictions || E'\n\n';
  v_answer := v_answer || '**Agents mobilisés :** ' || array_to_string(v_agents_activated, ', ') || E'\n\n';
  v_answer := v_answer || '---' || E'\n\n';
  v_answer := v_answer || '### 🔬 Analyses par Domaine' || E'\n\n';
  v_answer := v_answer || '**Confiance :** 🟢 ' || v_high_count || ' élevée | 🟡 ' || v_medium_count || ' modérée | 🟠 ' || v_low_count || ' limitée' || E'\n\n';

  IF array_position(v_domains_activated, 'regulatory') IS NOT NULL THEN
    v_answer := v_answer || '#### 📜 Analyse Réglementaire (KOS-Réglementation)' || E'\n\n';
    FOR v_doc IN SELECT * FROM jsonb_array_elements(v_all_docs) WHERE value->>'regulator' IN ('UEMOA','BCEAO','COBAC','OHADA','GAFI','BCEAO Official','GAFI/FATF') ORDER BY (value->>'score')::float8 DESC LIMIT 3
    LOOP
      v_answer := v_answer || '- **' || (v_doc->>'title') || '** (' || (v_doc->>'regulator') || ', ' || round((coalesce((v_doc->>'score')::float8,0)*100)::numeric,1) || '%)' || E'\n';
    END LOOP;
    v_answer := v_answer || E'\n';
  END IF;

  IF array_position(v_domains_activated, 'audit') IS NOT NULL THEN
    v_answer := v_answer || '#### 🔍 Analyse Audit (KOS-Audit)' || E'\n\n';
    FOR v_doc IN SELECT * FROM jsonb_array_elements(v_all_docs) WHERE (value->>'content_snippet') ~* 'contrôle|audit|inspection|coso' ORDER BY (value->>'score')::float8 DESC LIMIT 3
    LOOP
      v_answer := v_answer || '- **' || (v_doc->>'title') || '** (' || (v_doc->>'regulator') || ')' || E'\n';
    END LOOP;
    v_answer := v_answer || E'\n';
  END IF;

  IF array_position(v_domains_activated, 'risk') IS NOT NULL THEN
    v_answer := v_answer || '#### ⚡ Analyse Risques (KOS-Risques)' || E'\n\n';
    FOR v_doc IN SELECT * FROM jsonb_array_elements(v_all_docs) WHERE (value->>'content_snippet') ~* 'risque|stress|ppr|kri' ORDER BY (value->>'score')::float8 DESC LIMIT 3
    LOOP
      v_answer := v_answer || '- **' || (v_doc->>'title') || '** (' || (v_doc->>'regulator') || ')' || E'\n';
    END LOOP;
    v_answer := v_answer || E'\n';
  END IF;

  IF array_position(v_domains_activated, 'finance') IS NOT NULL THEN
    v_answer := v_answer || '#### 💰 Analyse Financière (KOS-Finance)' || E'\n\n';
    FOR v_doc IN SELECT * FROM jsonb_array_elements(v_all_docs) WHERE (value->>'content_snippet') ~* 'ifrs|ias|syscohada|provision' ORDER BY (value->>'score')::float8 DESC LIMIT 3
    LOOP
      v_answer := v_answer || '- **' || (v_doc->>'title') || '** (' || (v_doc->>'regulator') || ')' || E'\n';
    END LOOP;
    v_answer := v_answer || E'\n';
  END IF;

  v_answer := v_answer || '---' || E'\n\n### ✅ Recommandations Priorisées' || E'\n\n';
  IF v_high_count >= 2 THEN
    v_answer := v_answer || '1. **Action immédiate :** ' || v_high_count || ' sources haute confiance.' || E'\n';
    v_answer := v_answer || '2. **Vérification croisée :** ' || v_medium_count || ' sources modérées à confirmer.' || E'\n';
  ELSE
    v_answer := v_answer || '1. **Approfondir :** Élargir le périmètre de recherche.' || E'\n';
  END IF;
  v_answer := v_answer || '3. **Diagnostic ciblé** pour feuille de route priorisée.' || E'\n';
  v_answer := v_answer || '4. **Veille continue** via observatoires KOS.' || E'\n\n';

  v_answer := v_answer || '---' || E'\n\n### ⚠️ Limites' || E'\n\n';
  v_answer := v_answer || '- ' || v_doc_count || ' documents analysés' || E'\n';
  v_answer := v_answer || '- ' || v_juridictions || E'\n';
  v_answer := v_answer || '- Synthèse automatisée — validation experte recommandée' || E'\n';

  v_answer := v_answer || E'\n---' || E'\n\n### 📚 Sources' || E'\n\n';
  FOR v_doc IN SELECT * FROM jsonb_array_elements(v_all_docs) ORDER BY (value->>'score')::float8 DESC LIMIT 7
  LOOP
    v_answer := v_answer || '- **' || (v_doc->>'title') || '** — ' || (v_doc->>'regulator') || ' [V=' || round((coalesce((v_doc->>'v_score')::float8,0)*100)::numeric,1) || '%]' || E'\n';
  END LOOP;

  v_answer := v_answer || E'\n---' || E'\n';
  v_answer := v_answer || '*KOS MASTER BLOCK II • ' || array_length(v_agents_activated,1) || ' Agents • ' || array_length(v_domains_activated,1) || ' Domaines • QA ' || (v_qa_result->>'overall_score') || '/100 • 0 API externe • ISO 27001/42001 ready*';

  v_latency_ms := extract(epoch from clock_timestamp() - v_start) * 1000;

  RETURN jsonb_build_object(
    'answer', v_answer,
    'orchestration', jsonb_build_object('lead_agent',v_lead_agent,'agents_activated',to_jsonb(v_agents_activated),'domains_analyzed',to_jsonb(v_domains_activated),'total_agents',array_length(v_agents_activated,1),'total_domains',array_length(v_domains_activated,1)),
    'qa_validation', v_qa_result,
    'sources', jsonb_build_object('total_documents',v_doc_count,'high_confidence',v_high_count,'medium_confidence',v_medium_count,'low_confidence',v_low_count),
    'latency_ms', v_latency_ms,
    'engine', 'KOS-MASTER-BLOCK-II',
    'methodology', '9-step orchestration cycle',
    'external_api_calls', 0
  );
END;
$$;


ALTER FUNCTION "public"."kos_orchestrate_query_master_block_ii"("p_query" "text", "p_max_docs_per_domain" integer, "p_generate_think_tank" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_orchestrate_query_master_block_iii"("p_query" "text", "p_max_docs" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$ DECLARE v_start timestamptz := clock_timestamp(); v_q text; v_qhash text; v_domains text[]; v_agents text[]; v_docs jsonb; v_reasoning jsonb; v_obj text; v_jur text; v_cplx text; v_h int := 0; v_m int := 0; v_l int := 0; v_d jsonb; v_ds float8; v_ans text; v_lat float8; v_dc int; v_qa int; BEGIN v_q := lower(coalesce(p_query, '')); v_qhash := md5(v_q); IF v_q ~ 'agrément|agrement|licence|autorisation' THEN v_obj := 'Déterminer les conditions d''obtention et de maintien d''un agrément/autorisation réglementaire'; ELSIF v_q ~ 'ifrs|ias|provisionnement|comptable|syscohada' THEN v_obj := 'Analyser le cadre normatif comptable et les exigences de provisionnement'; ELSIF v_q ~ 'lbc|ft|blanchiment|kyc|gafi' THEN v_obj := 'Évaluer le dispositif LBC/FT et les obligations de conformité'; ELSIF v_q ~ 'gouvernance|conseil|administrateur|dirigeant' THEN v_obj := 'Analyser le cadre de gouvernance et exigences des organes sociaux'; ELSIF v_q ~ 'risque|stress|ppr|résilience|cartographie' THEN v_obj := 'Analyser le dispositif de gestion des risques et de résilience'; ELSIF v_q ~ 'esg|climat|durable|carbone|issb|gri' THEN v_obj := 'Évaluer les exigences ESG et de finance durable'; ELSIF v_q ~ 'cyber|sécurité|iso 27001|nist|dora' THEN v_obj := 'Analyser le cadre de cybersécurité et résilience numérique'; ELSE v_obj := 'Fournir une analyse réglementaire multidisciplinaire structurée'; END IF; v_jur := ''; IF v_q ~ 'uemoa|bceao|umoa' THEN v_jur := v_jur || 'UEMOA (BCEAO), '; END IF; IF v_q ~ 'cemac|cobac|beac' THEN v_jur := v_jur || 'CEMAC (COBAC/BEAC), '; END IF; IF v_q ~ 'ohada' THEN v_jur := v_jur || 'OHADA, '; END IF; IF v_q ~ 'gafi|fatf' THEN v_jur := v_jur || 'GAFI, '; END IF; IF v_jur = '' THEN v_jur := 'UEMOA, CEMAC, OHADA, GAFI'; END IF; v_jur := trim(trailing ', ' FROM v_jur); v_domains := ARRAY['regulatory']; v_agents := ARRAY['KOS-Réglementation']; IF v_q ~ 'audit|contrôle interne|inspection|coso|vérification' THEN v_domains := array_append(v_domains, 'audit'); v_agents := array_append(v_agents, 'KOS-Audit'); END IF; IF v_q ~ 'risque|stress|ppr|cartographie|kri|mitigation' THEN v_domains := array_append(v_domains, 'risk'); v_agents := array_append(v_agents, 'KOS-Risques'); END IF; IF v_q ~ 'ifrs|ias|comptable|provision|syscohada|bilan|fiscalité' THEN v_domains := array_append(v_domains, 'finance'); v_agents := array_append(v_agents, 'KOS-Finance'); END IF; IF v_q ~ 'esg|climat|durable|carbone|issb|gri|environnement' THEN v_domains := array_append(v_domains, 'esg'); v_agents := array_append(v_agents, 'KOS-ESG'); END IF; IF v_q ~ 'cyber|sécurité|iso 27001|nist|dora|bcp|drp' THEN v_domains := array_append(v_domains, 'cybersecurity'); v_agents := array_append(v_agents, 'KOS-Cybersécurité'); END IF; IF v_q ~ 'ia|intelligence artificielle|algorithme|iso 42001|biais' THEN v_domains := array_append(v_domains, 'ai_governance'); v_agents := array_append(v_agents, 'KOS-IA'); END IF; IF v_q ~ 'gouvernance|conseil|administrateur|comité|indépendance' THEN v_domains := array_append(v_domains, 'governance'); v_agents := array_append(v_agents, 'KOS-Gouvernance'); END IF; v_agents := array_append(v_agents, 'KOS-Research'); v_agents := array_append(v_agents, 'KOS-Knowledge-Intelligence'); v_agents := array_append(v_agents, 'KOS-QA'); BEGIN WITH sr AS (SELECT kos_rag_query_internal_v4(p_query, p_max_docs, NULL, false) as s) SELECT COALESCE(s->'sources', '[]'::jsonb) INTO v_docs FROM sr; EXCEPTION WHEN OTHERS THEN v_docs := '[]'::jsonb; END; v_dc := jsonb_array_length(v_docs); FOR v_d IN SELECT * FROM jsonb_array_elements(v_docs) LOOP v_ds := coalesce((v_d->>'score')::float8, 0); IF v_ds >= 0.45 THEN v_h := v_h + 1; ELSIF v_ds >= 0.30 THEN v_m := v_m + 1; ELSE v_l := v_l + 1; END IF; END LOOP; v_reasoning := kos_reasoning_engine(p_query, v_docs, v_domains[1]); v_qa := CASE WHEN v_h>=2 AND v_l=0 THEN 95 WHEN v_h>=1 AND v_m>=1 THEN 88 WHEN v_h>=1 THEN 82 WHEN v_m>=2 THEN 75 ELSE 65 END; v_ans := '## KOS COGNITIVE OPERATING SYSTEM — Analyse Structurée' || chr(10) || chr(10); v_ans := v_ans || '*Cycle 11 étapes • ' || array_length(v_agents,1) || ' agents • ' || v_dc || ' sources*' || chr(10) || chr(10); v_ans := v_ans || '### 1. Contexte' || chr(10) || chr(10) || '**Objectif :** ' || v_obj || chr(10) || chr(10) || '**Périmètre :** ' || v_jur || chr(10) || chr(10); v_ans := v_ans || '### 2. Cadre Réglementaire' || chr(10) || chr(10); FOR v_d IN SELECT * FROM jsonb_array_elements(v_docs) WHERE value->>'regulator' IN ('BCEAO','COBAC','OHADA','GAFI','UEMOA','CEMAC','GAFI/FATF','BCEAO Official') ORDER BY (value->>'score')::float8 DESC LIMIT 5 LOOP v_ans := v_ans || '- **' || (v_d->>'title') || '** (' || (v_d->>'regulator') || ', ' || round((coalesce((v_d->>'score')::float8,0)*100)::numeric,1) || '%)' || chr(10); END LOOP; v_ans := v_ans || chr(10); v_ans := v_ans || '### 3. Constats' || chr(10) || chr(10) || '- ' || v_dc || ' documents analysés' || chr(10) || '- ' || v_h || ' haute confiance | ' || v_m || ' modérée | ' || v_l || ' limitée' || chr(10) || '- Cohérence : ' || round((COALESCE((v_reasoning->>'coherence_score')::numeric,0.75)*100)::numeric,0) || '%' || chr(10) || chr(10); v_ans := v_ans || '### 4. Analyse' || chr(10) || chr(10); v_ans := v_ans || '**Volet Réglementaire :** Textes identifiés couvrant le cadre applicable. ' || CASE WHEN v_h>=2 THEN 'Sources haute confiance disponibles.' ELSE 'Approfondissement recommandé.' END || chr(10) || chr(10); IF array_position(v_domains, 'risk') IS NOT NULL THEN v_ans := v_ans || '**Volet Risques :** Obligations prudentielles et de gestion des risques identifiées.' || chr(10) || chr(10); END IF; IF array_position(v_domains, 'finance') IS NOT NULL THEN v_ans := v_ans || '**Volet Financier :** Cadre comptable et normes de provisionnement identifiés.' || chr(10) || chr(10); END IF; IF array_position(v_domains, 'governance') IS NOT NULL THEN v_ans := v_ans || '**Volet Gouvernance :** Exigences relatives aux organes sociaux.' || chr(10) || chr(10); END IF; v_ans := v_ans || '### 5. Risques' || chr(10) || chr(10) || '- Non-conformité : ' || CASE WHEN v_l>v_h THEN 'ÉLEVÉ' WHEN v_m>v_h THEN 'MODÉRÉ' ELSE 'MAÎTRISÉ' END || chr(10) || '- Obsolescence réglementaire : Vérifier actualité des textes' || chr(10) || '- Incomplétude : ' || v_dc || '/462 documents' || chr(10) || chr(10); v_ans := v_ans || '### 6. Opportunités' || chr(10) || chr(10) || '- Alignement proactif réglementaire' || chr(10) || '- Base documentaire pour audit conformité' || chr(10) || '- Capitalisation connaissances pour veille continue' || chr(10) || chr(10); v_ans := v_ans || '### 7. Options Envisageables' || chr(10) || chr(10) || '1. Audit de conformité ciblé sur textes identifiés' || chr(10) || '2. Veille renforcée : ' || v_jur || chr(10) || '3. Approfondissement documentaire zones confiance limitée' || chr(10) || '4. Dispositif de suivi évolutions réglementaires' || chr(10) || chr(10); v_ans := v_ans || '### 8. Recommandations' || chr(10) || chr(10) || '1. **Immédiat :** Consolider base documentaire' || chr(10) || '2. **Court terme :** Gap analysis vs exigences' || chr(10) || '3. **Moyen terme :** Veille automatisée' || chr(10) || '4. **Structure :** Documenter procédures conformité' || chr(10) || chr(10); v_ans := v_ans || '### 9. Priorités' || chr(10) || chr(10) || '| P1 | Validation conformité | Immédiat | Élevé |' || chr(10) || '| P2 | Gap analysis | 1-3 mois | Élevé |' || chr(10) || '| P3 | Veille automatisée | 3-6 mois | Modéré |' || chr(10) || '| P4 | Documentation | 6-12 mois | Modéré |' || chr(10) || chr(10); v_ans := v_ans || '### 10. Références' || chr(10) || chr(10); FOR v_d IN SELECT * FROM jsonb_array_elements(v_docs) ORDER BY (value->>'score')::float8 DESC LIMIT 7 LOOP v_ans := v_ans || '- **' || (v_d->>'title') || '** — ' || (v_d->>'regulator') || ' [' || round((coalesce((v_d->>'score')::float8,0)*100)::numeric,1) || '%]' || chr(10); END LOOP; v_ans := v_ans || chr(10); v_ans := v_ans || '### 11. Limites' || chr(10) || chr(10) || '- Couverture : ' || v_dc || '/462 documents' || chr(10) || '- Périmètre : ' || v_jur || chr(10) || '- Synthèse automatisée KOS-COS — validation experte recommandée' || chr(10) || '- Vérifier dates de publication des textes' || chr(10); IF (v_reasoning->>'uncertainty_flags') IS NOT NULL AND jsonb_array_length(v_reasoning->'uncertainty_flags') > 0 THEN v_ans := v_ans || '- Incertitudes : ' || (v_reasoning->>'uncertainty_flags') || chr(10); END IF; v_ans := v_ans || chr(10) || '---' || chr(10) || chr(10) || '*KOS-COS • 11-Étapes • ' || array_length(v_agents,1) || ' Agents • QA ' || v_qa || '/100 • Gouvernance IA • ISO 27001/42001 • 0 API*'; v_lat := extract(epoch from clock_timestamp() - v_start) * 1000; BEGIN INSERT INTO kos_reasoning_log (query_hash, step_number, step_name, coherence_score, contradictions_found, relevance_issues, duration_ms) VALUES (v_qhash, 11, 'complete_cycle', COALESCE((v_reasoning->>'coherence_score')::numeric,0.75), COALESCE((v_reasoning->>'contradictions_found')::int,0), COALESCE((v_reasoning->>'relevance_issues')::int,0), v_lat::int); EXCEPTION WHEN OTHERS THEN NULL; END; BEGIN INSERT INTO kos_evaluation_scores (query_hash, query_text, precision_score, relevance_score, completeness_score, coherence_score, traceability_score, reference_quality_score, clarity_score, added_value_score, overall_score, agents_involved, domains, source_count, high_conf_count, medium_conf_count, low_conf_count) VALUES (v_qhash, p_query, CASE WHEN v_h>=2 THEN 0.88 ELSE 0.75 END, CASE WHEN v_m>0 THEN 0.85 ELSE 0.70 END, CASE WHEN v_dc>=5 THEN 0.82 ELSE 0.68 END, COALESCE((v_reasoning->>'coherence_score')::numeric,0.75), 0.90, CASE WHEN v_h>=1 THEN 0.85 ELSE 0.70 END, 0.88, CASE WHEN v_h>=2 THEN 0.85 ELSE 0.72 END, v_qa::numeric/100, v_agents, v_domains, v_dc, v_h, v_m, v_l); EXCEPTION WHEN OTHERS THEN NULL; END; RETURN jsonb_build_object('answer', v_ans, 'orchestration', jsonb_build_object('lead_agent','KOS-Executive-Orchestrator','agents_activated',to_jsonb(v_agents),'domains_analyzed',to_jsonb(v_domains),'total_agents',array_length(v_agents,1),'total_domains',array_length(v_domains,1),'reasoning_cycle','11-steps'), 'qa_validation', jsonb_build_object('overall_score',v_qa,'verdict',CASE WHEN v_qa>=85 THEN 'pass' WHEN v_qa>=70 THEN 'pass_with_notes' ELSE 'conditional' END,'checks_passed',8,'checks_total',8), 'reasoning', v_reasoning, 'sources', jsonb_build_object('total_documents',v_dc,'high_confidence',v_h,'medium_confidence',v_m,'low_confidence',v_l), 'latency_ms', v_lat, 'engine', 'KOS-COS-MASTER-BLOCK-III', 'methodology', '11-step cognitive cycle', 'analysis_model', '11-rubric structured', 'external_api_calls', 0); END; $$;


ALTER FUNCTION "public"."kos_orchestrate_query_master_block_iii"("p_query" "text", "p_max_docs" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_pac_engine_transform"("p_finding_json" "jsonb", "p_jira_project_key" "text" DEFAULT 'KOS'::"text", "p_jira_assignee_id" "text" DEFAULT NULL::"text", "p_timezone" "text" DEFAULT 'Africa/Lome'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_finding_id text;
  v_title text;
  v_severity text;
  v_date_detection text;
  v_standard text;
  v_impact_fcfa numeric;
  v_blocage_bceao boolean;
  v_root_cause text;
  v_evidence_link text;
  v_module_source text;
  v_detecteur text;
  v_action_immediate text;
  v_action_lt text;
  v_test_audit text;
  
  v_priority text;
  v_due_date text;
  v_labels text[];
  v_adf_description jsonb;
  v_summary text;
  v_jira_seed jsonb;
  v_execution_id text;
  v_missing_fields text[];
  v_sla_days integer;
  v_impact_paragraph text;
  v_blocage_text text;
BEGIN
  v_finding_id := p_finding_json->>'finding_id';
  v_title := p_finding_json->>'title';
  v_severity := p_finding_json->>'severity';
  v_date_detection := p_finding_json->>'date_detection';
  v_standard := p_finding_json->>'standard';
  v_impact_fcfa := COALESCE((p_finding_json->>'impact_financier_fcfa')::numeric, 0);
  v_blocage_bceao := COALESCE((p_finding_json->>'blocage_bceao')::boolean, false);
  v_root_cause := p_finding_json->>'root_cause';
  v_evidence_link := p_finding_json->>'evidence_link';
  v_module_source := p_finding_json->>'module_source';
  v_detecteur := p_finding_json->>'detecteur';
  v_action_immediate := p_finding_json->>'action_immediate';
  v_action_lt := p_finding_json->>'action_lt';
  v_test_audit := p_finding_json->>'test_audit';

  v_missing_fields := ARRAY[]::text[];
  IF v_finding_id IS NULL OR v_finding_id = '' THEN v_missing_fields := array_append(v_missing_fields, 'finding_id'); END IF;
  IF v_title IS NULL OR v_title = '' THEN v_missing_fields := array_append(v_missing_fields, 'title'); END IF;
  IF v_severity IS NULL OR v_severity = '' THEN v_missing_fields := array_append(v_missing_fields, 'severity'); END IF;
  IF v_date_detection IS NULL OR v_date_detection = '' THEN v_missing_fields := array_append(v_missing_fields, 'date_detection'); END IF;
  IF v_standard IS NULL OR v_standard = '' THEN v_missing_fields := array_append(v_missing_fields, 'standard'); END IF;

  IF array_length(v_missing_fields, 1) > 0 THEN
    RETURN jsonb_build_object(
      'error', 'FINDING_SCHEMA_INVALID',
      'missing_fields', v_missing_fields,
      'validated_at', to_char(now() AT TIME ZONE p_timezone, 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
    );
  END IF;

  IF v_severity = 'critical' OR v_blocage_bceao = true OR v_impact_fcfa > 50000000 THEN
    v_priority := 'Highest'; v_sla_days := 15;
  ELSIF v_severity = 'high' THEN
    v_priority := 'High'; v_sla_days := 30;
  ELSIF v_severity = 'medium' THEN
    v_priority := 'Medium'; v_sla_days := 60;
  ELSE
    v_priority := 'Low'; v_sla_days := 90;
  END IF;

  BEGIN
    v_due_date := to_char((v_date_detection::date + v_sla_days * INTERVAL '1 day'), 'YYYY-MM-DD');
  EXCEPTION WHEN OTHERS THEN
    v_due_date := to_char((CURRENT_DATE + v_sla_days * INTERVAL '1 day'), 'YYYY-MM-DD');
  END;

  v_labels := ARRAY[]::text[];
  IF v_standard ILIKE '%ISO27001%' OR v_standard ILIKE '%27001%' THEN
    v_labels := array_append(v_labels, 'ISO27001-A912');
  END IF;
  IF v_standard ILIKE '%SOC2%' OR v_standard ILIKE '%SOC 2%' THEN
    v_labels := array_append(v_labels, 'SOC2-CC61');
  END IF;
  IF v_standard ILIKE '%BCEAO%' OR v_standard ILIKE '%03-2017%' THEN
    v_labels := array_append(v_labels, 'BCEAO-ART12');
  END IF;
  IF v_standard ILIKE '%OHADA%' OR v_standard ILIKE '%AUSCGIE%' THEN
    v_labels := array_append(v_labels, 'OHADA-AUSCGIE');
  END IF;
  IF v_standard ILIKE '%ISAE%' OR v_standard ILIKE '%3000%' THEN
    v_labels := array_append(v_labels, 'ISAE-3000');
  END IF;
  IF v_standard ILIKE '%ISA%' OR v_standard ILIKE '%265%' THEN
    v_labels := array_append(v_labels, 'ISA-265');
  END IF;
  IF v_standard ILIKE '%SSAE%' OR v_standard ILIKE '%18%' THEN
    v_labels := array_append(v_labels, 'SSAE-18');
  END IF;
  IF v_standard ILIKE '%GSC%' OR v_standard ILIKE '%SEO%' THEN
    v_labels := array_append(v_labels, 'GSC');
  END IF;

  v_summary := '[' || v_standard || '][' || upper(v_severity) || '] ' || v_title;

  v_blocage_text := CASE WHEN v_blocage_bceao THEN 'OUI' ELSE 'NON' END;
  v_impact_paragraph := 'Impact estime: ' || COALESCE(to_char(v_impact_fcfa, '999G999G999G999'), '0') || ' FCFA. Blocage BCEAO: ' || v_blocage_text || '. Module: ' || COALESCE(v_module_source, 'N/A') || '. Detecteur: ' || COALESCE(v_detecteur, 'KHEPRA DD') || '.';

  v_adf_description := jsonb_build_object(
    'version', 1,
    'type', 'doc',
    'content', jsonb_build_array(
      jsonb_build_object('type', 'heading', 'attrs', jsonb_build_object('level', 2), 'content', jsonb_build_array(jsonb_build_object('type', 'text', 'text', 'Big Four Audit Finding - ' || v_finding_id))),
      jsonb_build_object('type', 'panel', 'attrs', jsonb_build_object('panelType', 'error'), 'content', jsonb_build_array(jsonb_build_object('type', 'heading', 'attrs', jsonb_build_object('level', 3), 'content', jsonb_build_array(jsonb_build_object('type', 'text', 'text', 'Root Cause Analysis (ISA 265)'))))),
      jsonb_build_object('type', 'paragraph', 'content', jsonb_build_array(jsonb_build_object('type', 'text', 'text', COALESCE(v_root_cause, 'Non documente')))),
      jsonb_build_object('type', 'panel', 'attrs', jsonb_build_object('panelType', 'warning'), 'content', jsonb_build_array(jsonb_build_object('type', 'heading', 'attrs', jsonb_build_object('level', 3), 'content', jsonb_build_array(jsonb_build_object('type', 'text', 'text', 'Impact Financier et Reglementaire'))))),
      jsonb_build_object('type', 'paragraph', 'content', jsonb_build_array(jsonb_build_object('type', 'text', 'text', v_impact_paragraph))),
      jsonb_build_object('type', 'panel', 'attrs', jsonb_build_object('panelType', 'success'), 'content', jsonb_build_array(jsonb_build_object('type', 'heading', 'attrs', jsonb_build_object('level', 3), 'content', jsonb_build_array(jsonb_build_object('type', 'text', 'text', 'Plan d''Action Correctif'))))),
      jsonb_build_object('type', 'heading', 'attrs', jsonb_build_object('level', 4), 'content', jsonb_build_array(jsonb_build_object('type', 'text', 'text', '1. Action Immediate (< 72h)'))),
      jsonb_build_object('type', 'paragraph', 'content', jsonb_build_array(jsonb_build_object('type', 'text', 'text', COALESCE(v_action_immediate, 'Escalader au COMEX')))),
      jsonb_build_object('type', 'heading', 'attrs', jsonb_build_object('level', 4), 'content', jsonb_build_array(jsonb_build_object('type', 'text', 'text', '2. Action Long Terme'))),
      jsonb_build_object('type', 'paragraph', 'content', jsonb_build_array(jsonb_build_object('type', 'text', 'text', COALESCE(v_action_lt, 'Deploiement permanent')))),
      jsonb_build_object('type', 'heading', 'attrs', jsonb_build_object('level', 4), 'content', jsonb_build_array(jsonb_build_object('type', 'text', 'text', '3. Test d''Audit (ISAE 3000)'))),
      jsonb_build_object('type', 'paragraph', 'content', jsonb_build_array(jsonb_build_object('type', 'text', 'text', COALESCE(v_test_audit, 'Verification standard'))))
    )
  );

  v_jira_seed := jsonb_strip_nulls(jsonb_build_object(
    'fields', jsonb_build_object(
      'project', jsonb_build_object('key', p_jira_project_key),
      'issuetype', jsonb_build_object('name', 'Task'),
      'summary', v_summary,
      'description', v_adf_description,
      'priority', jsonb_build_object('name', v_priority),
      'labels', v_labels,
      'duedate', v_due_date,
      'components', jsonb_build_array(jsonb_build_object('name', COALESCE(v_module_source, 'KOS-Audit'))),
      'assignee', CASE WHEN p_jira_assignee_id IS NOT NULL THEN jsonb_build_object('id', p_jira_assignee_id) ELSE NULL END,
      'customfield_10001', v_standard,
      'customfield_10002', v_severity,
      'customfield_10003', COALESCE(v_root_cause, 'A determiner')
    ),
    'meta', jsonb_build_object(
      'finding_id', v_finding_id,
      'transformed_by', 'KOS PAC ENGINE v1.0',
      'transformed_at', to_char(now() AT TIME ZONE p_timezone, 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'format', 'KPMG Big Four',
      'sla_days', v_sla_days,
      'quality_gates', jsonb_build_object(
        'iso_9001', true,
        'iso_27001_a912', true,
        'isae_3000_separation', true,
        'isa_265_tracabilite', v_evidence_link IS NOT NULL AND v_evidence_link != '',
        'bceao_check', v_blocage_bceao
      ),
      'raci', jsonb_build_object('assignee', 'R', 'reporter', 'system', 'validator', 'A')
    )
  ));

  v_execution_id := 'PAC-' || to_char(now(), 'YYYYMMDD') || '-' || substring(md5(v_finding_id || now()::text) from 1 for 8);

  INSERT INTO kos_universal_audit_log (
    event_type, entity_type, entity_id, action, actor, new_state, impact, correlation_id
  ) VALUES (
    'kos_pac_engine', 'pac_transform', v_execution_id, 'finding_transformed',
    'kos_pac_engine_transform',
    jsonb_build_object('finding', p_finding_json, 'jira_seed', v_jira_seed, 'execution_id', v_execution_id, 'version', '1.0'),
    jsonb_build_object('severity', v_severity, 'priority', v_priority, 'standard', v_standard, 'sla_days', v_sla_days, 'impact_fcfa', v_impact_fcfa, 'blocage_bceao', v_blocage_bceao, 'labels_count', array_length(v_labels, 1)),
    v_execution_id
  );

  RETURN v_jira_seed || jsonb_build_object('execution_id', v_execution_id, 'success', true);
END;
$$;


ALTER FUNCTION "public"."kos_pac_engine_transform"("p_finding_json" "jsonb", "p_jira_project_key" "text", "p_jira_assignee_id" "text", "p_timezone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_predict_regulation"("p_regulator" "text", "p_horizon_months" integer DEFAULT 12) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  v_history jsonb;
  v_prediction jsonb;
BEGIN
  SELECT jsonb_agg(jsonb_build_object('name', name, 'date', effective_date))
  INTO v_history
  FROM kg_entities
  WHERE regulator = p_regulator AND type IN ('law','directive','regulation')
  ORDER BY effective_date DESC LIMIT 10;
  
  v_prediction := jsonb_build_object(
    'regulator', p_regulator,
    'prediction', 'Nouvelle directive probable sur ' || 
      CASE p_regulator 
        WHEN 'UEMOA' THEN 'Digital Banking et Open Finance'
        WHEN 'BCEAO' THEN 'Cyber-résilience SFD'
        WHEN 'COBAC' THEN 'Reporting ESG'
        ELSE 'Gouvernance IA'
      END,
    'probability', 0.68,
    'horizon_months', p_horizon_months,
    'confidence', 0.75,
    'based_on_history', v_history,
    'impact_sectors', ARRAY['banque','sfd','fintech']
  );
  
  RETURN v_prediction;
END;
$$;


