CREATE OR REPLACE FUNCTION "public"."kos_rag_query_internal"("p_query" "text", "p_top_k" integer DEFAULT 5) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  results jsonb;
BEGIN
  SELECT jsonb_build_object(
    'sources', COALESCE(jsonb_agg(
      jsonb_build_object(
        'title', s.title,
        'regulator', s.regulator,
        'big_four_summary', s.big_four_summary,
        'score', round(s.score_total::numeric, 4)
      ) ORDER BY s.score_total DESC
    ), '[]'::jsonb),
    'external_api_calls', 0
  )
  INTO results
  FROM kos_search_bigfour(p_query, p_top_k) AS s;

  RETURN results;
END;
$$;


ALTER FUNCTION "public"."kos_rag_query_internal"("p_query" "text", "p_top_k" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_rag_query_internal"("p_query" "text", "p_top_k" integer DEFAULT 5, "p_regulator" "text" DEFAULT NULL::"text", "p_min_score" double precision DEFAULT 0.15) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_start timestamptz := clock_timestamp();
  v_results jsonb;
  v_count int;
BEGIN
  -- Search with 2x top_k to allow post-filtering by threshold
  SELECT jsonb_build_object(
    'answer', CASE 
      WHEN count(*) = 0 THEN 'Aucun document réglementaire trouvé dans la base KOS pour "' || p_query || '". Vérifiez que les sources BCEAO/COBAC/OHADA/GAFI sont indexées. Essayez de reformuler avec des termes plus précis.'
      WHEN count(*) = 1 THEN 'Synthèse basée sur 1 document réglementaire'
      ELSE 'Synthèse basée sur ' || count(*) || ' documents réglementaires BCEAO/COBAC/OHADA/GAFI'
    END,
    'sources', COALESCE(jsonb_agg(jsonb_build_object(
      'title', title,
      'regulator', regulator,
      'content_snippet', content_snippet,
      'score', round(score_total::numeric, 3),
      'big_four_summary', big_four_summary
    ) ORDER BY score_total DESC), '[]'::jsonb),
    'source_count', count(*),
    'latency_ms', round((extract(epoch from clock_timestamp() - v_start) * 1000)::numeric, 1),
    'engine', 'MC-SEMANTIC-INTERNAL-150',
    'external_api_calls', 0,
    'min_score_applied', p_min_score,
    'regulator_filter', COALESCE(p_regulator, 'ALL'),
    'trademark', 'KOS REGTECH AI™ — Big Four Precision Engine'
  ) INTO v_results
  FROM kos_search_bigfour(p_query, p_top_k * 2, p_regulator)
  WHERE score_total >= p_min_score
    AND regulator IN ('BCEAO', 'COBAC', 'OHADA', 'GAFI', 'KHEPRA Experts', 'UEMOA', 'BEAC');

  RETURN v_results;
END;
$$;


ALTER FUNCTION "public"."kos_rag_query_internal"("p_query" "text", "p_top_k" integer, "p_regulator" "text", "p_min_score" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_rag_query_internal"("p_query" "text", "p_top_k" integer DEFAULT 5, "p_regulator" "text" DEFAULT NULL::"text", "p_min_score" double precision DEFAULT 0.15, "p_context" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
v_agent_result jsonb;
v_context jsonb;
BEGIN
v_context := p_context;
IF v_context IS NULL THEN v_context := jsonb_build_object(); END IF;
v_agent_result := kos_agent_reasoning(p_query, v_context, 3);
RETURN v_agent_result;
END;
$$;


