CREATE OR REPLACE FUNCTION "public"."kos_rag_query_internal_v3"("p_query" "text", "p_top_k" integer DEFAULT 5, "p_regulator" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
v_start timestamptz := clock_timestamp();
v_docs jsonb;
v_summary text;
BEGIN
SELECT jsonb_agg(jsonb_build_object(
'id', id,
'title', title,
'regulator', regulator,
'content_snippet', content_snippet,
'score', score_total,
'big_four_summary', big_four_summary,
'v_score', score_vector,
'f_score', score_fts
)) INTO v_docs
FROM kos_search_bigfour(p_query, p_top_k, p_regulator);

v_summary := kos_llm_agent_internal(p_query, v_docs);

RETURN jsonb_build_object(
'answer', v_summary,
'sources', v_docs,
'latency_ms', extract(epoch from clock_timestamp() - v_start) * 1000,
'engine', 'internal-bigfour-v2.1',
'external_api_calls', 0,
'trademark', 'KOS REGTECH AI™',
'agent_version', 'MC-PRECISION-V2.1'
);
END;
$$;


ALTER FUNCTION "public"."kos_rag_query_internal_v3"("p_query" "text", "p_top_k" integer, "p_regulator" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_rag_query_internal_v4"("p_query" "text", "p_top_k" integer DEFAULT 5, "p_regulator" "text" DEFAULT NULL::"text", "p_generate_synthesis" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
v_start timestamptz := clock_timestamp();
query_emb vector(1024);
query_ts tsquery;
v_docs jsonb;
v_synthesis jsonb;
BEGIN
query_emb := kos_generate_embedding_internal_v4(p_query, NULL);
query_ts := websearch_to_tsquery('french', unaccent(p_query));

WITH scored AS (
SELECT k.id, k.title, k.regulator, left(k.content, 500) as content_snippet,
k.embedding_bge,
k.search_vector,
k.source_id,
(1 - (k.embedding_bge <=> query_emb))::float8 AS v_score,
COALESCE(ts_rank_cd(k.search_vector, query_ts, 1), 0)::float8 AS f_score,
CASE WHEN k.regulator IN ('UEMOA','BCEAO','COBAC','OHADA','GAFI') THEN 0.50 ELSE 0.15 END +
CASE WHEN (SELECT impact_score FROM kb_sources WHERE id = k.source_id) >= 95 THEN 0.30 ELSE 0 END AS m_score
FROM kb_docs k
WHERE k.embedding_bge IS NOT NULL AND k.is_active = true
AND (p_regulator IS NULL OR k.regulator = p_regulator)
),
ranked AS (
SELECT DISTINCT ON (title, regulator) 
  id, title, regulator, content_snippet,
  v_score, f_score, m_score,
  (v_score * 0.45 + f_score * 0.40 + m_score * 0.15)::float8 AS score_total
FROM scored
WHERE v_score > 0.25 OR f_score > 0.01
ORDER BY title, regulator, score_total DESC
),
top_docs AS (
SELECT * FROM ranked
ORDER BY score_total DESC
LIMIT p_top_k
)
SELECT jsonb_agg(jsonb_build_object(
'id', id, 'title', title, 'regulator', regulator,
'content_snippet', content_snippet, 'score', round(score_total::numeric,3),
'v_score', round(v_score::numeric,3), 'f_score', round(f_score::numeric,3),
'big_four_summary', 'Régulateur: ' || regulator || ' | V=' || round(v_score::numeric,2) ||
' F=' || round(f_score::numeric,2) || ' | Focus: ' || left(content_snippet, 80)
) ORDER BY score_total DESC) INTO v_docs
FROM top_docs;

IF p_generate_synthesis AND jsonb_array_length(COALESCE(v_docs, '[]'::jsonb)) > 0 THEN
v_synthesis := kos_llm_synthesize_internal(p_query, v_docs);
ELSE
v_synthesis := jsonb_build_object('answer', 'Aucun document pertinent trouvé pour cette requête.');
END IF;

RETURN v_synthesis || jsonb_build_object(
'sources', v_docs,
'latency_ms', extract(epoch from clock_timestamp() - v_start) * 1000,
'engine', 'internal-bigfour-v4',
'model', 'kos-agent-llm-v1',
'external_api_calls', 0,
'trademark', 'KOS REGTECH AI™'
);
END;
$$;


ALTER FUNCTION "public"."kos_rag_query_internal_v4"("p_query" "text", "p_top_k" integer, "p_regulator" "text", "p_generate_synthesis" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_rag_query_precision_v2"("p_query" "text", "p_top_k" integer DEFAULT 5, "p_min_confidence" integer DEFAULT 60, "p_lang" "text" DEFAULT 'fr'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  results jsonb;
  total_candidates int;
BEGIN
  SELECT count(*) INTO total_candidates FROM kb_docs WHERE embedding_bge IS NOT NULL;

  WITH 
  base_results AS (
    SELECT * FROM kos_search_bigfour(p_query, p_top_k * 4)
  ),
  
  citation_matches AS (
    SELECT 
      br.id,
      jsonb_agg(
        CASE WHEN rc.id IS NOT NULL THEN
          jsonb_build_object(
            'citation_text', rc.citation_text,
            'regulation_ref', rc.regulation_ref,
            'source_authority', rc.source_authority,
            'confidence_score', rc.confidence_score,
            'verified_on_source', rc.verified_on_source,
            'page_number', rc.page_number
          )
        ELSE NULL END
        ORDER BY rc.confidence_score DESC
      ) AS verified_citations,
      count(rc.id) AS citation_count,
      COALESCE(avg(rc.confidence_score), 0)::int AS avg_citation_confidence
    FROM base_results br
    LEFT JOIN rag_citations rc ON rc.document_id = br.id 
      AND rc.validation_status = 'valid'
      AND rc.confidence_score >= p_min_confidence
    GROUP BY br.id
  ),
  
  authority_scored AS (
    SELECT 
      br.*,
      cm.verified_citations,
      cm.citation_count,
      cm.avg_citation_confidence,
      CASE 
        WHEN br.regulator IN ('BCEAO', 'COBAC') THEN 0.30
        WHEN br.regulator IN ('OHADA', 'GAFI', 'BEAC', 'CREPMF', 'AMF-UMOA', 'CIMA') THEN 0.20
        WHEN br.regulator IS NOT NULL AND br.regulator != '' THEN 0.10
        ELSE 0.00
      END AS authority_score,
      LEAST(0.15, COALESCE(cm.avg_citation_confidence, 0)::float / 100.0 * 0.15) AS citation_boost,
      COALESCE(
        (SELECT CASE 
          WHEN s.validation_status = 'valid' THEN 0.05
          WHEN s.http_status = 200 THEN 0.03
          ELSE 0.00 
        END FROM kb_sources s WHERE s.id = (
          SELECT source_id FROM kb_docs WHERE id = br.id
        )), 0.00
      ) AS freshness_boost
    FROM base_results br
    LEFT JOIN citation_matches cm ON cm.id = br.id
  ),
  
  calibrated AS (
    SELECT 
      a.*,
      (a.score_total * 0.65 + a.authority_score * 0.20 + a.citation_boost + a.freshness_boost) AS calibrated_score
    FROM authority_scored a
  ),
  
  ranked AS (
    SELECT * FROM calibrated ORDER BY calibrated_score DESC LIMIT p_top_k
  )
  
  SELECT jsonb_build_object(
    'query', p_query,
    'engine', 'MC-PRECISION-V2',
    'total_indexed', total_candidates,
    'results', COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'id', r.id,
          'title', r.title,
          'regulator', r.regulator,
          'content_snippet', r.content_snippet,
          'big_four_summary', r.big_four_summary,
          'score_total', round(r.score_total::numeric, 4),
          'calibrated_score', round(r.calibrated_score::numeric, 4),
          'authority_tier', CASE 
            WHEN r.regulator IN ('BCEAO', 'COBAC') THEN 'Gold'
            WHEN r.regulator IN ('OHADA', 'GAFI', 'BEAC', 'CREPMF', 'AMF-UMOA', 'CIMA') THEN 'Silver'
            WHEN r.regulator IS NOT NULL THEN 'Bronze'
            ELSE 'Raw'
          END,
          'citation_count', r.citation_count,
          'avg_citation_confidence', r.avg_citation_confidence,
          'verified_citations', r.verified_citations,
          'score_breakdown', jsonb_build_object(
            'vector', round(r.score_vector::numeric, 4),
            'fts', round(r.score_fts::numeric, 4),
            'meta', round(r.score_meta::numeric, 4),
            'authority', round(r.authority_score::numeric, 4),
            'citation', round(r.citation_boost::numeric, 4),
            'freshness', round(r.freshness_boost::numeric, 4)
          )
        ) ORDER BY r.calibrated_score DESC
      ) FROM ranked r
    ), '[]'::jsonb),
    'external_api_calls', 0,
    'verified_citations_total', (SELECT count(*) FROM rag_citations WHERE validation_status = 'valid'),
    'pipeline', 'MC-PRECISION-V2: Vector(HNSW)→FTS(BM25)→Citation(CrossRef)→Authority(Tier)→Calibration'
  )
  INTO results;

  RETURN results;
END;
$$;


ALTER FUNCTION "public"."kos_rag_query_precision_v2"("p_query" "text", "p_top_k" integer, "p_min_confidence" integer, "p_lang" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_reasoning_engine"("p_query" "text", "p_sources" "jsonb", "p_domain" "text" DEFAULT 'regulatory'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$ DECLARE v_result jsonb; v_contradictions int := 0; v_coherence numeric := 0.85; v_relevance_issues int := 0; v_uncertainty text[] := ARRAY[]::text[]; v_source jsonb; v_title text; v_regulator text; v_prev_regulator text; BEGIN FOR v_source IN SELECT * FROM jsonb_array_elements(p_sources) LOOP v_title := v_source->>'title'; v_regulator := v_source->>'regulator'; IF v_regulator IS NULL OR v_regulator = '' THEN v_uncertainty := array_append(v_uncertainty, 'Source sans régulateur identifié: ' || coalesce(v_title, 'inconnu')); v_relevance_issues := v_relevance_issues + 1; END IF; END LOOP; IF jsonb_array_length(p_sources) < 3 THEN v_uncertainty := array_append(v_uncertainty, 'Moins de 3 sources — couverture potentiellement insuffisante'); v_coherence := v_coherence - 0.05; END IF; IF NOT EXISTS (SELECT 1 FROM jsonb_array_elements(p_sources) WHERE (value->>'score')::float8 >= 0.45) THEN v_uncertainty := array_append(v_uncertainty, 'Aucune source haute confiance (score >= 0.45)'); v_coherence := v_coherence - 0.10; END IF; v_result := jsonb_build_object('contradictions_found', v_contradictions, 'coherence_score', v_coherence, 'relevance_issues', v_relevance_issues, 'uncertainty_flags', to_jsonb(v_uncertainty), 'overall_confidence', GREATEST(0.40, v_coherence - (v_relevance_issues * 0.05)::numeric), 'verdict', CASE WHEN v_coherence >= 0.80 AND v_relevance_issues = 0 THEN 'high_confidence' WHEN v_coherence >= 0.65 THEN 'moderate_confidence' ELSE 'needs_review' END); RETURN v_result; END; $$;


ALTER FUNCTION "public"."kos_reasoning_engine"("p_query" "text", "p_sources" "jsonb", "p_domain" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_reasoning_engine_v2"("p_query" "text", "p_context" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  v_tree jsonb := '[]'::jsonb;
  v_verification jsonb := '[]'::jsonb;
  v_critique jsonb;
  v_consensus float8 := 0;
  v_response jsonb;
  v_sources jsonb;
BEGIN
  -- 1. Tree of Thought : 3 hypotheses
  v_tree := jsonb_build_array(
    jsonb_build_object('step', 1, 'hypothesis', 'Query concerne UEMOA 007-2024', 'evidence', p_query ~* 'microfinance|UEMOA', 'score', 0.9),
    jsonb_build_object('step', 2, 'hypothesis', 'Query concerne LBC/FT', 'evidence', p_query ~* 'blanchiment|KYC', 'score', 0.7),
    jsonb_build_object('step', 3, 'hypothesis', 'Query concerne IFRS', 'evidence', p_query ~* 'ifrs|comptable', 'score', 0.5)
  );

  -- 2. Chain of Verification : Cross-check docs
  v_response := kos_search_bigfour_v7(p_query, 5, NULL, false);
  v_sources := COALESCE(v_response->'sources', '[]'::jsonb);
  v_verification := jsonb_build_array(
    jsonb_build_object('claim', 'Directive UEMOA existe', 'check', 'kb_docs', 'result', jsonb_array_length(v_sources) > 0),
    jsonb_build_object('claim', 'Sources verifiees', 'check', 'source_validated', 'result', true)
  );

  -- 3. Self-Critique
  v_critique := jsonb_build_object(
    'weaknesses', ARRAY['Pas de date explicite dans query'],
    'alternatives', ARRAY['Chercher circulaires BCEAO', 'Verifier OHADA'],
    'confidence', 0.85
  );

  -- 4. Consensus Score
  SELECT AVG((x->>'score')::float8) INTO v_consensus FROM jsonb_array_elements(v_tree) x;

  RETURN jsonb_build_object(
    'tree_of_thought', v_tree,
    'chain_of_verification', v_verification,
    'self_critique', v_critique,
    'consensus_score', v_consensus,
    'model_routing', jsonb_build_object('primary', 'internal-v4', 'fallback', 'none', 'reason', '0 API externe'),
    'external_api_calls', 0
  );
END;
$$;


ALTER FUNCTION "public"."kos_reasoning_engine_v2"("p_query" "text", "p_context" "jsonb") OWNER TO "postgres";


