CREATE OR REPLACE FUNCTION "public"."kos_replace_brand_global"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_tables text[] := ARRAY['pages', 'blog_posts', 'brochures', 'email_templates', 'kos_knowledge_base'];
  v_cols text[] := ARRAY['title', 'content', 'description', 'meta_title', 'meta_description'];
  v_table text;
  v_col text;
  v_updated int := 0;
BEGIN
  FOREACH v_table IN ARRAY v_tables LOOP
    FOREACH v_col IN ARRAY v_cols LOOP
      IF EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_name = v_table AND column_name = v_col
      ) THEN
        EXECUTE format('UPDATE %I SET %I = REPLACE(REPLACE(%I, ''KHEPRA EXPERTS'', ''KOS''), ''Khepra Experts'', ''KOS'') WHERE %I ILIKE ''%%KHEPRA%%''', v_table, v_col, v_col, v_col);
        GET DIAGNOSTICS v_updated = ROW_COUNT;
      END IF;
    END LOOP;
  END LOOP;

  UPDATE public.kos_brand_assets SET updated_at = now() WHERE asset_type = 'brand_name';

  RETURN jsonb_build_object('status', 'success', 'replacements', v_updated, 'timestamp', now());
END; $$;


