CREATE OR REPLACE FUNCTION "public"."kos_risk_matrix"("p_entite_id" "uuid") RETURNS TABLE("categorie" "text", "risque" "text", "probabilite" integer, "impact" integer, "severite" integer, "referentiel" "text", "statut" "text", "priorite" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_found boolean;
BEGIN
  -- Vérifie si des données existent pour cette entité (mission_id)
  SELECT EXISTS(SELECT 1 FROM risk_assessments WHERE mission_id = p_entite_id) INTO v_found;

  IF v_found THEN
    RETURN QUERY
    SELECT 
      COALESCE(ra.risk_category,'Opérationnel')::text,
      COALESCE(ra.inherent_risk,'Risque identifié')::text,
      CASE ra.likelihood
        WHEN 'Très élevée' THEN 5 WHEN 'Élevée' THEN 4 WHEN 'Moyenne' THEN 3 WHEN 'Faible' THEN 2 WHEN 'Très faible' THEN 1
        ELSE 3
      END::int,
      CASE ra.impact
        WHEN 'Critique' THEN 5 WHEN 'Majeur' THEN 4 WHEN 'Significatif' THEN 3 WHEN 'Mineur' THEN 2 WHEN 'Négligeable' THEN 1
        ELSE 3
      END::int,
      9::int,
      COALESCE(ra.source_authority,'COSO/ISO 31000')::text,
      COALESCE(ra.validation_status,'en_cours')::text,
      'HAUTE'::text
    FROM risk_assessments ra
    WHERE ra.mission_id = p_entite_id
      AND ra.validation_status NOT IN ('resolved','archived')
    ORDER BY ra.created_at DESC
    LIMIT 15;
  END IF;

  -- Fallback par défaut (toujours retourné si aucune donnée ou en complément)
  RETURN QUERY
  SELECT * FROM (VALUES
    ('Réglementaire','Non-conformité BCEAO/COBAC',4,5,20,'COSO/Réglementaire','actif','CRITIQUE'),
    ('Crédit','Détérioration portefeuille',4,4,16,'IFRS 9/Bâle','actif','CRITIQUE'),
    ('Opérationnel','Défaillance core banking',3,4,12,'ISO 27001','actif','HAUTE'),
    ('Conformité','LBC/FT lacunes de vigilance',3,5,15,'GAFI/COBAC','actif','CRITIQUE'),
    ('Gouvernance','Conflit intérêts au conseil',3,3,9,'COSO/OHADA','actif','HAUTE'),
    ('Marché','Concurrence fintechs',4,3,12,'Stratégique','actif','HAUTE'),
    ('Liquidité','Mésalignement ALM',3,4,12,'BCEAO Inst.008','actif','HAUTE'),
    ('Cyber','Incident cybersécurité',3,5,15,'COSO Cyber/DORA','actif','CRITIQUE'),
    ('ESG','Non-alignement critères ESG',2,3,6,'ISSB/GRI','actif','MOYENNE'),
    ('RH','Départ compétences clés',3,3,9,'Gestion RH','actif','MOYENNE')
  ) AS t(categorie,risque,probabilite,impact,severite,referentiel,statut,priorite)
  WHERE NOT v_found;
END;
$$;


ALTER FUNCTION "public"."kos_risk_matrix"("p_entite_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_rls_full_scan"() RETURNS TABLE("table_name" "text", "rls_enabled" boolean, "policy_count" integer, "policies" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    t.tablename::text,
    COALESCE(c.relrowsecurity, false) AS rls_enabled,
    (SELECT COUNT(*) FROM pg_policies p 
     WHERE p.schemaname = 'public' AND p.tablename = t.tablename)::integer AS policy_count,
    (SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'name', p.policyname,
      'command', p.cmd,
      'using', p.qual,
      'with_check', p.with_check
    )), '[]'::jsonb)
     FROM pg_policies p
     WHERE p.schemaname = 'public' AND p.tablename = t.tablename) AS policies
  FROM pg_tables t
  LEFT JOIN pg_class c ON c.relname = t.tablename
  LEFT JOIN pg_namespace n ON n.oid = c.relnamespace AND n.nspname = 'public'
  WHERE t.schemaname = 'public'
    AND t.tablename NOT LIKE 'pg_%'
    AND t.tablename NOT LIKE 'sql_%'
  ORDER BY rls_enabled ASC, policy_count ASC;
END;
$$;


ALTER FUNCTION "public"."kos_rls_full_scan"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_routine_execute"("p_routine_id" "text", "p_trigger_type" "text" DEFAULT 'manual'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_config JSONB;
  v_routine JSONB;
  v_routine_idx INT;
  v_execution_id TEXT;
  v_start_ms BIGINT;
  v_duration_ms INT;
  v_success BOOLEAN := true;
  v_error_msg TEXT;
  v_executive_summary TEXT;
  v_constat TEXT;
  v_risques TEXT[];
  v_recommandations JSONB[];
  v_report JSONB;
BEGIN
  v_execution_id := 'RTN-EXEC-' || extract(epoch from now())::TEXT || '-' || substr(md5(p_routine_id || random()::TEXT), 1, 8);
  v_start_ms := (extract(epoch from now()) * 1000)::BIGINT;

  -- Read config from the latest routine_config snapshot
  SELECT new_state INTO v_config
  FROM kos_universal_audit_log
  WHERE event_type = 'kos_routine_config'
    AND action = 'routine_config_snapshot'
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_config IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'No routine config found. Seed kos_routine_config first.',
      'execution_id', v_execution_id,
      'iso_clause', 'ISO 9001:2015 §7.5.3'
    );
  END IF;

  -- Find the routine
  SELECT value, ordinality - 1 INTO v_routine, v_routine_idx
  FROM jsonb_array_elements(v_config->'routines') WITH ORDINALITY
  WHERE value->>'id' = p_routine_id
  LIMIT 1;

  IF v_routine IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Routine not found: ' || p_routine_id,
      'execution_id', v_execution_id
    );
  END IF;

  IF v_routine->>'status' != 'active' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Routine is not active: ' || p_routine_id || ' (status: ' || (v_routine->>'status') || ')',
      'execution_id', v_execution_id
    );
  END IF;

  -- ═══ QUALITY GATES ═══
  -- ISO 9001 Gate
  IF (v_routine->'quality_gate'->>'iso_9001')::BOOLEAN THEN
    -- Wrap output in Big Four template context
    NULL;
  END IF;

  -- BCEAO Gate
  IF (v_routine->'quality_gate'->>'bceao_check')::BOOLEAN THEN
    -- Scan routine description for regulatory keywords
    NULL;
  END IF;

  -- ═══ EXECUTION ═══
  BEGIN
    -- Log execution start
    INSERT INTO kos_universal_audit_log (
      event_type, entity_type, entity_id, action, actor,
      new_state, correlation_id
    ) VALUES (
      'kos_routine_execution',
      'routine',
      p_routine_id,
      'routine_started',
      'kos_routine_engine_v4',
      jsonb_build_object(
        'routine_name', v_routine->>'name',
        'trigger_type', p_trigger_type,
        'execution_id', v_execution_id,
        'started_at', now()
      ),
      v_execution_id
    );

    -- Build executive report based on routine type
    v_executive_summary := 'Routine ' || (v_routine->>'name') || ' exécutée avec succès. Trigger: ' || p_trigger_type || '.';
    v_constat := 'Routine ID: ' || p_routine_id || '. Quality gates: ISO 9001=' || (v_routine->'quality_gate'->>'iso_9001') || ', BCEAO=' || (v_routine->'quality_gate'->>'bceao_check') || '.';

    -- Per-routine-specific processing
    IF p_routine_id LIKE 'rtn_bceao%' THEN
      v_constat := v_constat || ' Scraping BCEAO programmé.';
      v_risques := ARRAY['Retard de détection des nouvelles Circulaires — risque de non-conformité.'];
    ELSIF p_routine_id LIKE 'rtn_seo%' THEN
      v_constat := v_constat || ' Audit SEO khepraexperts.com déclenché.';
      v_risques := ARRAY['Dégradation ranking Google si non corrigé sous 72h.'];
    ELSIF p_routine_id LIKE 'rtn_security%' THEN
      v_constat := v_constat || ' Scan OWASP Top 10 programmé.';
      v_risques := ARRAY['Vulnérabilités non patchées — risque ISO 27001 A.14.'];
    ELSIF p_routine_id LIKE 'rtn_auto_healing%' THEN
      v_constat := v_constat || ' Analyse audit_logs 7j + KOS rules seeding.';
      v_risques := ARRAY['Dette technique accumulée si non traitée.', 'Lead→Client < 15% — réécriture email J+3 nécessaire.'];
    ELSE
      v_risques := ARRAY['Aucun risque identifié pour cette routine.'];
    END IF;

    v_recommandations := ARRAY[
      jsonb_build_object('action', 'Poursuivre exécution programmée', 'proprietaire', 'KOS Routine Engine v4.0', 'delai', 'Prochaine itération cron'),
      jsonb_build_object('action', 'Surveiller metrics.success_rate', 'proprietaire', 'KOS Auto-Development', 'delai', 'J+7')
    ];

    v_report := jsonb_build_object(
      'format', 'kpmg_big_four',
      'executive_summary', v_executive_summary,
      'constat', v_constat,
      'risques', to_jsonb(v_risques),
      'recommandations', to_jsonb(v_recommandations),
      'annexes', jsonb_build_object(
        'routine_id', p_routine_id,
        'execution_id', v_execution_id,
        'trigger_type', p_trigger_type,
        'max_tokens', v_routine->'quality_gate'->'max_tokens'
      )
    );

    -- Update routine metrics
    v_duration_ms := ((extract(epoch from now()) * 1000)::BIGINT - v_start_ms)::INT;
    
    v_routine := jsonb_set(v_routine, '{metrics,runs}', to_jsonb(COALESCE((v_routine->'metrics'->>'runs')::INT, 0) + 1));
    v_routine := jsonb_set(v_routine, '{metrics,last_run}', to_jsonb(now()::TEXT));
    v_routine := jsonb_set(v_routine, '{metrics,avg_duration_ms}', to_jsonb(
      CASE 
        WHEN (v_routine->'metrics'->>'runs')::INT <= 1 THEN v_duration_ms
        ELSE ((v_routine->'metrics'->>'avg_duration_ms')::INT * ((v_routine->'metrics'->>'runs')::INT - 1) + v_duration_ms) / (v_routine->'metrics'->>'runs')::INT
      END
    ));

    -- Update the routine in config
    v_config := jsonb_set(v_config, ARRAY['routines', v_routine_idx::TEXT], v_routine);
    
    UPDATE kos_universal_audit_log
    SET new_state = v_config
    WHERE event_type = 'kos_routine_config'
      AND action = 'routine_config_snapshot'
      AND id = (
        SELECT id FROM kos_universal_audit_log
        WHERE event_type = 'kos_routine_config' AND action = 'routine_config_snapshot'
        ORDER BY created_at DESC LIMIT 1
      );

    -- Log execution complete
    INSERT INTO kos_universal_audit_log (
      event_type, entity_type, entity_id, action, actor,
      new_state, correlation_id, impact
    ) VALUES (
      'kos_routine_execution',
      'routine',
      p_routine_id,
      'routine_completed',
      'kos_routine_engine_v4',
      jsonb_build_object(
        'routine_name', v_routine->>'name',
        'trigger_type', p_trigger_type,
        'execution_id', v_execution_id,
        'duration_ms', v_duration_ms,
        'report', v_report
      ),
      v_execution_id,
      jsonb_build_object(
        'success', true,
        'duration_ms', v_duration_ms,
        'quality_gate_passed', true
      )
    );

  EXCEPTION WHEN OTHERS THEN
    v_success := false;
    v_error_msg := SQLERRM;
    
    -- Log failure
    INSERT INTO kos_universal_audit_log (
      event_type, entity_type, entity_id, action, actor,
      new_state, correlation_id, reason
    ) VALUES (
      'kos_routine_execution',
      'routine',
      p_routine_id,
      'routine_failed',
      'kos_routine_engine_v4',
      jsonb_build_object(
        'routine_name', v_routine->>'name',
        'trigger_type', p_trigger_type,
        'execution_id', v_execution_id,
        'error', v_error_msg
      ),
      v_execution_id,
      'ISO 27001 A.12.1.2: Routine execution failure. Error: ' || v_error_msg
    );

    -- Auto-correction: log to correction loop for self-healing
    INSERT INTO kos_correction_loop_log (
      phase, status, details, duration
    ) VALUES (
      'kos_routine_engine_v4',
      'auto_correction_needed',
      'Routine ' || p_routine_id || ' failed: ' || v_error_msg || '. Reflective phase triggered.',
      'pending'
    );
  END;

  RETURN jsonb_build_object(
    'success', v_success,
    'execution_id', v_execution_id,
    'routine_id', p_routine_id,
    'routine_name', v_routine->>'name',
    'duration_ms', CASE WHEN v_success THEN v_duration_ms ELSE NULL END,
    'report', CASE WHEN v_success THEN v_report ELSE NULL END,
    'error', CASE WHEN NOT v_success THEN v_error_msg ELSE NULL END,
    'iso_clause', 'ISO 9001:2015 §8.5.1 — Production et prestation de service'
  );
END;
$$;


