CREATE OR REPLACE FUNCTION "public"."kos_routine_tick"("p_timezone" "text" DEFAULT 'Africa/Lome'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_config JSONB;
  v_routines JSONB;
  v_routine JSONB;
  v_results JSONB[];
  v_now TIMESTAMPTZ;
  v_cron_hour INT;
  v_cron_minute INT;
  v_cron_dow INT;
  v_cron_match BOOLEAN;
  v_result JSONB;
  v_triggered_count INT := 0;
  v_execution_id TEXT;
BEGIN
  v_now := now() AT TIME ZONE p_timezone;
  v_cron_hour := extract(hour from v_now)::INT;
  v_cron_minute := extract(minute from v_now)::INT;
  v_cron_dow := extract(dow from v_now)::INT; -- 0=Sunday

  -- Read latest config
  SELECT new_state INTO v_config
  FROM kos_universal_audit_log
  WHERE event_type = 'kos_routine_config'
    AND action = 'routine_config_snapshot'
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_config IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'No routine config found',
      'routines_triggered', 0,
      'executed_at', v_now
    );
  END IF;

  v_routines := v_config->'routines';

  -- Iterate through routines, check cron, execute matches
  FOR i IN 0..jsonb_array_length(v_routines) - 1 LOOP
    v_routine := v_routines->i;
    
    -- Skip paused/deleted routines
    IF v_routine->>'status' != 'active' THEN
      CONTINUE;
    END IF;

    -- Simple cron matching (minute hour day-of-week)
    -- Format: "minute hour * * day-of-week"
    v_cron_match := false;
    DECLARE
      v_cron_parts TEXT[];
      v_cron_min TEXT;
      v_cron_hr TEXT;
      v_cron_d TEXT;
    BEGIN
      v_cron_parts := string_to_array(v_routine->>'cron_expr', ' ');
      IF array_length(v_cron_parts, 1) >= 5 THEN
        v_cron_min := v_cron_parts[1];
        v_cron_hr := v_cron_parts[2];
        v_cron_d := v_cron_parts[5];

        -- Check minute
        IF v_cron_min = '*' OR v_cron_min::INT = v_cron_minute THEN
          -- Check hour
          IF v_cron_hr = '*' OR v_cron_hr::INT = v_cron_hour THEN
            -- Check day of week
            IF v_cron_d = '*' THEN
              v_cron_match := true;
            ELSIF v_cron_d LIKE '%,%' THEN
              -- Comma-separated days
              v_cron_match := (',' || v_cron_d || ',') LIKE ('%,' || v_cron_dow::TEXT || ',%');
            ELSE
              v_cron_match := (v_cron_d::INT = v_cron_dow);
            END IF;
          END IF;
        END IF;
      END IF;
    END;

    IF v_cron_match THEN
      v_execution_id := 'RTN-TICK-' || extract(epoch from v_now)::TEXT || '-' || i::TEXT;
      
      -- Execute the routine
      v_result := kos_routine_execute(v_routine->>'id', 'cron_tick');
      v_results := array_append(v_results, v_result);
      v_triggered_count := v_triggered_count + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'routines_triggered', v_triggered_count,
    'executed_at', v_now,
    'timezone', p_timezone,
    'results', COALESCE(to_jsonb(v_results), '[]'::JSONB),
    'iso_clause', 'ISO 9001:2015 §8.5.1 — Exécution programmée KOS Routine Engine'
  );
END;
$$;


ALTER FUNCTION "public"."kos_routine_tick"("p_timezone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_routing_log_enrich"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  provider_cost NUMERIC(12,6);
BEGIN
  NEW.is_failover := NEW.provider_used LIKE 'fallback_%';

  provider_cost := CASE
    WHEN NEW.provider_used LIKE '%n8n%' THEN 0.005000
    WHEN NEW.provider_used LIKE '%edge_function%' THEN 0.001000
    ELSE 0.002000
  END;

  NEW.cost_eur := provider_cost;

  IF NEW.is_failover THEN
    NEW.failover_time_ms := NEW.latency_ms * 0.6;
  ELSE
    NEW.failover_time_ms := 0;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."kos_routing_log_enrich"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_run_compliance_check"("p_control_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_control record;
  v_result int;
  v_status text;
  v_results jsonb := '[]'::jsonb;
BEGIN
  FOR v_control IN SELECT * FROM public.kos_compliance_controls WHERE (p_control_code IS NULL OR control_code = p_control_code) AND automated = true LOOP
    BEGIN
      EXECUTE v_control.sql_check INTO v_result;
      v_status := CASE WHEN v_result = 0 THEN 'PASS' ELSE 'FAIL' END;

      UPDATE public.kos_compliance_controls SET
        last_checked_at = now(),
        last_status = v_status,
        last_evidence = jsonb_build_object('result', v_result, 'checked_at', now())
      WHERE id = v_control.id;

      v_results := v_results || jsonb_build_object('control', v_control.control_code, 'status', v_status, 'result', v_result);
    EXCEPTION WHEN OTHERS THEN
      v_results := v_results || jsonb_build_object('control', v_control.control_code, 'status', 'ERROR', 'error', SQLERRM);
    END;
  END LOOP;
  RETURN jsonb_build_object('checked', jsonb_array_length(v_results), 'results', v_results);
END; $$;


ALTER FUNCTION "public"."kos_run_compliance_check"("p_control_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_run_master_supreme"() RETURNS TABLE("run_id" "text", "total_deleted" integer, "dedup_removed" integer, "duration_ms" integer, "status" "text")
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_start_time TIMESTAMPTZ := clock_timestamp();
  v_run_id TEXT := 'MASTER_' || to_char(now(), 'YYYYMMDD_HH24MISS');
  v_total_deleted INT := 0;
  v_docs_processed INT := 0;
  v_severity TEXT;
  v_duration_ms INT;
  v_final_status TEXT;
BEGIN
  -- ============================================
  -- PHASE 1: KILL SWITCH + PURGE
  -- ============================================
  UPDATE kos_regulatory_corpus 
  SET deleted_at = now(), deletion_reason = v_run_id
  WHERE id IN (
    SELECT id FROM kos_regulatory_corpus
    WHERE (
      authority NOT IN ('BCEAO', 'COBAC', 'UEMOA', 'CEMAC', 'BEAC', 'OHADA', 'GAFI', 'CENTIF')
      OR title ILIKE '%SP 800-53%'
      OR title ILIKE '%NIST%'
      OR content ILIKE '%EU Regulation%'
    )
    AND deleted_at IS NULL
    LIMIT 10000
  );
  GET DIAGNOSTICS v_total_deleted = ROW_COUNT;

  -- ============================================
  -- PHASE 2: DEDUP + NORMALISATION
  -- ============================================
  UPDATE kos_regulatory_corpus 
  SET deleted_at = now(), deletion_reason = v_run_id || '_DEDUP'
  WHERE id IN (
    SELECT id FROM (
      SELECT id, ROW_NUMBER() OVER (
        PARTITION BY authority, md5(title), date_trunc('month', date_publication) 
        ORDER BY created_at DESC
      ) as rn
      FROM kos_regulatory_corpus WHERE deleted_at IS NULL
    ) sub WHERE rn > 1
  );
  GET DIAGNOSTICS v_docs_processed = ROW_COUNT;

  -- ============================================
  -- PHASE 3: QA SCORING REFRESH (2-step to avoid referencing qa_score in same SET)
  -- ============================================
  UPDATE kos_regulatory_corpus SET 
    qa_score = CASE 
      WHEN authority IN ('BCEAO', 'COBAC', 'UEMOA') THEN 95
      WHEN authority IN ('GAFI', 'CENTIF', 'OHADA') THEN 90
      WHEN authority IN ('CEMAC', 'BEAC') THEN 85
      ELSE 70
    END
    - CASE WHEN date_publication < now() - interval '5 years' THEN 10 ELSE 0 END
    + CASE WHEN array_length(tags, 1) > 3 THEN 5 ELSE 0 END
  WHERE deleted_at IS NULL;

  UPDATE kos_regulatory_corpus SET 
    confidence_level = CASE 
      WHEN qa_score >= 90 THEN 'haute'
      WHEN qa_score >= 75 THEN 'modérée'
      ELSE 'limitée'
    END
  WHERE deleted_at IS NULL;

  -- ============================================
  -- PHASE 4: AUDIT LOG + ALERTE SLACK
  -- ============================================
  v_duration_ms := EXTRACT(MILLISECOND FROM clock_timestamp() - v_start_time)::INT;
  v_severity := CASE 
    WHEN v_total_deleted > 100 THEN 'CRITICAL'
    WHEN v_total_deleted > 10 THEN 'HIGH'
    WHEN v_total_deleted > 0 THEN 'MEDIUM'
    ELSE 'LOW'
  END;
  v_final_status := CASE WHEN v_total_deleted > 0 THEN 'PURGED' ELSE 'CLEAN' END;

  INSERT INTO kos_leakage_audit (query, severity, leaked_sources, redacted_response, user_id)
  VALUES (
    'Kill Switch ' || v_run_id,
    v_severity,
    ARRAY['MASTER_SUPREME'],
    jsonb_build_object(
      'purged_ids', v_total_deleted,
      'total_deleted', v_total_deleted,
      'dedup_removed', v_docs_processed,
      'rag_active', true,
      'dry_run', false,
      'duration_ms', v_duration_ms
    ),
    'system'
  );

  -- Alerte Slack via pg_net (v2) si purge détectée
  IF v_total_deleted > 0 THEN
    PERFORM kos_notify_slack_v2(v_final_status, v_total_deleted, v_docs_processed, v_duration_ms, v_run_id);
  END IF;

  -- ============================================
  -- REFRESH VUES MONITORING
  -- ============================================
  CREATE OR REPLACE VIEW public.v_kos_killswitch_runs AS
  SELECT 
    id, created_at, query, severity, leaked_sources, user_id,
    (redacted_response::jsonb)->>'purged_ids' as purged_ids,
    COALESCE(((redacted_response::jsonb)->>'total_deleted')::int, 0) as total_deleted,
    COALESCE(((redacted_response::jsonb)->>'rag_active')::boolean, true) as rag_active,
    COALESCE(((redacted_response::jsonb)->>'dry_run')::boolean, false) as dry_run,
    0 as severity_rank,
    CASE 
      WHEN COALESCE(array_length(leaked_sources, 1), 0) = 0 THEN 'CLEAN'
      WHEN COALESCE(((redacted_response::jsonb)->>'total_deleted')::int, 0) > 0 THEN 'PURGED'
      ELSE 'BLOCKED'
    END as status,
    COALESCE(((redacted_response::jsonb)->>'dedup_removed')::int, 0) as dedup_removed,
    COALESCE(((redacted_response::jsonb)->>'duration_ms')::int, 0) as duration_ms
  FROM public.kos_leakage_audit WHERE query ILIKE 'Kill Switch%';

  RETURN QUERY SELECT 
    v_run_id,
    v_total_deleted,
    v_docs_processed,
    v_duration_ms,
    v_final_status;

END $$;


ALTER FUNCTION "public"."kos_run_master_supreme"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_sanitize_html_bigfour"("input_html" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$ BEGIN RETURN regexp_replace(regexp_replace(regexp_replace(input_html, 'background[^;]*#[0-9a-f]{3,6}[^;]*;', '', 'gi'), 'color[^;]*#[0-9a-f]{6}[^;]*;', '', 'gi'), 'class="[^"]*dark[^"]*"', '', 'gi'); END; $$;


