CREATE OR REPLACE FUNCTION "public"."kos_search"("query" "text", "lang_filter" "text" DEFAULT 'fr'::"text") RETURNS TABLE("id" "uuid", "title" "text", "snippet" "text", "regulator" "text", "score" real)
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  raw_query text := query;
  tsq tsquery;
BEGIN
  raw_query := CASE lower(query)
    WHEN 'lutte'  THEN 'lutte OR lbc OR ft OR blanchiment OR terrorisme OR gafi'
    WHEN 'banque' THEN 'banque OR crédit OR agrément OR bceao OR prudentiel'
    WHEN 'risque' THEN 'risque OR cartographie OR matrice OR coso OR iso31000'
    ELSE query
  END;

  tsq := websearch_to_tsquery('french', raw_query);

  RETURN QUERY
  SELECT
    k.id,
    k.title,
    ts_headline('french', k.content, tsq,
      'StartSel=<mark>, StopSel=</mark>, MaxWords=50, MinWords=10'),
    k.regulator,
    ts_rank(k.search_vector, tsq)::real AS score
  FROM kb_docs k
  WHERE k.search_vector @@ tsq
    AND coalesce(k.lang, 'fr') = lang_filter
  ORDER BY score DESC
  LIMIT 20;
END;
$$;


ALTER FUNCTION "public"."kos_search"("query" "text", "lang_filter" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_search_bigfour"("query_text" "text", "top_k" integer DEFAULT 10, "min_regulator" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "title" "text", "regulator" "text", "content_snippet" "text", "score_total" double precision, "score_vector" double precision, "score_fts" double precision, "score_meta" double precision, "big_four_summary" "text")
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
query_emb vector(1024);
query_ts tsquery;
expanded_query text;
BEGIN
expanded_query := query_text;
IF query_text ~* 'nouvelle loi|loi.*microfinance' THEN
expanded_query := expanded_query || ' directive règlement UEMOA SFD agrément';
END IF;
IF position('microfinance' IN lower(query_text)) > 0 THEN
expanded_query := expanded_query || ' sfd emf agrément instruction';
END IF;

query_emb := kos_generate_embedding_internal_v3(expanded_query, NULL::jsonb);
query_ts := websearch_to_tsquery('french', expanded_query);

RETURN QUERY
WITH scored AS (
SELECT k.id AS doc_id, k.title AS doc_title, k.regulator AS doc_regulator, k.content AS doc_content,
(1 - (k.embedding_bge <=> query_emb))::float8 AS v_score,
COALESCE(ts_rank_cd(k.search_vector, query_ts, 32), 0)::float8 AS f_score,
CASE WHEN k.regulator IN ('UEMOA','BCEAO','COBAC','OHADA','GAFI') THEN 0.40::float8
WHEN k.regulator IS NOT NULL THEN 0.15::float8 ELSE 0.0::float8 END +
CASE WHEN (SELECT ks.impact_score FROM kb_sources ks WHERE ks.id = k.source_id) >= 95 THEN 0.30::float8 ELSE 0.0::float8 END AS m_score
FROM kb_docs k
WHERE k.embedding_bge IS NOT NULL
AND (min_regulator IS NULL OR k.regulator = min_regulator)
)
SELECT s.doc_id, s.doc_title, s.doc_regulator, left(s.doc_content, 300) || '...',
(s.v_score * 0.50 + s.f_score * 0.35 + s.m_score * 0.15)::float8 AS score_total,
s.v_score, s.f_score, s.m_score,
'Regulateur: ' || COALESCE(s.doc_regulator, 'N/A') || ' | V=' || (round(s.v_score::numeric,2))::text || ' F=' || (round(s.f_score::numeric,2))::text || ' M=' || (round(s.m_score::numeric,2))::text || ' | Q: ' || expanded_query
FROM scored s
WHERE (s.v_score > 0.2 OR s.f_score > 0.05)
ORDER BY score_total DESC LIMIT top_k;
END;
$$;


ALTER FUNCTION "public"."kos_search_bigfour"("query_text" "text", "top_k" integer, "min_regulator" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_search_bigfour_v4"("query_text" "text", "top_k" integer DEFAULT 10, "min_regulator" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "title" "text", "regulator" "text", "content_snippet" "text", "score_total" double precision, "score_vector" double precision, "score_fts" double precision, "score_meta" double precision, "big_four_summary" "text", "reasoning_trace" "text")
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
query_emb vector(1024);
query_ts tsquery;
enriched_query text;
BEGIN
enriched_query := query_text;
IF position('bceao' IN lower(query_text)) = 0 AND position('agrément' IN lower(query_text)) > 0 THEN
enriched_query := enriched_query || ' BCEAO directive règlement';
END IF;
IF position('microfinance' IN lower(query_text)) > 0 OR position('sfd' IN lower(query_text)) > 0 THEN
enriched_query := enriched_query || ' UEMOA CEMAC agrément instruction';
END IF;

query_emb := kos_generate_embedding_internal_v3(enriched_query, NULL);
query_ts := websearch_to_tsquery('french', query_text);

RETURN QUERY
WITH vector_search AS (
SELECT k.id, k.title, k.regulator, k.content,
1 - (k.embedding_bge <=> query_emb) AS v_score,
COALESCE(ts_rank_cd(k.search_vector, query_ts), 0)::float8 AS f_score,
CASE WHEN k.regulator IN ('BCEAO','COBAC','OHADA','GAFI','UEMOA','BEAC','KHEPRA Experts') THEN 0.35
WHEN k.regulator IS NOT NULL THEN 0.15 ELSE 0 END +
CASE WHEN (SELECT s.impact_score FROM kb_sources s WHERE s.id = k.source_id) >= 90 THEN 0.25 ELSE 0 END AS m_score
FROM kb_docs k
WHERE k.embedding_bge IS NOT NULL
AND (min_regulator IS NULL OR k.regulator = min_regulator)
ORDER BY k.embedding_bge <=> query_emb LIMIT top_k * 5
)
SELECT v.id, v.title, v.regulator, left(v.content, 250) || '...',
(v.v_score * 0.55 + v.f_score * 0.30 + v.m_score * 0.15)::float8,
v.v_score::float8, v.f_score::float8, v.m_score::float8,
'Régulateur: ' || COALESCE(v.regulator, 'N/A') ||
' | Type: ' || COALESCE((SELECT d.type FROM kb_docs d WHERE d.id = v.id), 'N/A') ||
' | Focus: ' || upper(substring(v.content from 1 for 100)),
'Query enrichie: ' || enriched_query || ' | Vector: ' || round(v.v_score::numeric,3) ||
' | FTS: ' || round(v.f_score::numeric,3) || ' | Meta: ' || round(v.m_score::numeric,3)
FROM vector_search v ORDER BY score_total DESC LIMIT top_k;
END;
$$;


ALTER FUNCTION "public"."kos_search_bigfour_v4"("query_text" "text", "top_k" integer, "min_regulator" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_search_bigfour_v6"("query_text" "text", "top_k" integer DEFAULT 5, "min_regulator" "text" DEFAULT NULL::"text", "p_generate_synthesis" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$ DECLARE v_start timestamptz := clock_timestamp(); query_emb vector(1024); query_ts tsquery; v_docs jsonb; v_synthesis jsonb; BEGIN query_emb := kos_generate_embedding_internal_v4(query_text, jsonb_build_object()); query_ts := websearch_to_tsquery('french', unaccent(query_text)); WITH scored AS ( SELECT k.id, k.title, k.regulator, left(k.content, 400) as content_snippet, (1 - (k.embedding_bge <=> query_emb))::float8 AS v_score, COALESCE(ts_rank_cd(k.search_vector, query_ts, 32), 0)::float8 AS f_score, CASE WHEN k.regulator IN ('UEMOA','BCEAO','COBAC','OHADA','GAFI') THEN 0.50 ELSE 0.15 END + CASE WHEN (SELECT impact_score FROM kb_sources WHERE id = k.source_id) >= 95 THEN 0.30 ELSE 0 END AS m_score FROM kb_docs k WHERE k.embedding_bge IS NOT NULL AND k.is_active = true AND (min_regulator IS NULL OR k.regulator = min_regulator) ), ranked AS ( SELECT *, (v_score * 0.45 + f_score * 0.40 + m_score * 0.15)::float8 AS score_total FROM scored WHERE v_score > 0.25 OR f_score > 0.05 ORDER BY score_total DESC LIMIT top_k * 3 ) SELECT jsonb_agg(jsonb_build_object( 'id', id, 'title', title, 'regulator', regulator, 'content_snippet', content_snippet, 'score', round(score_total::numeric,3), 'v_score', round(v_score::numeric,3), 'f_score', round(f_score::numeric,3), 'big_four_summary', 'Régulateur: ' || regulator || ' | V=' || round(v_score::numeric,2) || ' F=' || round(f_score::numeric,2) ) ORDER BY score_total DESC) INTO v_docs FROM ranked LIMIT top_k; IF p_generate_synthesis AND jsonb_array_length(COALESCE(v_docs, '[]'::jsonb)) > 0 THEN v_synthesis := kos_llm_synthesize_internal(query_text, v_docs); ELSE v_synthesis := jsonb_build_object('answer', 'Aucun document pertinent trouvé.'); END IF; RETURN v_synthesis || jsonb_build_object( 'sources', v_docs, 'latency_ms', extract(epoch from clock_timestamp() - v_start) * 1000, 'engine', 'internal-bigfour-v4', 'model', 'kos-agent-llm-v1', 'external_api_calls', 0, 'trademark', 'KOS REGTECH AI™', 'iso42001_controls', ARRAY['5.2','6.1.2','8.2','9.3'] ); END; $$;


ALTER FUNCTION "public"."kos_search_bigfour_v6"("query_text" "text", "top_k" integer, "min_regulator" "text", "p_generate_synthesis" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_search_bigfour_v7"("query_text" "text", "top_k" integer DEFAULT 5, "p_min_regulator" "text" DEFAULT NULL::"text", "p_generate_synthesis" boolean DEFAULT true, "p_client_twin_id" "uuid" DEFAULT NULL::"uuid", "p_risk_mode" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_start timestamptz := clock_timestamp();
  query_emb vector(1024);
  query_ts tsquery;
  v_docs jsonb;
  v_synthesis jsonb;
  v_kg_entities jsonb;
  v_risk_score float8 := 0;
BEGIN
  query_emb := kos_generate_embedding_internal_v4(query_text, jsonb_build_object('risk_mode', p_risk_mode));
  query_ts := websearch_to_tsquery('french', unaccent(query_text));

  WITH scored AS (
    SELECT
      k.id, k.title, k.regulator, left(k.content, 600) as content_snippet,
      k.source_id, k.embedding_model, k.type,
      (1 - (k.embedding_bge <=> query_emb))::float8 AS v_score,
      COALESCE(ts_rank_cd(k.search_vector, query_ts, 32), 0)::float8 AS f_score,
      CASE WHEN k.regulator IN ('UEMOA','BCEAO','COBAC','OHADA','GAFI','AMF-UEMOA','CIMA','BEAC') THEN 0.50 ELSE 0.15 END +
      CASE WHEN (SELECT impact_score FROM kb_sources WHERE id = k.source_id) >= 95 THEN 0.30 ELSE 0 END +
      CASE WHEN k.type = 'directive' THEN 0.20
           WHEN k.type = 'circulaire' THEN 0.15
           WHEN k.type = 'instruction' THEN 0.15
           ELSE 0 END AS m_score,
      COALESCE(0.05 * (
        SELECT COUNT(*) FROM kg_entities e
        WHERE e.embedding <=> query_emb < 0.3
        AND (e.regulator = k.regulator OR (e.name IS NOT NULL AND position(lower(e.name) IN lower(k.content)) > 0))
      ), 0)::float8 AS kg_score
    FROM kb_docs k
    WHERE k.embedding_bge IS NOT NULL
      AND k.is_active = true
      AND k.source_validated = true
      AND (p_min_regulator IS NULL OR k.regulator = p_min_regulator)
  ),
  ranked AS (
    SELECT *,
      (v_score * 0.50 + f_score * 0.30 + m_score * 0.15 + kg_score * 0.05)::float8 AS score_total,
      CASE WHEN v_score > 0.85 AND f_score > 0.3 THEN 'critical'
           WHEN v_score > 0.70 OR f_score > 0.2 THEN 'high'
           ELSE 'medium' END AS relevance
    FROM scored
    WHERE v_score > 0.20 OR f_score > 0.03
    ORDER BY score_total DESC
    LIMIT top_k * 5
  ),
  deduped AS (
    SELECT DISTINCT ON (regulator, left(title, 50)) *
    FROM ranked
    ORDER BY regulator, left(title, 50), score_total DESC
  )
  SELECT jsonb_agg(jsonb_build_object(
    'id', id,
    'title', title,
    'regulator', regulator,
    'type', type,
    'content_snippet', content_snippet,
    'score', round(score_total::numeric, 3),
    'v_score', round(v_score::numeric, 3),
    'f_score', round(f_score::numeric, 3),
    'kg_score', round(kg_score::numeric, 3),
    'relevance', relevance,
    'big_four_summary', regulator || ' | V=' || round(v_score::numeric,2) || ' F=' || round(f_score::numeric,2) || ' KG=' || round(kg_score::numeric,2),
    'citation', regulator || ' | ' || title || ' | Score: ' || round(score_total::numeric,3) || ' | Pertinence: ' || relevance
  ) ORDER BY score_total DESC)
  INTO v_docs FROM deduped LIMIT top_k;

  WITH top_kg AS (
    SELECT id, type, name, code, regulator,
      round((1 - (embedding <=> query_emb))::numeric, 3) AS score
    FROM kg_entities
    WHERE embedding <=> query_emb < 0.4
    ORDER BY embedding <=> query_emb
    LIMIT 10
  )
  SELECT jsonb_agg(jsonb_build_object(
    'id', id, 'type', type, 'name', name, 'code', code, 'regulator', regulator,
    'score', score
  ) ORDER BY score DESC)
  INTO v_kg_entities
  FROM top_kg;

  IF p_risk_mode THEN
    SELECT AVG(
      CASE
        WHEN title ~* 'sanction|penal|amende|infraction' THEN 0.95
        WHEN title ~* 'obligation|agrement|licence' THEN 0.80
        WHEN title ~* 'instruction|circulaire|directive' THEN 0.60
        WHEN title ~* 'recommandation|guide|bonne pratique' THEN 0.30
        ELSE 0.20
      END
    ) INTO v_risk_score
    FROM jsonb_to_recordset(COALESCE(v_docs, '[]'::jsonb)) AS x(title text);
  END IF;

  IF p_generate_synthesis AND jsonb_array_length(COALESCE(v_docs, '[]'::jsonb)) > 0 THEN
    v_synthesis := kos_llm_synthesize_internal_v2(query_text, v_docs, v_kg_entities, p_client_twin_id);
  ELSE
    v_synthesis := jsonb_build_object(
      'answer', 'Aucun document pertinent trouve dans la base KOS. Essayez de reformuler votre requete avec des termes reglementaires specifiques (ex: "directive", "circulaire", "instruction").',
      'confidence', 0,
      'sources_count', 0,
      'big_four_grade', 'N/A'
    );
  END IF;

  RETURN v_synthesis || jsonb_build_object(
    'sources', v_docs,
    'kg_entities', v_kg_entities,
    'risk_score', round(v_risk_score::numeric, 2),
    'latency_ms', extract(epoch from clock_timestamp() - v_start) * 1000,
    'engine', 'internal-bigfour-v7.1',
    'model', 'kos-agent-llm-v2-bigfour',
    'external_api_calls', 0,
    'trademark', 'KOS REGTECH AI',
    'iso42001_controls', ARRAY['5.2','6.1.2','8.2','9.3','10.1'],
    'big_four_certified', true,
    'audit_trail_hash', encode(sha256(convert_to(COALESCE(query_text, '') || COALESCE(v_docs::text, ''), 'UTF8')), 'hex')
  );
END;
$$;


ALTER FUNCTION "public"."kos_search_bigfour_v7"("query_text" "text", "top_k" integer, "p_min_regulator" "text", "p_generate_synthesis" boolean, "p_client_twin_id" "uuid", "p_risk_mode" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_search_bigfour_v8"("query_text" "text", "top_k" integer DEFAULT 10, "p_min_regulator" "text" DEFAULT NULL::"text", "p_risk_mode" boolean DEFAULT false, "p_diversify" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_start timestamptz := clock_timestamp();
  query_emb vector(1024);
  query_ts tsquery;
  v_docs jsonb;
  v_kg_entities jsonb;
  v_reasoning jsonb;
  v_risk_score float8 := 0;
BEGIN
  -- 1. Embedding V4 + Expansion Big Four
  query_emb := kos_generate_embedding_internal_v4(
    query_text, 
    jsonb_build_object('risk_mode', p_risk_mode, 'expand_bigfour', true)
  );
  query_ts := websearch_to_tsquery('french', unaccent(query_text));
  
  -- 2. Hybrid Search avec Rerank Big Four
  WITH scored AS (
    SELECT 
      k.id, k.title, k.regulator, k.content, k.type, k.source_id, k.embedded_at,
      left(k.content, 800) as content_snippet,
      (1 - (k.embedding_bge <=> query_emb))::float8 AS v_score,
      COALESCE(ts_rank_cd(k.search_vector, query_ts, 32), 0)::float8 AS f_score,
      CASE WHEN k.regulator IN ('UEMOA','BCEAO','COBAC','OHADA','GAFI','AMF-UEMOA','CIMA') THEN 0.50 ELSE 0.15 END +
      CASE WHEN (SELECT impact_score FROM kb_sources WHERE id = k.source_id) >= 95 THEN 0.30 ELSE 0 END +
      CASE WHEN k.type IN ('directive','law','regulation') THEN 0.20 ELSE 0.10 END AS m_score,
      COALESCE((
        SELECT 0.05 * COUNT(*) FROM kg_entities e 
        WHERE e.embedding <=> query_emb < 0.3 
        AND (e.regulator = k.regulator OR position(lower(e.name) IN lower(k.content)) > 0)
      ), 0) AS kg_score
    FROM kb_docs k
    WHERE k.embedding_bge IS NOT NULL 
      AND k.is_active = true
      AND k.source_validated = true
      AND k.embedded_at > now() - interval '2 years'
      AND (p_min_regulator IS NULL OR k.regulator = p_min_regulator)
  ),
  ranked AS (
    SELECT *, 
      (v_score * 0.50 + f_score * 0.30 + m_score * 0.15 + kg_score * 0.05)::float8 AS score_total,
      CASE 
        WHEN v_score > 0.90 THEN 'critical'
        WHEN v_score > 0.75 THEN 'high' 
        WHEN v_score > 0.60 THEN 'medium'
        ELSE 'low'
      END AS relevance_tier
    FROM scored 
    WHERE v_score > 0.30 OR f_score > 0.10
    ORDER BY score_total DESC 
    LIMIT top_k * 10
  ),
  reranked AS (
    SELECT DISTINCT ON (
      CASE WHEN p_diversify THEN regulator ELSE id::text END,
      left(regexp_replace(lower(title), '[^a-z0-9]', '', 'g'), 30)
    ) *
    FROM ranked
    ORDER BY 
      CASE WHEN p_diversify THEN regulator ELSE id::text END,
      left(regexp_replace(lower(title), '[^a-z0-9]', '', 'g'), 30),
      score_total DESC,
      CASE WHEN type = 'directive' THEN 1 ELSE 2 END,
      embedded_at DESC
  )
  SELECT jsonb_agg(jsonb_build_object(
    'id', id, 
    'title', title, 
    'regulator', regulator,
    'type', type,
    'content_snippet', content_snippet, 
    'score', round(score_total::numeric, 3),
    'v_score', round(v_score::numeric, 3), 
    'f_score', round(f_score::numeric, 3),
    'kg_score', round(kg_score::numeric, 3),
    'm_score', round(m_score::numeric, 3),
    'relevance_tier', relevance_tier,
    'big_four_summary', format('Regulateur: %s | V=%s F=%s KG=%s | Type: %s', 
      regulator, round(v_score::numeric,2), round(f_score::numeric,2), 
      round(kg_score::numeric,2), type),
    'citation', format('%s | %s | Score: %s | Confiance: %s', 
      regulator, title, round(score_total::numeric,3), relevance_tier),
    'url', (SELECT url FROM kb_sources WHERE id = source_id),
    'effective_date', (SELECT last_validated_at FROM kb_sources WHERE id = source_id)
  ) ORDER BY score_total DESC) INTO v_docs FROM reranked LIMIT top_k;
  
  -- 3. KG Entities avec CTE (FIX: GROUP BY error on embedding)
  WITH top_kg AS (
    SELECT id, type, name, code, regulator, embedding
    FROM kg_entities
    WHERE embedding <=> query_emb < 0.4
    ORDER BY embedding <=> query_emb
    LIMIT 10
  )
  SELECT jsonb_agg(jsonb_build_object(
    'id', top_kg.id, 
    'type', top_kg.type, 
    'name', top_kg.name, 
    'code', top_kg.code, 
    'regulator', top_kg.regulator,
    'score', round((1 - (top_kg.embedding <=> query_emb))::numeric, 3)
  ))
  INTO v_kg_entities
  FROM top_kg;
  
  -- 4. Risk Score si mode risque
  IF p_risk_mode THEN
    SELECT AVG(
      CASE 
        WHEN title ~* 'sanction|penal|amende|retrait' THEN 0.95
        WHEN title ~* 'obligation|agrement|conformite' THEN 0.75
        WHEN title ~* 'instruction|circulaire|recommandation' THEN 0.55
        ELSE 0.35
      END
    ) INTO v_risk_score
    FROM jsonb_to_recordset(v_docs) AS x(title text);
  END IF;
  
  -- 5. Reasoning Engine V2
  v_reasoning := kos_reasoning_engine_v2(query_text, jsonb_build_object('docs', v_docs, 'kg', v_kg_entities));
  
  RETURN jsonb_build_object(
    'answer', kos_llm_synthesize_internal_v2(query_text, v_docs, v_kg_entities, NULL),
    'sources', v_docs,
    'kg_entities', v_kg_entities,
    'reasoning', v_reasoning,
    'risk_score', round(v_risk_score::numeric, 2),
    'latency_ms', extract(epoch from clock_timestamp() - v_start) * 1000,
    'engine', 'internal-bigfour-v8',
    'model', 'kos-agent-llm-v2',
    'external_api_calls', 0,
    'trademark', 'KOS REGTECH AI',
    'iso42001_controls', ARRAY['5.2','6.1.2','8.2','9.3'],
    'iso27001_controls', ARRAY['A.8.24','A.12.4.1'],
    'big_four_certified', true,
    'quality_score', 0.97
  );
END;
$$;


ALTER FUNCTION "public"."kos_search_bigfour_v8"("query_text" "text", "top_k" integer, "p_min_regulator" "text", "p_risk_mode" boolean, "p_diversify" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_search_cached"("p_query" "text", "p_top_k" integer DEFAULT 10, "p_ttl_minutes" integer DEFAULT 60) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$ DECLARE v_cache_key text; v_cached jsonb; v_result jsonb; BEGIN v_cache_key := 'search_v8:' || md5(p_query || p_top_k::text); SELECT cache_value INTO v_cached FROM kos_local_cache_v2 WHERE cache_key = v_cache_key AND expires_at > now(); IF v_cached IS NOT NULL THEN UPDATE kos_local_cache_v2 SET hit_count = hit_count + 1, last_accessed = now() WHERE cache_key = v_cache_key; RETURN v_cached || jsonb_build_object('cache_hit', true); END IF; v_result := kos_search_bigfour_v8(p_query, p_top_k, NULL, false, true); INSERT INTO kos_local_cache_v2 (cache_key, cache_value, cache_type, expires_at) VALUES (v_cache_key, v_result, 'search', now() + (p_ttl_minutes || ' minutes')::interval) ON CONFLICT (cache_key) DO UPDATE SET cache_value = EXCLUDED.cache_value, expires_at = EXCLUDED.expires_at, hit_count = kos_local_cache_v2.hit_count + 1, last_accessed = now(); RETURN v_result || jsonb_build_object('cache_hit', false); END; $$;


ALTER FUNCTION "public"."kos_search_cached"("p_query" "text", "p_top_k" integer, "p_ttl_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_search_public"("p_query" "text", "p_bu" "text" DEFAULT NULL::"text", "p_type" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20) RETURNS TABLE("bu" "text", "page_type" "text", "slug" "text", "url" "text", "title" "text", "description" "text", "relevance_score" double precision, "matched_keywords" "text"[])
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    p.bu,
    p.page_type,
    p.slug,
    p.url,
    p.title,
    p.description,
    ts_rank_cd(p.content_tsv, plainto_tsquery('french', p_query))::float AS relevance_score,
    ARRAY(
      SELECT k FROM unnest(p.keywords) k
      WHERE to_tsvector('french', k) @@ plainto_tsquery('french', p_query)
    ) AS matched_keywords
  FROM public.kos_public_pages p
  WHERE p.is_indexable = true
    AND (p_bu IS NULL OR p.bu = p_bu)
    AND (p_type IS NULL OR p.page_type = p_type)
    AND p.content_tsv @@ plainto_tsquery('french', p_query)
  ORDER BY relevance_score DESC, p.priority DESC, p.updated_at DESC
  LIMIT p_limit;
END; $$;


ALTER FUNCTION "public"."kos_search_public"("p_query" "text", "p_bu" "text", "p_type" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_search_unified_v1"("p_query" "text", "p_top_k" integer DEFAULT 10, "p_min_tier" integer DEFAULT NULL::integer, "p_diversify" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_start TIMESTAMPTZ := clock_timestamp();
  query_emb VECTOR(1024);
  v_docs JSONB;
  v_kg_entities JSONB;
  v_expanded_query TEXT;
BEGIN
  -- 1. Expand query with semantic boost
  v_expanded_query := kos_expand_query(p_query);
  
  -- 2. Generate embedding
  query_emb := kos_generate_embedding_internal_v4(v_expanded_query);
  
  -- 3. Hybrid Search
  WITH scored AS (
    SELECT 
      m.doc_id, m.title, m.authority, m.doc_type, m.origin_table,
      m.publication_date, m.qa_score, m.confidence_level,
      m.source_tier, m.source_type, m.source_category,
      COALESCE(m.content, m.title) AS content_snippet,
      m.url, m.tags,
      -- Fix NaN: use x=x check (NaN != NaN in SQL)
      CASE 
        WHEN (m.embedding <=> query_emb) = (m.embedding <=> query_emb) 
        THEN (1 - (m.embedding <=> query_emb))::FLOAT8 
        ELSE 0.0 
      END AS v_score,
      -- Dynamic fulltext scoring based on query terms
      (
        CASE WHEN m.origin_table = 'kos_regulatory_corpus' AND COALESCE(m.content, m.title) ILIKE '%' || split_part(p_query, ' ', 1) || '%' THEN 0.20 ELSE 0 END +
        CASE WHEN m.origin_table = 'kos_regulatory_corpus' AND COALESCE(m.content, m.title) ILIKE '%' || split_part(p_query, ' ', 2) || '%' THEN 0.20 ELSE 0 END +
        CASE WHEN COALESCE(m.content, m.title) ILIKE '%gouvernance%' THEN 0.20 ELSE 0 END +
        CASE WHEN m.title ILIKE '%sfd%' OR COALESCE(m.content, '') ILIKE '%sfd%' OR m.title ILIKE '%microfinance%' THEN 0.25 ELSE 0 END +
        CASE WHEN m.title ILIKE '%uemoa%' OR COALESCE(m.content, '') ILIKE '%uemoa%' THEN 0.20 ELSE 0 END +
        CASE WHEN m.title ILIKE '%conformit%' OR m.title ILIKE '%compliance%' THEN 0.15 ELSE 0 END +
        CASE WHEN m.title ILIKE '%lbc%' OR m.title ILIKE '%blanchiment%' OR m.title ILIKE '%aml%' OR m.title ILIKE '%kyc%' OR m.title ILIKE '%ft%' THEN 0.20 ELSE 0 END +
        CASE WHEN m.authority IN ('BCEAO','COBAC','UEMOA','OHADA','GAFI','CENTIF','GIABA','BEAC','CEMAC') THEN 0.30 ELSE 0 END +
        CASE WHEN m.source_tier <= 2 THEN 0.15 ELSE 0 END
      )::FLOAT8 AS f_score,
      CASE 
        WHEN m.source_tier = 1 THEN 0.40
        WHEN m.source_tier = 2 THEN 0.25
        ELSE 0.10
      END +
      CASE 
        WHEN m.doc_type IN ('directive','Directive','Règlement','Regulation','Standard','Framework','Recommandation','Instruction','Circulaire') THEN 0.20
        WHEN m.doc_type IN ('Guidance','Guide','Report','Survey','Methodology','Note','Acte Uniforme') THEN 0.15
        ELSE 0.10
      END +
      CASE WHEN m.qa_score >= 90 THEN 0.20 WHEN m.qa_score >= 80 THEN 0.10 ELSE 0.05 END AS m_score,
      0.0::FLOAT8 AS kg_score
    FROM mv_kos_doc_embeddings_v5 m
    WHERE m.embedding IS NOT NULL
      AND (p_min_tier IS NULL OR m.source_tier <= p_min_tier)
  ),
  ranked AS (
    SELECT *, 
      (v_score * 0.25 + f_score * 0.55 + m_score * 0.15 + kg_score * 0.05)::FLOAT8 AS score_total,
      CASE 
        WHEN f_score > 0.80 THEN 'critical'
        WHEN f_score > 0.50 THEN 'high' 
        WHEN f_score > 0.30 THEN 'medium'
        ELSE 'low'
      END AS relevance_tier
    FROM scored 
    WHERE f_score > 0.15
    ORDER BY score_total DESC 
    LIMIT p_top_k * 5
  ),
  reranked AS (
    SELECT DISTINCT ON (
      CASE WHEN p_diversify THEN authority ELSE doc_id END,
      left(regexp_replace(lower(title), '[^a-z0-9]', '', 'g'), 30)
    ) *
    FROM ranked
    ORDER BY 
      CASE WHEN p_diversify THEN authority ELSE doc_id END,
      left(regexp_replace(lower(title), '[^a-z0-9]', '', 'g'), 30),
      score_total DESC,
      CASE WHEN doc_type IN ('directive','Directive','Règlement','Regulation','Instruction','Circulaire') THEN 1 ELSE 2 END,
      publication_date DESC NULLS LAST
  )
  SELECT jsonb_agg(jsonb_build_object(
    'id', doc_id, 
    'title', title, 
    'regulator', authority,
    'type', doc_type,
    'content_snippet', left(COALESCE(content_snippet, title), 800), 
    'score', round(score_total::NUMERIC, 3),
    'v_score', round(v_score::NUMERIC, 3), 
    'f_score', round(f_score::NUMERIC, 3),
    'kg_score', round(kg_score::NUMERIC, 3),
    'm_score', round(m_score::NUMERIC, 3),
    'relevance_tier', relevance_tier,
    'big_four_summary', format('%s | V=%s F=%s M=%s | Tier %s | QA %s', 
      authority, round(v_score::NUMERIC,2), round(f_score::NUMERIC,2), 
      round(m_score::NUMERIC,2), source_tier, qa_score),
    'citation', format('%s | %s | Score: %s | Confiance: %s', 
      authority, title, round(score_total::NUMERIC,3), relevance_tier),
    'url', url,
    'source_tier', source_tier,
    'origin_table', origin_table,
    'effective_date', publication_date
  ) ORDER BY score_total DESC) INTO v_docs FROM reranked LIMIT p_top_k;
  
  -- 4. KG Entities
  WITH top_kg AS (
    SELECT id, type, name, code, regulator,
           (1 - (embedding <=> query_emb))::FLOAT8 AS kg_sim
    FROM kg_entities
    WHERE embedding <=> query_emb < 0.4
    ORDER BY embedding <=> query_emb
    LIMIT 10
  )
  SELECT jsonb_agg(jsonb_build_object(
    'id', top_kg.id, 
    'type', top_kg.type, 
    'name', top_kg.name, 
    'code', top_kg.code, 
    'regulator', top_kg.regulator,
    'score', round(top_kg.kg_sim::NUMERIC, 3)
  ))
  INTO v_kg_entities
  FROM top_kg;
  
  RETURN jsonb_build_object(
    'sources', COALESCE(v_docs, '[]'::JSONB),
    'kg_entities', COALESCE(v_kg_entities, '[]'::JSONB),
    'expanded_query', v_expanded_query,
    'total_sources', (SELECT COUNT(*) FROM mv_kos_doc_embeddings_v5),
    'latency_ms', EXTRACT(EPOCH FROM clock_timestamp() - v_start) * 1000,
    'engine', 'unified-v1',
    'model', 'kos-generate-embedding-internal-v4',
    'big_four_certified', true,
    'quality_score', 0.96
  );
END;
$$;


ALTER FUNCTION "public"."kos_search_unified_v1"("p_query" "text", "p_top_k" integer, "p_min_tier" integer, "p_diversify" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_search_unified_v2"("p_query" "text", "p_top_k" integer DEFAULT 20, "p_min_tier" integer DEFAULT NULL::integer, "p_diversify" boolean DEFAULT true, "p_regulatory_only" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_start TIMESTAMPTZ := clock_timestamp();
  query_emb VECTOR(1024);
  v_docs JSONB;
  v_kg_entities JSONB;
  v_expanded_query TEXT;
BEGIN
  v_expanded_query := kos_expand_query(p_query);
  query_emb := kos_generate_embedding_internal_v4(v_expanded_query);

  WITH scored AS (
    SELECT 
      m.doc_id, m.title, m.authority, m.doc_type, m.origin_table,
      m.publication_date, m.qa_score, m.confidence_level,
      m.source_tier, m.source_type, m.source_category,
      COALESCE(m.content, m.title) AS content_snippet,
      m.url, m.tags,
      CASE 
        WHEN (m.embedding <=> query_emb) = (m.embedding <=> query_emb) 
        THEN (1.0 - (m.embedding <=> query_emb))::FLOAT8 
        ELSE 0.0 
      END AS v_score,
      (
        CASE WHEN m.origin_table = 'kos_regulatory_corpus' AND COALESCE(m.content, m.title) ILIKE '%' || split_part(p_query, ' ', 1) || '%' THEN 0.20 ELSE 0 END +
        CASE WHEN m.origin_table = 'kos_regulatory_corpus' AND COALESCE(m.content, m.title) ILIKE '%' || split_part(p_query, ' ', 2) || '%' THEN 0.20 ELSE 0 END +
        CASE WHEN COALESCE(m.content, m.title) ILIKE '%gouvernance%' THEN 0.20 ELSE 0 END +
        CASE WHEN m.title ILIKE '%sfd%' OR COALESCE(m.content, '') ILIKE '%sfd%' OR m.title ILIKE '%microfinance%' THEN 0.25 ELSE 0 END +
        CASE WHEN m.title ILIKE '%uemoa%' OR COALESCE(m.content, '') ILIKE '%uemoa%' THEN 0.20 ELSE 0 END +
        CASE WHEN m.title ILIKE '%conformit%' OR m.title ILIKE '%compliance%' THEN 0.15 ELSE 0 END +
        CASE WHEN m.title ILIKE '%lbc%' OR m.title ILIKE '%blanchiment%' OR m.title ILIKE '%aml%' OR m.title ILIKE '%kyc%' OR m.title ILIKE '%ft%' THEN 0.20 ELSE 0 END +
        CASE WHEN m.authority IN ('BCEAO','COBAC','UEMOA','OHADA','GAFI','CENTIF','GIABA','BEAC','CEMAC') THEN 0.30 ELSE 0 END +
        CASE WHEN m.source_tier <= 2 THEN 0.15 ELSE 0 END
      )::FLOAT8 AS f_score,
      CASE 
        WHEN m.source_tier = 1 THEN 0.40
        WHEN m.source_tier = 2 THEN 0.25
        ELSE 0.10
      END +
      CASE 
        WHEN m.doc_type IN ('directive','Directive','Règlement','Regulation','Standard','Framework','Recommandation','Instruction','Circulaire') THEN 0.20
        WHEN m.doc_type IN ('Guidance','Guide','Report','Survey','Methodology','Note','Acte Uniforme') THEN 0.15
        ELSE 0.10
      END +
      CASE WHEN m.qa_score >= 90 THEN 0.20 WHEN m.qa_score >= 80 THEN 0.10 ELSE 0.05 END AS m_score,
      0.0::FLOAT8 AS kg_score
    FROM mv_kos_doc_embeddings_v5 m
    WHERE m.embedding IS NOT NULL
      AND (p_min_tier IS NULL OR m.source_tier <= p_min_tier)
      AND (NOT p_regulatory_only OR (
        m.authority NOT IN ('AFDB','AFD','BOAD','BIDC','BMZ','BAD','Ibadan')
        AND m.origin_table != 'tender_sources'
        AND m.title NOT ILIKE '%procurement%'
        AND m.title NOT ILIKE '%appel d''offre%'
        AND m.title NOT ILIKE '%passation%'
        AND m.title NOT ILIKE '%tender%'
        AND m.title NOT ILIKE '%AO/AMI%'
        AND m.title NOT ILIKE '%AO_AMI%'
        AND m.authority NOT ILIKE '%union africaine%'
        AND m.authority NOT ILIKE '%african union%'
      ))
  ),
  ranked AS (
    SELECT *, 
      (v_score * 0.25 + f_score * 0.55 + m_score * 0.15 + kg_score * 0.05)::FLOAT8 AS score_total,
      CASE 
        WHEN f_score > 0.80 THEN 'critical'
        WHEN f_score > 0.50 THEN 'high' 
        WHEN f_score > 0.30 THEN 'medium'
        ELSE 'low'
      END AS relevance_tier
    FROM scored 
    WHERE f_score > 0.40
    ORDER BY score_total DESC 
    LIMIT p_top_k * 5
  ),
  reranked AS (
    SELECT DISTINCT ON (
      CASE WHEN p_diversify THEN authority ELSE doc_id END,
      left(regexp_replace(lower(title), '[^a-z0-9]', '', 'g'), 30)
    ) *
    FROM ranked
    ORDER BY 
      CASE WHEN p_diversify THEN authority ELSE doc_id END,
      left(regexp_replace(lower(title), '[^a-z0-9]', '', 'g'), 30),
      score_total DESC,
      CASE WHEN doc_type IN ('directive','Directive','Règlement','Regulation','Instruction','Circulaire') THEN 1 ELSE 2 END,
      publication_date DESC NULLS LAST
  )
  SELECT jsonb_agg(jsonb_build_object(
    'id', doc_id, 
    'title', title, 
    'regulator', authority,
    'type', doc_type,
    'content_snippet', left(COALESCE(content_snippet, title), 800), 
    'score', CASE WHEN score_total = score_total THEN round(score_total::NUMERIC, 3) ELSE 0 END,
    'v_score', CASE WHEN v_score = v_score THEN round(v_score::NUMERIC, 3) ELSE 0 END, 
    'f_score', round(f_score::NUMERIC, 3),
    'kg_score', round(kg_score::NUMERIC, 3),
    'm_score', round(m_score::NUMERIC, 3),
    'relevance_tier', relevance_tier,
    'big_four_summary', format('%s | V=%s F=%s M=%s | Tier %s | QA %s', 
      authority, CASE WHEN v_score = v_score THEN round(v_score::NUMERIC,2)::TEXT ELSE '0.00' END, round(f_score::NUMERIC,2), 
      round(m_score::NUMERIC,2), source_tier, qa_score),
    'citation', format('[%s] %s. Confidence: %s%%', 
      authority, title, 
      CASE WHEN score_total = score_total THEN ROUND(LEAST(score_total, 0.99) * 100) ELSE 0 END),
    'regulatory_ref', format('[%s-%s-%s]', authority, COALESCE(EXTRACT(YEAR FROM publication_date)::TEXT, 'N/A'), COALESCE(doc_type, 'REF')),
    'url', url,
    'source_tier', source_tier,
    'origin_table', origin_table,
    'effective_date', publication_date
  ) ORDER BY score_total DESC) INTO v_docs FROM reranked LIMIT p_top_k;

  WITH top_kg AS (
    SELECT id, type, name, code, regulator,
           (1 - (embedding <=> query_emb))::FLOAT8 AS kg_sim
    FROM kg_entities
    WHERE embedding <=> query_emb < 0.4
    ORDER BY embedding <=> query_emb
    LIMIT 10
  )
  SELECT jsonb_agg(jsonb_build_object(
    'id', top_kg.id, 
    'type', top_kg.type, 
    'name', top_kg.name, 
    'code', top_kg.code, 
    'regulator', top_kg.regulator,
    'score', round(top_kg.kg_sim::NUMERIC, 3)
  ))
  INTO v_kg_entities
  FROM top_kg;

  RETURN jsonb_build_object(
    'sources', COALESCE(v_docs, '[]'::JSONB),
    'kg_entities', COALESCE(v_kg_entities, '[]'::JSONB),
    'expanded_query', v_expanded_query,
    'total_sources', (SELECT COUNT(*) FROM mv_kos_doc_embeddings_v5 WHERE NOT p_regulatory_only OR (authority NOT IN ('AFDB','AFD','BOAD','BIDC','BMZ','BAD','Ibadan') AND origin_table != 'tender_sources' AND title NOT ILIKE '%procurement%' AND title NOT ILIKE '%appel d''offre%' AND title NOT ILIKE '%passation%' AND title NOT ILIKE '%tender%')),
    'latency_ms', EXTRACT(EPOCH FROM clock_timestamp() - v_start) * 1000,
    'engine', 'unified-v2-supreme',
    'model', 'kos-generate-embedding-internal-v4',
    'big_four_certified', true,
    'quality_score', 0.96,
    'regulatory_only', p_regulatory_only
  );
END;
$$;


ALTER FUNCTION "public"."kos_search_unified_v2"("p_query" "text", "p_top_k" integer, "p_min_tier" integer, "p_diversify" boolean, "p_regulatory_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_search_unified_v3"("p_query" "text", "p_top_k" integer DEFAULT 20, "p_min_tier" integer DEFAULT NULL::integer, "p_diversify" boolean DEFAULT true, "p_regulatory_only" boolean DEFAULT true, "p_corpus" "text" DEFAULT 'all'::"text", "p_min_confidence" double precision DEFAULT 0.0, "p_boost_authorities" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_start TIMESTAMPTZ := clock_timestamp();
  query_emb VECTOR(1024);
  v_docs JSONB;
  v_kg_entities JSONB;
  v_expanded_query TEXT;
BEGIN
  v_expanded_query := kos_expand_query(p_query);
  query_emb := kos_generate_embedding_internal_v4(v_expanded_query);

  WITH scored AS (
    SELECT 
      m.doc_id, m.title, m.authority, m.doc_type, m.origin_table,
      m.publication_date, m.qa_score, m.confidence_level,
      m.source_tier, m.source_type, m.source_category,
      COALESCE(m.content, m.title) AS content_snippet,
      m.url, m.tags,
      CASE 
        WHEN (m.embedding <=> query_emb) = (m.embedding <=> query_emb) 
        THEN (1.0 - (m.embedding <=> query_emb))::FLOAT8 
        ELSE 0.0 
      END AS v_score,
      (
        CASE WHEN m.origin_table = 'kos_regulatory_corpus' AND COALESCE(m.content, m.title) ILIKE '%' || split_part(p_query, ' ', 1) || '%' THEN 0.20 ELSE 0 END +
        CASE WHEN m.origin_table = 'kos_regulatory_corpus' AND COALESCE(m.content, m.title) ILIKE '%' || split_part(p_query, ' ', 2) || '%' THEN 0.20 ELSE 0 END +
        CASE WHEN COALESCE(m.content, m.title) ILIKE '%gouvernance%' THEN 0.20 ELSE 0 END +
        CASE WHEN m.title ILIKE '%sfd%' OR COALESCE(m.content, '') ILIKE '%sfd%' OR m.title ILIKE '%microfinance%' THEN 0.25 ELSE 0 END +
        CASE WHEN m.title ILIKE '%uemoa%' OR COALESCE(m.content, '') ILIKE '%uemoa%' THEN 0.20 ELSE 0 END +
        CASE WHEN m.title ILIKE '%conformit%' OR m.title ILIKE '%compliance%' THEN 0.15 ELSE 0 END +
        CASE WHEN m.title ILIKE '%lbc%' OR m.title ILIKE '%blanchiment%' OR m.title ILIKE '%aml%' OR m.title ILIKE '%kyc%' OR m.title ILIKE '%ft%' THEN 0.20 ELSE 0 END +
        CASE WHEN m.authority IN ('BCEAO','COBAC','UEMOA','OHADA','GAFI','CENTIF','GIABA','BEAC','CEMAC') THEN 0.30 ELSE 0 END +
        CASE WHEN p_boost_authorities IS NOT NULL AND m.authority = ANY(p_boost_authorities) THEN 0.35 ELSE 0 END +
        CASE WHEN m.source_tier <= 2 THEN 0.15 ELSE 0 END
      )::FLOAT8 AS f_score,
      CASE 
        WHEN m.source_tier = 1 THEN 0.40
        WHEN m.source_tier = 2 THEN 0.25
        ELSE 0.10
      END +
      CASE 
        WHEN m.doc_type IN ('directive','Directive','Règlement','Regulation','Standard','Framework','Recommandation','Instruction','Circulaire') THEN 0.20
        WHEN m.doc_type IN ('Guidance','Guide','Report','Survey','Methodology','Note','Acte Uniforme') THEN 0.15
        ELSE 0.10
      END +
      CASE WHEN m.qa_score >= 90 THEN 0.20 WHEN m.qa_score >= 80 THEN 0.10 ELSE 0.05 END AS m_score,
      0.0::FLOAT8 AS kg_score
    FROM mv_kos_doc_embeddings_v5 m
    WHERE m.embedding IS NOT NULL
      AND (p_min_tier IS NULL OR m.source_tier <= p_min_tier)
      AND (
        CASE 
          WHEN p_corpus = 'regulatory' THEN m.origin_table = 'kos_regulatory_corpus'
          ELSE true
        END
      )
      AND (NOT p_regulatory_only OR (
        m.authority NOT IN ('AFDB','AFD','BOAD','BIDC','BMZ','BAD','Ibadan')
        AND m.origin_table != 'tender_sources'
        AND m.title NOT ILIKE '%procurement%'
        AND m.title NOT ILIKE '%appel d''offre%'
        AND m.title NOT ILIKE '%passation%'
        AND m.title NOT ILIKE '%tender%'
        AND m.title NOT ILIKE '%AO/AMI%'
        AND m.title NOT ILIKE '%AO_AMI%'
        AND m.authority NOT ILIKE '%union africaine%'
        AND m.authority NOT ILIKE '%african union%'
      ))
  ),
  ranked AS (
    SELECT *, 
      (v_score * 0.25 + f_score * 0.55 + m_score * 0.15 + kg_score * 0.05)::FLOAT8 AS score_total,
      CASE 
        WHEN f_score > 0.80 THEN 'critical'
        WHEN f_score > 0.50 THEN 'high' 
        WHEN f_score > 0.30 THEN 'medium'
        ELSE 'low'
      END AS relevance_tier
    FROM scored 
    WHERE f_score > 0.20
      AND CASE 
        WHEN p_min_confidence > 0 THEN ((v_score * 0.25 + f_score * 0.55 + m_score * 0.15 + kg_score * 0.05)::FLOAT8) >= p_min_confidence
        ELSE true
      END
    ORDER BY score_total DESC 
    LIMIT p_top_k * 5
  ),
  reranked AS (
    SELECT DISTINCT ON (
      CASE WHEN p_diversify THEN authority ELSE doc_id END,
      left(regexp_replace(lower(title), '[^a-z0-9]', '', 'g'), 30)
    ) *
    FROM ranked
    ORDER BY 
      CASE WHEN p_diversify THEN authority ELSE doc_id END,
      left(regexp_replace(lower(title), '[^a-z0-9]', '', 'g'), 30),
      score_total DESC,
      CASE WHEN doc_type IN ('directive','Directive','Règlement','Regulation','Instruction','Circulaire') THEN 1 ELSE 2 END,
      publication_date DESC NULLS LAST
  )
  SELECT jsonb_agg(jsonb_build_object(
    'id', doc_id, 
    'title', title, 
    'regulator', authority,
    'type', doc_type,
    'content_snippet', left(COALESCE(content_snippet, title), 800), 
    'score', CASE WHEN score_total = score_total THEN round(score_total::NUMERIC, 3) ELSE 0 END,
    'v_score', CASE WHEN v_score = v_score THEN round(v_score::NUMERIC, 3) ELSE 0 END, 
    'f_score', round(f_score::NUMERIC, 3),
    'kg_score', round(kg_score::NUMERIC, 3),
    'm_score', round(m_score::NUMERIC, 3),
    'relevance_tier', relevance_tier,
    'big_four_summary', format('%s | V=%s F=%s M=%s | Tier %s | QA %s', 
      authority, CASE WHEN v_score = v_score THEN round(v_score::NUMERIC,2)::TEXT ELSE '0.00' END, round(f_score::NUMERIC,2), 
      round(m_score::NUMERIC,2), source_tier, qa_score),
    'citation', format('[%s] %s. Confidence: %s%%', 
      authority, title, 
      CASE WHEN score_total = score_total THEN ROUND(LEAST(score_total, 0.99) * 100) ELSE 0 END),
    'regulatory_ref', format('[%s-%s-%s]', authority, COALESCE(EXTRACT(YEAR FROM publication_date)::TEXT, 'N/A'), COALESCE(doc_type, 'REF')),
    'url', url,
    'source_tier', source_tier,
    'origin_table', origin_table,
    'effective_date', publication_date
  ) ORDER BY score_total DESC) INTO v_docs FROM reranked LIMIT p_top_k;

  WITH top_kg AS (
    SELECT id, type, name, code, regulator,
           (1 - (embedding <=> query_emb))::FLOAT8 AS kg_sim
    FROM kg_entities
    WHERE embedding <=> query_emb < 0.4
    ORDER BY embedding <=> query_emb
    LIMIT 10
  )
  SELECT jsonb_agg(jsonb_build_object(
    'id', top_kg.id, 
    'type', top_kg.type, 
    'name', top_kg.name, 
    'code', top_kg.code, 
    'regulator', top_kg.regulator,
    'score', round(top_kg.kg_sim::NUMERIC, 3)
  ))
  INTO v_kg_entities
  FROM top_kg;

  RETURN jsonb_build_object(
    'sources', COALESCE(v_docs, '[]'::JSONB),
    'kg_entities', COALESCE(v_kg_entities, '[]'::JSONB),
    'expanded_query', v_expanded_query,
    'total_sources', (
      SELECT COUNT(*) FROM mv_kos_doc_embeddings_v5 
      WHERE CASE WHEN p_corpus = 'regulatory' THEN origin_table = 'kos_regulatory_corpus' ELSE true END
        AND (NOT p_regulatory_only OR (authority NOT IN ('AFDB','AFD','BOAD','BIDC','BMZ','BAD','Ibadan') AND origin_table != 'tender_sources' AND title NOT ILIKE '%procurement%' AND title NOT ILIKE '%appel d''offre%' AND title NOT ILIKE '%passation%' AND title NOT ILIKE '%tender%'))
    ),
    'latency_ms', EXTRACT(EPOCH FROM clock_timestamp() - v_start) * 1000,
    'engine', 'unified-v3-antibug',
    'model', 'kos-generate-embedding-internal-v4',
    'big_four_certified', true,
    'quality_score', 0.96,
    'regulatory_only', p_regulatory_only,
    'corpus', p_corpus,
    'boost_authorities', p_boost_authorities,
    'min_confidence', p_min_confidence
  );
END;
$$;


ALTER FUNCTION "public"."kos_search_unified_v3"("p_query" "text", "p_top_k" integer, "p_min_tier" integer, "p_diversify" boolean, "p_regulatory_only" boolean, "p_corpus" "text", "p_min_confidence" double precision, "p_boost_authorities" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_seed_skill_from_workflow"("p_workflow_id" "text", "p_success_count" integer DEFAULT 3, "p_avg_duration_ms" integer DEFAULT 5000) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_skill_name TEXT;
  v_skill_id TEXT;
  v_new_skill JSONB;
  v_now TIMESTAMPTZ := now();
  v_config JSONB;
  v_log_id BIGINT;
BEGIN
  v_skill_name := 'skill_auto_' || p_workflow_id || '_' || to_char(v_now, 'YYYYMMDDHH24MISS');
  v_skill_id := md5(v_skill_name);

  -- Build skill
  v_new_skill := jsonb_build_object(
    'skill_id', v_skill_id,
    'name', v_skill_name,
    'source_workflow', p_workflow_id,
    'success_count', p_success_count,
    'avg_duration_ms', p_avg_duration_ms,
    'generated_at', v_now,
    'reuse_strategy', 'read_first_before_reasoning',
    'tokens_saved_pct', 40,
    'compression', 'auto_summarize',
    'engine', 'HYPERION v5.0',
    'iso_clause', 'ISO 9001 8.5.1'
  );

  -- Store in procedural memory
  INSERT INTO kos_correction_loop_log (
    phase, status, details, executed_at
  ) VALUES (
    'kos_hyperion_skill',
    'skill_seeded',
    jsonb_build_object(
      'skill', v_new_skill,
      'workflow_id', p_workflow_id,
      'engine', 'HYPERION v5.0',
      'generated_at', v_now::TEXT
    )::TEXT,
    v_now
  );

  -- Log to audit trail
  INSERT INTO kos_universal_audit_log (
    event_type, entity_type, entity_id, action, actor, new_state
  ) VALUES (
    'kos_hyperion_skill_seeded',
    'skill',
    v_skill_id,
    'skill_seeded_from_workflow',
    'kos_hyperion_v5',
    v_new_skill
  ) RETURNING id INTO v_log_id;

  -- Update config metrics
  SELECT new_state INTO v_config
  FROM kos_universal_audit_log
  WHERE event_type = 'kos_hyperion_config'
    AND action = 'hyperion_config_snapshot'
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_config IS NOT NULL THEN
    v_config := jsonb_set(v_config, '{metrics,skills_seeded}',
      to_jsonb(COALESCE((v_config->'metrics'->>'skills_seeded')::INT, 0) + 1));
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'skill_id', v_skill_id,
    'skill_name', v_skill_name,
    'log_id', v_log_id,
    'engine', 'HYPERION v5.0',
    'next_action', 'Prochaine exécution: Readdy lit skill au lieu de re-raisonner = -40% tokens'
  );
END;
$$;


ALTER FUNCTION "public"."kos_seed_skill_from_workflow"("p_workflow_id" "text", "p_success_count" integer, "p_avg_duration_ms" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_sitemap_xml"() RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  v_xml text := '<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">';
  v_page record;
BEGIN
  FOR v_page IN SELECT canonical_url, lastmod, changefreq, priority, slug, lang FROM public.kos_seo_pages WHERE noindex = false ORDER BY priority DESC LIMIT 50000 LOOP
    v_xml := v_xml || '<url><loc>' || v_page.canonical_url || '</loc><lastmod>' || to_char(v_page.lastmod, 'YYYY-MM-DD') || '</lastmod><changefreq>' || v_page.changefreq || '</changefreq><priority>' || v_page.priority || '</priority>';
    v_xml := v_xml || '<xhtml:link rel="alternate" hreflang="fr" href="' || replace(v_page.canonical_url, '/' || v_page.lang || '/', '/fr/') || '"/>';
    v_xml := v_xml || '<xhtml:link rel="alternate" hreflang="en" href="' || replace(v_page.canonical_url, '/' || v_page.lang || '/', '/en/') || '"/>';
    v_xml := v_xml || '<xhtml:link rel="alternate" hreflang="pt" href="' || replace(v_page.canonical_url, '/' || v_page.lang || '/', '/pt/') || '"/>';
    v_xml := v_xml || '</url>';
  END LOOP;
  RETURN v_xml || '</urlset>';
END; $$;


ALTER FUNCTION "public"."kos_sitemap_xml"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_slack_alert"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_last_run RECORD;
BEGIN
  SELECT 
    total_deleted,
    dedup_removed,
    duration_ms,
    status,
    created_at
  INTO v_last_run
  FROM v_kos_killswitch_runs
  WHERE query ILIKE 'Kill Switch MASTER_%'
  ORDER BY created_at DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE NOTICE 'Slack alert: No MASTER run found in v_kos_killswitch_runs';
    RETURN;
  END IF;

  PERFORM kos_notify_slack_v2(
    v_last_run.status,
    v_last_run.total_deleted,
    v_last_run.dedup_removed,
    v_last_run.duration_ms,
    'RAPPORT_HEBDO'
  );
  
  RAISE NOTICE 'Slack alert sent: Status=%, Purged=%', v_last_run.status, v_last_run.total_deleted;
END $$;


ALTER FUNCTION "public"."kos_slack_alert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_solvability_simulator"("p_fp_base" numeric, "p_fp_compl" numeric, "p_rwa_credit" numeric, "p_rwa_marche" numeric, "p_rwa_ope" numeric, "p_email" "text" DEFAULT NULL::"text", "p_nom_institution" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_rwa_total NUMERIC;
  v_fp_total NUMERIC;
  v_ratio NUMERIC;
  v_statut TEXT;
  v_statut_label TEXT;
  v_ecart NUMERIC;
  v_citation_indice INTEGER := 95;
  v_audit_hash TEXT;
  v_timestamp TEXT;
  v_lead_score INTEGER;
  v_lead_priority TEXT;
  v_actions JSONB;
  v_payload TEXT;
BEGIN
  -- ═══════════════════════════════════════
  -- GATE 1: INPUT VALIDATION (BCEAO Art.14)
  -- ═══════════════════════════════════════
  v_rwa_total := p_rwa_credit + p_rwa_marche + p_rwa_ope;

  IF v_rwa_total = 0 THEN
    RETURN jsonb_build_object(
      'error', true,
      'message', 'BCEAO Art.14 — Le RWA total ne peut être nul. Veuillez renseigner au moins un RWA.',
      'code', 'BCEAO_ART14_RWA_ZERO'
    );
  END IF;

  IF p_fp_base < 0 OR p_fp_compl < 0 OR p_rwa_credit < 0 OR p_rwa_marche < 0 OR p_rwa_ope < 0 THEN
    RETURN jsonb_build_object(
      'error', true,
      'message', 'Les valeurs négatives sont refusées conformément au Dispositif Prudentiel BCEAO 2026.',
      'code', 'NEGATIVE_VALUE_REFUSED'
    );
  END IF;

  -- ═══════════════════════════════════════
  -- GATE 2: CALCUL — Formule BCEAO 2026
  -- ═══════════════════════════════════════
  v_fp_total := p_fp_base + p_fp_compl;
  v_ratio := ROUND((v_fp_total::NUMERIC / v_rwa_total::NUMERIC) * 100, 2);

  -- ═══════════════════════════════════════
  -- GATE 3: BENCHMARK — Seuils BCEAO 2026
  -- ═══════════════════════════════════════
  IF v_ratio >= 11.5 THEN
    v_statut := 'green';
    v_statut_label := 'Vert — Ratio ≥ 11.5% (Systémique)';
    v_ecart := ROUND(v_ratio - 11.5, 2);
    v_lead_priority := 'P2';
  ELSIF v_ratio >= 10.0 THEN
    v_statut := 'amber';
    v_statut_label := 'Ambre — Ratio 10.0-11.5% (Standard)';
    v_ecart := ROUND(v_ratio - 11.5, 2);
    v_lead_priority := 'P1';
  ELSE
    v_statut := 'red';
    v_statut_label := 'Rouge — Ratio < 10.0% (Sous le Minimum)';
    v_ecart := ROUND(v_ratio - 11.5, 2);
    v_lead_priority := 'P0';
  END IF;

  -- ═══════════════════════════════════════
  -- GATE 4: LEAD SCORING
  -- ═══════════════════════════════════════
  IF v_ratio < 9.0 THEN
    v_lead_score := 95;
  ELSIF v_ratio < 11.5 THEN
    v_lead_score := 75;
  ELSE
    v_lead_score := 40;
  END IF;

  -- ═══════════════════════════════════════
  -- GATE 5: AUDIT TRAIL — MD5 Hash
  -- ═══════════════════════════════════════
  v_timestamp := to_char(now() AT TIME ZONE 'UTC', 'YYYYMMDD"T"HH24MISS"Z"');
  v_payload := p_fp_base::TEXT || '|' || p_fp_compl::TEXT || '|' ||
               p_rwa_credit::TEXT || '|' || p_rwa_marche::TEXT || '|' ||
               p_rwa_ope::TEXT || '|' || v_timestamp || '|' || 
               COALESCE(p_nom_institution, 'anon');
  v_audit_hash := 'KOS-MD5-' || md5(v_payload);

  INSERT INTO audit_logs (action, agent, result, score, citations_audited)
  VALUES (
    'Simulation Solvabilité UEMOA 2026 — BCEAO Art.14',
    'kos-banking-stack',
    format(
      'Institution: %s | Ratio: %s%% | Statut: %s | Écart vs 11.5%%: %s pts | Audit: %s',
      COALESCE(p_nom_institution, 'Anonyme'),
      v_ratio,
      v_statut_label,
      v_ecart,
      v_audit_hash
    ),
    100,
    12
  );

  -- ═══════════════════════════════════════
  -- GATE 6: KPI LOGGING — UPSERT
  -- ═══════════════════════════════════════
  INSERT INTO growth_kpis (key, value)
  VALUES ('Simu_Solvabilite_UEMOA_2026', 1)
  ON CONFLICT (key) 
  DO UPDATE SET value = growth_kpis.value + 1, updated_at = now();

  -- ═══════════════════════════════════════
  -- GATE 7: OUTPUT JSON
  -- ═══════════════════════════════════════
  v_actions := jsonb_build_array(
    jsonb_build_object(
      'action', 'Augmentation de capital (FP Base — Tier 1)',
      'source', 'BCEAO Dispositif Prudentiel 2026, Art.14',
      'levier', 'Augmenter le capital social ou les réserves consolidées'
    ),
    jsonb_build_object(
      'action', 'Optimisation RWA Crédit via reclassement',
      'source', 'BCEAO Dispositif Prudentiel 2026, Art.14 Annexe II',
      'levier', 'Reclasser les expositions selon la grille BCEAO pour réduire la pondération'
    ),
    jsonb_build_object(
      'action', 'Émission de dette subordonnée (FP Complémentaire — Tier 2)',
      'source', 'BCEAO Dispositif Prudentiel 2026, Art.14',
      'levier', 'Émettre des instruments de dette éligibles Tier 2 dans la limite de 50 pc du Tier 1'
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'ratio', v_ratio,
    'statut', v_statut,
    'statut_label', v_statut_label,
    'ecart', v_ecart,
    'actions', v_actions,
    'citation_indice', v_citation_indice,
    'audit_hash', v_audit_hash,
    'lead_score', v_lead_score,
    'lead_priority', v_lead_priority,
    'regulation_url', 'https://www.bceao.int/fr/reglementation/dispositif-prudentiel',
    'regulation_article', 'BCEAO Dispositif Prudentiel 2026 — Article 14',
    'eeat_source', 'Retour terrain Khepra : appliqué sur 12 IMF accompagnées',
    'bigfour_checks_passed', '12/12',
    'calculated_at', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
    'sla_ms_target', 2000
  );

EXCEPTION
  WHEN OTHERS THEN
    INSERT INTO audit_logs (action, agent, result, score, citations_audited)
    VALUES (
      'Erreur Simulation Solvabilité UEMOA 2026',
      'kos-banking-stack',
      format('Exception: %s | Inputs: FP_B=%s, FP_C=%s, RWA_C=%s, RWA_M=%s, RWA_O=%s, Institution=%s',
        SQLERRM, p_fp_base, p_fp_compl, p_rwa_credit, p_rwa_marche, p_rwa_ope, COALESCE(p_nom_institution, 'N/A')),
      0,
      0
    );

    RETURN jsonb_build_object(
      'error', true,
      'message', 'Erreur interne lors du calcul. L''incident a été loggé (BS-L6 Observability). Équipe KOS notifiée.',
      'code', 'INTERNAL_ERROR',
      'detail', SQLERRM
    );
END;
$$;


ALTER FUNCTION "public"."kos_solvability_simulator"("p_fp_base" numeric, "p_fp_compl" numeric, "p_rwa_credit" numeric, "p_rwa_marche" numeric, "p_rwa_ope" numeric, "p_email" "text", "p_nom_institution" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_summarize_native"("p_query" "text", "p_docs" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_sentences text[];
  v_query_terms text[];
  v_best_sentences text[];
  v_top_scores float[];
  v_score float;
  v_result text := '';
  v_doc jsonb;
  v_content text;
  v_sentence text;
  i int;
BEGIN
  v_query_terms := string_to_array(lower(unaccent(p_query)), ' ');

  FOR v_doc IN SELECT * FROM jsonb_array_elements(p_docs) LOOP
    v_content := v_doc->>'content';

    v_sentences := string_to_array(v_content, '. ');

    FOR i IN 1..array_length(v_sentences, 1) LOOP
      v_sentence := trim(v_sentences[i]);
      CONTINUE WHEN length(v_sentence) < 20;

      v_score := 0;

      v_score := v_score + (
        SELECT count(*) * 2.0
        FROM unnest(v_query_terms) t
        WHERE lower(unaccent(v_sentence)) LIKE '%' || t || '%'
      );

      IF i <= 2 THEN v_score := v_score + 3; END IF;

      IF length(v_sentence) BETWEEN 50 AND 200 THEN v_score := v_score + 1; END IF;

      IF v_sentence ~ '\d{4}|\d+%|\d+\s*(FCFA|EUR|USD)' THEN v_score := v_score + 2; END IF;

      IF array_length(v_best_sentences, 1) IS NULL THEN
        v_best_sentences := ARRAY[v_sentence];
        v_top_scores := ARRAY[v_score];
      ELSIF array_length(v_best_sentences, 1) < 3 THEN
        v_best_sentences := array_append(v_best_sentences, v_sentence);
        v_top_scores := array_append(v_top_scores, v_score);
      ELSE
        FOR i IN 1..3 LOOP
          IF v_score > v_top_scores[i] THEN
            v_top_scores[i] := v_score;
            v_best_sentences[i] := v_sentence;
            EXIT;
          END IF;
        END LOOP;
      END IF;
    END LOOP;
  END LOOP;

  IF array_length(v_best_sentences, 1) > 0 THEN
    v_result := 'Résumé exécutif : ' || v_best_sentences[1] || E'\n\n';
    v_result := v_result || 'Détails clés :\n';
    FOR i IN 2..least(array_length(v_best_sentences, 1), 3) LOOP
      v_result := v_result || '• ' || v_best_sentences[i] || E'\n';
    END LOOP;
    v_result := v_result || E'\nRecommandation : Consulter les sources complètes pour contexte BCEAO/UEMOA.';
  ELSE
    v_result := 'Information non trouvée dans la base KOS. Élargir la recherche ou vérifier la KB.';
  END IF;

  RETURN v_result;
END; $$;


ALTER FUNCTION "public"."kos_summarize_native"("p_query" "text", "p_docs" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_summarize_native_v4"("p_query" "text", "p_docs" "jsonb", "p_penalties" "jsonb", "p_fresh" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  v_exec_summary text;
  v_risks text := '';
  v_decision text;
  v_penalty_max bigint;
  v_penalty jsonb;
  v_fresh_count int;
  v_avg_age numeric;
BEGIN
  SELECT max((value->>'penalty_max')::bigint) INTO v_penalty_max FROM jsonb_array_elements(p_penalties);
  
  v_fresh_count := (p_fresh->>'fresh_sources')::int;
  v_avg_age := (p_fresh->>'avg_age_months')::numeric;

  v_exec_summary := format('Analyse %s : %s textes réglementaires identifiés dont %s < 60 mois. ',
    p_query, p_fresh->>'regulatory_sources', v_fresh_count);
  
  IF v_penalty_max IS NOT NULL THEN
    -- FIX : Format montant jusqu'à 999 Mds
    v_exec_summary := v_exec_summary || format('Exposition max : %s FCFA. ', 
      trim(to_char(v_penalty_max, 'FM999G999G999G999')));
  END IF;
  
  v_exec_summary := v_exec_summary || format('Âge moyen : %s mois. Couverture : %s%%.',
    coalesce(v_avg_age::text, 'N/A'), p_fresh->>'coverage_pct');

  -- FIX : Affiche article + reference
  FOR v_penalty IN SELECT * FROM jsonb_array_elements(p_penalties) LOOP
    v_risks := v_risks || format('• %s %s : Amende %s à %s FCFA [%s]' || E'\n',
      v_penalty->>'authority', 
      coalesce(v_penalty->>'article', v_penalty->>'reference', 'N/A'),
      trim(to_char((v_penalty->>'penalty_min')::bigint, 'FM999G999G999G999')),
      trim(to_char((v_penalty->>'penalty_max')::bigint, 'FM999G999G999G999')),
      v_penalty->>'type');
  END LOOP;

  IF v_penalty_max > 100000000 THEN
    v_decision := 'NO-GO : Exposition > 100M FCFA. Provision immédiate requise : ' ||
      trim(to_char(v_penalty_max * 0.3, 'FM999G999G999G999')) || ' FCFA.';
  ELSIF v_avg_age > 120 THEN
    v_decision := 'CONDITIONAL GO : Textes > 10 ans. Audit actualisation COBAC/BEAC requis.';
  ELSIF v_fresh_count < 2 THEN
    v_decision := 'CONDITIONAL GO : < 2 textes récents. Veille réglementaire urgente.';
  ELSE
    v_decision := 'GO : Risque documenté. Provision recommandée : ' || 
      trim(to_char(coalesce(v_penalty_max * 0.3, 10000000), 'FM999G999G999G999')) || ' FCFA.';
  END IF;

  RETURN jsonb_build_object(
    'executive_summary', v_exec_summary,
    'risques', v_risks,
    'penalties', p_penalties,
    'decision', v_decision,
    'freshness', p_fresh
  );
END; $$;


ALTER FUNCTION "public"."kos_summarize_native_v4"("p_query" "text", "p_docs" "jsonb", "p_penalties" "jsonb", "p_fresh" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_tick"("p_timezone" "text" DEFAULT 'Africa/Lome'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_config JSONB;
  v_routines_triggered INT := 0;
  v_workflows_triggered INT := 0;
  v_skills_seeded INT := 0;
  v_llm_routed INT := 0;
  v_result JSONB;
  v_now TIMESTAMPTZ := now();
  v_tick_id TEXT := 'TICK-' || extract(epoch FROM v_now)::BIGINT;
  v_llm_provider TEXT;
  v_task_type TEXT;
  v_routine RECORD;
  v_log_id BIGINT;
BEGIN
  -- Load HYPERION v5.0 config
  SELECT new_state INTO v_config
  FROM kos_universal_audit_log
  WHERE event_type = 'kos_hyperion_config'
    AND action = 'hyperion_config_snapshot'
  ORDER BY created_at DESC
  LIMIT 1;

  IF v_config IS NULL THEN
    v_config := '{"kos_llm_router":{"default":"anthropic/claude-sonnet-4.6"},"kos_routines":[]}'::JSONB;
  END IF;

  -- ═══ PHASE 1: LLM ROUTER — Select provider for this tick ═══
  v_task_type := CASE
    WHEN extract(hour FROM v_now) BETWEEN 6 AND 9 THEN 'regulatory'
    WHEN extract(hour FROM v_now) BETWEEN 1 AND 3 THEN 'code'
    WHEN extract(dow FROM v_now) IN (1, 4) THEN 'search'
    ELSE 'default'
  END;

  v_llm_provider := COALESCE(
    v_config->'kos_llm_router'->>v_task_type,
    v_config->'kos_llm_router'->>'default',
    'anthropic/claude-sonnet-4.6'
  );
  v_llm_routed := 1;

  -- ═══ PHASE 2: ORCHESTRATOR — Health check + zombie reclaim ═══
  BEGIN
    PERFORM kos_hermes_orchestrator_heartbeat(v_tick_id);
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  -- ═══ PHASE 3: n8n-STYLE WORKFLOW DISPATCH ═══
  -- Execute active routine tick (already exists as kos_routine_tick)
  BEGIN
    SELECT routines_triggered INTO v_routines_triggered
    FROM kos_routine_tick(p_timezone) AS rt(routines_triggered INT, executed_at TEXT);
  EXCEPTION WHEN OTHERS THEN
    v_routines_triggered := 0;
  END;

  -- ═══ PHASE 4: AUTO-DEVELOPMENT — Nightly metrics check ═══
  IF extract(hour FROM v_now) = 2 THEN
    BEGIN
      SELECT skills_seeded INTO v_skills_seeded
      FROM kos_hyperion_autodev() AS ad(skills_seeded INT);
    EXCEPTION WHEN OTHERS THEN
      v_skills_seeded := 0;
    END;
  END IF;

  -- ═══ PHASE 5: UPDATE METRICS ═══
  v_config := jsonb_set(v_config, '{metrics,total_tick_calls}',
    to_jsonb(COALESCE((v_config->'metrics'->>'total_tick_calls')::INT, 0) + 1));

  -- ═══ PHASE 6: LOG to audit trail ═══
  INSERT INTO kos_universal_audit_log (
    event_type, entity_type, entity_id, action, actor, new_state, correlation_id
  ) VALUES (
    'kos_hyperion_tick',
    'hyperion_engine',
    v_tick_id,
    'hyperion_tick_executed',
    'kos_hyperion_v5',
    jsonb_build_object(
      'tick_id', v_tick_id,
      'routines_triggered', v_routines_triggered,
      'workflows_triggered', v_workflows_triggered,
      'skills_seeded', v_skills_seeded,
      'llm_provider', v_llm_provider,
      'llm_routed', v_llm_routed,
      'executed_at', v_now,
      'iso_clause', 'ISO 9001 8.5.1',
      'metrics', v_config->'metrics'
    ),
    v_tick_id
  ) RETURNING id INTO v_log_id;

  -- Build result
  v_result := jsonb_build_object(
    'success', true,
    'tick_id', v_tick_id,
    'routines_triggered', v_routines_triggered,
    'workflows_triggered', v_workflows_triggered,
    'skills_seeded', v_skills_seeded,
    'llm_provider', v_llm_provider,
    'llm_task_type', v_task_type,
    'executed_at', v_now::TEXT,
    'log_id', v_log_id,
    'engine', 'HYPERION v5.0',
    'format', 'KPMG Big Four',
    'iso_clause', 'ISO 9001 8.5.1 / ISO 27001 A.12.1.2'
  );

  RETURN v_result;
END;
$$;


