CREATE OR REPLACE FUNCTION "public"."kos_upsert_genie"("p_code" "text", "p_name" "text", "p_role" "text", "p_desc" "text", "p_risk" "text", "p_domains" "text"[], "p_meta" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  INSERT INTO public.kos_agents (agent_code, name, agent_role, description, risk_level, knowledge_domains, metadata, system_prompt)
  VALUES (p_code, p_name, p_role, p_desc, p_risk, p_domains, p_meta, 'KOS GENIE — ' || p_name)
