    name = EXCLUDED.name,
    agent_role = EXCLUDED.agent_role,
    description = EXCLUDED.description,
    risk_level = EXCLUDED.risk_level,
    knowledge_domains = EXCLUDED.knowledge_domains,
    metadata = kos_agents.metadata || EXCLUDED.metadata,
    active = true;
END; $$;


