CREATE OR REPLACE FUNCTION "public"."kos_validate_all_sources"() RETURNS TABLE("total_sources" integer, "valid_sources" integer, "obsolete_sources" integer, "dead_sources" integer, "duration_ms" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  start_time timestamptz := clock_timestamp();
  req_id bigint;
  res_body text;
  res_status int;
  parsed_total int := 0;
  parsed_valid int := 0;
  parsed_obsolete int := 0;
  parsed_dead int := 0;
  i int;
BEGIN
  SELECT net.http_post(
    'https://pgfwhahiwqvqeahpirjx.supabase.co/functions/v1/kos-source-validator',
    '{}',
    'application/json',
    '{}'::jsonb,
    60000
  ) INTO req_id;
  
  FOR i IN 1..60 LOOP
    PERFORM pg_sleep(0.5);
    SELECT status_code, content INTO res_status, res_body FROM net._http_response WHERE id = req_id;
    IF res_status IS NOT NULL THEN EXIT; END IF;
  END LOOP;
  
  IF res_status IS NULL OR res_status != 200 THEN
    RETURN QUERY SELECT 0, 0, 0, 0, round(extract(epoch from clock_timestamp() - start_time) * 1000, 2)::numeric;
    RETURN;
  END IF;
  
  parsed_total   := (res_body::jsonb->>'total')::int;
  parsed_valid   := (res_body::jsonb->>'valid')::int;
  parsed_obsolete := (res_body::jsonb->>'obsolete')::int;
  parsed_dead    := (res_body::jsonb->>'dead')::int;
  
  RETURN QUERY SELECT 
    parsed_total, parsed_valid, parsed_obsolete, parsed_dead,
    round(extract(epoch from clock_timestamp() - start_time) * 1000, 2)::numeric;
END;
$$;


ALTER FUNCTION "public"."kos_validate_all_sources"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_validate_all_sources_batch"("p_limit" integer DEFAULT 50, "p_delay_ms" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  src RECORD;
  result jsonb;
  valid_count int := 0;
  generic_count int := 0;
  dead_count int := 0;
  obsolete_count int := 0;
  pending_count int := 0;
  start_time timestamptz;
  processed int := 0;
BEGIN
  start_time := clock_timestamp();

  FOR src IN
    SELECT id, url, content_hash
    FROM kb_sources
    WHERE validation_status = 'pending'
      OR validation_status IS NULL
      OR last_validated_at IS NULL
    ORDER BY priority ASC NULLS LAST, bigfour_weight DESC NULLS LAST
    LIMIT p_limit
  LOOP
    BEGIN
      result := kos_validate_and_classify_source(src.id, src.url, src.content_hash);
      processed := processed + 1;

      CASE result->>'classification'
        WHEN 'valid' THEN valid_count := valid_count + 1;
        WHEN 'generic' THEN generic_count := generic_count + 1;
        WHEN 'dead' THEN dead_count := dead_count + 1;
        WHEN 'obsolete' THEN obsolete_count := obsolete_count + 1;
        ELSE pending_count := pending_count + 1;
      END CASE;

      PERFORM pg_sleep(p_delay_ms / 1000.0);
    EXCEPTION WHEN OTHERS THEN
      dead_count := dead_count + 1;
      UPDATE kb_sources SET
        validation_status = 'dead',
        validation_error = SQLERRM,
        last_validated_at = now()
      WHERE id = src.id;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'processed', processed,
    'valid', valid_count,
    'generic', generic_count,
    'dead', dead_count,
    'obsolete', obsolete_count,
    'pending_remaining', pending_count,
    'duration_seconds', round(extract(epoch from clock_timestamp() - start_time), 2),
    'batch_limit', p_limit,
    'delay_ms', p_delay_ms
  );
END;
$$;


ALTER FUNCTION "public"."kos_validate_all_sources_batch"("p_limit" integer, "p_delay_ms" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_validate_all_sources_internal"("batch_size" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  src RECORD;
  v_result jsonb;
  total_checked int := 0;
  valid_count int := 0;
  generic_count int := 0;
  dead_count int := 0;
  obsolete_count int := 0;
  start_time timestamptz := clock_timestamp();
BEGIN
  FOR src IN 
    SELECT id, url, content_hash
    FROM kb_sources 
    WHERE validation_status = 'pending' 
       OR validation_status IS NULL
       OR last_validated_at < now() - interval '7 days'
    ORDER BY bigfour_weight DESC NULLS LAST, priority ASC NULLS LAST
    LIMIT batch_size
  LOOP
    BEGIN
      v_result := kos_validate_retry(src.id, src.url, src.content_hash);
    EXCEPTION WHEN OTHERS THEN
      UPDATE kb_sources SET
        validation_status = 'dead',
        validation_error = SQLERRM,
        retry_count = COALESCE(retry_count,0) + 1,
        last_validated_at = now()
      WHERE id = src.id;
      total_checked := total_checked + 1;
      dead_count := dead_count + 1;
      CONTINUE;
    END;
    
    total_checked := total_checked + 1;
    
    CASE v_result->>'classification'
      WHEN 'valid' THEN valid_count := valid_count + 1;
      WHEN 'generic' THEN generic_count := generic_count + 1;
      WHEN 'dead' THEN dead_count := dead_count + 1;
      WHEN 'obsolete' THEN obsolete_count := obsolete_count + 1;
      ELSE NULL;
    END CASE;
    
    PERFORM pg_sleep(0.15);
  END LOOP;
  
  RETURN jsonb_build_object(
    'batch_size', batch_size,
    'checked', total_checked,
    'valid', valid_count,
    'generic', generic_count,
    'dead', dead_count,
    'obsolete', obsolete_count,
    'duration_sec', round(extract(epoch from clock_timestamp() - start_time), 2),
    'remaining_pending', (SELECT count(*) FROM kb_sources WHERE validation_status = 'pending' OR validation_status IS NULL),
    'engine', 'pg_net_internal_retry_v2'
  );
END;
$$;


ALTER FUNCTION "public"."kos_validate_all_sources_internal"("batch_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_validate_and_classify_source"("p_source_id" "uuid", "p_url" "text", "p_last_hash" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE
  req_id bigint;
  res_status int;
  res_body text;
  res_hash text;
  body_len int;
  link_count int;
  has_pdf_links boolean;
  has_doc_links boolean;
  title_text text;
  is_valid boolean := false;
  is_obsolete boolean := false;
  is_generic boolean := false;
  classification text := 'pending';
  reason text := '';
  i int;
BEGIN
  SELECT net.http_get(
    p_url,
    headers := '{"User-Agent":"KOS-Validator/2.0 (BigFour-Audit-Bot)"}'::jsonb
  ) INTO req_id;

  res_status := NULL;
  FOR i IN 1..15 LOOP
    PERFORM pg_sleep(0.5);
    SELECT status_code, content INTO res_status, res_body FROM net._http_response WHERE id = req_id;
    IF res_status IS NOT NULL THEN EXIT; END IF;
  END LOOP;

  IF res_status IS NULL THEN
    classification := 'dead';
    reason := 'HTTP timeout (>7.5s)';
    UPDATE kb_sources SET
      validation_status = classification,
      validation_error = reason,
      http_status = 0,
      last_validated_at = now(),
      updated_at = now()
    WHERE id = p_source_id;
    RETURN jsonb_build_object('status', 0, 'valid', false, 'classification', classification, 'reason', reason, 'hash', null, 'generic', false);
  END IF;

  body_len := length(COALESCE(res_body, ''));
  res_hash := encode(digest(COALESCE(res_body, ''), 'sha256'), 'hex');

  title_text := lower(COALESCE(substring(res_body from '<title>([^<]{1,200})</title>'), ''));
  link_count := (SELECT count(*) FROM regexp_matches(COALESCE(res_body, ''), '<a\\s', 'gi'));
  has_pdf_links := COALESCE(res_body, '') ~* '\.(pdf|docx?|odt)"';
  has_doc_links := COALESCE(res_body, '') ~* '(circulaire|instruction|decision|acte|arrete|directive|reglement|norme|texte).*\.(pdf|docx?|html)';

  IF res_status BETWEEN 200 AND 399 THEN
    is_valid := true;

    IF p_url ~* '(search|recherche|q=|query=|index\.|home|accueil|publications/?$|documents/?$|textes/?$|\?.*=.*)$' THEN
      is_generic := true;
      reason := reason || 'URL is portal/search page. ';
    END IF;

    IF title_text ~* '(search|recherche|accueil|home|index|publications|documents|textes|bibliotheque|library|portal|portail)' THEN
      is_generic := true;
      reason := reason || 'Title indicates portal/listing page. ';
    END IF;

    IF link_count > 50 AND NOT has_doc_links AND NOT has_pdf_links THEN
      is_generic := true;
      reason := reason || 'High link count (' || link_count || ') without direct document links. ';
    END IF;

    IF body_len < 2000 AND link_count > 20 THEN
      is_generic := true;
      reason := reason || 'Short content (' || body_len || ' chars) with many links. ';
    END IF;

    IF p_last_hash IS NOT NULL AND res_hash != p_last_hash AND body_len < 500 THEN
      is_obsolete := true;
      reason := reason || 'Content changed and now too short (obsolete). ';
    END IF;

    IF is_obsolete THEN
      classification := 'obsolete';
    ELSIF is_generic THEN
      classification := 'generic';
    ELSE
      classification := 'valid';
      reason := 'Source is a real document/page with direct content.';
    END IF;
  ELSE
    classification := 'dead';
    reason := 'HTTP ' || res_status || ' response.';
    is_valid := false;
  END IF;

  UPDATE kb_sources SET
    validation_status = classification,
    http_status = res_status,
    validation_error = reason,
    content_hash = res_hash,
    last_validated_at = now(),
    updated_at = now(),
    impact_score = CASE
      WHEN classification = 'valid' THEN COALESCE(impact_score, bigfour_weight, 50)
      WHEN classification = 'generic' THEN GREATEST(COALESCE(impact_score, 0) - 30, 0)
      WHEN classification = 'dead' THEN 0
      ELSE impact_score
    END
  WHERE id = p_source_id;

  RETURN jsonb_build_object(
    'status', res_status,
    'valid', is_valid,
    'classification', classification,
    'reason', reason,
    'hash', res_hash,
    'generic', is_generic,
    'body_length', body_len,
    'link_count', link_count,
    'has_pdf_links', has_pdf_links,
    'has_doc_links', has_doc_links,
    'title', title_text
  );
END;
$_$;


ALTER FUNCTION "public"."kos_validate_and_classify_source"("p_source_id" "uuid", "p_url" "text", "p_last_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_validate_publication"("p_pub_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_pub record;
  v_checks jsonb := '{"grammar": false, "regulatory": false, "methodological": false, "citations": false}'::jsonb;
  v_errors text[] := '';
BEGIN
  SELECT * INTO v_pub FROM public.kos_publications WHERE id = p_pub_id;

  IF length(v_pub.abstract) BETWEEN 200 AND 500 AND length(v_pub.content_md) > 1000 THEN
    v_checks := jsonb_set(v_checks, '{grammar}', 'true');
  ELSE
    v_errors := array_append(v_errors, 'Abstract ou contenu trop court');
  END IF;

  IF array_length(v_pub.iso_standards, 1) > 0 THEN
    IF EXISTS (SELECT 1 FROM public.kos_citations WHERE citation_type = 'REGULATOR' AND v_pub.content_md ILIKE '%' || source_name || '%') THEN
      v_checks := jsonb_set(v_checks, '{regulatory}', 'true');
    ELSE
      v_errors := array_append(v_errors, 'Citations réglementaires manquantes');
    END IF;
  ELSE
    v_checks := jsonb_set(v_checks, '{regulatory}', 'true');
  END IF;

  IF array_length(v_pub.bigfour_alignment, 1) > 0 THEN
    v_checks := jsonb_set(v_checks, '{methodological}', 'true');
  ELSE
    v_errors := array_append(v_errors, 'Alignement Big Four manquant');
  END IF;

  IF (SELECT count(*) FROM regexp_matches(v_pub.content_md, '\[([^\]]+)\]', 'g')) >= 3 THEN
    v_checks := jsonb_set(v_checks, '{citations}', 'true');
  ELSE
    v_errors := array_append(v_errors, 'Minimum 3 citations requises');
  END IF;

  UPDATE public.kos_publications
  SET editorial_check = v_checks,
      status = CASE WHEN v_checks @> '{"grammar": true, "regulatory": true, "methodological": true, "citations": true}'::jsonb
                    THEN 'PUBLISHED' ELSE 'REVIEW' END,
      updated_at = now()
  WHERE id = p_pub_id;

  RETURN jsonb_build_object(
    'valid', v_checks @> '{"grammar": true, "regulatory": true, "methodological": true, "citations": true}'::jsonb,
    'checks', v_checks,
    'errors', v_errors
  );
END; $$;


ALTER FUNCTION "public"."kos_validate_publication"("p_pub_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_validate_retry"("p_source_id" "uuid", "p_url" "text", "p_last_hash" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE
  req_id bigint; res_status int; res_body text; res_hash text;
  body_len int; link_count int; has_pdf_links boolean; has_doc_links boolean;
  title_text text; is_valid boolean := false; classification text := 'pending';
  reason text; current_retry int := 0; i int;
BEGIN
  SELECT COALESCE(retry_count,0) INTO current_retry FROM kb_sources WHERE id = p_source_id;

  SELECT net.http_get(p_url, headers := '{"User-Agent":"KOS-Validator/2.1"}'::jsonb) INTO req_id;

  FOR i IN 1..15 LOOP
    PERFORM pg_sleep(0.5);
    SELECT status_code, content INTO res_status, res_body FROM net._http_response WHERE id = req_id;
    IF res_status IS NOT NULL THEN EXIT; END IF;
  END LOOP;

  IF res_status IS NULL THEN
    current_retry := current_retry + 1;
    IF current_retry >= 3 THEN classification := 'dead'; reason := 'timeout after 3 retries';
    ELSE classification := 'pending'; reason := 'timeout retry ' || current_retry || '/3'; END IF;
    UPDATE kb_sources SET validation_status = classification, validation_error = reason, retry_count = current_retry, http_status = 0, last_validated_at = now(), updated_at = now() WHERE id = p_source_id;
    RETURN jsonb_build_object('status',0,'valid',false,'classification',classification,'reason',reason,'retry',current_retry);
  END IF;

  body_len := length(COALESCE(res_body,''));
  res_hash := encode(digest(COALESCE(res_body,''),'sha256'),'hex');
  title_text := lower(COALESCE(substring(res_body from '<title>([^<]{1,200})</title>'),''));
  link_count := (SELECT count(*) FROM regexp_matches(COALESCE(res_body,''),'<a\s','gi'));
  has_pdf_links := COALESCE(res_body,'') ~* '\.(pdf|docx?|odt)"';
  has_doc_links := COALESCE(res_body,'') ~* '(circulaire|instruction|decision|acte|arrete|directive|reglement|norme|texte).*\.(pdf|docx?|html)';

  IF res_status BETWEEN 200 AND 399 THEN
    is_valid := true;
    IF p_url ~* '(search|recherche|q=|query=|index\.|home|accueil|publications|documents|textes|\?.*=.*)$' THEN
      classification := 'generic'; reason := 'portal/search URL';
    ELSIF title_text ~* '(search|recherche|accueil|home|index|publications|documents|textes|bibliotheque|library|portal|portail)' THEN
      classification := 'generic'; reason := 'portal title';
    ELSIF link_count > 50 AND NOT has_doc_links AND NOT has_pdf_links THEN
      classification := 'generic'; reason := 'high links no docs';
    ELSIF body_len < 2000 AND link_count > 20 THEN
      classification := 'generic'; reason := 'short content many links';
    ELSIF p_last_hash IS NOT NULL AND res_hash != p_last_hash AND body_len < 500 THEN
      classification := 'obsolete'; reason := 'content shrunk (obsolete)';
    ELSE
      classification := 'valid'; reason := 'real document/page';
    END IF;
  ELSE
    current_retry := current_retry + 1;
    IF current_retry >= 3 THEN classification := 'dead'; reason := 'HTTP ' || res_status || ' after ' || current_retry || ' retries';
    ELSE classification := 'pending'; reason := 'HTTP ' || res_status || ' retry ' || current_retry || '/3'; END IF;
  END IF;

  UPDATE kb_sources SET validation_status = classification, http_status = res_status, validation_error = reason,
    content_hash = res_hash, last_validated_at = now(), updated_at = now(),
    retry_count = CASE WHEN classification = 'valid' THEN 0 ELSE current_retry END
  WHERE id = p_source_id;

  RETURN jsonb_build_object('status',res_status,'valid',is_valid,'classification',classification,'reason',reason,'hash',res_hash,'retry',CASE WHEN classification='valid' THEN 0 ELSE current_retry END);
END;
$_$;


ALTER FUNCTION "public"."kos_validate_retry"("p_source_id" "uuid", "p_url" "text", "p_last_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."kos_validate_source"("source_url" "text", "last_hash" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  req_id bigint;
  res_status int;
  res_body text;
  res_hash text;
  is_valid boolean := false;
  is_obsolete boolean := false;
  i int;
BEGIN
  -- HTTP GET via pg_net (timeout par defaut ~5s)
  SELECT net.http_get(source_url, headers := '{"User-Agent":"KOS-Source-Validator/1.0"}'::jsonb) INTO req_id;
  
  -- Polling progressif : 10 x 0.5s = 5s total
  res_status := NULL;
  FOR i IN 1..10 LOOP
    PERFORM pg_sleep(0.5);
    SELECT status_code, content INTO res_status, res_body FROM net._http_response WHERE id = req_id;
    IF res_status IS NOT NULL THEN
      EXIT;
    END IF;
  END LOOP;
  
  IF res_status IS NULL THEN
    RETURN jsonb_build_object('valid', false, 'reason', 'timeout', 'status', 0, 'hash', null);
  END IF;
  
  -- Validation : HTTP 200-399 = valid
  IF res_status BETWEEN 200 AND 399 THEN
    is_valid := true;
    res_hash := encode(digest(COALESCE(res_body, ''), 'sha256'), 'hex');
    
    -- Obsolescence : hash change ET contenu < 500 caracteres
    IF last_hash IS NOT NULL AND res_hash != last_hash AND length(COALESCE(res_body, '')) < 500 THEN
      is_obsolete := true;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'valid', is_valid,
    'obsolete', is_obsolete,
    'status', res_status,
    'hash', res_hash,
    'body_length', length(COALESCE(res_body, ''))
  );
END;
$$;


ALTER FUNCTION "public"."kos_validate_source"("source_url" "text", "last_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_action"("p_action" "text", "p_success" boolean DEFAULT true, "p_resource_type" "text" DEFAULT NULL::"text", "p_resource_id" "text" DEFAULT NULL::"text", "p_error_message" "text" DEFAULT NULL::"text", "p_duration_ms" integer DEFAULT NULL::integer, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_compliance_tags" "text"[] DEFAULT ARRAY[]::"text"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
