    user_id, user_email, action, resource_type, resource_id,
    success, error_message, duration_ms, metadata, compliance_tags
  ) VALUES (
    auth.uid(),
    auth.email(),
    p_action,
    p_resource_type,
    p_resource_id,
    p_success,
    p_error_message,
    p_duration_ms,
    p_metadata,
    p_compliance_tags
  );
END;
$$;


