CREATE OR REPLACE FUNCTION "public"."mark_circular_crawled"("p_circular_number" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_result jsonb;
  v_count int;
BEGIN
  UPDATE public.circulars
  SET crawled = true, updated_at = now()
  WHERE circular_number = p_circular_number AND crawled = false;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  SELECT jsonb_build_object(
    'circular_number', p_circular_number,
    'rows_updated', v_count,
    'pages_in_kb', COUNT(*)
  )
  INTO v_result
  FROM public.kb_pages kp
  JOIN public.circular_page_map cpm ON cpm.slug = kp.slug
  JOIN public.circulars c ON c.id = cpm.circular_id
  WHERE c.circular_number = p_circular_number;
  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."mark_circular_crawled"("p_circular_number" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."match_articles"("query_embedding" "public"."vector", "match_count" integer, "min_date" "date") RETURNS TABLE("id" "uuid", "contenu" "text", "regulateur" "text", "reference" "text", "article_num" "text", "url_source" "text", "similarity" double precision)
    LANGUAGE "sql" STABLE
    AS $$
  SELECT a.id, a.contenu, d.regulateur, d.reference, a.article_num, d.url_source,
         1 - (a.embedding <=> query_embedding) AS similarity
  FROM articles_loi a
  JOIN documents_reglementaires d ON a.document_id = d.id
  WHERE d.date_publication >= min_date
  ORDER BY a.embedding <=> query_embedding
  LIMIT match_count;
$$;


ALTER FUNCTION "public"."match_articles"("query_embedding" "public"."vector", "match_count" integer, "min_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."match_rag_documents"("query_embedding" "public"."vector", "match_threshold" double precision DEFAULT 0.5, "match_count" integer DEFAULT 5) RETURNS TABLE("id" "uuid", "titre" "text", "domaine" "text", "sous_domaine" "text", "pays" "text", "organisation" "text", "statut" "text", "description" "text", "mots_cles" "text"[], "type_document" "text", "content" "text", "similarity" double precision)
    LANGUAGE "plpgsql"
    AS $$ BEGIN RETURN QUERY SELECT rag_documents.id, rag_documents.titre, rag_documents.domaine, rag_documents.sous_domaine, rag_documents.pays, rag_documents.organisation, rag_documents.statut, rag_documents.description, rag_documents.mots_cles, rag_documents.type_document, rag_documents.content, 1 - (rag_documents.embedding <=> query_embedding) AS similarity FROM rag_documents WHERE rag_documents.embedding IS NOT NULL AND 1 - (rag_documents.embedding <=> query_embedding) > match_threshold ORDER BY rag_documents.embedding <=> query_embedding LIMIT match_count; END; $$;


