CREATE OR REPLACE FUNCTION "public"."poll_rag_embedding_batch"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  total_with int;
  total_without int;
  pending_count int;
  completed_count int;
BEGIN
  SELECT count(*) INTO total_with FROM rag_documents WHERE est_public = true AND embedding IS NOT NULL;
  SELECT count(*) INTO total_without FROM rag_documents WHERE est_public = true AND embedding IS NULL;
  SELECT count(*) INTO pending_count FROM net._http_response WHERE status_code IS NULL AND error_msg IS NULL;
  SELECT count(*) INTO completed_count FROM net._http_response WHERE status_code IS NOT NULL OR error_msg IS NOT NULL;

  RETURN jsonb_build_object(
    'documents_with_embeddings', total_with,
    'documents_without_embeddings', total_without,
    'pending_requests', pending_count,
    'completed_requests', completed_count,
    'progress_percent', CASE WHEN (total_with + total_without) > 0 
      THEN round((total_with::numeric / (total_with + total_without)::numeric) * 100, 1)
      ELSE 0 END
  );
END;
$$;


ALTER FUNCTION "public"."poll_rag_embedding_batch"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_kos_campaigns"() RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
declare
  camp record;
  pub record;
  payload jsonb;
  req_id bigint;
  res net.http_response_result;
  h text;
  api_token text;
begin
  for camp in 
    select * from public.kos_campaigns 
    where status = 'approved' and scheduled_at <= now()
    limit 5
  loop
    for pub in 
      select * from public.kos_publications 
      where campaign_id = camp.id and status = 'pending'
    loop
      -- Récupérer le token API
      select token into api_token from public.kos_social_tokens where network = pub.network;
      if api_token is null or api_token = '' then
        update public.kos_publications set 
          status = 'failed', 
          error = 'Token API non configuré pour ' || pub.network,
          audit_hash = encode(digest('no_token' || now()::text, 'sha256'), 'hex')
        where id = pub.id;
        continue;
      end if;

      -- Format payload par réseau Big Four
      payload := case pub.network
        when 'linkedin' then jsonb_build_object(
          'author', 'urn:li:organization:xxx',
          'commentary', camp.hook || E'\n\n' || camp.body || E'\n\n' || array_to_string(camp.hashtags, ' '),
          'visibility', 'PUBLIC',
          'distribution', jsonb_build_object('feedDistribution', 'MAIN_FEED')
        )
        when 'x' then jsonb_build_object('text', left(camp.hook || ' ' || camp.body, 280))
        when 'facebook' then jsonb_build_object(
          'message', camp.body, 
          'link', 'https://khepraexperts.com/' || coalesce(camp.kb_page_slug, '')
        )
        when 'instagram' then jsonb_build_object(
          'caption', camp.body, 
          'image_url', camp.image_url
        )
        when 'tiktok' then jsonb_build_object(
          'text', camp.hook, 
          'video_url', camp.image_url
        )
        when 'youtube' then jsonb_build_object(
          'snippet', jsonb_build_object(
            'title', camp.title,
            'description', camp.body
          )
        )
        when 'google_business' then jsonb_build_object(
          'message', camp.body
        )
        else ''::jsonb
      end;

      -- Appel API via pg_net (async → collect)
      req_id := net.http_post(
        url := case pub.network
          when 'linkedin' then 'https://api.linkedin.com/v2/ugcPosts'
          when 'x' then 'https://api.twitter.com/2/tweets'
          when 'facebook' then 'https://graph.facebook.com/v19.0/me/feed'
          when 'instagram' then 'https://graph.facebook.com/v19.0/me/media'
          when 'youtube' then 'https://www.googleapis.com/upload/youtube/v3/videos?part=snippet'
          when 'google_business' then 'https://mybusiness.googleapis.com/v4/accounts'
          else 'https://example.com'
        end,
        body := payload,
        headers := jsonb_build_object(
          'Authorization', 'Bearer ' || api_token,
          'Content-Type', 'application/json'
        )
      );

      -- Collecter la réponse
      res := net.http_collect_response(req_id);

      -- Hash d'audit SHA256
      h := encode(digest(payload::text || now()::text, 'sha256'), 'hex');

      if (res.response).status_code between 200 and 299 then
        update public.kos_publications set 
          status = 'published', 
          external_id = (res.response).body::jsonb->>'id',
          url = coalesce((res.response).body::jsonb->>'permalink_url', (res.response).body::jsonb->>'permalink'),
          published_at = now(),
          audit_hash = h
        where id = pub.id;
      else
        update public.kos_publications set 
          status = 'failed', 
          error = substring((res.response).body, 1, 1000),
          audit_hash = h
        where id = pub.id;
      end if;
    end loop;

    -- Marquer la campagne comme publiée
    update public.kos_campaigns set status = 'published' where id = camp.id;
  end loop;
end; $$;


ALTER FUNCTION "public"."publish_kos_campaigns"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purge_khepra_cache"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  edge_url TEXT;
  edge_token TEXT;
  payload JSONB;
  res RECORD;
  slug_val TEXT;
BEGIN
  -- Détermine le slug depuis la ligne modifiée
  -- kb_pages a probablement une colonne slug, sinon on utilise id
  slug_val := COALESCE(
    NEW.slug,
    NEW.url_slug,
    NEW.page_slug,
    NEW.id::TEXT
  );

  IF slug_val IS NULL OR slug_val = '' THEN
    RETURN NEW;
  END IF;

  -- URL de l'Edge Function (déployée et active)
  edge_url := 'https://pgfwhahiwqvqeahpirjx.supabase.co/functions/v1/cache-purge-handler';

  -- Token JWT de service pour authentifier l'appel vers l'edge function
  edge_token := current_setting('app.edge_service_token', true);

  -- Construction du payload
  payload := jsonb_build_object(
    'slug', slug_val,
    'table', TG_TABLE_NAME,
    'operation', TG_OP,
    'triggered_by', COALESCE(current_setting('request.jwt.claims', true)::jsonb->>'email', 'system')
  );

  -- Appel HTTP vers l'Edge Function via pg_net
  -- Si pg_net n'est pas disponible, cette partie échouera — voir fallback ci-dessous
  BEGIN
    SELECT * INTO res
    FROM net.http_post(
      url := edge_url,
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || COALESCE(edge_token, ''),
        'X-KOS-Source', 'supabase-trigger'
      ),
      body := payload
    );

    -- Log local immédiat (même si l'edge function est async)
    INSERT INTO public.cache_purge_log(slug, table_source, operation, provider, status, success, triggered_by)
    VALUES (slug_val, TG_TABLE_NAME, TG_OP, 'edge_function', res.status_code, res.status_code BETWEEN 200 AND 299, COALESCE(current_setting('request.jwt.claims', true)::jsonb->>'email', 'system'));

  EXCEPTION WHEN OTHERS THEN
    -- Fallback: log l'échec sans bloquer la transaction
    INSERT INTO public.cache_purge_log(slug, table_source, operation, provider, status, success, triggered_by)
    VALUES (slug_val, TG_TABLE_NAME, TG_OP, 'edge_function_error', 0, FALSE, COALESCE(current_setting('request.jwt.claims', true)::jsonb->>'email', 'system'));
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."purge_khepra_cache"() OWNER TO "postgres";


