CREATE OR REPLACE FUNCTION "public"."regtech_full_diagnostic"("p_country_code" "text", "p_sector_code" "text", "p_revenue" bigint, "p_employees" integer, "p_creation_year" integer) RETURNS json
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  result JSON;
BEGIN
  SELECT json_build_object(
    'profile', json_build_object(
      'country_code', p_country_code,
      'sector_code', p_sector_code,
      'revenue', p_revenue,
      'employees', p_employees,
      'creation_year', p_creation_year
    ),
    'rules', COALESCE((
      SELECT json_agg(json_build_object(
        'rule_code', r.rule_code,
        'description', r.description,
        'priority', r.priority,
        'country_name', r.country_name,
        'sector_name', r.sector_name
      ))
      FROM regtech_rules r
      WHERE
        (r.country_code = p_country_code OR r.country_code = 'ALL')
        AND (r.sector_code = p_sector_code OR r.sector_code IS NULL)
        AND (r.revenue_min IS NULL OR p_revenue >= r.revenue_min)
        AND (r.revenue_max IS NULL OR p_revenue < r.revenue_max)
        AND (r.employee_min IS NULL OR p_employees >= r.employee_min)
        AND (r.employee_max IS NULL OR p_employees <= r.employee_max)
        AND (r.creation_year_min IS NULL OR p_creation_year >= r.creation_year_min)
        AND (r.creation_year_max IS NULL OR p_creation_year <= r.creation_year_max)
    ), '[]'::JSON),
    'obligations', COALESCE((
      SELECT json_agg(DISTINCT json_build_object(
        'code', o.code,
        'domain', o.domain,
        'title', o.title,
        'description', o.description,
        'legal_reference', o.legal_reference,
        'authority', o.authority,
        'urgency', o.urgency,
        'deadline_type', o.deadline_type,
        'sanction_risk', o.sanction_risk
      ))
      FROM regtech_rules r
      CROSS JOIN LATERAL unnest(r.obligation_codes) AS oc(code)
      JOIN regtech_obligations o ON o.code = oc.code
      WHERE
        (r.country_code = p_country_code OR r.country_code = 'ALL')
        AND (r.sector_code = p_sector_code OR r.sector_code IS NULL)
        AND (r.revenue_min IS NULL OR p_revenue >= r.revenue_min)
        AND (r.revenue_max IS NULL OR p_revenue < r.revenue_max)
        AND (r.employee_min IS NULL OR p_employees >= r.employee_min)
        AND (r.employee_max IS NULL OR p_employees <= r.employee_max)
        AND (r.creation_year_min IS NULL OR p_creation_year >= r.creation_year_min)
        AND (r.creation_year_max IS NULL OR p_creation_year <= r.creation_year_max)
    ), '[]'::JSON),
    'documents', COALESCE((
      SELECT json_agg(DISTINCT json_build_object(
        'code', d.code,
        'title', d.title,
        'description', d.description,
        'document_type', d.document_type,
        'domain', d.domain,
        'country_code', d.country_code
      ))
      FROM regtech_rules r
      CROSS JOIN LATERAL unnest(r.document_codes) AS dc(code)
      JOIN regtech_documents d ON d.code = dc.code
      WHERE
        (r.country_code = p_country_code OR r.country_code = 'ALL')
        AND (r.sector_code = p_sector_code OR r.sector_code IS NULL)
        AND (r.revenue_min IS NULL OR p_revenue >= r.revenue_min)
        AND (r.revenue_max IS NULL OR p_revenue < r.revenue_max)
        AND (r.employee_min IS NULL OR p_employees >= r.employee_min)
        AND (r.employee_max IS NULL OR p_employees <= r.employee_max)
        AND (r.creation_year_min IS NULL OR p_creation_year >= r.creation_year_min)
        AND (r.creation_year_max IS NULL OR p_creation_year <= r.creation_year_max)
    ), '[]'::JSON),
    'summary', json_build_object(
      'total_rules', (
        SELECT COUNT(*) FROM regtech_rules r
        WHERE
          (r.country_code = p_country_code OR r.country_code = 'ALL')
          AND (r.sector_code = p_sector_code OR r.sector_code IS NULL)
          AND (r.revenue_min IS NULL OR p_revenue >= r.revenue_min)
          AND (r.revenue_max IS NULL OR p_revenue < r.revenue_max)
          AND (r.employee_min IS NULL OR p_employees >= r.employee_min)
          AND (r.employee_max IS NULL OR p_employees <= r.employee_max)
          AND (r.creation_year_min IS NULL OR p_creation_year >= r.creation_year_min)
          AND (r.creation_year_max IS NULL OR p_creation_year <= r.creation_year_max)
      ),
      'critical_count', (
        SELECT COUNT(*) FROM regtech_rules r
        WHERE r.priority = 'critical'
          AND (r.country_code = p_country_code OR r.country_code = 'ALL')
          AND (r.sector_code = p_sector_code OR r.sector_code IS NULL)
          AND (r.revenue_min IS NULL OR p_revenue >= r.revenue_min)
          AND (r.revenue_max IS NULL OR p_revenue < r.revenue_max)
          AND (r.employee_min IS NULL OR p_employees >= r.employee_min)
          AND (r.employee_max IS NULL OR p_employees <= r.employee_max)
          AND (r.creation_year_min IS NULL OR p_creation_year >= r.creation_year_min)
          AND (r.creation_year_max IS NULL OR p_creation_year <= r.creation_year_max)
      ),
      'domain_breakdown', (
        SELECT json_object_agg(domain, cnt) FROM (
          SELECT o.domain, COUNT(DISTINCT o.code) AS cnt
          FROM regtech_rules r
          CROSS JOIN LATERAL unnest(r.obligation_codes) AS oc(code)
          JOIN regtech_obligations o ON o.code = oc.code
          WHERE
            (r.country_code = p_country_code OR r.country_code = 'ALL')
            AND (r.sector_code = p_sector_code OR r.sector_code IS NULL)
            AND (r.revenue_min IS NULL OR p_revenue >= r.revenue_min)
            AND (r.revenue_max IS NULL OR p_revenue < r.revenue_max)
            AND (r.employee_min IS NULL OR p_employees >= r.employee_min)
            AND (r.employee_max IS NULL OR p_employees <= r.employee_max)
            AND (r.creation_year_min IS NULL OR p_creation_year >= r.creation_year_min)
            AND (r.creation_year_max IS NULL OR p_creation_year <= r.creation_year_max)
          GROUP BY o.domain
        ) sub
      ),
      'compliance_score', (
        SELECT CASE
          WHEN COUNT(*) = 0 THEN 100
          WHEN COUNT(*) FILTER (WHERE o.urgency = 'obligatoire') = 0 THEN 85
          WHEN COUNT(*) FILTER (WHERE o.urgency = 'obligatoire' OR r.priority = 'critical') <= 3 THEN 70
          WHEN COUNT(*) FILTER (WHERE o.urgency = 'obligatoire' OR r.priority = 'critical') <= 6 THEN 50
          ELSE 30
        END
        FROM regtech_rules r
        CROSS JOIN LATERAL unnest(r.obligation_codes) AS oc(code)
        JOIN regtech_obligations o ON o.code = oc.code
        WHERE
          (r.country_code = p_country_code OR r.country_code = 'ALL')
          AND (r.sector_code = p_sector_code OR r.sector_code IS NULL)
          AND (r.revenue_min IS NULL OR p_revenue >= r.revenue_min)
          AND (r.revenue_max IS NULL OR p_revenue < r.revenue_max)
          AND (r.employee_min IS NULL OR p_employees >= r.employee_min)
          AND (r.employee_max IS NULL OR p_employees <= r.employee_max)
          AND (r.creation_year_min IS NULL OR p_creation_year >= r.creation_year_min)
          AND (r.creation_year_max IS NULL OR p_creation_year <= r.creation_year_max)
      )
    )
  ) INTO result;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."regtech_full_diagnostic"("p_country_code" "text", "p_sector_code" "text", "p_revenue" bigint, "p_employees" integer, "p_creation_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."regtech_match_rules"("p_country_code" "text", "p_sector_code" "text", "p_revenue" bigint, "p_employees" integer, "p_creation_year" integer) RETURNS TABLE("rule_code" "text", "country_name" "text", "sector_name" "text", "description" "text", "priority" "text", "obligation_codes" "text"[], "document_codes" "text"[])
    LANGUAGE "plpgsql" STABLE
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    r.rule_code,
    r.country_name,
    r.sector_name,
    r.description,
    r.priority,
    r.obligation_codes,
    r.document_codes
  FROM regtech_rules r
  WHERE
    (r.country_code = p_country_code OR r.country_code = 'ALL')
    AND (r.sector_code = p_sector_code OR r.sector_code IS NULL)
    AND (r.revenue_min IS NULL OR p_revenue >= r.revenue_min)
    AND (r.revenue_max IS NULL OR p_revenue < r.revenue_max)
    AND (r.employee_min IS NULL OR p_employees >= r.employee_min)
    AND (r.employee_max IS NULL OR p_employees <= r.employee_max)
    AND (r.creation_year_min IS NULL OR p_creation_year >= r.creation_year_min)
    AND (r.creation_year_max IS NULL OR p_creation_year <= r.creation_year_max)
  ORDER BY
    CASE r.priority
      WHEN 'critical' THEN 1
      WHEN 'high' THEN 2
      WHEN 'standard' THEN 3
    END,
    CASE WHEN r.country_code = p_country_code THEN 0 ELSE 1 END;
END;
$$;


ALTER FUNCTION "public"."regtech_match_rules"("p_country_code" "text", "p_sector_code" "text", "p_revenue" bigint, "p_employees" integer, "p_creation_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."regtech_run_diagnostic"("p_country_code" "text", "p_sector_code" "text", "p_revenue" bigint, "p_employees" integer, "p_creation_year" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    AS $$
DECLARE
  result JSONB;
BEGIN
  SELECT jsonb_build_object(
    'profile', jsonb_build_object(
      'country_code', p_country_code,
      'sector_code', p_sector_code,
      'revenue', p_revenue,
      'employees', p_employees,
      'creation_year', p_creation_year
    ),
    'rules', COALESCE((
      SELECT jsonb_agg(rules_list) FROM (
        SELECT jsonb_build_object(
          'rule_code', r.rule_code,
          'description', r.description,
          'priority', r.priority,
          'country_name', r.country_name,
          'sector_name', r.sector_name
        ) AS rules_list
        FROM regtech_rules r
        WHERE
          (r.country_code = p_country_code OR r.country_code = 'ALL')
          AND (r.sector_code = p_sector_code OR r.sector_code IS NULL)
          AND (r.revenue_min IS NULL OR p_revenue >= r.revenue_min)
          AND (r.revenue_max IS NULL OR p_revenue < r.revenue_max)
          AND (r.employee_min IS NULL OR p_employees >= r.employee_min)
          AND (r.employee_max IS NULL OR p_employees <= r.employee_max)
          AND (r.creation_year_min IS NULL OR p_creation_year >= r.creation_year_min)
          AND (r.creation_year_max IS NULL OR p_creation_year <= r.creation_year_max)
        ORDER BY CASE r.priority WHEN 'critical' THEN 1 WHEN 'high' THEN 2 ELSE 3 END
      ) sub
    ), '[]'::JSONB),
    'obligations', COALESCE((
      SELECT jsonb_agg(obl_list) FROM (
        SELECT DISTINCT ON (o.code) jsonb_build_object(
          'code', o.code,
          'domain', o.domain,
          'title', o.title,
          'description', o.description,
          'legal_reference', o.legal_reference,
          'authority', o.authority,
          'urgency', o.urgency,
          'deadline_type', o.deadline_type,
          'sanction_risk', o.sanction_risk
        ) AS obl_list
        FROM regtech_rules r
        CROSS JOIN LATERAL unnest(r.obligation_codes) AS oc(code)
        JOIN regtech_obligations o ON o.code = oc.code
        WHERE
          (r.country_code = p_country_code OR r.country_code = 'ALL')
          AND (r.sector_code = p_sector_code OR r.sector_code IS NULL)
          AND (r.revenue_min IS NULL OR p_revenue >= r.revenue_min)
          AND (r.revenue_max IS NULL OR p_revenue < r.revenue_max)
          AND (r.employee_min IS NULL OR p_employees >= r.employee_min)
          AND (r.employee_max IS NULL OR p_employees <= r.employee_max)
          AND (r.creation_year_min IS NULL OR p_creation_year >= r.creation_year_min)
          AND (r.creation_year_max IS NULL OR p_creation_year <= r.creation_year_max)
      ) sub
    ), '[]'::JSONB),
    'documents', COALESCE((
      SELECT jsonb_agg(doc_list) FROM (
        SELECT DISTINCT ON (d.code) jsonb_build_object(
          'code', d.code,
          'title', d.title,
          'description', d.description,
          'document_type', d.document_type,
          'domain', d.domain,
          'country_code', d.country_code
        ) AS doc_list
        FROM regtech_rules r
        CROSS JOIN LATERAL unnest(r.document_codes) AS dc(code)
        JOIN regtech_documents d ON d.code = dc.code
        WHERE
          (r.country_code = p_country_code OR r.country_code = 'ALL')
          AND (r.sector_code = p_sector_code OR r.sector_code IS NULL)
          AND (r.revenue_min IS NULL OR p_revenue >= r.revenue_min)
          AND (r.revenue_max IS NULL OR p_revenue < r.revenue_max)
          AND (r.employee_min IS NULL OR p_employees >= r.employee_min)
          AND (r.employee_max IS NULL OR p_employees <= r.employee_max)
          AND (r.creation_year_min IS NULL OR p_creation_year >= r.creation_year_min)
          AND (r.creation_year_max IS NULL OR p_creation_year <= r.creation_year_max)
      ) sub
    ), '[]'::JSONB),
    'summary', jsonb_build_object(
      'total_rules', (SELECT COUNT(*) FROM regtech_rules r WHERE (r.country_code = p_country_code OR r.country_code = 'ALL') AND (r.sector_code = p_sector_code OR r.sector_code IS NULL) AND (r.revenue_min IS NULL OR p_revenue >= r.revenue_min) AND (r.revenue_max IS NULL OR p_revenue < r.revenue_max) AND (r.employee_min IS NULL OR p_employees >= r.employee_min) AND (r.employee_max IS NULL OR p_employees <= r.employee_max) AND (r.creation_year_min IS NULL OR p_creation_year >= r.creation_year_min) AND (r.creation_year_max IS NULL OR p_creation_year <= r.creation_year_max)),
      'critical_count', (SELECT COUNT(*) FROM regtech_rules r WHERE r.priority = 'critical' AND (r.country_code = p_country_code OR r.country_code = 'ALL') AND (r.sector_code = p_sector_code OR r.sector_code IS NULL) AND (r.revenue_min IS NULL OR p_revenue >= r.revenue_min) AND (r.revenue_max IS NULL OR p_revenue < r.revenue_max) AND (r.employee_min IS NULL OR p_employees >= r.employee_min) AND (r.employee_max IS NULL OR p_employees <= r.employee_max) AND (r.creation_year_min IS NULL OR p_creation_year >= r.creation_year_min) AND (r.creation_year_max IS NULL OR p_creation_year <= r.creation_year_max)),
      'compliance_score', 55
    )
  ) INTO result;

  RETURN result;
END;
$$;


ALTER FUNCTION "public"."regtech_run_diagnostic"("p_country_code" "text", "p_sector_code" "text", "p_revenue" bigint, "p_employees" integer, "p_creation_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_rag_embedding"("doc_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  doc_record record;
  embedding_text text;
  req_id bigint;
  api_key text;
BEGIN
  BEGIN
    SELECT decrypted_secret INTO api_key FROM vault.decrypted_secrets WHERE name = 'OPENAI_API_KEY';
  EXCEPTION WHEN OTHERS THEN
    api_key := NULL;
  END;

  IF api_key IS NULL OR api_key = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'OPENAI_API_KEY non configurée dans le Vault Supabase');
  END IF;

  SELECT id, titre, description, mots_cles, domaine, sous_domaine, pays, organisation, type_document, statut, content
  INTO doc_record FROM rag_documents WHERE id = doc_id;

  IF doc_record IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Document introuvable');
  END IF;

  embedding_text := '';
  IF doc_record.titre IS NOT NULL THEN embedding_text := embedding_text || 'Titre: ' || doc_record.titre || E'\n'; END IF;
  IF doc_record.description IS NOT NULL THEN embedding_text := embedding_text || 'Description: ' || doc_record.description || E'\n'; END IF;
  IF doc_record.domaine IS NOT NULL THEN embedding_text := embedding_text || 'Domaine: ' || doc_record.domaine || E'\n'; END IF;
  IF doc_record.sous_domaine IS NOT NULL THEN embedding_text := embedding_text || 'Sous-domaine: ' || doc_record.sous_domaine || E'\n'; END IF;
  IF doc_record.pays IS NOT NULL THEN embedding_text := embedding_text || 'Pays: ' || doc_record.pays || E'\n'; END IF;
  IF doc_record.organisation IS NOT NULL THEN embedding_text := embedding_text || 'Organisation: ' || doc_record.organisation || E'\n'; END IF;
  IF doc_record.type_document IS NOT NULL THEN embedding_text := embedding_text || 'Type: ' || doc_record.type_document || E'\n'; END IF;
  IF doc_record.statut IS NOT NULL THEN embedding_text := embedding_text || 'Statut: ' || doc_record.statut || E'\n'; END IF;
  IF doc_record.mots_cles IS NOT NULL THEN embedding_text := embedding_text || 'Mots-clés: ' || array_to_string(doc_record.mots_cles, ', ') || E'\n'; END IF;
  IF doc_record.content IS NOT NULL THEN embedding_text := embedding_text || 'Contenu: ' || substring(doc_record.content, 1, 6000); END IF;
  embedding_text := substring(embedding_text, 1, 8000);

  req_id := net.http_post(
    url := 'https://api.openai.com/v1/embeddings',
    body := jsonb_build_object('model', 'text-embedding-3-small', 'input', embedding_text, 'dimensions', 1536),
    headers := jsonb_build_object('Authorization', 'Bearer ' || api_key, 'Content-Type', 'application/json'),
    timeout_milliseconds := 30000
  );

  RETURN jsonb_build_object('success', true, 'document_id', doc_id, 'titre', doc_record.titre, 'net_request_id', req_id, 'text_length', length(embedding_text));
END;
$$;


ALTER FUNCTION "public"."request_rag_embedding"("doc_id" "uuid") OWNER TO "postgres";


