CREATE OR REPLACE FUNCTION "public"."search_rag_vector"("query_embedding" "public"."vector", "match_limit" integer DEFAULT 10, "match_domaine" "text" DEFAULT NULL::"text", "min_similarity" double precision DEFAULT 0.0) RETURNS TABLE("id" "uuid", "titre" "text", "domaine" "text", "sous_domaine" "text", "pays" "text", "organisation" "text", "statut" "text", "description" "text", "mots_cles" "text"[], "type_document" "text", "similarity" double precision)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    rd.id,
    rd.titre,
    rd.domaine,
    rd.sous_domaine,
    rd.pays,
    rd.organisation,
    rd.statut,
    rd.description,
    rd.mots_cles,
    rd.type_document,
    (1 - (rd.embedding <=> query_embedding))::float AS similarity
  FROM rag_documents rd
  WHERE rd.est_public = true
    AND rd.embedding IS NOT NULL
    AND (match_domaine IS NULL OR rd.domaine ILIKE '%' || match_domaine || '%')
    AND (1 - (rd.embedding <=> query_embedding))::float >= min_similarity
  ORDER BY rd.embedding <=> query_embedding ASC
  LIMIT match_limit;
END;
$$;


ALTER FUNCTION "public"."search_rag_vector"("query_embedding" "public"."vector", "match_limit" integer, "match_domaine" "text", "min_similarity" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seed_universities_bulk"("p_run_id" "text", "p_count" integer) RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_universities TEXT[] := ARRAY[
    'Yale','Princeton','Columbia','Chicago','UCL','Imperial','ETH Zurich','Tsinghua','Peking','Tokyo',
    'NUS','Toronto','McGill','Melbourne','Sydney','Cape Town','Cairo','Makerere','Nairobi','Addis Ababa',
