    'Harare','Gaborone','Windhoek','Maputo','Mbabane','Maseru','Port Louis','Victoria','Moroni','São Tomé',
    'KU Leuven','Amsterdam','Copenhagen','Helsinki','Oslo','Stockholm','Warsaw','Prague','Vienna','Budapest',
    'Barcelona','Madrid','Lisbon','Rome','Milan','Geneva','Zurich','Munich','Berlin','Heidelberg',
    'Kyoto','Osaka','Seoul','Hong Kong','Singapore Management','Auckland','Monash','Queensland','ANU','Western Australia',
    'Boston University','NYU','Michigan','UCLA','Duke','Northwestern','Cornell','Penn','Caltech','Carnegie Mellon',
    'Brown','Dartmouth','Georgetown','Johns Hopkins','Vanderbilt','Rice','Emory','Notre Dame','Virginia','UNC Chapel Hill',
    'Edinburgh','Manchester','Bristol','Warwick','Glasgow','Birmingham','Leeds','Sheffield','Nottingham','Southampton',
    'Sorbonne Nouvelle','Lyon','Aix-Marseille','Toulouse','Bordeaux','Lille','Strasbourg','Montpellier','Grenoble','Rennes',
    'Bocconi','Bologna','Politecnico Milano','Sapienza','KU Leuven','TU Delft','Erasmus','Leiden','Utrecht','Maastricht',
    'LUISS','Tilburg','Trinity Dublin','Helsinki','Tampere','Bergen','Lund','Uppsala','Aarhus','NTNU'
  ];
  v_topics TEXT[] := ARRAY[
    'AML Compliance','Financial Regulation','RegTech','Digital Banking','Microfinance Law',
    'Central Banking','Financial Inclusion','Cyber Risk','Data Governance','ESG Finance',
    'Cross-Border Regulation','Payment Systems','Sovereign Debt','Macroprudential Policy','Basel III',
    'IFRS 9 Implementation','Sustainable Finance','Corporate Governance','Risk Management','Islamic Finance'
  ];
  i INT;
BEGIN
  FOR i IN 1..p_count LOOP
    INSERT INTO kos_documents (authority, doc_type, jurisdiction, title, publication_date, tags, source_tier, qa_score, confidence_level, deletion_reason)
    VALUES (
      v_universities[1 + (i % array_length(v_universities,1))],
      'Research',
      'International',
      v_universities[1 + (i % array_length(v_universities,1))] || ': ' || v_topics[1 + (i % array_length(v_topics,1))] || ' 2025-' || (2026 - (i % 2)),
      ('2025-01-01'::date + (i || ' days')::interval)::date,
      ARRAY[v_topics[1 + (i % array_length(v_topics,1))], 'Academic', 'Research'],
      3,
      75 + (i % 10),
      'modérée',
      p_run_id
    );
  END LOOP;
  RETURN p_count;
END;
$$;


