CREATE OR REPLACE FUNCTION "public"."send_lead_confirmation_email"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Only fire for direct service-page form submissions
  -- (other form types go through process-lead-submission which already handles emailing)
  IF NEW.form_type = 'service-cta' THEN
    PERFORM net.http_post(
      url     := 'https://pgfwhahiwqvqeahpirjx.supabase.co/functions/v1/confirm-lead-submission',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer sb_publishable_tHDb6wdV1GrnJFVsZMUb8w_LtmLNem4'
      ),
      body    := jsonb_build_object(
        'id',           NEW.id::text,
        'full_name',    COALESCE(NEW.full_name, ''),
        'email',        COALESCE(NEW.email, ''),
        'phone',        NEW.phone,
        'organization', NEW.organization,
        'subject',      NEW.subject,
        'message',      NEW.message,
        'form_type',    NEW.form_type,
        'lead_score',   NEW.lead_score,
        'created_at',   to_char(COALESCE(NEW.created_at, now()) AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
      )
    );
  END IF;
  RETURN NEW;
END;
$$;


