CREATE OR REPLACE FUNCTION "public"."test_bigfour_sla"() RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_regulator_id uuid;
  v_exists uuid;
  v_result jsonb;
BEGIN
  SELECT id INTO v_regulator_id FROM public.regulators WHERE code = 'BCEAO' LIMIT 1;
  SELECT id INTO v_exists FROM public.circulars WHERE circular_number = '13-2026/CB/C' LIMIT 1;

  IF v_exists IS NULL THEN
    INSERT INTO public.circulars (
      reference, title, circular_number, date_issued, official_url,
      keywords, source_authority, regulator_id, status, summary,
      articles_cles, bigfour_impact, metadata
    )
    VALUES (
      'Circulaire 13-2026/CB/C — Test SLA Big Four Pipeline',
      'Test SLA Big Four Pipeline',
      '13-2026/CB/C',
      '2026-07-04',
      'https://www.bceao.int/fr/reglementations/circulaire-13-2026',
      ARRAY['test','sla','bigfour','pipeline','bceao'],
      'BCEAO',
      v_regulator_id,
      'in_force',
      'Circulaire de test pour valider le pipeline end-to-end Big Four <60s.',
      '{"1": "Test article SLA pipeline", "2": "Validation end-to-end"}'::jsonb,
      100,
      '{"test": true, "source_snippet": "meta-ai-e2e-test"}'::jsonb
    );
  ELSE
    UPDATE public.circulars SET crawled = false, updated_at = now() WHERE circular_number = '13-2026/CB/C';
  END IF;

  PERFORM public.generate_circular_page_map('BCEAO');
  UPDATE public.circulars SET crawled = true, updated_at = now() WHERE circular_number = '13-2026/CB/C';

  v_result := jsonb_build_object(
    'test', 'bigfour_sla',
    'circular_number', '13-2026/CB/C',
    'circular_inserted', v_exists IS NULL,
    'message', 'Circulaire 13-2026/CB/C marquée crawled=true. Pipeline déclenché.',
    'expected', jsonb_build_array(
      '5 pages kb_pages insérées/mises à jour avec last_updated = now()',
      'Trigger trg_notify déclenché sur kb_pages',
      'Webhook Slack : ":white_check_mark: KOS AI Big Four : 5 pages BCEAO mises à jour"',
      'Webhook Discord : embed coloré avec stats',
      'Edge Function kos-bigfour-pipeline : cache purge + Datadog + GSC ping',
      'Log dans bigfour_pipeline_log et webhook_notification_log'
    )
  );

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."test_bigfour_sla"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."top3_risques"("p_entite_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN (
    SELECT jsonb_agg(
      jsonb_build_object(
        'rang', row_number,
        'libelle', r.libelle,
        'famille', r.famille,
        'score', r.score,
        'probabilite', r.probabilite,
        'impact', r.impact,
        'statut', r.statut,
        'echeance', r.echeance,
        'niveau', CASE 
          WHEN r.score >= 15 THEN 'Critique'
          WHEN r.score >= 10 THEN 'Élevé'
          WHEN r.score >= 6 THEN 'Modéré'
          ELSE 'Faible'
        END,
        'tendance', CASE WHEN r.statut = 'en_traitement' THEN 'En décrue' ELSE 'Stable' END
      ) ORDER BY row_number
    )
    FROM (
      SELECT 
        libelle, famille, score, probabilite, impact, statut, echeance,
        ROW_NUMBER() OVER (ORDER BY score DESC, probabilite DESC) as row_number
      FROM risk_register
      WHERE entite_id = p_entite_id OR (p_entite_id IS NULL AND entite_id IS NULL)
      ORDER BY score DESC, probabilite DESC
      LIMIT 3
    ) r
  );
END;
$$;


ALTER FUNCTION "public"."top3_risques"("p_entite_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_kb_docs_auto_embed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  content_to_embed text;
  start_time timestamptz := clock_timestamp();
BEGIN
  IF NEW.content IS NULL OR length(NEW.content) < 50 THEN
    RETURN NEW;
  END IF;
  
  IF TG_OP = 'UPDATE' AND OLD.embedding_bge IS NOT NULL 
     AND OLD.content = NEW.content THEN
    RETURN NEW;
  END IF;

  content_to_embed := left(coalesce(NEW.title,'') || ' ' || coalesce(NEW.content,''), 2000);
  
  BEGIN
    NEW.embedding_bge := kos_generate_embedding_local(content_to_embed);
    NEW.embedding_model := 'bge-m3-local';
    NEW.embedded_at := now();
    NEW.embedding_latency_ms := extract(epoch from clock_timestamp() - start_time) * 1000;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'KOS-AUTO-EMBED: Échec embedding doc % : %', NEW.id, SQLERRM;
    NEW.embedding_bge := NULL;
  END;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trg_kb_docs_auto_embed"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_kb_docs_auto_embed_internal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE meta jsonb;
BEGIN
IF NEW.content IS NULL OR length(NEW.content) < 50 THEN RETURN NEW; END IF;
IF TG_OP = 'UPDATE' AND OLD.embedding_bge IS NOT NULL AND OLD.content = NEW.content THEN RETURN NEW; END IF;
meta := jsonb_build_object(
'regulator', NEW.regulator,
'impact_score', COALESCE((SELECT impact_score FROM kb_sources WHERE id = NEW.source_id), 0),
'lang', NEW.lang,
'type', NEW.type
);
NEW.embedding_bge := kos_generate_embedding_internal_v2(
left(coalesce(NEW.title,'') || ' ' || coalesce(NEW.content,''), 3000), meta);
NEW.embedding_model := 'internal-bigfour-v2';
NEW.embedded_at := now();
RETURN NEW;
END;
$$;


