CREATE OR REPLACE FUNCTION "public"."trigger_quota_alert_check"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_log_id    UUID;
  v_start     TIMESTAMPTZ := NOW();
  v_request_id BIGINT;
BEGIN
  -- Insérer un log "pending"
  INSERT INTO public.cron_job_logs (job_name, status, notes)
  VALUES ('quota_alert_checker', 'pending', 'Triggered by pg_cron at ' || NOW()::TEXT)
  RETURNING id INTO v_log_id;

  -- Appel HTTP via pg_net vers l'edge function
  SELECT net.http_get(
    url := 'https://pgfwhahiwqvqeahpirjx.supabase.co/functions/v1/quota-alert-checker',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || current_setting('app.supabase_service_role_key', true)
    ),
    timeout_milliseconds := 30000
  ) INTO v_request_id;

  -- Mettre à jour le log avec l'ID de requête pg_net
  UPDATE public.cron_job_logs
  SET 
    status = 'dispatched',
    notes = 'pg_net request_id: ' || v_request_id::TEXT || ' | dispatched at ' || NOW()::TEXT,
    duration_ms = EXTRACT(EPOCH FROM (NOW() - v_start)) * 1000
  WHERE id = v_log_id;

EXCEPTION WHEN OTHERS THEN
  UPDATE public.cron_job_logs
  SET status = 'error', notes = SQLERRM
  WHERE id = v_log_id;
  RAISE WARNING '[quota_alert_checker] Erreur: %', SQLERRM;
END;
$$;


ALTER FUNCTION "public"."trigger_quota_alert_check"() OWNER TO "postgres";


