CREATE OR REPLACE FUNCTION "public"."validate_pipeline_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  allowed TEXT[];
BEGIN
  allowed := ARRAY(
    SELECT CASE
      WHEN OLD.current_state = 'TOPIC_SELECTED' THEN ARRAY['SCRIPT_GENERATED', 'FAILED']
      WHEN OLD.current_state = 'SCRIPT_GENERATED' THEN ARRAY['SCRIPT_VALIDATED', 'FAILED']
      WHEN OLD.current_state = 'SCRIPT_VALIDATED' THEN ARRAY['VOICE_GENERATED', 'FAILED']
      WHEN OLD.current_state = 'VOICE_GENERATED' THEN ARRAY['VIDEO_RENDERING', 'FAILED']
      WHEN OLD.current_state = 'VIDEO_RENDERING' THEN ARRAY['VIDEO_READY', 'FAILED']
      WHEN OLD.current_state = 'VIDEO_READY' THEN ARRAY['THUMBNAIL_READY', 'FAILED']
      WHEN OLD.current_state = 'THUMBNAIL_READY' THEN ARRAY['SEO_READY', 'FAILED']
      WHEN OLD.current_state = 'SEO_READY' THEN ARRAY['READY_FOR_UPLOAD', 'FAILED']
      WHEN OLD.current_state = 'READY_FOR_UPLOAD' THEN ARRAY['UPLOADING', 'FAILED']
      WHEN OLD.current_state = 'UPLOADING' THEN ARRAY['PROCESSING', 'FAILED']
      WHEN OLD.current_state = 'PROCESSING' THEN ARRAY['PUBLISHED', 'FAILED']
      WHEN OLD.current_state = 'PUBLISHED' THEN ARRAY['TOPIC_SELECTED']
      WHEN OLD.current_state = 'FAILED' THEN ARRAY[
        'TOPIC_SELECTED', 'SCRIPT_GENERATED', 'SCRIPT_VALIDATED',
        'VOICE_GENERATED', 'VIDEO_RENDERING', 'VIDEO_READY',
        'THUMBNAIL_READY', 'SEO_READY', 'READY_FOR_UPLOAD',
        'UPLOADING', 'PROCESSING'
      ]
      ELSE ARRAY[]::TEXT[]
    END
  );
  
  IF NOT (NEW.current_state = ANY(allowed)) THEN
    RAISE EXCEPTION 'Transition invalide: % → % (autorisees: %)',
      OLD.current_state, NEW.current_state, array_to_string(allowed, ', ');
  END IF;
  
  NEW.previous_state := OLD.current_state;
  NEW.updated_at := now();
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_pipeline_transition"() OWNER TO "postgres";


