CREATE OR REPLACE VIEW "public"."kos_auto_dev_metrics" AS
 SELECT ( SELECT "count"(*) AS "count"
           FROM "public"."kb_docs") AS "total_docs",
    ( SELECT "count"(*) AS "count"
           FROM "public"."kb_docs"
          WHERE ("kb_docs"."embedding_bge" IS NOT NULL)) AS "docs_embedded",
    ( SELECT "count"(*) AS "count"
           FROM "public"."kb_docs"
          WHERE ("kb_docs"."embedded_at" > ("now"() - '24:00:00'::interval))) AS "embedded_24h",
    ( SELECT "count"(*) AS "count"
           FROM "public"."kb_sources") AS "active_sources",
    ( SELECT "max"("kb_docs"."embedded_at") AS "max"
           FROM "public"."kb_docs") AS "last_embedding",
    ( SELECT "avg"("kos_routing_log"."latency_ms") AS "avg"
           FROM "public"."kos_routing_log"
          WHERE ("kos_routing_log"."created_at" > ("now"() - '01:00:00'::interval))) AS "avg_latency_1h",
    ((100.0 * (( SELECT "count"(*) AS "count"
           FROM "public"."kb_docs"
          WHERE ("kb_docs"."embedding_bge" IS NOT NULL)))::numeric) / (NULLIF(( SELECT "count"(*) AS "count"
           FROM "public"."kb_docs"), 0))::numeric) AS "embedding_coverage_pct",
    'bge-m3-local'::"text" AS "embedding_engine",
    0 AS "external_api_calls";


ALTER VIEW "public"."kos_auto_dev_metrics" OWNER TO "postgres";


COMMENT ON VIEW "public"."kos_auto_dev_metrics" IS 'KOS REGTECH AI™ — 100% Auto-développement | 0 API Externe';



