CREATE OR REPLACE VIEW "public"."kos_embedding_health" AS
 WITH "stats" AS (
         SELECT "count"(*) FILTER (WHERE (("kb_docs"."content" IS NOT NULL) AND ("length"("kb_docs"."content") > 50))) AS "docs_eligible",
            "count"(*) FILTER (WHERE ("kb_docs"."embedding_bge" IS NOT NULL)) AS "docs_embedded",
            "count"(*) FILTER (WHERE (("kb_docs"."embedding_bge" IS NULL) AND ("kb_docs"."content" IS NOT NULL) AND ("length"("kb_docs"."content") > 50))) AS "docs_pending",
            "count"(*) AS "total_docs",
            COALESCE("avg"("kb_docs"."embedding_latency_ms") FILTER (WHERE ("kb_docs"."embedding_latency_ms" IS NOT NULL)), (0)::numeric) AS "avg_latency_ms",
            "max"("kb_docs"."embedding_latency_ms") FILTER (WHERE ("kb_docs"."embedding_latency_ms" IS NOT NULL)) AS "max_latency_ms",
            "count"(*) FILTER (WHERE ("kb_docs"."embedding_model" = 'bge-m3-local'::"text")) AS "local_embedded",
            "count"(*) FILTER (WHERE (("kb_docs"."embedding_model" IS NULL) OR ("kb_docs"."embedding_model" = ''::"text"))) AS "no_model"
           FROM "public"."kb_docs"
        )
 SELECT "docs_eligible",
    "docs_embedded",
    "docs_pending",
    "total_docs",
    "round"(((("docs_embedded")::numeric / (NULLIF("docs_eligible", 0))::numeric) * (100)::numeric), 2) AS "coverage_pct",
    "avg_latency_ms",
    "max_latency_ms",
    "local_embedded",
    "no_model",
    0 AS "external_api_calls",
    "now"() AS "checked_at"
   FROM "stats";


ALTER VIEW "public"."kos_embedding_health" OWNER TO "postgres";


