CREATE OR REPLACE VIEW "public"."kos_internal_metrics" AS
 SELECT 'embedding_coverage'::"text" AS "metric",
    "count"(*) FILTER (WHERE ("kb_docs"."embedding_bge" IS NOT NULL)) AS "value",
    "count"(*) AS "total",
    "round"(((100.0 * ("count"(*) FILTER (WHERE ("kb_docs"."embedding_bge" IS NOT NULL)))::numeric) / (NULLIF("count"(*), 0))::numeric), 2) AS "pct",
    'docs'::"text" AS "unit",
    'model: internal-bigfour-v3'::"text" AS "detail"
   FROM "public"."kb_docs"
  WHERE ("kb_docs"."content" IS NOT NULL)
UNION ALL
 SELECT 'source_validity'::"text" AS "metric",
    "count"(*) FILTER (WHERE ("kb_sources"."validation_status" = 'valid'::"text")) AS "value",
    "count"(*) AS "total",
    "round"(((100.0 * ("count"(*) FILTER (WHERE ("kb_sources"."validation_status" = 'valid'::"text")))::numeric) / (NULLIF("count"(*), 0))::numeric), 2) AS "pct",
    'sources'::"text" AS "unit",
    ('regulators: '::"text" || "count"(DISTINCT "kb_sources"."type")) AS "detail"
   FROM "public"."kb_sources"
UNION ALL
 SELECT 'agent_avg_latency_ms'::"text" AS "metric",
    ("percentile_cont"((0.95)::double precision) WITHIN GROUP (ORDER BY "kos_routing_log"."latency_ms"))::integer AS "value",
    NULL::bigint AS "total",
    NULL::numeric AS "pct",
    'ms'::"text" AS "unit",
    'engine: kos-agent-internal-v1'::"text" AS "detail"
   FROM "public"."kos_routing_log"
  WHERE (("kos_routing_log"."created_at" > ("now"() - '01:00:00'::interval)) AND ("kos_routing_log"."function_name" = 'kos_rag_query_internal'::"text"))
UNION ALL
 SELECT 'external_api_calls_24h'::"text" AS "metric",
    0 AS "value",
    NULL::bigint AS "total",
    0.0 AS "pct",
    'calls'::"text" AS "unit",
    'engine: 100% PostgreSQL'::"text" AS "detail"
   FROM "generate_series"(1, 1) "generate_series"("generate_series");


ALTER VIEW "public"."kos_internal_metrics" OWNER TO "postgres";


COMMENT ON VIEW "public"."kos_internal_metrics" IS 'KOS REGTECH AI — Monitoring Big Four. 0 API externe.';



CREATE TABLE IF NOT EXISTS "public"."kos_knowledge_base" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "source_type" "text" NOT NULL,
    "source_url" "text",
    "title" "text" NOT NULL,
    "content" "text" NOT NULL,
    "content_tsv" "tsvector" GENERATED ALWAYS AS ("to_tsvector"('"french"'::"regconfig", ((COALESCE("title", ''::"text") || ' '::"text") || COALESCE("content", ''::"text")))) STORED,
    "metadata" "jsonb",
