CREATE OR REPLACE VIEW "public"."kos_public_sitemap" AS
 SELECT 'publication'::"text" AS "type",
    "kos_publications"."slug",
    "kos_publications"."title",
    "kos_publications"."updated_at" AS "lastmod",
    0.9 AS "priority"
   FROM "public"."kos_publications"
  WHERE ("kos_publications"."status" = 'PUBLISHED'::"text")
UNION ALL
 SELECT 'hub'::"text" AS "type",
    "kos_hubs"."slug",
    "kos_hubs"."name" AS "title",
    "kos_hubs"."created_at" AS "lastmod",
    0.8 AS "priority"
   FROM "public"."kos_hubs"
  WHERE ("kos_hubs"."visibility_level" = 'PUBLIC'::"text")
UNION ALL
 SELECT 'tool'::"text" AS "type",
    "kos_tools"."slug",
    "kos_tools"."name" AS "title",
    "kos_tools"."created_at" AS "lastmod",
    0.7 AS "priority"
   FROM "public"."kos_tools"
  WHERE ("kos_tools"."visibility" = 'PUBLIC'::"text");


ALTER VIEW "public"."kos_public_sitemap" OWNER TO "postgres";


