CREATE MATERIALIZED VIEW "public"."kos_routing_kpis_24h" AS
 SELECT "percentile_cont"((0.99)::double precision) WITHIN GROUP (ORDER BY "latency_ms") AS "latency_p99",
    "percentile_cont"((0.95)::double precision) WITHIN GROUP (ORDER BY "latency_ms") AS "latency_p95",
    "avg"("latency_ms") AS "latency_avg",
    "avg"(
        CASE
            WHEN "is_failover" THEN "latency_ms"
            ELSE NULL::double precision
        END) AS "failover_avg_ms",
    ((1)::double precision - (("sum"(
        CASE
            WHEN ("status" = 'error'::"text") THEN 1
            ELSE 0
        END))::double precision / (NULLIF("count"(*), 0))::double precision)) AS "success_rate",
    ((1)::double precision - (("sum"(
        CASE
            WHEN ((NOT "is_failover") AND ("status" = 'error'::"text")) THEN 1
            ELSE 0
        END))::double precision / (NULLIF("count"(
        CASE
            WHEN (NOT "is_failover") THEN 1
            ELSE NULL::integer
        END), 0))::double precision)) AS "primary_success_rate",
    (("sum"(
        CASE
            WHEN ("is_failover" AND ("status" <> 'error'::"text")) THEN 1
            ELSE 0
        END))::double precision / (NULLIF("sum"(
        CASE
            WHEN "is_failover" THEN 1
            ELSE 0
        END), 0))::double precision) AS "degraded_recovery_rate",
    "count"(*) AS "total_requests",
    "sum"(
        CASE
            WHEN ("status" = 'error'::"text") THEN 1
            ELSE 0
        END) AS "error_count",
    "sum"(
        CASE
            WHEN "is_failover" THEN 1
            ELSE 0
        END) AS "failover_count",
        CASE
            WHEN ("count"(*) > 0) THEN ("sum"("cost_eur") / (("count"(*))::numeric / 1000000.0))
            ELSE (0)::numeric
        END AS "cost_per_1m",
    "now"() AS "refreshed_at"
   FROM "public"."kos_routing_log"
  WHERE ("created_at" > ("now"() - '24:00:00'::interval))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."kos_routing_kpis_24h" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."kos_routing_kpis_hourly" AS
 SELECT "date_trunc"('hour'::"text", "created_at") AS "hour",
    "avg"("latency_ms") AS "latency_avg",
    ((1)::double precision - (("sum"(
        CASE
            WHEN ("status" = 'error'::"text") THEN 1
            ELSE 0
        END))::double precision / ("count"(*))::double precision)) AS "success_rate",
    "sum"(
        CASE
            WHEN "is_failover" THEN 1
            ELSE 0
        END) AS "failover_count"
   FROM "public"."kos_routing_log"
  WHERE ("created_at" > ("now"() - '7 days'::interval))
  GROUP BY ("date_trunc"('hour'::"text", "created_at"))
  ORDER BY ("date_trunc"('hour'::"text", "created_at"))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."kos_routing_kpis_hourly" OWNER TO "postgres";


