CREATE OR REPLACE VIEW "public"."kos_search_analytics" AS
 SELECT "date_trunc"('day'::"text", "created_at") AS "day",
    "model_used",
    "count"(*) AS "total_queries",
    "avg"("latency_ms") AS "avg_latency_ms",
    "avg"("quality_score") AS "avg_quality",
    "sum"(
        CASE
            WHEN "hallucination_flag" THEN 1
            ELSE 0
        END) AS "hallucinations",
    "avg"(("tokens_input" + "tokens_output")) AS "avg_tokens"
   FROM "public"."kos_search_logs"
  WHERE ("created_at" >= ("now"() - "make_interval"("days" => 30)))
  GROUP BY ("date_trunc"('day'::"text", "created_at")), "model_used"
  ORDER BY ("date_trunc"('day'::"text", "created_at")) DESC, "model_used";


