CREATE OR REPLACE VIEW "public"."kos_seo_dashboard" AS
 SELECT ( SELECT "count"(*) AS "count"
           FROM "public"."kos_brand_assets"
          WHERE ("kos_brand_assets"."new_value" ~~ '%KOS%'::"text")) AS "brand_kos_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."kos_seo_keywords"
          WHERE ("kos_seo_keywords"."priority" >= 90)) AS "high_priority_keywords",
    ( SELECT "count"(DISTINCT "kos_request_logs"."path") AS "count"
           FROM "public"."kos_request_logs"
          WHERE (("kos_request_logs"."is_bot" = true) AND ("kos_request_logs"."created_at" > ("now"() - '7 days'::interval)))) AS "bot_pages_crawled",
    ( SELECT "count"(*) AS "count"
           FROM "public"."kos_social_agents"
          WHERE ("kos_social_agents"."status" = 'ACTIVE'::"text")) AS "active_social_agents",
    ( SELECT "count"(*) AS "count"
           FROM "public"."kos_tenders"
          WHERE ("kos_tenders"."notified_at" IS NOT NULL)) AS "tenders_notified",
    ( SELECT "avg"("kos_search_logs"."quality_score") AS "avg"
           FROM "public"."kos_search_logs"
          WHERE ("kos_search_logs"."created_at" > ("now"() - '30 days'::interval))) AS "ai_search_quality";


