CREATE MATERIALIZED VIEW "public"."kos_seo_index" AS
 SELECT ('https://khepraexperts.com/publications/'::"text" || "kos_publications"."slug") AS "url",
    "kos_publications"."title",
    "kos_publications"."seo_description" AS "description",
    "kos_publications"."publication_date" AS "date",
    'article'::"text" AS "type",
    "array_to_string"("kos_publications"."keywords", ','::"text") AS "keywords"
   FROM "public"."kos_publications"
  WHERE ("kos_publications"."status" = 'PUBLISHED'::"text")
UNION ALL
 SELECT ('https://khepraexperts.com/hubs/'::"text" || "kos_hubs"."slug") AS "url",
    "kos_hubs"."name" AS "title",
    "kos_hubs"."description",
    ("kos_hubs"."created_at")::"date" AS "date",
    'hub'::"text" AS "type",
    "array_to_string"("kos_hubs"."iso_coverage", ','::"text") AS "keywords"
   FROM "public"."kos_hubs"
  WHERE ("kos_hubs"."visibility_level" = 'PUBLIC'::"text")
  WITH NO DATA;


