CREATE OR REPLACE VIEW "public"."kos_source_health" AS
 WITH "stats" AS (
         SELECT "count"(*) AS "total_sources",
            "count"(*) FILTER (WHERE ("kb_sources"."validation_status" = 'valid'::"text")) AS "valid_sources",
            "count"(*) FILTER (WHERE ("kb_sources"."validation_status" = 'invalid'::"text")) AS "dead_sources",
            "count"(*) FILTER (WHERE ("kb_sources"."validation_status" = 'obsolete'::"text")) AS "obsolete_sources",
            "count"(*) FILTER (WHERE ("kb_sources"."validation_status" = 'pending'::"text")) AS "pending_sources",
            COALESCE("avg"("kb_sources"."impact_score"), (0)::numeric) AS "avg_impact"
           FROM "public"."kb_sources"
        )
 SELECT "total_sources",
    "valid_sources",
    "dead_sources",
    "obsolete_sources",
    "pending_sources",
    "round"(((("valid_sources")::numeric / (NULLIF("total_sources", 0))::numeric) * (100)::numeric), 2) AS "validity_pct",
    "round"(((("obsolete_sources")::numeric / (NULLIF("total_sources", 0))::numeric) * (100)::numeric), 2) AS "obsolescence_pct",
    "round"(((("dead_sources")::numeric / (NULLIF("total_sources", 0))::numeric) * (100)::numeric), 2) AS "dead_pct",
    "avg_impact",
    0 AS "external_api_calls",
    "now"() AS "checked_at"
   FROM "stats";


ALTER VIEW "public"."kos_source_health" OWNER TO "postgres";


