CREATE OR REPLACE VIEW "public"."kpi_conversion" AS
 SELECT "date_trunc"('week'::"text", "published_at") AS "semaine",
    "count"(*) FILTER (WHERE ("agent_status" = 'replied'::"text")) AS "commentaires_traites",
    "count"(*) FILTER (WHERE ("agent_status" = 'lead_detected'::"text")) AS "leads_generes",
        CASE
            WHEN ("count"(*) > 0) THEN "round"(((100.0 * ("count"(*) FILTER (WHERE ("agent_status" = 'lead_detected'::"text")))::numeric) / ("count"(*))::numeric), 2)
            ELSE (0)::numeric
        END AS "taux_conversion"
   FROM "public"."yt_comments"
  GROUP BY ("date_trunc"('week'::"text", "published_at"))
  ORDER BY ("date_trunc"('week'::"text", "published_at")) DESC;


ALTER VIEW "public"."kpi_conversion" OWNER TO "postgres";


