CREATE MATERIALIZED VIEW "public"."mv_kos_doc_embeddings_v3" AS
 SELECT "d"."id",
    "d"."title",
    "d"."authority",
    "d"."date_publication",
    "d"."qa_score",
    "d"."confidence_level",
    "d"."content",
    "s"."source_type",
    "s"."priority"
   FROM ("public"."kos_regulatory_corpus" "d"
     LEFT JOIN "public"."kos_sources_extended" "s" ON (("s"."authority" = "d"."authority")))
  WHERE ("d"."deleted_at" IS NULL)
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_kos_doc_embeddings_v3" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_kos_doc_embeddings_v4" AS
 SELECT ("d"."id")::"text" AS "doc_id",
    "d"."title",
    "d"."authority",
    "d"."publication_date",
    "d"."qa_score",
    "d"."confidence_level",
    "d"."embedding",
    "d"."source_tier",
    "s"."source_type",
    "s"."priority",
    COALESCE("s"."source_type",
        CASE
            WHEN ("d"."source_tier" = 3) THEN 'UNIVERSITY_RESEARCH'::"text"
            ELSE 'UNCATEGORIZED'::"text"
        END) AS "source_category",
    'kos_documents'::"text" AS "origin_table",
    "d"."content"
   FROM ("public"."kos_documents" "d"
     LEFT JOIN "public"."kos_sources_extended" "s" ON ((("s"."authority" = "d"."authority") AND ("s"."active" = true))))
  WHERE ("d"."deleted_at" IS NULL)
UNION ALL
 SELECT ("r"."id")::"text" AS "doc_id",
    "r"."title",
    "r"."authority",
    "r"."date_publication" AS "publication_date",
    COALESCE("r"."qa_score", 70) AS "qa_score",
    'haute'::"text" AS "confidence_level",
    NULL::"public"."vector" AS "embedding",
    1 AS "source_tier",
    "s"."source_type",
    "s"."priority",
    COALESCE("s"."source_type", 'REGULATORY_CORPUS'::"text") AS "source_category",
    'kos_regulatory_corpus'::"text" AS "origin_table",
    "r"."content"
   FROM ("public"."kos_regulatory_corpus" "r"
     LEFT JOIN "public"."kos_sources_extended" "s" ON ((("s"."authority" = "r"."authority") AND ("s"."active" = true))))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_kos_doc_embeddings_v4" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_kos_doc_embeddings_v5" AS
 SELECT ("kos_documents"."id")::"text" AS "doc_id",
    "kos_documents"."title",
    "kos_documents"."authority",
    "kos_documents"."doc_type",
    "kos_documents"."publication_date",
    "kos_documents"."qa_score",
    "kos_documents"."confidence_level",
    "kos_documents"."embedding",
    "kos_documents"."source_tier",
    'NORMALISATION'::"text" AS "source_type",
    10 AS "priority",
    'NORMALISATION'::"text" AS "source_category",
    'kos_documents'::"text" AS "origin_table",
    NULL::"text" AS "content",
    "kos_documents"."url",
    "kos_documents"."tags"
   FROM "public"."kos_documents"
  WHERE (("kos_documents"."deleted_at" IS NULL) AND ("kos_documents"."embedding" IS NOT NULL))
UNION ALL
 SELECT ("kos_regulatory_corpus"."id")::"text" AS "doc_id",
    "kos_regulatory_corpus"."title",
    "kos_regulatory_corpus"."authority",
    "kos_regulatory_corpus"."doc_type",
    "kos_regulatory_corpus"."date_publication" AS "publication_date",
    "kos_regulatory_corpus"."qa_score",
    "kos_regulatory_corpus"."confidence_level",
    "kos_regulatory_corpus"."embedding",
    1 AS "source_tier",
    'REGULATEUR'::"text" AS "source_type",
    10 AS "priority",
    'REGULATEUR'::"text" AS "source_category",
    'kos_regulatory_corpus'::"text" AS "origin_table",
    "kos_regulatory_corpus"."content",
    "kos_regulatory_corpus"."url_officielle" AS "url",
    "kos_regulatory_corpus"."tags"
   FROM "public"."kos_regulatory_corpus"
  WHERE (("kos_regulatory_corpus"."deleted_at" IS NULL) AND ("kos_regulatory_corpus"."embedding" IS NOT NULL))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_kos_doc_embeddings_v5" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_kos_routine_metrics" AS
 SELECT "entity_id" AS "routine_id",
    "count"(*) FILTER (WHERE ("action" = 'routine_completed'::"text")) AS "total_runs",
    "count"(*) FILTER (WHERE ("action" = 'routine_failed'::"text")) AS "total_failures",
        CASE
            WHEN ("count"(*) FILTER (WHERE ("action" = ANY (ARRAY['routine_completed'::"text", 'routine_failed'::"text"]))) > 0) THEN "round"(((100.0 * ("count"(*) FILTER (WHERE ("action" = 'routine_completed'::"text")))::numeric) / ("count"(*) FILTER (WHERE ("action" = ANY (ARRAY['routine_completed'::"text", 'routine_failed'::"text"]))))::numeric), 1)
            ELSE (0)::numeric
        END AS "success_rate_pct",
    (COALESCE("avg"((("new_state" ->> 'duration_ms'::"text"))::integer) FILTER (WHERE ("action" = 'routine_completed'::"text")), (0)::numeric))::integer AS "avg_duration_ms",
    "max"("created_at") AS "last_run_at",
        CASE
            WHEN ("count"(*) FILTER (WHERE ("action" = 'routine_failed'::"text")) > 0) THEN true
            ELSE false
        END AS "needs_auto_correction"
   FROM "public"."kos_universal_audit_log"
  WHERE (("event_type" = 'kos_routine_execution'::"text") AND ("action" = ANY (ARRAY['routine_completed'::"text", 'routine_failed'::"text"])) AND ("created_at" > ("now"() - '30 days'::interval)))
  GROUP BY "entity_id"
  ORDER BY ("count"(*) FILTER (WHERE ("action" = 'routine_completed'::"text"))) DESC
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_kos_routine_metrics" OWNER TO "postgres";


CREATE MATERIALIZED VIEW "public"."mv_kos_skills"
WITH ("autovacuum_vacuum_scale_factor"='0.05') AS
 SELECT "md5"((COALESCE("entity_type", 'unknown'::"text") || COALESCE("action", 'unknown'::"text"))) AS "skill_id",
    "entity_type" AS "task_type",
    "action" AS "action_type",
    "count"(*) AS "total_executions",
    "count"(*) FILTER (WHERE (("new_state" IS NOT NULL) AND (("new_state" ->> 'modulesPassed'::"text") IS NOT NULL))) AS "success_count",
        CASE
            WHEN ("count"(*) > 0) THEN "round"(((("count"(*) FILTER (WHERE (("new_state" IS NOT NULL) AND (("new_state" ->> 'modulesPassed'::"text") IS NOT NULL))))::numeric / ("count"(*))::numeric) * (100)::numeric), 1)
            ELSE (0)::numeric
        END AS "success_rate_pct",
    "count"(DISTINCT "actor") AS "actor_count",
    "min"("created_at") AS "first_seen",
    "max"("created_at") AS "last_seen",
    "jsonb_agg"(DISTINCT "new_state") FILTER (WHERE ("new_state" IS NOT NULL)) AS "example_outputs",
    "now"() AS "last_trained"
   FROM "public"."kos_universal_audit_log"
  WHERE ("created_at" > ("now"() - '90 days'::interval))
  GROUP BY "entity_type", "action"
 HAVING ("count"(*) >= 1)
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."mv_kos_skills" OWNER TO "postgres";


