CREATE MATERIALIZED VIEW "public"."mv_regulatory_coverage_gaps" AS
 WITH "regulated_domains" AS (
         SELECT "unnest"(ARRAY['BCEAO'::"text", 'COBAC'::"text", 'OHADA'::"text", 'GAFI'::"text", 'CIMA'::"text", 'CREPMF'::"text", 'COSUMAF'::"text", 'GIABA'::"text", 'GABAC'::"text", 'BEAC'::"text", 'IFRS'::"text", 'ISO'::"text", 'NIST'::"text", 'COSO'::"text", 'RGPD'::"text"]) AS "authority"
        ), "coverage" AS (
         SELECT
                CASE
                    WHEN ("regulations"."source_authority" ~~* '%bceao%'::"text") THEN 'BCEAO'::"text"
                    WHEN ("regulations"."source_authority" ~~* '%cobac%'::"text") THEN 'COBAC'::"text"
                    WHEN ("regulations"."source_authority" ~~* '%ohada%'::"text") THEN 'OHADA'::"text"
                    WHEN (("regulations"."source_authority" ~~* '%gafi%'::"text") OR ("regulations"."source_authority" ~~* '%fatf%'::"text")) THEN 'GAFI'::"text"
                    WHEN ("regulations"."source_authority" ~~* '%cima%'::"text") THEN 'CIMA'::"text"
                    WHEN ("regulations"."source_authority" ~~* '%crepmf%'::"text") THEN 'CREPMF'::"text"
                    WHEN ("regulations"."source_authority" ~~* '%cosumaf%'::"text") THEN 'COSUMAF'::"text"
                    WHEN ("regulations"."source_authority" ~~* '%giaba%'::"text") THEN 'GIABA'::"text"
                    WHEN ("regulations"."source_authority" ~~* '%gabac%'::"text") THEN 'GABAC'::"text"
                    WHEN ("regulations"."source_authority" ~~* '%beac%'::"text") THEN 'BEAC'::"text"
                    WHEN (("regulations"."source_authority" ~~* '%ifrs%'::"text") OR ("regulations"."source_authority" ~~* '%iasb%'::"text")) THEN 'IFRS'::"text"
                    WHEN ("regulations"."source_authority" ~~* '%iso%'::"text") THEN 'ISO'::"text"
                    WHEN ("regulations"."source_authority" ~~* '%nist%'::"text") THEN 'NIST'::"text"
                    WHEN ("regulations"."source_authority" ~~* '%coso%'::"text") THEN 'COSO'::"text"
                    WHEN (("regulations"."source_authority" ~~* '%rgpd%'::"text") OR ("regulations"."source_authority" ~~* '%gdpr%'::"text")) THEN 'RGPD'::"text"
                    ELSE 'OTHER'::"text"
                END AS "authority",
            "count"(*) AS "text_count"
           FROM "public"."regulations"
          WHERE ("regulations"."source_authority" IS NOT NULL)
          GROUP BY
                CASE
                    WHEN ("regulations"."source_authority" ~~* '%bceao%'::"text") THEN 'BCEAO'::"text"
                    WHEN ("regulations"."source_authority" ~~* '%cobac%'::"text") THEN 'COBAC'::"text"
                    WHEN ("regulations"."source_authority" ~~* '%ohada%'::"text") THEN 'OHADA'::"text"
                    WHEN (("regulations"."source_authority" ~~* '%gafi%'::"text") OR ("regulations"."source_authority" ~~* '%fatf%'::"text")) THEN 'GAFI'::"text"
                    WHEN ("regulations"."source_authority" ~~* '%cima%'::"text") THEN 'CIMA'::"text"
                    WHEN ("regulations"."source_authority" ~~* '%crepmf%'::"text") THEN 'CREPMF'::"text"
                    WHEN ("regulations"."source_authority" ~~* '%cosumaf%'::"text") THEN 'COSUMAF'::"text"
                    WHEN ("regulations"."source_authority" ~~* '%giaba%'::"text") THEN 'GIABA'::"text"
                    WHEN ("regulations"."source_authority" ~~* '%gabac%'::"text") THEN 'GABAC'::"text"
                    WHEN ("regulations"."source_authority" ~~* '%beac%'::"text") THEN 'BEAC'::"text"
                    WHEN (("regulations"."source_authority" ~~* '%ifrs%'::"text") OR ("regulations"."source_authority" ~~* '%iasb%'::"text")) THEN 'IFRS'::"text"
                    WHEN ("regulations"."source_authority" ~~* '%iso%'::"text") THEN 'ISO'::"text"
                    WHEN ("regulations"."source_authority" ~~* '%nist%'::"text") THEN 'NIST'::"text"
                    WHEN ("regulations"."source_authority" ~~* '%coso%'::"text") THEN 'COSO'::"text"
                    WHEN (("regulations"."source_authority" ~~* '%rgpd%'::"text") OR ("regulations"."source_authority" ~~* '%gdpr%'::"text")) THEN 'RGPD'::"text"
                    ELSE 'OTHER'::"text"
                END
        )
 SELECT "rd"."authority",
    COALESCE("c"."text_count", (0)::bigint) AS "texts_covered",
        CASE
            WHEN (COALESCE("c"."text_count", (0)::bigint) = 0) THEN 'CRITICAL_GAP'::"text"
            WHEN (COALESCE("c"."text_count", (0)::bigint) < 5) THEN 'PARTIAL_COVERAGE'::"text"
            WHEN (COALESCE("c"."text_count", (0)::bigint) < 15) THEN 'ADEQUATE'::"text"
            ELSE 'STRONG'::"text"
        END AS "coverage_status",
        CASE
            WHEN (COALESCE("c"."text_count", (0)::bigint) = 0) THEN 0
            WHEN (COALESCE("c"."text_count", (0)::bigint) < 5) THEN 40
            WHEN (COALESCE("c"."text_count", (0)::bigint) < 15) THEN 75
            ELSE 95
        END AS "coverage_score"
   FROM ("regulated_domains" "rd"
     LEFT JOIN "coverage" "c" ON (("rd"."authority" = "c"."authority")))
  ORDER BY
        CASE
            WHEN (COALESCE("c"."text_count", (0)::bigint) = 0) THEN 0
            WHEN (COALESCE("c"."text_count", (0)::bigint) < 5) THEN 40
            WHEN (COALESCE("c"."text_count", (0)::bigint) < 15) THEN 75
            ELSE 95
        END
  WITH NO DATA;


