    CONSTRAINT "risk_register_impact_check" CHECK ((("impact" >= 1) AND ("impact" <= 5))),
    CONSTRAINT "risk_register_probabilite_check" CHECK ((("probabilite" >= 1) AND ("probabilite" <= 5))),
