CREATE MATERIALIZED VIEW "public"."risk_dashboard_live" AS
 SELECT "famille",
    "count"(*) AS "nb_risques",
    "round"("avg"("score"), 2) AS "score_moyen",
    "max"("score") AS "score_max",
    "jsonb_agg"("libelle" ORDER BY "score" DESC) FILTER (WHERE ("score" >= 15)) AS "top_risques",
    "jsonb_agg"("jsonb_build_object"('id', "id", 'libelle', "libelle", 'score', "score", 'probabilite', "probabilite", 'impact', "impact", 'responsable', "responsable", 'echeance', "echeance", 'statut', "statut") ORDER BY "score" DESC) FILTER (WHERE ("score" >= 15)) AS "top_risques_detail"
   FROM "public"."risk_register"
  WHERE ("statut" = 'ouvert'::"text")
  GROUP BY "famille"
  WITH NO DATA;


