CREATE OR REPLACE VIEW "public"."rls_coverage_audit" AS
 SELECT "schemaname",
    "tablename",
        CASE
            WHEN "rowsecurity" THEN 'RLS ACTIVE'::"text"
            ELSE 'RLS INACTIVE!!!'::"text"
        END AS "rls_status",
    ( SELECT "count"(*) AS "count"
           FROM "pg_policies" "p"
          WHERE (("p"."schemaname" = "t"."schemaname") AND ("p"."tablename" = "t"."tablename"))) AS "policy_count"
   FROM "pg_tables" "t"
  WHERE (("schemaname" = 'public'::"name") AND ("tablename" !~~ 'pg_%'::"text"))
  ORDER BY "rowsecurity", "tablename";


ALTER VIEW "public"."rls_coverage_audit" OWNER TO "postgres";


