CREATE OR REPLACE VIEW "public"."table_bloat" AS
 SELECT "schemaname",
    "relname" AS "table_name",
    "n_live_tup",
    "n_dead_tup",
    "round"(((("n_dead_tup")::numeric * 100.0) / (NULLIF(("n_live_tup" + "n_dead_tup"), 0))::numeric), 2) AS "dead_tuple_percent",
    "last_vacuum",
    "last_autovacuum"
   FROM "pg_stat_user_tables"
  WHERE (("schemaname" = 'public'::"name") AND (("n_dead_tup" > 1000) OR (((("n_dead_tup")::numeric * 100.0) / (NULLIF(("n_live_tup" + "n_dead_tup"), 0))::numeric) > (20)::numeric)))
  ORDER BY "n_dead_tup" DESC;


ALTER VIEW "public"."table_bloat" OWNER TO "postgres";


