CREATE OR REPLACE VIEW "public"."unused_indexes" AS
 SELECT "i"."schemaname",
    "i"."relname" AS "table_name",
    "i"."indexrelname" AS "index_name",
    "pg_size_pretty"("pg_relation_size"(("i"."indexrelid")::"regclass")) AS "index_size",
    "i"."idx_scan" AS "index_scans"
   FROM ("pg_stat_user_indexes" "i"
     JOIN "pg_index" USING ("indexrelid"))
  WHERE (("i"."idx_scan" = 0) AND ("i"."schemaname" = 'public'::"name") AND (NOT "pg_index"."indisunique"))
  ORDER BY ("pg_relation_size"(("i"."indexrelid")::"regclass")) DESC;


