CREATE OR REPLACE VIEW "public"."v_bigfour_circular_pages" AS
 SELECT "c"."id" AS "circular_id",
    "c"."circular_number",
    "c"."title" AS "circular_title",
    "c"."date_issued",
    "c"."crawled",
    "c"."bigfour_impact",
    "c"."source_authority" AS "regulator",
    "count"("cpm"."id") AS "mapped_pages",
    "count"("kp"."slug") AS "generated_pages",
    "jsonb_agg"(DISTINCT "jsonb_build_object"('slug', "cpm"."slug", 'type', "cpm"."type", 'intent', "cpm"."intent", 'generated', ("kp"."slug" IS NOT NULL))) FILTER (WHERE ("cpm"."id" IS NOT NULL)) AS "page_map"
   FROM (("public"."circulars" "c"
     LEFT JOIN "public"."circular_page_map" "cpm" ON (("cpm"."circular_id" = "c"."id")))
     LEFT JOIN "public"."kb_pages" "kp" ON (("kp"."slug" = "cpm"."slug")))
  WHERE ("c"."source_authority" = 'BCEAO'::"text")
  GROUP BY "c"."id", "c"."circular_number", "c"."title", "c"."date_issued", "c"."crawled", "c"."bigfour_impact", "c"."source_authority"
  ORDER BY "c"."date_issued" DESC;


ALTER VIEW "public"."v_bigfour_circular_pages" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_bigfour_pipeline_status" AS
 SELECT "regulator",
    "circular_number",
    "pages_count",
    "duration_seconds",
    "cache_purge_results",
    "datadog_result",
    "gsc_result",
    "ran_at",
        CASE
            WHEN ("duration_seconds" < 60) THEN 'OK'::"text"
            ELSE 'ALERTE'::"text"
        END AS "sla_status"
   FROM "public"."bigfour_pipeline_log" "bpl"
  ORDER BY "ran_at" DESC;


ALTER VIEW "public"."v_bigfour_pipeline_status" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_kos_active_routing" AS
 SELECT "function_name",
    "description",
    "primary_provider",
    "fallback_provider",
    "n8n_webhook_url",
    "edge_function_name",
    "status",
    "error_count",
    "max_errors_before_fallback",
    ("error_count" >= "max_errors_before_fallback") AS "is_degraded",
        CASE
            WHEN ("status" = ANY (ARRAY['inactive'::"text", 'deprecated'::"text"])) THEN "fallback_provider"
            WHEN ("error_count" >= "max_errors_before_fallback") THEN "fallback_provider"
            ELSE "primary_provider"
        END AS "current_provider",
    "last_routed_at",
    "updated_at"
   FROM "public"."kos_function_routing" "fr"
  WHERE (("status" <> 'deprecated'::"text") OR ("fallback_provider" <> 'none'::"text"));


ALTER VIEW "public"."v_kos_active_routing" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_kos_agent_performance" AS
 SELECT "date_trunc"('hour'::"text", "created_at") AS "hour",
    "count"(*) AS "queries",
    ("avg"("latency_ms"))::integer AS "avg_latency_ms",
    ("percentile_cont"((0.95)::double precision) WITHIN GROUP (ORDER BY "latency_ms"))::integer AS "p95_latency_ms",
    "count"(*) FILTER (WHERE ("status" = 'success'::"text")) AS "success_count"
   FROM "public"."kos_routing_log"
  WHERE (("function_name" ~~ 'kos_%'::"text") AND ("created_at" > ("now"() - '24:00:00'::interval)))
  GROUP BY ("date_trunc"('hour'::"text", "created_at"))
  ORDER BY ("date_trunc"('hour'::"text", "created_at")) DESC;


ALTER VIEW "public"."v_kos_agent_performance" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_kos_health" AS
 SELECT "count"(*) FILTER (WHERE ("deleted_at" IS NULL)) AS "docs_active",
    "count"(*) FILTER (WHERE ("deleted_at" IS NOT NULL)) AS "docs_purged",
    "count"(*) FILTER (WHERE (("qa_score" >= 90) AND ("deleted_at" IS NULL))) AS "docs_haute_conf",
    "count"(*) FILTER (WHERE (("date_publication" > ("now"() - '1 year'::interval)) AND ("deleted_at" IS NULL))) AS "docs_recent",
    "pg_size_pretty"("pg_total_relation_size"('"public"."kos_regulatory_corpus"'::"regclass")) AS "table_size",
    "max"("created_at") AS "last_ingestion",
    ( SELECT "max"("kos_leakage_audit"."created_at") AS "max"
           FROM "public"."kos_leakage_audit"
          WHERE ("kos_leakage_audit"."query" ~~* 'Kill Switch%'::"text")) AS "last_killswitch"
   FROM "public"."kos_regulatory_corpus";


ALTER VIEW "public"."v_kos_health" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_kos_killswitch_runs" AS
 SELECT "id",
    "created_at",
    "query",
    "severity",
    "leaked_sources",
    "user_id",
    (("redacted_response")::"jsonb" ->> 'purged_ids'::"text") AS "purged_ids",
    COALESCE(((("redacted_response")::"jsonb" ->> 'total_deleted'::"text"))::integer, 0) AS "total_deleted",
    COALESCE(((("redacted_response")::"jsonb" ->> 'rag_active'::"text"))::boolean, true) AS "rag_active",
    COALESCE(((("redacted_response")::"jsonb" ->> 'dry_run'::"text"))::boolean, false) AS "dry_run",
    0 AS "severity_rank",
        CASE
            WHEN (COALESCE("array_length"("leaked_sources", 1), 0) = 0) THEN 'CLEAN'::"text"
            WHEN (COALESCE(((("redacted_response")::"jsonb" ->> 'total_deleted'::"text"))::integer, 0) > 0) THEN 'PURGED'::"text"
            ELSE 'BLOCKED'::"text"
        END AS "status",
    COALESCE(((("redacted_response")::"jsonb" ->> 'dedup_removed'::"text"))::integer, 0) AS "dedup_removed",
    COALESCE(((("redacted_response")::"jsonb" ->> 'duration_ms'::"text"))::integer, 0) AS "duration_ms"
   FROM "public"."kos_leakage_audit"
  WHERE ("query" ~~* 'Kill Switch%'::"text");


ALTER VIEW "public"."v_kos_killswitch_runs" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_kos_rag_extended" AS
 SELECT "s"."source_type",
    "s"."authority",
    "count"("d"."doc_id") AS "docs_count",
    "round"("avg"(COALESCE("d"."qa_score", 70)), 1) AS "avg_qa_score",
    "max"("d"."publication_date") AS "last_doc_date",
    "s"."priority"
   FROM ("public"."kos_sources_extended" "s"
     LEFT JOIN "public"."mv_kos_doc_embeddings_v4" "d" ON (("d"."authority" = "s"."authority")))
  WHERE ("s"."active" = true)
  GROUP BY "s"."source_type", "s"."authority", "s"."priority"
  ORDER BY "s"."priority" DESC, ("count"("d"."doc_id")) DESC;


ALTER VIEW "public"."v_kos_rag_extended" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_kos_rag_extended_v2" AS
 SELECT COALESCE("s"."source_type", 'UNKNOWN'::"text") AS "source_category",
    "s"."authority",
    "count"("d"."doc_id") AS "docs_count",
    "round"("avg"(COALESCE("d"."qa_score", 70)), 1) AS "avg_qa_score",
    "max"("d"."publication_date") AS "last_doc_date",
    "s"."priority",
    "count"(*) FILTER (WHERE ("d"."origin_table" = 'kos_documents'::"text")) AS "with_embeddings",
    "count"(*) FILTER (WHERE ("d"."origin_table" = 'kos_regulatory_corpus'::"text")) AS "without_embeddings",
        CASE
            WHEN ("count"("d"."doc_id") > 0) THEN 'active'::"text"
            ELSE 'empty'::"text"
        END AS "embedding_status",
    "count"(DISTINCT "d"."origin_table") AS "nb_origin_tables"
   FROM ("public"."kos_sources_extended" "s"
     LEFT JOIN "public"."mv_kos_doc_embeddings_v4" "d" ON (("d"."authority" = "s"."authority")))
  WHERE ("s"."active" = true)
  GROUP BY "s"."source_type", "s"."authority", "s"."priority"
  ORDER BY "s"."priority" DESC, ("count"("d"."doc_id")) DESC;


ALTER VIEW "public"."v_kos_rag_extended_v2" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_kos_seed_summary" AS
 SELECT "source_tier",
        CASE "source_tier"
            WHEN 1 THEN 'Tier 1 - Régulateurs + Normalisation'::"text"
            WHEN 2 THEN 'Tier 2 - Big Four'::"text"
            WHEN 3 THEN 'Tier 3 - Universités + Research'::"text"
            ELSE NULL::"text"
        END AS "tier_name",
    "count"(*) AS "nb_docs",
    "count"(*) FILTER (WHERE ("confidence_level" = 'haute'::"text")) AS "haute_conf",
    "round"("avg"(COALESCE("qa_score", 70)), 1) AS "qa_moyen",
    "count"(DISTINCT "authority") AS "nb_sources"
   FROM "public"."mv_kos_doc_embeddings_v4" "t"
  GROUP BY "source_tier"
  ORDER BY "source_tier";


ALTER VIEW "public"."v_kos_seed_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_kos_seed_summary_v2" AS
 SELECT "source_tier",
        CASE "source_tier"
            WHEN 1 THEN 'Tier 1 - Régulateurs + Normalisation'::"text"
            WHEN 2 THEN 'Tier 2 - Big Four'::"text"
            WHEN 3 THEN 'Tier 3 - Universités + Research'::"text"
            ELSE NULL::"text"
        END AS "tier_name",
    "count"(*) AS "nb_docs",
    "count"(*) FILTER (WHERE ("confidence_level" = 'haute'::"text")) AS "haute_conf",
    "round"("avg"(COALESCE("qa_score", 70)), 1) AS "qa_moyen",
    "count"(DISTINCT "authority") AS "nb_sources",
    "count"(*) FILTER (WHERE ("origin_table" = 'kos_documents'::"text")) AS "doc_documents",
    "count"(*) FILTER (WHERE ("origin_table" = 'kos_regulatory_corpus'::"text")) AS "doc_corpus"
   FROM "public"."mv_kos_doc_embeddings_v4" "t"
  GROUP BY "source_tier"
  ORDER BY "source_tier";


ALTER VIEW "public"."v_kos_seed_summary_v2" OWNER TO "postgres";


