CREATE OR REPLACE VIEW "public"."v_ao_pending_notifications" AS
 SELECT "ao"."id",
    "ao"."source",
    "ao"."type",
    "ao"."titre",
    "ao"."pays",
    "ao"."montant_usd",
    "ao"."deadline",
    "ao"."url",
    "ao"."secteurs",
    "ao"."crawled_at",
    "count"("sub"."id") AS "matched_subscribers"
   FROM ("public"."ao_ami" "ao"
     LEFT JOIN "public"."ao_alert_subs" "sub" ON (((("sub"."pays" IS NULL) OR ("ao"."pays" = ANY ("sub"."pays"))) AND ((COALESCE("ao"."montant_usd", (0)::bigint) >= "sub"."budget_min") AND (COALESCE("ao"."montant_usd", (0)::bigint) <= "sub"."budget_max")) AND (("sub"."secteurs" IS NULL) OR ("sub"."secteurs" && "ao"."secteurs")))))
  WHERE (("ao"."notified" = false) AND ("ao"."crawled_at" > ("now"() - '24:00:00'::interval)))
  GROUP BY "ao"."id"
  ORDER BY "ao"."crawled_at" DESC;



